INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p1-3', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', 'UNKNOWN', 1, 'Edited by Bret Jordan, Rich Piazza, and Trey Darley. Latest stage: https://docs.oasis-open.org/cti/stix/v2.1/stix-v2.1.html. This specification is related to: TAXII Version 2.1. Edited by Bret Jordan and Drew Varner. Latest stage: https://docs.oasis- open.org/cti/taxii/v2.1/taxii-v2.1.html. STIX/TAXII 2.0 Interoperability Test Document: Part 1 Version 1.1. Edited by Allan Thomson and Jason Keirstead. Latest stage: https://docs.oasis-open.org/cti/stix-taxii-2-interop-p1/v1.1/stix-taxii- 2-interop-p1-v1.1.html.', 'vec_doc-10-oasis-stix21-p1-3', 0, 129, 'v2.1.0', '6453da2a2400e6dd8b626d92a2551c6c78c9b9a1e76352c8aad42c026e466554', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"UNKNOWN","subsection":"UNKNOWN","table_id":null,"page":1,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":3,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"General Document Content"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p2-4', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', 'UNKNOWN', 2, 'Standards Track Work Product 02 April 2025 - Page 2 of 276Copyright © OASIS Open 2025. All Rights Reserved. STIX/TAXII 2.0 Interoperability Test Document: Part 2 Version 1.0. Edited by Allan Thomson and Jason Keirstead. Latest stage: https://docs.oasis-open.org/cti/stix-taxii-2-interop-p2/v1.0/stix-taxii- 2-interop-p2-v1.0.html. Abstract: Structured Threat Information Expression (STIX) is a language for expressing cyber threat and observable information. This document defines concepts that apply across all of STIX and defines the overall structure of the STIX language. Status: This document was last revised or approved by the membership of OASIS on the above date. The level of approval is also listed above. Check the “Latest stage” location noted above for possible later revisions of this document. Any other numbered Versions and other technical work produced by the Technical Committee (TC) are listed at https://www.oasis-open.org/committees/tc_home.php? wg_abbrev=cti#technical.', 'vec_doc-10-oasis-stix21-p2-4', 0, 249, 'v2.1.0', '5637540441f05c26a32fa68e6ab704237968f2da5739dd59bff5cd55b40ee8b2', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"UNKNOWN","subsection":"UNKNOWN","table_id":null,"page":2,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":4,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"General Document Content"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p2-5', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', 'UNKNOWN', 2, 'TC members should send comments on this document to the TC’s email list. Others should send comments to the TC’s public comment list, after subscribing to it by following the instructions at the “Send A Comment” button on the TC’s web page at https://www.oasis-open.org/committees/cti/. This specification is provided under the Non-Assertion Mode of the OASIS IPR Policy, the mode chosen when the Technical Committee was established. For information on whether any patents have been disclosed that may be essential to implementing this specification, and any offers of patent licensing terms, please refer to the Intellectual Property Rights section of the TC’s web page (https://www.oasis- open.org/committees/cti/ipr.php). Note that any machine-readable content (Computer Language Definitions) declared Normative for this Work Product is provided in separate plain text files.', 'vec_doc-10-oasis-stix21-p2-5', 0, 220, 'v2.1.0', '30f5c09f2aafa9e45b310b0f8f15b2227dd828863574f030d2b890ec87057779', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"UNKNOWN","subsection":"UNKNOWN","table_id":null,"page":2,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":5,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"General Document Content"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p2-6', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', 'UNKNOWN', 2, 'In the event of a discrepancy between any such plain text file and display content in the Work Product’s prose narrative document(s), the content in the separate plain text file prevails. Key words: The key words “MUST”, “MUST NOT”, “REQUIRED”, “SHALL”, “SHALL NOT”, “SHOULD”, “SHOULD NOT”, “RECOMMENDED”, “NOT RECOMMENDED”, “MAY”, and “OPTIONAL” in this document are to be interpreted as described in BCP 14 [RFC2119] [RFC8174] when, and only when, they appear in all capitals, as shown here. Citation format: When referencing this specification the following citation format should be used: [STI-v2.1-errata01] STIX Version 2.1 Errata 01. Edited by Rich Piazza, Emily Ratliff, Stephan Relitz and Christian Studer. 02 April 2025. OASIS Committee Specification Draft 01. https://docs.oasis-open.org/cti/stix/v2.1/stix- v2.1.html. Latest stage: https://docs.oasis-open.org/cti/stix/v2.1/stix-v2.1.html. Notices Copyright © OASIS Open 2025. All Rights Reserved.', 'vec_doc-10-oasis-stix21-p2-6', 0, 240, 'v2.1.0', 'fcc1c45264c0f44a1bed24238cc827485665a3059a6a9836caaff0f60a7a34b2', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"UNKNOWN","subsection":"UNKNOWN","table_id":null,"page":2,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":6,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"General Document Content"}');
