INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p8-57', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '12.7 STIX Patterning Conformance Levels', 8, '12.7.1 Level 1: Basic Conformance 12.7.2 Level 2: Basic Conformance plus Observation Operators 12.7.3 Level 3: Full Conformance Appendix A: Confidence Scales Appendix B: Relationship Summary Table Appendix C: Additional Examples C.1 Infrastructure Additional Examples C.1.1 Malware & Target List Hosting Domain C.1.2 Malware Botnet Infrastructure C.1.3 Related/Component Botnet Infrastructure C.1.4 Malware Instance Hosted on Compromised Domain C.2 Extension Definition Additional Examples C.2.1 Create a new object type with a copyright marking definition C.2.2 Adding properties to an existing STIX object instance C.2.3 Adding properties to an existing STIX relationship object instance C.2.4 Adding properties to an existing STIX marking definition object instance C.2.5 Adding properties to an existing STIX language content object instance Appendix D: IANA Considerations Appendix E: References E.1 Normative References', 'vec_doc-10-oasis-stix21-p8-57', 0, 232, 'v2.1.0', 'e80e2233cb2e0ffb009b277da8d6442aa5811ca93816241c1c471fbeecfbb8a2', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"12.7 STIX Patterning Conformance Levels","subsection":"UNKNOWN","table_id":null,"page":8,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":57,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"12.7 STIX Patterning Conformance Levels"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p10-58', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '1. Introduction', 10, 'Structured Threat Information Expression (STIX) is a language and serialization format used to exchange cyber threat intelligence (CTI). STIX enables organizations to share CTI with one another in a consistent and machine-readable manner, allowing security communities to better understand what computer-based attacks they are most likely to see and to anticipate and/or respond to those attacks faster and more effectively. STIX is designed to improve many different capabilities, such as collaborative threat analysis, automated threat exchange, automated detection and response, and more. The objects and features added for inclusion in STIX 2.1 represent an iterative approach to fulfilling basic consumer and producer requirements for CTI sharing. Objects and properties not included in this version of STIX, but deemed necessary by the community, will be included in future releases.', 'vec_doc-10-oasis-stix21-p10-58', 0, 223, 'v2.1.0', 'b97cec4e9948b65e763c6b9c3f2c4390eb2d0d1eec722251ab7426c2f3cd8d0f', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"1. Introduction","subsection":"UNKNOWN","table_id":null,"page":10,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":58,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"1. Introduction"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p10-59', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '1.1 Document Conventions', 10, 'The following color, font and font style conventions are used in this document: The Consolas font is used for all type names, property names and literals. type names are in red with a light red background – threat-actor property names are in bold style – created_at literals (values) are in blue with a blue background – malicious-activity All relationship types are string literals; therefore, they will also appear in blue with a blue background – related-to In an object’s property table, if a common property is being redefined in some way, then the background is dark grey. All examples in this document are expressed in JSON. They are in mono font, with straight quotes, black text and a light grey background, and using 2-space indentation. JSON examples in this document are representations of JSON objects [RFC8259]. They should not be interpreted as string literals. The ordering of object keys is insignificant. Whitespace before or after JSON structural characters in the examples are insignificant [RFC8259]. Parts of the example may be omitted for conciseness and clarity. These omitted parts are denoted with the ellipses (… ). The term “hyphen” is used throughout this document to refer to the ASCII hyphen or minus character, which in Unicode is “hyphen-minus”, U+002D.', 'vec_doc-10-oasis-stix21-p10-59', 0, 322, 'v2.1.0', 'ce5b2cedfc816771503bb26f1902605d405f2eb84fd5ade0eee47ce52c476ca6', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"1.1 Document Conventions","subsection":"UNKNOWN","table_id":null,"page":10,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":59,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"1.1 Document Conventions"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p10-60', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '1.2 Overview', 10, 'STIX is a schema that defines a taxonomy of cyber threat intelligence that is represented by the following objects: STIX Objects STIX Bundle Object STIX Core Objects STIX Meta Objects (SMO) STIX Domain Objects (SDO) STIX Cyber- observable Objects (SCO) STIX Relationship Objects (SRO) Extension Definition Objects Language Content Objects Marking Definition Objects STIX Core Objects', 'vec_doc-10-oasis-stix21-p10-60', 0, 96, 'v2.1.0', 'dad2703c5514707124f7ebcd7d09283b86c3f4f0599e97f371bafa0fb9e762aa', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"1.2 Overview","subsection":"UNKNOWN","table_id":null,"page":10,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":60,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"1.2 Overview"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p11-61', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '1.2 Overview', 11, 'Standards Track Work Product 02 April 2025 - Page 11 of 276Copyright © OASIS Open 2025. All Rights Reserved. Any SDO, SCO, or SRO. STIX Domain Objects Higher Level Intelligence Objects that represent behaviors and constructs that threat analysts would typically create or work with while understanding the threat landscape. STIX Cyber-observable Objects Objects that represent observed facts about a network or host that may be used and related to higher level intelligence to form a more complete understanding of the threat landscape. STIX Relationship Objects Objects that connect STIX Domain Objects together, STIX Cyber-observable Objects together, and connect STIX Domain Objects and STIX Cyber-observable Objects together to form a more complete understanding of the threat landscape. STIX Meta Objects (SMO) A STIX Object that provides the necessary glue and associated metadata to enrich or extend STIX Core Objects to support user and system workflows.', 'vec_doc-10-oasis-stix21-p11-61', 0, 241, 'v2.1.0', 'f5c743b24915d99b7b74ad214b3fc1637ff65f8f6f393807e4df3855259ba831', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"1.2 Overview","subsection":"UNKNOWN","table_id":null,"page":11,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":61,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"1.2 Overview"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p11-62', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '1.2 Overview', 11, 'STIX Bundle Object An object that provides a wrapper mechanism for packaging arbitrary STIX content together. 1.2.1 Graph-Based Model STIX is a connected graph of nodes and edges. STIX Domain Objects and STIX Cyber-observable Objects define the graph nodes and STIX relationships (including both external STIX Relationship Objects and embedded relationships) define the edges. This graph-based language conforms to common analysis approaches and allows for flexible, modular, structured, and consistent representations of CTI. 1.2.2 STIX Domain Objects STIX defines a set of STIX Domain Objects (SDOs): Attack Pattern, Campaign, Course of Action, Grouping, Identity, Indicator, Infrastructure, Intrusion Set, Location, Malware, Malware Analysis, Note, Observed Data, Opinion, Report, Threat Actor, Tool, and Vulnerability. Each of these objects corresponds to a concept commonly used in CTI. STIX Domain Objects are defined in section 4.', 'vec_doc-10-oasis-stix21-p11-62', 0, 235, 'v2.1.0', '3110003ddccb4281bbaf1b28f224a0879d29d2cf784db8ea3064ebc41585bb04', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"1.2 Overview","subsection":"UNKNOWN","table_id":null,"page":11,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":62,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"1.2 Overview"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p11-63', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '1.2 Overview', 11, '1.2.3 STIX Cyber-observable Objects STIX defines a set of STIX Cyber-observable Objects (SCOs) for characterizing host-based and network- based information. SCOs are used by various STIX Domain Objects (SDOs) to provide supporting context. The Observed Data SDO, for example, indicates that the raw data was observed at a particular time. STIX Cyber-observable Objects (SCOs) document the facts concerning what happened on a network or host, and do not capture the who, when, or why. By associating SCOs with STIX Domain Objects (SDOs), it is possible to convey a higher-level understanding of the threat landscape, and to potentially provide insight as to the who and the why particular intelligence may be relevant to an organization. For example, information about a file that existed, a process that was observed running, or that network traffic occurred between two IPs can all be captured as SCOs. STIX Cyber-observable Objects (SCOs) are defined in section 6.', 'vec_doc-10-oasis-stix21-p11-63', 0, 242, 'v2.1.0', '731e16ed697bae87ffeea87e571d12b5de5b0f37ce1986ef1319d0e972961a29', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"1.2 Overview","subsection":"UNKNOWN","table_id":null,"page":11,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":63,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"1.2 Overview"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p11-64', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '1.2 Overview', 11, 'Previously, in STIX 2.0, Cyber-observable Objects could only exist as objects within an Observed Data object. It is still possible to represent Cyber-observable Objects in this way, but this method has been deprecated. See section 2.13.', 'vec_doc-10-oasis-stix21-p11-64', 0, 59, 'v2.1.0', '22f42359c75378503ab030b155d713175421311ac7a0d726248ca1b1b160bae0', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"1.2 Overview","subsection":"UNKNOWN","table_id":null,"page":11,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":64,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"1.2 Overview"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p12-65', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '1.2 Overview', 12, 'Standards Track Work Product 02 April 2025 - Page 12 of 276Copyright © OASIS Open 2025. All Rights Reserved. 1.2.4 STIX Relationships A relationship is a link between STIX Domain Objects (SDOs), STIX Cyber-observable Objects (SCOs), or between an SDO and a SCO that describes the way in which the objects are related. Relationships can be represented using an external STIX Relationship Object (SRO) or, in some cases, through certain properties which store an identifier reference that comprises an embedded relationship, (for example the created_by_ref property). The generic STIX Relationship Object (SRO) is one of two SROs and is used for most relationships in STIX. This generic SRO contains a property called relationship_type to describe more specifically what the relationship represents. This specification defines a set of known terms to use for the relationship_type property between SDOs of specific types.', 'vec_doc-10-oasis-stix21-p12-65', 0, 230, 'v2.1.0', '03e5b334243d2c0453bed377c3b1e50273bdbb26b24b49dcf6e081d0ea2f7a0a', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"1.2 Overview","subsection":"UNKNOWN","table_id":null,"page":12,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":65,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"1.2 Overview"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p12-66', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '1.2 Overview', 12, 'For example, the Indicator SDO defines a relationship from itself to Malware via a relationship_type of indicates to describe how the Indicator can be used to detect the presence of the corresponding Malware. In addition to the terms defined in the specification, STIX also allows for user-defined terms to be used as the relationship type. Currently the only other SRO (besides a generic Relationship) is the Sighting SRO. The Sighting object is used to capture cases where an entity has “seen” an SDO, such as sighting an indicator. Sighting is a separate SRO because it contains additional properties such as count that are only applicable to Sighting relationships. Other SROs may be defined in future versions of STIX if new relationships are identified that also require additional properties not present on the generic Relationship object. In addition to relationships created using the SROs (Relationship and Sighting), STIX also uses ID references to represent embedded relationships.', 'vec_doc-10-oasis-stix21-p12-66', 0, 249, 'v2.1.0', 'd0a6f7fe28ff31ef9f6187dd70f8dcd8ecd1131d5bd1ce0e734d5b515136021f', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"1.2 Overview","subsection":"UNKNOWN","table_id":null,"page":12,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":66,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"1.2 Overview"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p12-67', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '1.2 Overview', 12, 'Embedded relationships are simply ID reference properties on STIX Objects that contain the ID of a different STIX Object. Embedded relationships are used when the property is an inherent part of the object and not something that a third party might add or something that might require the inclusion of a confidence score. Because they represent an inherent linkage and have no other properties, an SRO is not needed to represent them. An embedded relationship can only be asserted by the creator of the object (“object creator”) it is contained in. For example, the entity that created a STIX Object is an inherent, factual part of that object and therefore that information is captured in an embedded relationship contained in the created_by_ref property rather than through the use of an SRO. Embedded relationships (ID references) are described in section 3.3 and STIX Relationship Objects (SROs) are defined in section 5.', 'vec_doc-10-oasis-stix21-p12-67', 0, 232, 'v2.1.0', '755de612669f5bc6f3e48c8d4b3f890bf016867ab72f77d96a9a4fb3b5c379df', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"1.2 Overview","subsection":"UNKNOWN","table_id":null,"page":12,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":67,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"1.2 Overview"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p12-68', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '1.2 Overview', 12, '1.2.5 STIX Cyber Observable Observed Data Relationships (Deprecated) While refining STIX for the 2.1 specification, the CTI TC reached consensus that the STIX 2.0 Cyber Observable Container (see section 2.13) and the Observed Data object’s graph within a graph model was insufficient to support critical CTI use cases. Consequently, in STIX 2.1, the Cyber Observable Container is deprecated, and implementers are encouraged to use STIX Relationship Objects (SROs) instead. Within the context of the (deprecated) Cyber Observable Container’s graph within a graph model, an object relationship is a reference linking two (or more) related SCOs and these relationships are constrained to SCOs contained within the same Cyber Observable Container. A Cyber Observable Container relationship should not be confused with STIX Relationship Objects (SROs) that are defined in section 5. 1.2.6 STIX Patterning The STIX Patterning language enables the detection of activity on networks and endpoints.', 'vec_doc-10-oasis-stix21-p12-68', 0, 248, 'v2.1.0', 'cf8901a2eb82fb2af344c9df6ea03b5aada671b3e382c835515980a4215accff', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"1.2 Overview","subsection":"UNKNOWN","table_id":null,"page":12,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":68,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"1.2 Overview"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p12-69', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '1.2 Overview', 12, 'This language allows matching against time stamped cyber observable data collected by a threat intelligence platform or other similar system. STIX Patterning is currently only used by the STIX Indicator object, but it can be employed in other use cases. Before undertaking work on STIX Patterning, a thorough effort to evaluate existing patterning languages (e.g., Snort or Yara) was performed. This effort identified that no existing patterning language solves or supports the STIX use cases. Extending other languages was ruled out as unfeasible, both from a', 'vec_doc-10-oasis-stix21-p12-69', 0, 140, 'v2.1.0', '8c7338da028e5a8cdcc0103a61d93117df6288797168899f065810a9260f6367', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"1.2 Overview","subsection":"UNKNOWN","table_id":null,"page":12,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":69,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"1.2 Overview"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p13-70', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '1.2 Overview', 13, 'Standards Track Work Product 02 April 2025 - Page 13 of 276Copyright © OASIS Open 2025. All Rights Reserved. technical perspective as well as taking into consideration that from a licensing/IPR perspective, extending an existing language under the auspices of OASIS would have been problematic. STIX Patterning was primarily designed to support STIX Indicators. As such it is a mechanism for communicating how to find malicious code and/or threat actors active within a given network or endpoint. This language release is focused on supporting a common set of use cases and therefore allows for the expression of an initial set of patterns that producers and consumers of STIX can utilize. As more complex patterns are deemed necessary, the STIX patterning language will be extended in future releases to improve its effectiveness as an automated detection/remediation method. STIX Patterning is defined in section 9.', 'vec_doc-10-oasis-stix21-p13-70', 0, 230, 'v2.1.0', '60f89d8fbd71dae89f3023385e615587b9a399d0d75e1ba1a1954c6b66e0f0a2', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"1.2 Overview","subsection":"UNKNOWN","table_id":null,"page":13,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":70,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"1.2 Overview"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p13-71', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '1.2 Overview', 13, '1.2.7 STIX Common Properties STIX Domain Objects (SDOs) and Relationship Objects (SROs) all share a common set of properties which provide core capabilities such as versioning and data markings (representing how data can be shared and used). All STIX Cyber-observable Objects (SCOs) likewise share a common set of properties that are applicable for all SCOs. Similarly, STIX Meta Objects (SMOs) use some but not all of the common properties. 1.2.8 STIX Open Vocabularies and Enumerations Some STIX properties are defined using open vocabularies or enumerations. Enumerations and open vocabularies are defined in STIX in order to enhance interoperability by increasing the likelihood that different entities use the same exact string to represent the same concept. If used consistently, open vocabularies make it less likely that one entity refers to the energy sector as “Energy” and another as “Energy Sector”, thereby making comparison and correlation easier.', 'vec_doc-10-oasis-stix21-p13-71', 0, 241, 'v2.1.0', '7f9ded6b069e8f890f7f5c5e7a58e96290391059556a9e91ddb7be209481d288', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"1.2 Overview","subsection":"UNKNOWN","table_id":null,"page":13,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":71,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"1.2 Overview"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p13-72', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '1.2 Overview', 13, 'While using predefined values from STIX vocabularies is strongly encouraged, in some cases this may not be feasible. To address this, producers are permitted to use values outside of the open vocabulary. Inthe case of enumerations, producers are required to use only the values defined within the STIX specification. STIX open vocabularies and enumerations are defined in section 10. Properties that are defined as open vocabularies identify a suggested vocabulary from that section. For example, the Threat Actor sophistication property, as defined in section 4.17, uses the Threat Actor Sophistication vocabulary as defined in section 10.25. 1.2.9 Reserved Names Reserved property names are marked with a type called RESERVED and a description text of “RESERVED FOR FUTURE USE”. For more information please see section 3.8 1.2.10 Serialization STIX is defined independent of any specific storage or serialization.', 'vec_doc-10-oasis-stix21-p13-72', 0, 229, 'v2.1.0', '7af7e6b066523b3e65fa4c2bc16f9b1c309e01d0b667de3845c3e1e8e3826f23', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"1.2 Overview","subsection":"UNKNOWN","table_id":null,"page":13,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":72,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"1.2 Overview"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p13-73', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '1.2 Overview', 13, 'However, the mandatory-to- implement (MTI) serialization for STIX 2.1 is UTF-8 encoded JSON as defined in RFC7493 and RFC8259, which uses the JSON Object type described within when representing all STIX Objects. In other words, all STIX-conformant tools have to implement support for JSON but can implement support for other serializations. 1.2.11 Transporting STIX STIX 2.1 is transport-agnostic, i.e., the structures and serializations do not rely on any specific transport mechanism. A companion CTI specification, TAXII, is designed specifically to transport STIX Objects. STIX provides a Bundle (see section 8) as a container for STIX Objects to allow for transportation of bulk STIX data, especially over non-TAXII communication mechanisms.', 'vec_doc-10-oasis-stix21-p13-73', 0, 187, 'v2.1.0', '9de51be3ab0633b6e35729ca4d4e05d046d6a67b2740c31ddf699ca5aeb7c620', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"1.2 Overview","subsection":"UNKNOWN","table_id":null,"page":13,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":73,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"1.2 Overview"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p14-74', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '1.2 Overview', 14, 'Standards Track Work Product 02 April 2025 - Page 14 of 276Copyright © OASIS Open 2025. All Rights Reserved. 1.2.12 JSON Schemas JSON schemas have been developed by members of the Cyber Threat Intelligence Technical Committee. The JSON schemas are informative and serve as a best effort attempt to validate that STIX 2.1 content meets the structural requirements identified in this specification. This specification is the normative description of STIX 2.1.', 'vec_doc-10-oasis-stix21-p14-74', 0, 115, 'v2.1.0', '3c4a8e53d2bc3119dc16ad44e54fa2ca1bee9068514f1418c1e94e2611a11d15', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"1.2 Overview","subsection":"UNKNOWN","table_id":null,"page":14,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":74,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"1.2 Overview"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p14-75', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '1.3 Changes From Earlier Version', 14, 'This section lists all of the changes from the previous 2.1 version of STIX. 1.3.1 STIX 2.1 Errata 01 Changes From Earlier Version STIX 2.1 Errata 01 differs from STIX 2.1 in the following ways: Updated Malware Embedded Relationships table with missing property in section 4.11.2. operating_system_refs is no longer missing in the table. Malware Analysis Relationships table fixed with the right relationship type between Malware Analysis and Malware in section 4.12.2. wrong analysis-of is replaced with the right av-analysis-of relationship type. Email Message property descriptions fixed in section 6.6.1. from_ref, sender_ref, to_refs, cc_refs and bcc_refs properties descriptions now mention the right email-addr type they are referencing. HTTP Request Extension examples fixed in section 6.12.2.1. the request_header property is now a list of type string in the examples, as expected from the description. Observation Expression Qualifiers example fixed in section 9.5.1.', 'vec_doc-10-oasis-stix21-p14-75', 0, 245, 'v2.1.0', '8d2bdd1b93bee90c8a6cf20a9f7cd6542da306c2325e38a5ee73633b9842e627', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"1.3 Changes From Earlier Version","subsection":"UNKNOWN","table_id":null,"page":14,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":75,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"1.3 Changes From Earlier Version"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p14-76', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '1.3 Changes From Earlier Version', 14, 'the example used to illustrate the use of Observation Expression WITHIN x SECONDS now has the right windows-registry-key Observable type. Updated Implementation Language Vocabulary in section 10.9. rust value was added. Updated Industry Sector Vocabulary in section 10.11. legal value was added. Fixed Infrastructure Type Vocabulary Summary in section 10.12. missing control-system, firewall, routers-switches and workstation values were added to the Summary as they were already described in the Vocabulary table. Enhanced Malware Result Vocabulary in section 10.14. descriptions for every vocabulary values were improved with more descriptive definitions. Fixed Report Type Vocabulary in section 10.22. missing incident value was added. Updated Threat Actor Type Vocabulary in section 10.23. private-sector value was added.', 'vec_doc-10-oasis-stix21-p14-76', 0, 207, 'v2.1.0', 'c749ffb6527340255b2b85953a5ff3c0efea10c484db2c8951467112b53999e0', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"1.3 Changes From Earlier Version","subsection":"UNKNOWN","table_id":null,"page":14,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":76,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"1.3 Changes From Earlier Version"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p14-77', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '1.3 Changes From Earlier Version', 14, 'Fixed multiple Enumeration headers Enumerations now have the right headers, to differenciate enumerations from vocabularies, including: Enumeration Name is now used instead of Vocabulary Name Enumeration Summary is now used instead of Vocabulary Summary Enumeration Value is now used instead of Vocabulary Value These changes apply on: Encryption Algorithm Enumeration in section 10.4 Extension Type Enumeration in section 10.5 Network Socket Address Family Enumeration in section 10.16 Network Socket Type Enumeration in section 10.17 Opinion Enumeration in section 10.18 Windows™ Integrity Level Enumeration in section 10.27 Windows™ Registry Datatype Enumeration in section 10.29 Windows™ Service Start Type Enumeration in section 10.30 Windows™ Service Type Enumeration in section 10.31 Windows™ Service Status Enumeration in section 10.32', 'vec_doc-10-oasis-stix21-p14-77', 0, 211, 'v2.1.0', '8868a6d964f9755b7691e5a7d7b8fa8e223875d58a0bea28c59ee1757b96f7ae', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"1.3 Changes From Earlier Version","subsection":"UNKNOWN","table_id":null,"page":14,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":77,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"1.3 Changes From Earlier Version"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p15-78', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '1.3 Changes From Earlier Version', 15, 'Standards Track Work Product 02 April 2025 - Page 15 of 276Copyright © OASIS Open 2025. All Rights Reserved. Relationship Summary Table has been update in Appendix B. Duplicated relationship located-at between threat-actor and location has been removed. Misspelled relationship exfiltrates-to between malware and infrastructure has been fixed. Missing relationships have been added, including: remediates between course-of-action and malware remediates between course-of-action and vulnerability uses between tool and infrastructure resolves-to between domain-name and domain-name resolves-to between domain-name and ipv4-addr resolves-to between domain-name and ipv6-addr resolves-to between ipv4-addr and mac-addr belongs-to between ipv6-addr and autonomous-system resolves-to between ipv4-addr and mac-addr belongs-to between ipv6-addr and autonomous-system Fixed typos in Extension Definition Additional Examples typos were fixed in titles for section C.2.2 and section C.2.3. Special characters were fixed in some participants names in Appendix F. All SCO ids were updated in examples to agree with the generate_id method in python-stix2 library. Included all changes based on ITU recommandations. Improved references through the document. missing references to sections were added at different places. some references were fixed to point to the right section. in the description of STIX object properties whose value is either a vocabulary or an enumeration, a reference poiting to the given vocabulary or enumeration was added.', 'vec_doc-10-oasis-stix21-p15-78', 0, 384, 'v2.1.0', '9f35857b77f0c9b780aec9061073702d9fa9b380b4c408e12df6bfe5cd7cdd4d', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"1.3 Changes From Earlier Version","subsection":"UNKNOWN","table_id":null,"page":15,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":78,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"1.3 Changes From Earlier Version"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p15-79', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '1.4 Glossary', 15, 'AV - Anti-Virus / Anti-Malware solution CAPEC - Common Attack Pattern Enumeration and Classification Consumer - Any entity that receives STIX content CTI - Cyber Threat Intelligence Deprecated - STIX features or properties that are in the process of being replaced by newer ones. Embedded Relationship - A link (an “edge” in a graph) between one STIX Object and another represented as a property on one object containing the ID of another object Entity - Anything that has a separately identifiable existence (e.g., organization, person, group, etc.) IEP - FIRST (Forum of Incident Response and Security Teams) Information Exchange Policy Instance - A single occurrence of a STIX Object version# MTI - Mandatory To Implement Object Creator - The entity that created or updated a STIX Object (see section 3.5) Object Representation - An instance of an object version that is serialized as STIX Producer - Any entity that distributes STIX content, including object creators as well as those passing along existing content SCO - STIX Cyber-observable Object', 'vec_doc-10-oasis-stix21-p15-79', 0, 264, 'v2.1.0', 'e8131ce83e6f7186155ac9128783d7801af160e9657430e8f3a02780bfad13cd', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"1.4 Glossary","subsection":"UNKNOWN","table_id":null,"page":15,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":79,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"1.4 Glossary"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p16-80', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '1.4 Glossary', 16, 'Standards Track Work Product 02 April 2025 - Page 16 of 276Copyright © OASIS Open 2025. All Rights Reserved. SDO - STIX Domain Object (a “node” in a graph) SMO - STIX Meta Object SRO - STIX Relationship Object (one mechanism to represent an “edge” in a graph) STIX - Structured Threat Information Expression STIX Content - STIX documents, including STIX Objects, STIX Objects grouped as bundles, etc. STIX Object - A STIX Domain Object (SDO), STIX Cyber Observable Object (SCO), STIX Relationship Object (SRO), or STIX Meta Object (SMO). STIX Relationship - A link (an “edge” in a graph) between two STIX Objects represented by either an SRO or an embedded relationship STIX Extension - A set of mechanisms supporting adding new objects and updating existing objects in a standard way. TAXII - An application layer protocol for the communication of cyber threat information TLP - Traffic Light Protocol TTP - Tactic, technique, or procedure; behaviors and resources that attackers use to carry out their attacks', 'vec_doc-10-oasis-stix21-p16-80', 0, 253, 'v2.1.0', 'd9ca6536b77cb235be74c6c997e68aea1dfd146e6b21605525e92e126651a3bf', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"1.4 Glossary","subsection":"UNKNOWN","table_id":null,"page":16,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":80,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"1.4 Glossary"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p17-81', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '2. Common Data Types', 17, 'This section defines the common types used throughout STIX for all STIX Objects. These types will be referenced by the “Type” column in other sections. This section defines the names and permitted values of common types that are used in the STIX information model; it does not, however, define the meaning of any properties using these types. These types may be further restricted elsewhere in the document. The table below is a summary of the data types defined in this section. Type Description binary A sequence of bytes. boolean A value of true or false. dictionary A set of key/value pairs. enum A value from a STIX Enumeration. external-reference A non-STIX identifier or reference to other related external content. float An IEEE 754 [IEEE 754-2008] double-precision number. hashes One or more cryptographic hashes. hex An array of octets as hexadecimal. identifier An identifier (ID) is for STIX Objects. integer A whole number. kill-chain-phase A name and a phase of a kill chain. list A sequence of values ordered based on how they appear in the list. The phrasing “list of type <type>” is used to indicate that all values within the list MUST conform to the specified type. observable-container One or more STIX Cyber-observable Objects in the deprecated Cyber Observable Container. open-vocab A value from a STIX open (open-vocab) or suggested vocabulary. string A series of Unicode characters. timestamp A time value (date and time).', 'vec_doc-10-oasis-stix21-p17-81', 0, 362, 'v2.1.0', 'ce86d7bafc52e2d21756c0b47db07e8d669ffd4b5ca7d417b63263b11aebe4a3', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"2. Common Data Types","subsection":"UNKNOWN","table_id":null,"page":17,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":81,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"2. Common Data Types"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p18-82', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '2.1 Binary', 18, 'Standards Track Work Product 02 April 2025 - Page 18 of 276Copyright © OASIS Open 2025. All Rights Reserved. The binary data type represents a sequence of bytes. In order to allow pattern matching on custom objects, for all properties that use the binary type, the property name MUST end with _bin. The JSON MTI serialization represents this as a base64- encoded string as specified in [RFC4648] . Other serializations SHOULD use a native binary type, if available.', 'vec_doc-10-oasis-stix21-p18-82', 0, 117, 'v2.1.0', 'b9cc8d12380e625f5cc5bfbd245261ed1d8cf5017d30a5b02c3d500eb451150d', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"2.1 Binary","subsection":"UNKNOWN","table_id":null,"page":18,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":82,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"2.1 Binary"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p18-83', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '2.2 Boolean', 18, 'Type Name: boolean A boolean is a value of either true or false. Properties with this type MUST have a value of true or false. The JSON MTI serialization uses the true and false (boolean) values from the JSON values [RFC8259], which are a literal (unquoted) true or false. Example { ... "summary": true, ... }', 'vec_doc-10-oasis-stix21-p18-83', 0, 78, 'v2.1.0', 'ff2fe63b5fa1493888382878d9343dd271a89e0e06e6626acc2c767d06aeebd4', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"2.2 Boolean","subsection":"UNKNOWN","table_id":null,"page":18,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":83,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"2.2 Boolean"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p18-84', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '2.3 Dictionary', 18, 'Type Name: dictionary A dictionary captures an arbitrary set of key/value pairs. Dictionary keys MUST be unique in each dictionary, MUST be in ASCII, and are limited to the characters a-z (lowercase ASCII), A-Z (uppercase ASCII), numerals 0-9, hyphen (-), and underscore (_). Dictionary keys MUST be no longer than 250 ASCII characters in length and SHOULD be lowercase. Empty dictionaries are prohibited in STIX and MUST NOT be used as a substitute for omitting the property if it is optional. If the property is required, the dictionary MUST be present and MUST have at least one key-value pair. dictionary values MUST be valid property base types', 'vec_doc-10-oasis-stix21-p18-84', 0, 163, 'v2.1.0', 'b375c85dc67c9fe465c4adef98eea25e7821a4ca3911580357d5c252753e5019', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"2.3 Dictionary","subsection":"UNKNOWN","table_id":null,"page":18,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":84,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"2.3 Dictionary"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p18-85', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '2.4 Enum', 18, 'Type Name: enum The enum type is a hardcoded list of terms that is represented as a string. For properties that use this type there is a defined list of values that is identified in the definition for said properties. The STIX Enumerations are defined in section 10. Terms defined in an enum by the specification MUST NOT be expanded by implementations. The JSON MTI serialization uses the JSON String type [RFC8259] when representing enum enumeration.', 'vec_doc-10-oasis-stix21-p18-85', 0, 113, 'v2.1.0', '131d74ce3b5a731446de586dfacea4bb5332ee28d97dfca967a4f92b38bd84db', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"2.4 Enum","subsection":"UNKNOWN","table_id":null,"page":18,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":85,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"2.4 Enum"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p18-86', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '2.5 External Reference', 18, 'Type Name: external-reference External references are used to describe pointers to information represented outside of STIX. For example, a Malware object could use an external reference to indicate an ID for that malware in an external database or a report could use references to represent source material.', 'vec_doc-10-oasis-stix21-p18-86', 0, 77, 'v2.1.0', '138c55a80905235c452d7638e77d648bc4f162634a3347faa38b773283b6d3fc', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"2.5 External Reference","subsection":"UNKNOWN","table_id":null,"page":18,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":86,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"2.5 External Reference"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p19-87', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '2.5 External Reference', 19, 'Standards Track Work Product 02 April 2025 - Page 19 of 276Copyright © OASIS Open 2025. All Rights Reserved. The JSON MTI serialization uses the JSON Object type [RFC8259] when representing external- reference. 2.5.1 Properties Property Name Type Description source_name (required) string The name of the source that the external-reference is defined within (system, registry,organization, etc.). description (optional) string A human readable description. url (optional) string A URL reference to an external resource [RFC3986] hashes (optional) hashes Specifies a dictionary of hashes for the contents of the url. This SHOULD be provided when the url property is present. Dictionary keys MUST come from one of the entries listed in the hash-algorithm-ov open vocabulary. As stated in section 2.7, to ensure interoperability, a SHA- 256 hash SHOULD be included when possible. external_id (optional) string An identifier for the external reference content. 2.5.2 Requirements In addition to the source_name property, at least one of the description, url or external_id properties MUST be present. Examples An external-reference to a VERIS Community Database (VCDB) [VERIS] entry { ... "external_references": [ { "source_name": "veris", "external_id": "0001AA7F-C601-424A-B2B8-BE6C9F5164E7", "url": "https://github.com/vz- risk/VCDB/blob/125307638178efddd3ecfe2c267ea434667a4eea/data/json/validated/0001AA7F-C601- 424A-B2B8-BE6C9F5164E7.json", "hashes": { "SHA-256": "6db12788c37247f2316052e142f42f4b259d6561751e5f401a1ae2a6df9c674b" } } ],', 'vec_doc-10-oasis-stix21-p19-87', 0, 385, 'v2.1.0', 'caface3f227523290e0ef7f5eb324512b457180c3fac4f0447301009694cbfb7', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"2.5 External Reference","subsection":"UNKNOWN","table_id":null,"page":19,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":87,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"2.5 External Reference"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p20-88', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '2.5 External Reference', 20, 'Standards Track Work Product 02 April 2025 - Page 20 of 276Copyright © OASIS Open 2025. All Rights Reserved. ... } An external-reference from the CAPEC™ [CAPEC] repository { ... "external_references": [ { "source_name": "capec", "external_id": "CAPEC-550" } ], ... } An external-reference from the CAPEC repository with URL { ... "external_references": [ { "source_name": "capec", "external_id": "CAPEC-550", "url": "http://capec.mitre.org/data/definitions/550.html" } ], ... } An external-reference to ACME Threat Intel’s report document { ... "external_references": [ { "source_name": "ACME Threat Intel", "description": "Threat report", "url": "http://intelreport.mandiant.com/Mandiant_APT1_Report.pdf" } ], ... } An external-reference to a Bugzilla item { ... "external_references": [ { "source_name": "ACME Bugzilla",', 'vec_doc-10-oasis-stix21-p20-88', 0, 206, 'v2.1.0', 'c07de3999fa4ae8c1bc5d922d3fac56ced10d56ca27d3771bd27b53079c3d07a', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"2.5 External Reference","subsection":"UNKNOWN","table_id":null,"page":20,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":88,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"2.5 External Reference"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p21-89', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '2.5 External Reference', 21, 'Standards Track Work Product 02 April 2025 - Page 21 of 276Copyright © OASIS Open 2025. All Rights Reserved. "external_id": "1370", "url": "https://issues.oasis-open.org/browse/TAB-1370" } ], ... } An external-reference to an offline threat report (i.e., e-mailed, offline, etc.) { ... "external_references": [ { "source_name": "ACME Threat Intel", "description": "Threat report" } ], ... }', 'vec_doc-10-oasis-stix21-p21-89', 0, 98, 'v2.1.0', '6435cf3d065f5b716359052ce64d9b34bec6919cb3dfb7f6c948b5bc58a9f0e3', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"2.5 External Reference","subsection":"UNKNOWN","table_id":null,"page":21,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":89,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"2.5 External Reference"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p21-90', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '2.6 Float', 21, 'Type Name: float The float data type represents an IEEE 754 [IEEE 754-2008] double-precision number (e.g., a number with a fractional part). However, because the values ±Infinity and NaN are not representable in JSON, they are not valid values in STIX. In the JSON MTI serialization, floating point values are represented by the JSON Number type [RFC7493]. Example { ... "distance": 8.321, ... }', 'vec_doc-10-oasis-stix21-p21-90', 0, 99, 'v2.1.0', '88011dbd5b9bf0e97a7eb67f5c45817884c555e9fda509c1fc022da5a1c2e239', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"2.6 Float","subsection":"UNKNOWN","table_id":null,"page":21,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":90,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"2.6 Float"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p21-91', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '2.7 Hashes', 21, 'Type Name: hashes The Hashes type represents one or more cryptographic hashes, as a special set of key/value pairs. Accordingly, the name of each hashing algorithm MUST be specified as a key in the dictionary and MUST identify the name of the hashing algorithm used to generate the corresponding value. This name SHOULD come from one of the values defined in the hash-algorithm-ov open vocabulary. Dictionary keys MUST be unique in each hashes property, MUST be in ASCII, and are limited to the characters a-z (lowercase ASCII), A-Z (uppercase ASCII), numerals 0-9, hyphen (-), and underscore (_). Dictionary keys MUST have a minimum length of 3 ASCII characters and MUST be no longer than 250 ASCII characters in length. The value MUST be a string in the appropriate format defined by the hashtype indicated in the dictionary key. To enhance compatibility, the SHA-256 hash SHOULD be used whenever possible. Example', 'vec_doc-10-oasis-stix21-p21-91', 0, 229, 'v2.1.0', '6c9fc063f4f9d4dd30dc8624472e5efcf25bbbf7dc2938097bb969995a30c375', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"2.7 Hashes","subsection":"UNKNOWN","table_id":null,"page":21,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":91,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"2.7 Hashes"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p22-92', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '2.8 Hexadecimal', 22, 'Type Name: hex The hex data type encodes an array of octets (8-bit bytes) as hexadecimal. The string MUST consist of an even number of hexadecimal characters, which are the digits ‘0’ through ‘9’ and the lower-case letters ‘a’ through ‘f’. In order to allow pattern matching on custom objects, for all properties that use the hex type, the property name MUST end with ‘_hex’. Example { ... "src_flags_hex": "00000002" ... }', 'vec_doc-10-oasis-stix21-p22-92', 0, 106, 'v2.1.0', 'b7e6215edce660cc24a5adbfd76327b28ed228e24dccaccc220e4086e7e0f5b5', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"2.8 Hexadecimal","subsection":"UNKNOWN","table_id":null,"page":22,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":92,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"2.8 Hexadecimal"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p22-93', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '2.9 Identifier', 22, 'Type Name: identifier An identifier uniquely identifies a STIX Object and MAY do so in a deterministic way. A deterministic identifier means that the identifier generated by more than one producer for the exact same STIX Object using the same namespace, “ID Contributing Properties”, and UUID method will have the exact same identifier value. All identifiers, excluding those used in the deprecated Cyber Observable Container, MUST follow the form object-type–UUID, where object-type is the exact value (all type names are lowercase strings, by definition) from the type property of the object being identified or referenced and where the UUID MUST be an RFC 4122-compliant UUID [RFC4122]. The UUID part of the identifier MUST be unique across all objects produced by a given producer regardless of the type identified by the object-type prefix. Meaning, a producer MUST NOT reuse the UUID portion of the identifier for objects of different types.', 'vec_doc-10-oasis-stix21-p22-93', 0, 237, 'v2.1.0', '9a741bbf7ad8162edfc39323734a5a81312637bff9bb3e1694763ffab1504673', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"2.9 Identifier","subsection":"UNKNOWN","table_id":null,"page":22,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":93,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"2.9 Identifier"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p22-94', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '2.9 Identifier', 22, 'STIX Domain Objects, STIX Relationship Objects, STIX Meta Objects, and STIX Bundle Object SHOULD use UUIDv4 for the UUID portion of the identifier. Producers using something other than UUIDv4 need to be mindful of potential collisions and should use a namespace that guarantees uniqueness, however, they MUST NOT use a namespace of 00abedb4-aa42-466c-9c01-fed23315a9b7 if generating a UUIDv5. STIX Cyber-observable Objects SHOULD use UUIDv5 for the UUID portion of the identifier and the UUID portion of the UUIDv5-based identifier SHOULD be generated according to the following rules: - The namespace SHOULD be 00abedb4-aa42-466c-9c01-fed23315a9b7. This defined namespace is necessary to support the goal of deduplication and semantic equivalence of some STIX objects in the community of producers.', 'vec_doc-10-oasis-stix21-p22-94', 0, 200, 'v2.1.0', '4109e4471561bce10b0fadedd105e0fd9ab085c26fc5e95c3d08c21ae649ada0', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"2.9 Identifier","subsection":"UNKNOWN","table_id":null,"page":22,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":94,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"2.9 Identifier"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p22-95', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '2.9 Identifier', 22, '- The value of the name portion SHOULD be the list of “ID Contributing Properties” (property-name and property value pairs) as defined on each SCO object and SHOULD be represented as a JSON object that is then serialized / stringified according to [RFC8785] to ensure a canonical representation of the JSON data. - If the contributing properties are all optional, and none are present on the SCO, then a UUIDv4 MUST be used. - Producers not following these rules', 'vec_doc-10-oasis-stix21-p22-95', 0, 116, 'v2.1.0', '0173d8cfb473cc81a6f75b74f8a1125120db7b62a787c531c53c6db058525806', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"2.9 Identifier","subsection":"UNKNOWN","table_id":null,"page":22,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":95,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"2.9 Identifier"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p23-96', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '2.9 Identifier', 23, 'Standards Track Work Product 02 April 2025 - Page 23 of 276Copyright © OASIS Open 2025. All Rights Reserved. MUST NOT use a namespace of 00abedb4-aa42-466c-9c01-fed23315a9b7 and SHOULD use UUIDv4 in cases where the id would not be unique. STIX Cyber-observable Objects that are used in the deprecated Cyber Observable Container MAY use any string value for the identifier. For the deprecated Cyber Observable Container, it is common for implementers to use simple numerical strings for these identifiers (e.g., “0”, “1”, “2”, etc.). See', 'vec_doc-10-oasis-stix21-p23-96', 0, 134, 'v2.1.0', 'cf357d277bf9060e28cb6cc407c99c9faf8404b5510ee92ff6f509673bc3dc64', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"2.9 Identifier","subsection":"UNKNOWN","table_id":null,"page":23,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":96,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"2.9 Identifier"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p23-97', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', 'section 2.13 for more information.', 23, 'These identifiers, when used inside the deprecated Cyber-observable Objects Container specify a local reference to a Cyber-observable Object. These references MUST be valid within the local scope of the Cyber Observable Container (observable-container) that holds both the source Cyber-observable Object and the Cyber-observable Object that it references. These identifiers SHOULD be a non-negative monotonically increasing integer, incrementing by 1from a starting value of 0, and represented as a string within the JSON MTI serialization. However, implementers MAY elect to use an alternate key format if necessary. Using Identifiers: Consumers of STIX Cyber Threat Intelligence that are processing the objects property of an Observed- Data object can assume that the identifier is an old deprecated Cyber Observable Container identifier.', 'vec_doc-10-oasis-stix21-p23-97', 0, 210, 'v2.1.0', '3f95519c239cbcff71e278e17de230dd5f6d988d75085ea88e9b30901e564eeb', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"section 2.13 for more information.","subsection":"UNKNOWN","table_id":null,"page":23,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":97,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"section 2.13 for more information."}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p23-98', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', 'section 2.13 for more information.', 23, 'Consumers can also inspect the identifier to see if it contains an object-type, if not, they can assume that it is a deprecated Cyber Observable Container identifier. If it does have an object-type and it matches a SCO, then chances are it is a UUIDv5 deterministic identifier, but this can be verified by inspecting the UUID portion of the identifier. [RFC4122] defines how one can distinguish between a UUIDv4 and UUIDv5 value. NOTE: Please see the security considerations section in Appendix D for information about using UUIDv5. The JSON MTI serialization uses the JSON String type [RFC8259] when representing identifier. Examples { ... "type": "indicator", "id": "indicator--e2e1a340-4415-4ba8-9671-f7343fbf0836", ... } { "type": "ipv4-addr", "id": "ipv4-addr--28bb3599-77cd-5a82-a950-b5bc3caf07c4", "value": "198.51.100.3" } Deprecated Cyber Observable Container Identifiers { "0": { "type": "ipv4-addr", "value": "198.51.100.2" }, "1": { "type": "network-traffic", "dst_ref": "0" } }', 'vec_doc-10-oasis-stix21-p23-98', 0, 248, 'v2.1.0', '2fad98b5f8ab0e02d9169487ece903d0eb5ce8001324f3f907652fb3d56c4b68', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"section 2.13 for more information.","subsection":"UNKNOWN","table_id":null,"page":23,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":98,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"section 2.13 for more information."}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p24-99', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '2.10 Integer', 24, 'Type Name: integer The integer data type represents a whole number. Unless otherwise specified, all integers MUST be capable of being represented as a signed 54-bit value ([-(2**53)+1, (2**53)-1]) as defined in [RFC7493]. Additional restrictions MAY be placed on the type as described where it is used. The integer size is limited to a 54-bit value not a 64-bit value as per the RFC. In the JSON MTI serialization, integers are represented by the JSON Number type [RFC7493]. Example { ... "count": 8, ... }', 'vec_doc-10-oasis-stix21-p24-99', 0, 127, 'v2.1.0', '1eaf0fa6f368612ecc7c0ed78bbb5877887b9a589f9af4b47437cc88eae6e496', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"2.10 Integer","subsection":"UNKNOWN","table_id":null,"page":24,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":99,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"2.10 Integer"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p24-100', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '2.11 Kill Chain Phase', 24, 'Type Name: kill-chain-phase The kill-chain-phase represents a phase in a kill chain, which describes the various phases an attacker may undertake in order to achieve their objectives. The JSON MTI serialization uses the JSON Object type [RFC8259] when representing kill-chain- phase. Property Name Type Description kill_chain_name (required) string The name of the kill chain. The value of this property SHOULD be all lowercase and SHOULD use hyphens instead of spaces or underscores as word separators. phase_name (required) string The name of the phase in the kill chain. The value of this property SHOULD be all lowercase and SHOULD use hyphens instead of spaces or underscores as word separators. When referencing a kill chain, the kill_chain_name property MUST be the name of that kill chain. Examples Example specifying the “reconnaissance” phase from the Lockheed Martin Cyber Kill Chain { ... "kill_chain_phases": [ { "kill_chain_name": "lockheed-martin-cyber-kill-chain", "phase_name": "reconnaissance" } ], ... } Example specifying the “pre-attack” phase from the “foo” kill-chain', 'vec_doc-10-oasis-stix21-p24-100', 0, 273, 'v2.1.0', '079cad85e4319bf8e269f1516a19fad6f45e5f618c103cbec13c613293f35f65', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"2.11 Kill Chain Phase","subsection":"UNKNOWN","table_id":null,"page":24,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":100,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"2.11 Kill Chain Phase"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p25-101', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '2.12 List', 25, 'Type Name: list The list type defines a sequence of values ordered based on how they appear in the list. The phrasing “list of type <type>” is used to indicate that all values within the list MUST conform to the specified type. For instance, list of type integer means that all values of the list must be of the integer type. This specification does not specify the maximum number of allowed values in a list; however, every instance of a list MUST have at least one value. Specific STIX Object properties may define more restrictive upper and/or lower bounds for the length of the list. Empty lists are prohibited in STIX and MUST NOT be used as a substitute for omitting the property if it is optional. If the property is required, the list MUST be present and MUST have at least one value. The JSON MTI serialization uses the JSON Array type [RFC8259], which is an ordered list of zero or more values. Example { ... "observed_data_refs": [ "observed-data--b67d30ff-02ac-498a-92f9-32f845f448cf", "observed-data--c96f4120-2b4b-47c3-b61f-eceaa54bd9c6", "observed-data--787710c9-1988-4a1b-9761-a2de5e19c62f" ], ... }', 'vec_doc-10-oasis-stix21-p25-101', 0, 279, 'v2.1.0', '2f0f1347f85a56a722b256d6c82609166cd6fff554e569bf19d4b609f13e7738', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"2.12 List","subsection":"UNKNOWN","table_id":null,"page":25,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":101,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"2.12 List"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p25-102', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '2.13 Observable Container (deprecated)', 25, 'Type Name: observable-container Representing Cyber-observable Objects in an Observable Container has been deprecated and SHOULD NOT be used when creating new content. Existing Observable Data objects using Observable Containers may contain SCOs as defined in this specification, but also may contain Cyber-observable Objects as described in version 2.0 of STIX (STIX Version 2.0. Part 3: STIX Objects). The Observable Container type can contain one or more STIX Cyber-observable Objects as a special set of key/value pairs. The keys in the dictionary are the references used to refer to an object which is located in the observable container as a value to some key. The value of this “key” is a reference that can be used in the embedded relationship properties in other objects, which MUST be in the same container (such as the src_ref property on the Network Traffic object). Resolving a reference is the process of identifying all of the objects in an observable container by their “key” reference value. References resolve to an object when the value of the property (e.g., src_ref) is an exact match with the key of another object that resides in the same container as the object that specifies the reference. All such references are local to the container and the referenced object MUST be provided', 'vec_doc-10-oasis-stix21-p25-102', 0, 326, 'v2.1.0', '36358af356a6096490ea3ae2b195e458f210bb8db08907513372a009c2951c0b', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"2.13 Observable Container (deprecated)","subsection":"UNKNOWN","table_id":null,"page":25,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":102,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"2.13 Observable Container (deprecated)"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p26-103', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '2.13 Observable Container (deprecated)', 26, 'Standards Track Work Product 02 April 2025 - Page 26 of 276Copyright © OASIS Open 2025. All Rights Reserved. within the same container. This specification does not address the implementation of reference resolution. Each key in the observable container dictionary is an identifier. STIX 2.0 Example Network Traffic with Source/Destination IPv4 Addresses and AS { "0": { "type": "ipv4-addr", "value": "1.2.3.4", "belongs_to_refs": ["3"] }, "1": { "type": "ipv4-addr", "value": "2.3.4.5" }, "2": { "type": "network-traffic", "src_ref": "0", "dst_ref": "1", } "3": { "type": "as" "number": 42 } } Email Message with Source/Destination Email Addresses { "0": { "type": "email-addr", "value": "jdoe@example.com", "display_name": "John Doe" }, "1": { "type": "email-addr", "value": "mary@example.com", "display_name": "Mary Smith" }, "2": { "type": "email-message", "from_ref": "0", "to_refs": ["1"], "date": "1997-11-21T15:55:06Z", "subject": "Saying Hello" } }', 'vec_doc-10-oasis-stix21-p26-103', 0, 239, 'v2.1.0', '7ea3fe7a322d571c77a7357b07c0a825a1195f2c81da3fb8d72c8ee98c798ff6', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"2.13 Observable Container (deprecated)","subsection":"UNKNOWN","table_id":null,"page":26,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":103,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"2.13 Observable Container (deprecated)"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p26-104', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '2.14 Open Vocabulary', 26, 'Type Name: open-vocab The open-vocab type is represented as a string. For properties that use this type there will be a list of suggested values, known as the suggested vocabulary, that is identified in the definition for that property. The suggested vocabularies are defined in section 10. The value of the property SHOULD be chosen from the suggested vocabulary, but MAY be any other string value. Values that are not from the suggested vocabulary SHOULD be all lowercase and SHOULD use hyphens instead of spaces or underscores as word separators.', 'vec_doc-10-oasis-stix21-p26-104', 0, 138, 'v2.1.0', 'ae0e61e28f43df5db52534387345f81532ec6611b5393da9e62cecc8827fb77e', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"2.14 Open Vocabulary","subsection":"UNKNOWN","table_id":null,"page":26,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":104,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"2.14 Open Vocabulary"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p27-105', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '2.14 Open Vocabulary', 27, 'Standards Track Work Product 02 April 2025 - Page 27 of 276Copyright © OASIS Open 2025. All Rights Reserved. A consumer that receives STIX content with one or more open-vocab terms not defined in the suggested vocabulary MAY ignore those values. The JSON MTI serialization uses the JSON String type [RFC8259] when representing open-vocab. Examples Example using value from the suggested vocabulary. In this example the Threat Actor sophistication property is an open vocabulary and we are using one of the suggested vocabulary values. { ... "sophistication": "intermediate", ... } Example using a user-defined value. In this example, for the same Threat Actor sophistication property, we are not using a value in the suggested vocabulary. { ... "sophistication": "pbx-advanced-activity", ... }', 'vec_doc-10-oasis-stix21-p27-105', 0, 199, 'v2.1.0', '566fa373c07aecc93b6ac892824289875dd784d7af62af07e2f5840f1a59b469', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"2.14 Open Vocabulary","subsection":"UNKNOWN","table_id":null,"page":27,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":105,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"2.14 Open Vocabulary"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p27-106', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '2.15 String', 27, 'Type Name: string The string data type represents a finite-length string of valid characters from the Unicode coded character set [ISO10646]. Unicode incorporates ASCII and the characters of many other international character sets. The JSON MTI serialization uses the JSON String type [RFC8259], which mandates the UTF-8 encoding for supporting Unicode. Example { ... "name": "The Black Vine Cyberespionage Group", ... }', 'vec_doc-10-oasis-stix21-p27-106', 0, 105, 'v2.1.0', 'd16757a211570dfc8e5c0b2e49cf6174688b51574ea156ad52c9cfed30ccb6c6', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"2.15 String","subsection":"UNKNOWN","table_id":null,"page":27,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":106,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"2.15 String"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p27-107', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '2.16 Timestamp', 27, 'Type Name: timestamp The timestamp type defines how dates and times are represented in STIX. The JSON MTI serialization uses the JSON String type [RFC8259] when representing timestamp. 2.16.1 Requirements The timestamp property MUST be a valid RFC 3339-formatted timestamp [RFC3339] using the format YYYY-MM-DDTHH:mm:ss[.s+]Z where the “s+” represents 1 or more sub-second values.', 'vec_doc-10-oasis-stix21-p27-107', 0, 95, 'v2.1.0', '780564abdcf032e73768f8e392939cb31c88623fb4860566e1e114db647aea6e', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"2.16 Timestamp","subsection":"UNKNOWN","table_id":null,"page":27,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":107,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"2.16 Timestamp"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p28-108', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '2.16 Timestamp', 28, 'Standards Track Work Product 02 April 2025 - Page 28 of 276Copyright © OASIS Open 2025. All Rights Reserved. The brackets denote that sub-second precision is optional, and that if no digits are provided, the decimal place MUST NOT be present. The timestamp MUST be represented in the UTC timezone and MUST use the “Z” designation to indicate this. NOTE: when using precisions greater than nanoseconds there may be implications for interoperability as they may be truncated when stored as a UNIX timestamp or floating point number due to the fundamental precision of those formats. Example { ... "created": "2016-01-20T12:31:12.123Z", ... }', 'vec_doc-10-oasis-stix21-p28-108', 0, 160, 'v2.1.0', '1c862bf62c60dbdf7723530e4e0efbed5fa3af1688111b4cac2954cb7896dce6', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"2.16 Timestamp","subsection":"UNKNOWN","table_id":null,"page":28,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":108,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"2.16 Timestamp"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p29-109', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '3.1 Property Names and String Literals', 29, 'All type names, property names, and literals MUST be in lowercase, except when referencing canonical names defined in another standard (e.g., literal values from an IANA registry). Lowercase is defined by the locality conventions. Type names and property names MUST begin with a letter character (for example in ASCII that would be a through z). Words in property names MUST be separated with an underscore (\_), while words in type names and string enumerations MUST be separated with a hyphen (-). Dictionary key and hash algorithm names MAY have underscores (_) or hyphens (-). All type names, property names, object names, and vocabulary terms MUST be between three and 250 characters long.', 'vec_doc-10-oasis-stix21-p29-109', 0, 174, 'v2.1.0', '7fca2fdeb433e2fd1d3154cb245a7eb16efbc8e4bbc09efbbd6ee05c568478cf', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"3.1 Property Names and String Literals","subsection":"UNKNOWN","table_id":null,"page":29,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":109,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"3.1 Property Names and String Literals"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p29-110', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '3.1 Property Names and String Literals', 29, 'Certain names of properties MUST have specific suffixes: If the value of the property contains an ID reference for embedded relationships it MUST end in _ref If the value of the property contains a list of embedded relationships it MUST end in _refs If the value of the property contains a binary value, it MUST end in _bin If the value of the property contains a hexadecimal value, it MUST end in _hex A property might contain a string with an alternative encoding. Some object types will define an additional optional property to specify this encoding. The name of the additional property MUST end in _enc. For example, the name property might contain text in an alternative encoding, and the name_enc property would be used to specify which encoding is used. The encoding property MUST NOT be present when the original property is not present.', 'vec_doc-10-oasis-stix21-p29-110', 0, 212, 'v2.1.0', '19a15702221eb54bbf64d473db0a2157f0b307424bb54eef5710a3ff2020e37f', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"3.1 Property Names and String Literals","subsection":"UNKNOWN","table_id":null,"page":29,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":110,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"3.1 Property Names and String Literals"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p29-111', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '3.1 Property Names and String Literals', 29, 'In the JSON serialization all property names and string literals MUST be exactly the same, including case, as the names listed in the property tables in this specification. For example, the SDO common property created_by_ref must result in the JSON key name "created_by_ref". Properties marked required in the property tables MUST be present in the JSON serialization. Some properties may be designated as “deprecated.” These properties are in the process of being removed or replaced and implementers should consider using the newer designs.', 'vec_doc-10-oasis-stix21-p29-111', 0, 136, 'v2.1.0', 'd93432449584247b19b48f5792fc0756ee42a5ce23c12e6493ce4f6b84ca7b19', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"3.1 Property Names and String Literals","subsection":"UNKNOWN","table_id":null,"page":29,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":111,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"3.1 Property Names and String Literals"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p29-112', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '3.2 Common Properties', 29, 'This section defines the common properties that MAY exist on a STIX Object. While some STIX Objects use all of these common properties, not all object types do. Each type of STIX Object defines which common properties are required, which are optional, and which are not in use. A comparison summary table is provided below in this section. This information can also be found at the start of the properties table for each object. Property Name Type Description type string The type property identifies the type of STIX Object. The value of the type property MUST be the name of one of the types of STIX Objects defined in section 4, section 5, section 6, and section 7 (e.g., indicator) or the name of a Custom Object as defined by section section 11.2. spec_version string The version of the STIX specification used to', 'vec_doc-10-oasis-stix21-p29-112', 0, 205, 'v2.1.0', '3ec4bac60e80a3a3150306dce18f1213a00fe079996c3b8250102b4eac882e0f', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"3.2 Common Properties","subsection":"UNKNOWN","table_id":null,"page":29,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":112,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"3.2 Common Properties"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p30-113', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '3.2 Common Properties', 30, 'Standards Track Work Product 02 April 2025 - Page 30 of 276Copyright © OASIS Open 2025. All Rights Reserved. Property Name Type Description represent this object. The value of this property MUST be 2.1 for STIX Objects defined according to this specification. Since SCOs are now top-level objects in STIX 2.1, the default value for SCOs is 2.1. id identifier The id property uniquely identifies this object. For objects that support versioning, all objects with the same id are considered different versions of the same object and the version of the object is identified by its modified property. created_by_ref identifier The created_by_ref property specifies the id property of the identity object that describes the entity that created this object. If this attribute is omitted, the source of this information is undefined. This may be used by object creators who wish to remain anonymous. created timestamp The created property represents the time at which the object was originally created. The object creator can use the time it deems most appropriate as the time the object was created. The minimum precision MUST be milliseconds (three digits after the decimal place in seconds), but MAY be more precise. The created property MUST NOT be changed when creating a new version of the object. See section 3.6 for further definition of versioning. modified timestamp The modified property is only used by STIX Objects that support versioning and represents the time that this particular version of the object was last modified. The object creator can use the', 'vec_doc-10-oasis-stix21-p30-113', 0, 391, 'v2.1.0', 'c867b184cc351e19db8bdba363158509cc4c9d198628ff8edc5429c887881653', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"3.2 Common Properties","subsection":"UNKNOWN","table_id":null,"page":30,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":113,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"3.2 Common Properties"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p31-114', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '3.2 Common Properties', 31, 'Standards Track Work Product 02 April 2025 - Page 31 of 276Copyright © OASIS Open 2025. All Rights Reserved. Property Name Type Description time it deems most appropriate as the time this version of the object was modified. The minimum precision MUST be milliseconds (three digits after the decimal place in seconds), but MAY be more precise. If the created property is defined, then the value of the modified property for a given object version MUST be later than or equal to the value of the created property. Object creators MUST set the modified property when creating a new version of an object if the created property was set. See section 3.6 for further definition of versioning. revoked boolean The revoked property is only used by STIX Objects that support versioning and indicates whether the object has been revoked. Revoked objects are no longer considered valid by the object creator. Revoking an object is permanent; future versions of the object with this id MUST NOT be created. The default value of this property is false. See', 'vec_doc-10-oasis-stix21-p31-114', 0, 261, 'v2.1.0', 'cdae531a7dffa2decd185ce71940f8411d63f6b399436a6e614b8768281ecc9b', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"3.2 Common Properties","subsection":"UNKNOWN","table_id":null,"page":31,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":114,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"3.2 Common Properties"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p31-115', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', 'section 3.6 for further', 31, 'definition of versioning. labels list of type string The labels property specifies a set of terms used to describe this object. The terms are user-defined or trust-group defined and their meaning is outside the scope of this specification and MAY be ignored. Where an object has a specific property defined in the specification for characterizing subtypes of that object, the labels property MUST NOT be used for that purpose. For example, the Malware SDO has a property malware_types that contains a list of Malware', 'vec_doc-10-oasis-stix21-p31-115', 0, 129, 'v2.1.0', '0fda795748ac8b56987b84b7c2acb483378e8a2aed277b4bb377adfb06f0e5f5', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"section 3.6 for further","subsection":"UNKNOWN","table_id":null,"page":31,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":115,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"section 3.6 for further"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p32-116', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', 'section 3.6 for further', 32, 'Standards Track Work Product 02 April 2025 - Page 32 of 276Copyright © OASIS Open 2025. All Rights Reserved. Property Name Type Description subtypes (dropper, RAT, etc.). In this example, the labels property cannot be used to describe these Malware subtypes. confidence integer The confidence property identifies the confidence that the creator has in the correctness of their data. The confidence value MUST be a number in the range of 0–', 'vec_doc-10-oasis-stix21-p32-116', 0, 110, 'v2.1.0', '7b2eb50999fc822e5f669c55e49c187a170e5afc6c18e477eb4cf3e5ed9230a0', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"section 3.6 for further","subsection":"UNKNOWN","table_id":null,"page":32,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":116,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"section 3.6 for further"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p32-117', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '100. Appendix A contains a', 32, 'table of normative mappings to other confidence scales that MUST be used when presenting the confidence value in one of those scales. If the confidence property is not present, then the confidence of the content is unspecified. lang string The lang property identifies the language of the text content in this object. When present, it MUST be a language code conformant to [RFC5646]. If the property is not present, then the language of the content is en (English). This property SHOULD be present if the object type contains translatable text properties (e.g., name, description). The language of individual fields in this object MAY be overridden by the lang property in granular markings (see section 7.2.3). external_references list of type external-reference The external_references property specifies a list of external references which refers to non-STIX information. This property is used to provide one or more URLs, descriptions, or IDs to records in other systems. object_marking_refs list of type identifier The object_marking_refs property specifies a list of id properties of marking- definition objects that apply to this object. In some', 'vec_doc-10-oasis-stix21-p32-117', 0, 288, 'v2.1.0', 'fa68c9abf26e59dc64f2f80ad430b33d5e503839baf6e1248f90cb172c3a450b', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"100. Appendix A contains a","subsection":"UNKNOWN","table_id":null,"page":32,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":117,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"100. Appendix A contains a"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p33-118', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '100. Appendix A contains a', 33, 'Standards Track Work Product 02 April 2025 - Page 33 of 276Copyright © OASIS Open 2025. All Rights Reserved. Property Name Type Description cases, though uncommon, marking definitions themselves may be marked with sharing or handling guidance. In this case, this property MUST NOT contain any references to the same Marking Definition object (i.e., it cannot contain any circular references). See', 'vec_doc-10-oasis-stix21-p33-118', 0, 99, 'v2.1.0', '7c3acbe10ba6be3ff07e51026d653692feedea5b28ddc6b5206ba9252487958c', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"100. Appendix A contains a","subsection":"UNKNOWN","table_id":null,"page":33,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":118,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"100. Appendix A contains a"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p33-119', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', 'section 7.2 for further', 33, 'definition of data markings. granular_markings list of type granular-marking The granular_markings property specifies a list of granular markings applied to this object. In some cases, though uncommon, marking definitions themselves may be marked with sharing or handling guidance. In this case, this property MUST NOT contain any references to the same Marking Definition object (i.e., it cannot contain any circular references). See section 7.2 for further definition of data markings. defanged boolean This property defines whether or not the data contained within the object has been defanged. The default value for this property is false. This property MUST NOT be used on any STIX Objects other than SCOs. extensions dictionary Specifies any extensions of the object, as a dictionary. Dictionary keys SHOULD be the id of a STIX Extension object or the name of a predefined object extension found in this specification, depending on the type of extension being used. The corresponding dictionary values MUST contain the contents of the extension instance. Each extension dictionary MAY contain the property extension_type. The value of this property', 'vec_doc-10-oasis-stix21-p33-119', 0, 289, 'v2.1.0', 'ff78a3dc0cf908575b4e9699e6b9848b5f6ae9354c123f518694dc39245047dd', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"section 7.2 for further","subsection":"UNKNOWN","table_id":null,"page":33,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":119,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"section 7.2 for further"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p34-120', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', 'section 7.2 for further', 34, 'Standards Track Work Product 02 April 2025 - Page 34 of 276Copyright © OASIS Open 2025. All Rights Reserved. Property Name Type Description MUST come from the extension-type-enum enumeration. If the extension_type property is not present, then this is a predefined extension which does not use the extension facility described in section 7.3. When this extension facility is used the extension_type property MUST be present. This table lists all common properties and how they are used for each type of STIX Object. The following table is informational, and the body of the spec is normative and the definitive reference. STIX Core Objects STIX Meta Object Property Name SDOs SROs SCOs Extension Language Markings Bundle type Required Required Required Required Required Required Required spec_version Required Required Optional Required Required Required N/A id Required Required Required Required Required Required Required created_by_ref Optional Optional N/A Required Optional Optional N/A created Required Required N/A Required Required Required N/A modified Required Required N/A Required Required N/A N/A revoked Optional Optional N/A Optional Optional N/A N/A labels Optional Optional N/A Optional Optional N/A N/A confidence Optional Optional N/A N/A Optional N/A N/A lang Optional Optional N/A N/A N/A N/A N/A external_references Optional Optional N/A Optional Optional Optional N/A object_marking_refs Optional Optional Optional Optional Optional Optional N/A granular_markings Optional Optional Optional Optional Optional Optional N/A defanged N/A N/A Optional N/A N/A N/A N/A extensions Optional Optional Optional N/A Optional Optional N/A', 'vec_doc-10-oasis-stix21-p34-120', 0, 413, 'v2.1.0', '4fff7d92d5e2f718851abc36f7196eca9aabffbef71d6005c57dc959784c59a7', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"section 7.2 for further","subsection":"UNKNOWN","table_id":null,"page":34,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":120,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"section 7.2 for further"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p34-121', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '3.3 Object IDs and References', 34, 'All STIX Objects and the STIX Bundle Object have an id property that uniquely identifies each instance of the object. This id MUST meet the requirements of the identifier type (see section 2.9]).', 'vec_doc-10-oasis-stix21-p34-121', 0, 49, 'v2.1.0', 'b0382fd9932652e56c199034c1b8c42060bdfcd50815755ab758080af9ee4a07', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"3.3 Object IDs and References","subsection":"UNKNOWN","table_id":null,"page":34,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":121,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"3.3 Object IDs and References"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p35-122', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '3.3 Object IDs and References', 35, 'Standards Track Work Product 02 April 2025 - Page 35 of 276Copyright © OASIS Open 2025. All Rights Reserved. The identifier type is also used as an ID reference to define a relationship to other STIX Objects. Resolving an ID reference is the process of identifying and obtaining the actual object referred to by the ID reference property. ID references resolve to an object when the value of the ID reference property (e.g., created_by_ref) is an exact match with the id property of another object. If a consumer has access to multiple versions of an object, the consumer SHOULD interpret any references to that object as referring to the latest version as defined in section 3.6. ID references can refer to objects to which the consumer/producer may not currently have access; this specification does not address the implementation of ID reference resolution. Some ID references (embedded relationships) may be restricted to a subset of object types, as specified in the description of the property that defines the relationship. For example, the object_marking_refs common property specifies that the only valid target of the relationship is one or more marking- definition objects.', 'vec_doc-10-oasis-stix21-p35-122', 0, 296, 'v2.1.0', '1b29842b16d9c84d03b33b255554e8c98637dddc586b46a756e1d496777f57f1', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"3.3 Object IDs and References","subsection":"UNKNOWN","table_id":null,"page":35,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":122,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"3.3 Object IDs and References"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p35-123', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '3.4 SCO Deterministic ID Creation', 35, 'To enable deterministic IDs for STIX Cyber-observable Objects (SCOs), each SCO defines a set of one or more properties named “ID Contributing Properties.” These properties MAY be used in the default calculation of the id when creating a SCO. In some cases, additional selection of extension properties that contribute to the ID may be described in the ID Contributing Properties section listed on each SCO. The default algorithm that creates the SCO ID based on those named properties is a UUIDv5 as defined in section 2.9, however, other algorithms for creating the SCO ID MAY be used. Deterministic IDs (UUIDv5) in the example SCOs contained in this specification were computed using the algorithm defined in section 2.9. Every attempt was made for these IDs to be accurate. Certain IDs which were used in reference properties of the examples did not include the actual object, and therefore it was impossible to accurately compute the appropriate UUIDv5. In these cases, a UUIDv4 was generated.', 'vec_doc-10-oasis-stix21-p35-123', 0, 250, 'v2.1.0', 'da88069992955559160c920a6d2cdb1c23b5120e52583f7be0d48aef4a379db7', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"3.4 SCO Deterministic ID Creation","subsection":"UNKNOWN","table_id":null,"page":35,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":123,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"3.4 SCO Deterministic ID Creation"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p35-124', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '3.5 Object Creator', 35, 'The object creator is the entity (e.g., system, organization, instance of a tool) that generates the id property for a given object. Object creators are represented as Identity objects. Some STIX Objects allow this designation (see section 3.2). An embedded relationship to the Identity object representing the object creator SHOULD be captured in the created_by_ref property (or that property can be omitted, meaning the object creator is anonymous). Entities that re-publish an object from another entity without making any changes to the object, and thus maintaining the original id, are not considered the object creator and MUST NOT change the created_by_ref property. An entity that accepts objects and republishes them with modifications, additions, or omissions MUST create a new id for the object. They are considered the object creator of the new object for purposes of versioning.', 'vec_doc-10-oasis-stix21-p35-124', 0, 223, 'v2.1.0', '213660f55d1dc90f002890323dcd21d5e152f8eb59a783c1883cff29c28b75b6', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"3.5 Object Creator","subsection":"UNKNOWN","table_id":null,"page":35,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":124,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"3.5 Object Creator"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p35-125', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '3.6 Versioning', 35, 'Versioning is the mechanism that object creators use to update and revoke the STIX Objects that they create. This section describes the versioning process and normative rules for performing versioning and revocation. STIX Objects that are versioned MUST use the property names created_by_ref, created, modified, and revoked. SCOs are not versioned and thus do not have the four versioning properties. See the properties table in section 3.2 for full definitions and normative usage of those properties. STIX Objects MAY be versioned in order to update, add, or remove information. A version of a STIX Object is identified uniquely by the combination of its id and modified properties. The first version of the object MUST have the same timestamp for the created and modified properties. More recent values of the modified property indicate later versions of the object. Implementations MUST consider the version of the STIX Object with the most recent modified value to be the most recent state of the object. For every new version of an object, the modified property MUST be updated to represent the time that the new version was created. If a consumer receives two objects that are different, but have the same id and modified timestamp, it is not defined how the consumer handles the objects. This specification does not address how implementations should handle versions of the object that are not current.', 'vec_doc-10-oasis-stix21-p35-125', 0, 353, 'v2.1.0', 'c47eb052634181a757a511a91f87b35842fcae8ecd0ca7dc33e3a4c6aa3242c6', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"3.6 Versioning","subsection":"UNKNOWN","table_id":null,"page":35,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":125,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"3.6 Versioning"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p36-126', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '3.6 Versioning', 36, 'Standards Track Work Product 02 April 2025 - Page 36 of 276Copyright © OASIS Open 2025. All Rights Reserved. STIX Objects have a single object creator, the entity that generates the id for the object and creates the first version. The object creator MAY (but not necessarily will) be identified in the created_by_ref property of the object. Only the object creator is permitted to create new versions of a STIX Object. Producers other than the object creator MUST NOT create new versions of that object. If a producer other than the object creator wishes to create a new version, they MUST instead create a new object with a new id. They SHOULD additionally create a derived-from Relationship object to relate their new object to the original object that it was derived from.', 'vec_doc-10-oasis-stix21-p36-126', 0, 194, 'v2.1.0', 'c6a37958945751cccc1d9f6dda65823194bf8fa05568aee437c5e1f04111f54e', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"3.6 Versioning","subsection":"UNKNOWN","table_id":null,"page":36,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":126,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"3.6 Versioning"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p36-127', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '3.6 Versioning', 36, 'Every representation (each time the object version is serialized and shared) of a version of an object (identified by the object’s id and modified properties) MUST always have the same set of properties and the same values for each property. If a property has the same value as the default, it MAY be omitted from a representation, and this does not represent a change to the object. In order to change the value of any property, or to add or remove properties, the modified property MUST be updated with the time of the change to indicate a new version. Objects can also be revoked, which means that they are no longer considered valid by the object creator. As with issuing a new version, only the object creator is permitted to revoke a STIX Object. A value of true in the revoked property indicates that an object (including the current version and all past versions) has been revoked. Revocation is permanent: once an object is marked as revoked, later versions of that object MUST NOT be created.', 'vec_doc-10-oasis-stix21-p36-127', 0, 251, 'v2.1.0', 'c24f2e6f2277d9945e53653f481950f099502236692d39504c14b8c7c2914df1', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"3.6 Versioning","subsection":"UNKNOWN","table_id":null,"page":36,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":127,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"3.6 Versioning"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p36-128', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '3.6 Versioning', 36, 'Changing the revoked property to indicate that an object is revoked is an update to the object, and therefore its modified property MUST be updated at the same time. This specification does not address how implementations should handle revoked data. It should be noted that if a producer versions a SCO (assigns value to these four properties) that no other producer would be allowed to create or modify the same SCO with an equivalent deterministic id, as that would conflict with the strict versioning rules defined in STIX2. Therefore, for interoperability and sharing, producers versioning SCOs MUST NOT use the default namespace for deterministic ID creation. Otherwise multiple different producers will conflict with each other if producing the same SCO intelligence. 3.6.1 Versioning Timestamps There are two timestamp properties used to indicate when STIX Objects were created and modified: created and modified. The created property indicates the time the first version of the object was created.', 'vec_doc-10-oasis-stix21-p36-128', 0, 252, 'v2.1.0', '5c973bf699d102df474d463290ffe156eb926d2f5b3a0e94177a1b2e93c72714', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"3.6 Versioning","subsection":"UNKNOWN","table_id":null,"page":36,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":128,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"3.6 Versioning"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p36-129', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '3.6 Versioning', 36, 'The modified property indicates the time the specific version of the object was created. The modified time MUST NOT be earlier than the created time. This specification does not address the specifics of how implementations should determine the value of the creation and modification times for use in the created and modified properties (e.g., one system might use when the object is first added to the local database as the creation time, while another might use the time when the object is first distributed as STIX). 3.6.2 New Version or New Object? Eventually an implementation will encounter a case where a decision must be made regarding whether a change is a new version of an existing object or is different enough that it is a new object. This is generally considered a data quality problem and therefore this specification does not provide any normative text. However, to assist implementers and promote consistency across implementations, some rules of thumb are provided.', 'vec_doc-10-oasis-stix21-p36-129', 0, 246, 'v2.1.0', 'bb9b57cc6cb224c39ab002bb1efb8e3036f8d016b727aea45aedc56f5de334e7', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"3.6 Versioning","subsection":"UNKNOWN","table_id":null,"page":36,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":129,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"3.6 Versioning"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p36-130', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '3.6 Versioning', 36, 'Any time a change indicates a material change to the meaning of the object, a new object with a different id should be used. A material change is any change that the object creator believes substantively changes the meaning of the object. As an example, an object creator might consider changing a Threat Actor from one country to another is a material change. These decisions are always made by the object creator. The object creator should also think about relationships to the object when deciding if a change is material. If the change would invalidate the usefulness of relationships to the object, then the change is considered material and a new object id should be used. Examples Example of a new version', 'vec_doc-10-oasis-stix21-p36-130', 0, 178, 'v2.1.0', '9052475a1e947ca3ac5cc273bf551b3b8f3c8dd7f2528961b895e468ed69dd14', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"3.6 Versioning","subsection":"UNKNOWN","table_id":null,"page":36,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":130,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"3.6 Versioning"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p37-131', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '3.6 Versioning', 37, 'Standards Track Work Product 02 April 2025 - Page 37 of 276Copyright © OASIS Open 2025. All Rights Reserved. One object creator has decided that the previous name they used for an SDO is incorrect. They consider that change as an update to the object. NOTE: the IDs in the example below use a simplified format to help illustrate the changing IDs more clearly. Step # </span STIX Object Object Creator Action 1 { "type": "example", "id": "example--1", "created": "2016-05- 01T06:13:14.000Z", "modified": "2016-05- 01T06:13:14.000Z", "name": "attention", "description": "this is the description" } Original object created. 2 N/A, STIX is not involved in this step Object creator changes the name in their internal database. 3 { "type": "example", "id": "example--1", "created": "2016-05- 01T06:13:14.000Z", "modified": "2016-05- 08T03:43:44.000Z", "name": "Attention!", "description": "this is the description" } Object creator updates the modified property. Example of a derived object One object creator has decided that the previous name they used for an SDO is incorrect. They consider that change fundamental to the meaning of the object and therefore revoke the object and issue a new one. Step # STIX Object Object Creator Action 1 { "type": "example", "id": "example--2", "created": "2016-05- 01T06:13:14.000Z", "modified": "2016-05- 01T06:13:14.000Z", "name": "attention", "description": "this is the description" } Original object created (via new id and setting created and modified to the same value).', 'vec_doc-10-oasis-stix21-p37-131', 0, 378, 'v2.1.0', '4ce6c2717f339e0cab45f85eacdaa002fcc03cfd5ae0136462c667006b0e07d6', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"3.6 Versioning","subsection":"UNKNOWN","table_id":null,"page":37,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":131,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"3.6 Versioning"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p38-132', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '3.6 Versioning', 38, 'Standards Track Work Product 02 April 2025 - Page 38 of 276Copyright © OASIS Open 2025. All Rights Reserved. 2 N/A, STIX is not involved inthis step Object creator changes the name in their internaldatabase. 3 { "type": "example", "id": "example--2", "created": "2016-05- 01T06:13:14.000Z", "modified": "2016-05- 08T03:43:44.000Z", "name": "Attention!", "description": "this is the description", "revoked": true } Object creator revokes the existing object by setting revoked to true. The modified property is updated. 4 { "type": "example", "id": "example--3", "created": "2016-05- 08T03:43:44.000Z", "modified": "2016-05- 08T03:43:44.000Z", "name": "Something completely different", "description": "this is the description" } Object creator creates a new object (with a new id and setting created and modified to the same value). 5 { "type": "relationship", "id": "relationship--4", "created": "2016-05- 08T03:43:44.000Z", "modified": "2016-05- 08T03:43:44.000Z", "relationship_type": "derived-from", "source_ref": "example--2", "target_ref": "example--3" } (Optional) Object creator creates a new Relationship object indicating that the new object is derived from the old object. Examples of consumer workflow This section describes an example workflow where a consumer receives multiple updates to a particular object. (In this example, the STIX Objects have been truncated for brevity.) Step # STIX Object Object Creator Action 1 { "type": "example", "id": "example--5", "created": "2016-05- 01T06:13:14.000Z", "modified": "2016-05- 01T06:13:14.000Z" } Consumer stores example object because this is the first time they have seen the object.', 'vec_doc-10-oasis-stix21-p38-132', 0, 412, 'v2.1.0', '9e8537cb74ed65d1f612c61504423ab270fabe68d1f7e7b76c8d74055ca55670', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"3.6 Versioning","subsection":"UNKNOWN","table_id":null,"page":38,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":132,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"3.6 Versioning"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p39-133', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '3.6 Versioning', 39, 'Standards Track Work Product 02 April 2025 - Page 39 of 276Copyright © OASIS Open 2025. All Rights Reserved. 2 { "type": "example", "id": "example--5", "created": "2016-05- 01T06:13:14.000Z", "modified": "2016-05- 08T03:43:44.000Z" } Consumer updates example object because the received modified property is later than the object that is currently stored. 3 { "type": "example", "id": "example--5", "created": "2016-05- 01T06:13:14.000Z", "modified": "2016-05- 06T06:23:45.000Z" } Consumer ignores this object because they already have a newer version of the object. Note: consumer might choose to store meta-information about received objects, including versions that were received out-of- order. The consumer also may choose to store a copy for reference.', 'vec_doc-10-oasis-stix21-p39-133', 0, 190, 'v2.1.0', '2d7a7d92b1538c2f2b73a702d5686ee67b2cd3a0ca5f316656a472b6922d9b55', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"3.6 Versioning","subsection":"UNKNOWN","table_id":null,"page":39,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":133,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"3.6 Versioning"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p39-134', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '3.6 Versioning', 39, '4 { "type": "example", "id": "example--5", "created": "2016-05- 01T06:13:14.000Z", "modified": "2016-05- 11T06:41:21.000Z", "revoked": true } Consumer receives revoked version and decides to delete example object but keeps some metadata regarding the object. 5 { "type": "example", "id": "example--5", "created": "2016-05- 01T06:13:14.000Z", "modified": "2016-05- 10T17:28:54.000Z" } Consumer ignores this object because they already have a newer version of the object (the revoked version). Example of object creator workflow This section describes an example workflow where an object creator publishes multiple updates to a particular object. This scenario assumes a human using a STIX implementation. (In this example, the STIX Objects have been truncated for brevity.) Step # STIX Object Object Creator Action 1 N/A - STIX is not involved in this scenario.', 'vec_doc-10-oasis-stix21-p39-134', 0, 215, 'v2.1.0', '8fdc04624c081347e4ce71c8f36347494d5a1291221d97bd17835bbd772d14a4', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"3.6 Versioning","subsection":"UNKNOWN","table_id":null,"page":39,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":134,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"3.6 Versioning"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p39-135', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '3.6 Versioning', 39, '(Tools could choose to create and track STIX versions for internal changes, but it is not required by the specification.) User clicks a create button in the user interface, creates an SDO, then clicks save. This action causes information to be stored in the product’s database.', 'vec_doc-10-oasis-stix21-p39-135', 0, 70, 'v2.1.0', 'a77b689f5319c121ac95a2ad79edea5d34571eadca9c2ce3bbb8b021670011e9', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"3.6 Versioning","subsection":"UNKNOWN","table_id":null,"page":39,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":135,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"3.6 Versioning"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p40-136', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '3.6 Versioning', 40, 'Standards Track Work Product 02 April 2025 - Page 40 of 276Copyright © OASIS Open 2025. All Rights Reserved. 2 { "type": "example", "id": "example--6", "created": "2016-05-01T06:13:14.000Z", "modified": "2016-05-01T06:13:14.000Z" } The user clicks the “share” button, deliveringthe intelligence to sharing partners. 3 N/A - STIX is not involved in this scenario. (Tools could choose to create and track STIX versions for internal changes, but it is not required by the specification.) The user performs additional analysis within the STIX implementation, performing multiple modifications and saving their work multiple times. 4 { "type": "example", "id": "example--6", "created": "2016-05-01T06:13:14.000Z", "modified": "2016-05-03T16:33:51.000Z" } The user, happy with the status of their work,decides to provide an update to some properties of the previously published object (not shown). 5 { "type": "example", "id": "example--6", "created": "2016-05-01T06:13:14.000Z", "modified": "2016-05-08T13:35:12.000Z", "revoked": true } The user receives lots of negative feedback regarding the quality of their work and decides to retract the object by pressing the “revoke” button.', 'vec_doc-10-oasis-stix21-p40-136', 0, 295, 'v2.1.0', 'fc2888bbe0ebb19828028f8790b309b3ff7f3da5294ef3ae298a078d41d78b15', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"3.6 Versioning","subsection":"UNKNOWN","table_id":null,"page":40,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":136,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"3.6 Versioning"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p40-137', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '3.7 Common Relationships', 40, 'Each SDO and SCO has its own set of relationship types that are specified in the definition of that SDO or SCO. The following common relationship types are defined for all SDOs and SCOs. See STIX Relationships for more information about relationships. Relationship Type Source Target Description derived-from <SDO or SCO of same type as target> <SDO or SCO of same type as source> The information in the target object is based on information from the source object. derived-from is an explicit relationship between two separate objects. It is not a substitute for the versioning process defined in Section 3.6. duplicate-of <SDO or SCO of same type as target> <SDO or SCO of same type as source> The referenced source and target objectsare semantically duplicates of each other. This specification does not address whether the source or the target object is the duplicate object or what action, if any, a consumer should take when receiving an instance of this relationship.', 'vec_doc-10-oasis-stix21-p40-137', 0, 244, 'v2.1.0', '22d90131a1669f9cdd20567d1b113f54fa36641393243a083461ac9c90930e85', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"3.7 Common Relationships","subsection":"UNKNOWN","table_id":null,"page":40,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":137,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"3.7 Common Relationships"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p41-138', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '3.7 Common Relationships', 41, 'Standards Track Work Product 02 April 2025 - Page 41 of 276Copyright © OASIS Open 2025. All Rights Reserved. As an example, a Campaign object from one organization could be marked as a duplicate-of a Campaign object from another organization if they both described the same campaign. related-to <SDO or SCO of any type> <SDO or SCO of any type> Asserts a non-specific relationship between two SDOs. This relationship can be used when none of the other predefined relationships are appropriate, and a user- defined one is not needed. As an example, a Malware object describing a piece of malware could be marked as related-to a Tool if they are commonly used together. That relationship is not common enough to standardize but may be useful to some analysts.', 'vec_doc-10-oasis-stix21-p41-138', 0, 190, 'v2.1.0', 'bf93ce0f35db581a68d149be644d954392dbe920337f0076b6b38df266d0717e', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"3.7 Common Relationships","subsection":"UNKNOWN","table_id":null,"page":41,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":138,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"3.7 Common Relationships"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p41-139', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '3.8 Reserved Names', 41, 'This section defines property names that are reserved for future revisions of this document. The property names defined in this section and any property name that is marked as RESERVED MUST NOT be used for the name of any Custom Property or be present in any STIX content conforming to this version of the specification. Properties that are currently reserved across all STIX Objects are: severity username phone_number action', 'vec_doc-10-oasis-stix21-p41-139', 0, 107, 'v2.1.0', 'e6e38e9fc60535ed9653f011b9f9f9b57c1de80fdf201bf807573145fd362afd', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"3.8 Reserved Names","subsection":"UNKNOWN","table_id":null,"page":41,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":139,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"3.8 Reserved Names"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p41-140', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '3.9 Object Property Metadata', 41, '3.9.1 SCO String Encoding Capturing the observed encoding of a particular STIX Cyber-observable Object (SCO) string is useful for attribution, the creation of indicators, and related use cases. Certain string properties in STIX Cyber-observable Objects may contain an additional sibling property with the same base name and a suffix of _enc that captures the name of the original observed encoding of the property value. All _enc properties MUST specify their encoding using the ccorresponding name from the IANA character set registry [CharacterSets]. If the preferred MIME name for a character set is defined, this value MUST be used; if it is not defined, then the Name value from the registry MUST be used instead. Example File with Unicode representation of the filename and a corresponding encoding specification { "type": "file", "id": "file-1389b98d-a3d3-5190-a996-716fd444059a", "hashes": { "SHA-256": "effb46bba03f6c8aea5c653f9cf984f170dcdd3bbbe2ff6843c3e5da0e698766" }, "name": "quêry.dll", "name_enc": "windows-1252" }', 'vec_doc-10-oasis-stix21-p41-140', 0, 258, 'v2.1.0', 'c27c9ab5d5639022c6840fefa4d04d4caeca77ca4aaed9de7a3f20b764eb50be', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"3.9 Object Property Metadata","subsection":"UNKNOWN","table_id":null,"page":41,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":140,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"3.9 Object Property Metadata"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p42-141', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '3.10 Predefined Object Extensions', 42, 'Predefined Object Extensions have a specific purpose in STIX Objects: defining coherent sets of properties beyond the base, e.g., HTTP request information for a Network Traffic object. Accordingly, each object may include one or more Predefined Object Extensions. Each Predefined Object Extension can be defined at most once on a given STIX Object. Each extension is specified under the extensions property, which is of type dictionary. Note that this means that each extension is specified through a corresponding key in the extensions property. For example, when specified in a File object instance, the NTFS File Extension would be specified using the key value of ntfs-ext. Example Basic File with NTFS Extension { "type": "file", "spec_version": "2.1", "id": "file--1b40e321-ae73-5637-bd97-33c35a86b80d", "hashes": { "MD5": "3773a88f65a5e780c8dff9cdc3a056f3" }, "size": 25537, "extensions": { "ntfs-ext": { "sid": "1234567" } } }', 'vec_doc-10-oasis-stix21-p42-141', 0, 234, 'v2.1.0', 'aa5df0f6fdd41a59c5df3cda9a7776420e671ce92272491e82b7636e717bf620', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"3.10 Predefined Object Extensions","subsection":"UNKNOWN","table_id":null,"page":42,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":141,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"3.10 Predefined Object Extensions"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p43-142', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '4. STIX Domain Objects', 43, 'This specification defines the set of STIX Domain Objects (SDOs), each of which corresponds to a unique concept commonly represented in CTI. Using SDOs, STIX Cyber-observable Objects (SCOs), and STIX Relationship Objects (SROs) as building blocks, individuals can create and share broad and comprehensive cyber threat intelligence. Property information, relationship information, and examples are provided for each SDO defined below. Property information includes common properties as well as properties that are specific to each SDO. Relationship information includes embedded relationships (e.g., created_by_ref), common relationships (e.g., related-to), and SDO-specific relationships. Forward relationships (i.e., relationships from the SDO to other SDOs or SCOs) are fully defined, while reverse relationships (i.e., relationships to the SDO from other SDOs or SCOs) are duplicated for convenience. Some SDOs are similar and can be grouped together into categories. Attack Pattern, Malware, and Tool can all be considered types of tactics, techniques, and procedures (TTPs): they describe behaviors and resources that attackers use to carry out their attacks. Similarly, Campaign, Intrusion Set, and Threat Actor all describe information about why adversaries carry out attacks and how they organize themselves.', 'vec_doc-10-oasis-stix21-p43-142', 0, 329, 'v2.1.0', 'd0ebc3b6121651647987e1e09874faf621d7d9d6513ecbc4f3c7a35cfd5fd6da', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"4. STIX Domain Objects","subsection":"UNKNOWN","table_id":null,"page":43,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":142,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"4. STIX Domain Objects"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p43-143', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '4.1 Attack Pattern', 43, 'Type Name: attack-pattern Attack Patterns are a type of TTP that describe ways that adversaries attempt to compromise targets. Attack Patterns are used to help categorize attacks, generalize specific attacks to the patterns that they follow, and provide detailed information about how attacks are performed. An example of an attack pattern is “spear phishing”: a common type of attack where an attacker sends a carefully crafted e-mail message to a party with the intent of getting them to click a link or open an attachment to delivermalware. Attack Patterns can also be more specific; spear phishing as practiced by a particular threat actor (e.g., they might generally say that the target won a contest) can also be an Attack Pattern. The Attack Pattern SDO contains textual descriptions of the pattern along with references to externally- defined taxonomies of attacks such as CAPEC. 4.1.1 Properties Required Common Properties type, spec_version, id, created, modified Optional Common Properties created_by_ref, revoked, labels, confidence, lang, external_references, object_marking_refs, granular_markings, extensions Not Applicable Common Properties defanged Attack Pattern Specific Properties name, description, aliases, kill_chain_phases Property Name</span Type</span Description</span', 'vec_doc-10-oasis-stix21-p43-143', 0, 324, 'v2.1.0', '5a2fffe6b1f46a6773cb6911b78f691dc6ae77d5c5aaa5e5bfab9f76e17bf6eb', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"4.1 Attack Pattern","subsection":"UNKNOWN","table_id":null,"page":43,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":143,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"4.1 Attack Pattern"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p44-144', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '4.1 Attack Pattern', 44, 'Standards Track Work Product 02 April 2025 - Page 44 of 276Copyright © OASIS Open 2025. All Rights Reserved. type (required) string The value of this property MUST be attack-pattern. external_references (optional) list of type external-reference A list of external references which refer to non-STIX information. This property MAY be used to provide one or more Attack Pattern identifiers, such as a CAPEC ID. When specifying a CAPEC ID, the source_name property of the external reference MUST be set to capec and the external_id property MUST be formatted as CAPEC- [id]. name (required) string A name used to identify the Attack Pattern. description (optional) string A description that provides more details and context about the Attack Pattern, potentially including its purpose and its key characteristics. aliases (optional) list of type string Alternative names used to identify this Attack Pattern.', 'vec_doc-10-oasis-stix21-p44-144', 0, 227, 'v2.1.0', 'a07efbeb42855ae626dfaa26d9c3fa75ffe929aef2acaf65a75d03463b08d676', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"4.1 Attack Pattern","subsection":"UNKNOWN","table_id":null,"page":44,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":144,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"4.1 Attack Pattern"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p44-145', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '4.1 Attack Pattern', 44, 'kill_chain_phases (optional) list of type kill-chain-phase The list of Kill Chain Phases for which this Attack Pattern is used. 4.1.2 Relationships These are the relationships explicitly defined between the Attack Pattern object and other STIX Objects. The first section lists the embedded relationships by property name along with their corresponding target. The rest of the table identifies the relationships that can be made from this object type to another object type by way of the Relationship object. The reverse relationships section illustrates the relationships targeting this object type from another object type. They are included here for convenience. For their definitions, please see the “Source” object. Relationships are not restricted to those listed below. Relationships can be created between any objects using the related-to relationship type or, as with open vocabularies, user-defined names.', 'vec_doc-10-oasis-stix21-p44-145', 0, 229, 'v2.1.0', '3adcf25d4ee11f09cfa103a51cb5c15e1245a92bb49ee1d3125fb8904051937e', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"4.1 Attack Pattern","subsection":"UNKNOWN","table_id":null,"page":44,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":145,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"4.1 Attack Pattern"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p44-146', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '4.1 Attack Pattern', 44, 'Embedded Relationships created_by_ref identifier (of type identity) object_marking_refs list of type identifier (of type marking- definition) Common Relationships duplicate-of, derived-from, related-to Source Relationship Type Target Description', 'vec_doc-10-oasis-stix21-p44-146', 0, 62, 'v2.1.0', 'd9fe4d51a2b1ce2d250d1c9c16430cc671b3887dcf569f39bae1ae913a844d04', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"4.1 Attack Pattern","subsection":"UNKNOWN","table_id":null,"page":44,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":146,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"4.1 Attack Pattern"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p45-147', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '4.1 Attack Pattern', 45, 'Standards Track Work Product 02 April 2025 - Page 45 of 276Copyright © OASIS Open 2025. All Rights Reserved. attack- pattern delivers malware This Relationship describes that thisAttack Pattern is used to deliver this malware instance (or family). attack- pattern targets identity, location, vulnerability This Relationship describes that this Attack Pattern typically targets the type of victim, location, or vulnerability represented by the related Identity, Location, or Vulnerability object. For example, a targets Relationship linking an Attack Pattern for SQL injection to an Identity object representing domain administrators means that the form of SQL injection characterized by the Attack Pattern targets domain administrators in order to achieve its objectives. Another example is a Relationship linking an Attack Pattern for SQL injection to a Vulnerability in blogging software means that the particular SQL injection attack exploits that vulnerability. attack- pattern uses malware, tool This Relationship describes that the related Malware or Tool is used to perform the behavior identified in the Attack Pattern. For example, a uses Relationship linking an Attack Pattern for a distributed denial of service (DDoS) to a Tool for Low Orbit Ion Cannon (LOIC) indicates that the tool can be used to perform those DDoS attacks. Reverse Relationships indicator indicates attack- pattern See forward relationship for definition. course-of- action mitigates attack- pattern See forward relationship for definition. campaign, intrusion- set, malware, threat-actor uses attack- pattern See forward relationship for definition. Examples A generic attack pattern for spear phishing, referencing CAPEC', 'vec_doc-10-oasis-stix21-p45-147', 0, 426, 'v2.1.0', 'f9433a9f53d8afc9de663392a374f03593a9e4272a1d615c536ba0e7a18f8a79', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"4.1 Attack Pattern","subsection":"UNKNOWN","table_id":null,"page":45,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":147,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"4.1 Attack Pattern"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p46-148', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '4.1 Attack Pattern', 46, 'Standards Track Work Product 02 April 2025 - Page 46 of 276Copyright © OASIS Open 2025. All Rights Reserved. { "type": "attack-pattern", "spec_version": "2.1", "id": "attack-pattern--0c7b5b88-8ff7-4a4d-aa9d-feb398cd0061", "created": "2016-05-12T08:17:27.000Z", "modified": "2016-05-12T08:17:27.000Z", "name": "Spear Phishing", "description": "...", "external_references": [ { "source_name": "capec", "external_id": "CAPEC-163" } ] } A specific attack pattern for a particular form of spear phishing, referencing CAPEC [ { "type": "attack-pattern", "spec_version": "2.1", "id": "attack-pattern--7e33a43e-e34b-40ec-89da-36c9bb2cacd5", "created": "2016-05-12T08:17:27.000Z", "modified": "2016-05-12T08:17:27.000Z", "name": "Spear Phishing as Practiced by Adversary X", "description": "A particular form of spear phishing where the attacker claims that the target had won a contest, including personal details, to get them to click on a link.", "external_references": [ { "source_name": "capec", "external_id": "CAPEC-163" } ] }, { "type": "relationship", "spec_version": "2.1", "id": "relationship--57b56a43-b8b0-4cba-9deb-34e3e1faed9e", "created": "2016-05-12T08:17:27.000Z", "modified": "2016-05-12T08:17:27.000Z", "relationship_type": "uses", "source_ref": "intrusion-set--0c7e22ad-b099-4dc3-b0df-2ea3f49ae2e6", "target_ref": "attack-pattern--7e33a43e-e34b-40ec-89da-36c9bb2cacd5" }, { "type": "intrusion-set", "spec_version": "2.1", "id": "intrusion-set--0c7e22ad-b099-4dc3-b0df-2ea3f49ae2e6", "created": "2016-05-12T08:17:27.000Z", "modified": "2016-05-12T08:17:27.000Z", "name": "Adversary X" } ]', 'vec_doc-10-oasis-stix21-p46-148', 0, 400, 'v2.1.0', 'a912b533a51fb91e35dc6bffa8882f0b6e8761608806e348d0e5dc9c09e42dd9', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"4.1 Attack Pattern","subsection":"UNKNOWN","table_id":null,"page":46,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":148,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"4.1 Attack Pattern"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p46-149', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '4.2 Campaign', 46, 'Type Name: campaign A Campaign is a grouping of adversarial behaviors that describes a set of malicious activities or attacks (sometimes called waves) that occur over a period of time against a specific set of targets. Campaigns usually have well defined objectives and may be part of an Intrusion Set.', 'vec_doc-10-oasis-stix21-p46-149', 0, 76, 'v2.1.0', '51f5a7cb274e246146a291a1bde3f09cd406d2685fae674c8e655c7076dc142c', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"4.2 Campaign","subsection":"UNKNOWN","table_id":null,"page":46,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":149,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"4.2 Campaign"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p47-150', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '4.2 Campaign', 47, 'Standards Track Work Product 02 April 2025 - Page 47 of 276Copyright © OASIS Open 2025. All Rights Reserved. Campaigns are often attributed to an intrusion set and threat actors. The threat actors may reuse known infrastructure from the intrusion set or may set up new infrastructure specific for conducting that campaign. Campaigns can be characterized by their objectives and the incidents they cause, people or resources they target, and the resources (infrastructure, intelligence, Malware, Tools, etc.) they use. For example, a Campaign could be used to describe a crime syndicate’s attack using a specific variant of malware and new C2 servers against the executives of ACME Bank during the summer of 2016 in order to gain secret information about an upcoming merger with another bank.', 'vec_doc-10-oasis-stix21-p47-150', 0, 198, 'v2.1.0', '56db4ab04c665347ea00bad2440f62466c66c291d56bb9c776e287221acca06f', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"4.2 Campaign","subsection":"UNKNOWN","table_id":null,"page":47,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":150,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"4.2 Campaign"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p47-151', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '4.2 Campaign', 47, '4.2.1 Properties Required Common Properties type, spec_version, id, created, modified Optional Common Properties created_by_ref, revoked, labels, confidence, lang, external_references, object_marking_refs, granular_markings, extensions Not Applicable Common Properties defanged Campaign Specific Properties name, description, aliases, first_seen, last_seen, objective Property Name</span Type</span Description</span type (required) string The value of this property MUST be campaign. name (required) string A name used to identify the Campaign. description (optional) string A description that provides more details and context about the Campaign, potentially including its purpose and its key characteristics. aliases (optional) list of type string Alternative names used to identify this Campaign. first_seen (optional) timestamp The time that this Campaign was first seen. A summary property of data from sightings and other data that may or may not be available in STIX.', 'vec_doc-10-oasis-stix21-p47-151', 0, 244, 'v2.1.0', 'e42eb12e36017fdc6aeb57a350f24f6c05eba796dbcd73c3f4c55250f960691b', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"4.2 Campaign","subsection":"UNKNOWN","table_id":null,"page":47,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":151,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"4.2 Campaign"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p47-152', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '4.2 Campaign', 47, 'If new sightings are received that are earlier than the first seen timestamp, the object may be updated to account for the new data. last_seen (optional) timestamp The time that this Campaign was last seen. A summary property of data from sightings and other data that may or may not be available in STIX. If new sightings are received that are later than the last seen timestamp, the', 'vec_doc-10-oasis-stix21-p47-152', 0, 96, 'v2.1.0', 'b3bc1421191bb276527fb7ccbfc2759e3144f8c63b9e9ea6b584e1e31de75ef4', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"4.2 Campaign","subsection":"UNKNOWN","table_id":null,"page":47,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":152,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"4.2 Campaign"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p48-153', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '4.2 Campaign', 48, 'Standards Track Work Product 02 April 2025 - Page 48 of 276Copyright © OASIS Open 2025. All Rights Reserved. object may be updated to account for the new data. If this property and the first_seen property are both defined, then this property MUST be greater than or equal to the timestamp in the first_seen property. objective (optional) string The Campaign’s primary goal, objective, desired outcome, or intended effect — what the Threat Actor or Intrusion Set hopes to accomplish with this Campaign. 4.2.2 Relationships These are the relationships explicitly defined between the Campaign object and other STIX Objects. The first section lists the embedded relationships by property name along with their corresponding target. The rest of the table identifies the relationships that can be made from this object type to another object type by way of the Relationship object. The reverse relationships section illustrates the relationships targeting this object type from another object type.', 'vec_doc-10-oasis-stix21-p48-153', 0, 248, 'v2.1.0', '2724399deae00a3776bd7793158907f8164e8b2a171bd688fa9ceae563600468', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"4.2 Campaign","subsection":"UNKNOWN","table_id":null,"page":48,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":153,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"4.2 Campaign"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p48-154', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '4.2 Campaign', 48, 'They are included here for convenience. For their definitions, please see the “Source” object. Relationships are not restricted to those listed below. Relationships can be created between any objects using the related-to relationship type or, as with open vocabularies, user-defined names. Embedded Relationships created_by_ref identifier (of type identity) object_marking_refs list of type identifier (of type marking- definition) Common Relationships duplicate-of, derived-from, related-to Source Relationship Type Target Description campaign attributed-to intrusion-set, threat-actor This Relationship describes that the Intrusion Set or Threat Actor that is involved in carrying out the Campaign. For example, an attributed-to Relationship from the Glass Gazelle Campaign to the Urban Fowl Threat Actor means that the actor carried out or was involved in some of the activity described by the Campaign.', 'vec_doc-10-oasis-stix21-p48-154', 0, 227, 'v2.1.0', 'e7bedd28b65c98b147dc2a39efcd304d04bcad7891902dd4d49e0ae16c87093f', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"4.2 Campaign","subsection":"UNKNOWN","table_id":null,"page":48,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":154,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"4.2 Campaign"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p48-155', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '4.2 Campaign', 48, 'campaign compromises infrastructure This Relationship describes that the Campaign compromises the related Infrastructure. campaign originates- from location This Relationship describes that the Campaign originates from the related Location.', 'vec_doc-10-oasis-stix21-p48-155', 0, 60, 'v2.1.0', '17ca4bd63b727bff6bee7107fb2dcb87e87ea98dbb490784c78f47f6f8240883', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"4.2 Campaign","subsection":"UNKNOWN","table_id":null,"page":48,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":155,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"4.2 Campaign"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p49-156', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '4.2 Campaign', 49, 'Standards Track Work Product 02 April 2025 - Page 49 of 276Copyright © OASIS Open 2025. All Rights Reserved. For example, an originates-from Relationship from the Glass Gazelle Campaign to a Location representing North America means that Glass Gazelle appears to originate from or is located in North America. campaign targets identity, location, vulnerability This Relationship describes that the Campaign uses exploits of the related Vulnerability or targets the type of victims described by the related Identity or Location. For example, a targets Relationship from the Glass Gazelle Campaign to a Vulnerability in a blogging platform indicates that attacks performed as part of Glass Gazelle often exploit that Vulnerability. Similarly, a targets Relationship from the Glass Gazelle Campaign to an Identity describing the energy sector in the United States means that the Campaign typically carries out attacks against targets in that sector. campaign uses attack-pattern, infrastructure, malware, tool This Relationship describes that attacks carried out as part of the Campaign typically use the related Attack Pattern, Infrastructure, Malware, or Tool. For example, a uses Relationship from the Glass Gazelle Campaign to the xInject Malware indicates that xInject is often used during attacks attributed to that Campaign. A campaign, threat actor, intrusion set, malware, or tool takes infrastructure and compromises and/or uses it for their own. Reverse Relationships indicator indicates campaign See forward relationship for definition. Example { "type": "campaign", "spec_version": "2.1", "id": "campaign--8e2e2d2b-17d4-4cbf-938f-98ee46b3cd3f", "created_by_ref": "identity--f431f809-377b-45e0-aa1c-6a4751cae5ff",', 'vec_doc-10-oasis-stix21-p49-156', 0, 431, 'v2.1.0', '2d5017600d93e23628194cbca022c067185340c49ac49ef87166a8972a8ca829', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"4.2 Campaign","subsection":"UNKNOWN","table_id":null,"page":49,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":156,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"4.2 Campaign"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p50-157', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '4.3 Course of Action', 50, 'Type Name: course-of-action NOTE: The Course of Action object in STIX 2.1 is a stub. It is included to support basicuse cases (such as sharing prose courses of action) but does not support the ability to represent automated courses of action or contain properties to represent metadata about courses of action. Future STIX 2 releases will expand it to include these capabilities. A Course of Action is an action taken either to prevent an attack or to respond to an attack that is in progress. It may describe technical, automatable responses (applying patches, reconfiguring firewalls) but can also describe higher level actions like employee training or policy changes. For example, a course of action to mitigate a vulnerability could describe applying the patch that fixes it. The Course of Action SDO contains a textual description of the action; a reserved action property also serves as a placeholder for future inclusion of machine automatable courses of action. 4.3.1 Properties Required Common Properties type, spec_version, id, created, modified Optional Common Properties created_by_ref, revoked, labels, confidence, lang, external_references, object_marking_refs, granular_markings, extensions Not Applicable Common Properties defanged Course of Action Specific Properties name, description, action Property Name</span Type</span Description</span type (required) string The value of this property MUST be course-of-action. name (required) string A name used to identify the Course of Action. description (optional) string A description that provides more details and context about the Course of Action, potentially including its purpose and its key characteristics. action (optional) RESERVED RESERVED - To capture structured/automated courses of action.', 'vec_doc-10-oasis-stix21-p50-157', 0, 442, 'v2.1.0', '1949b78df16ebacb06067c3e930cf90eedaf581a4cea36f2a59714d77f9ca067', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"4.3 Course of Action","subsection":"UNKNOWN","table_id":null,"page":50,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":157,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"4.3 Course of Action"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p51-158', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '4.3 Course of Action', 51, 'Standards Track Work Product 02 April 2025 - Page 51 of 276Copyright © OASIS Open 2025. All Rights Reserved. 4.3.2 Relationships These are the relationships explicitly defined between the Course of Action object and other STIX Objects. The first section lists the embedded relationships by property name along with their corresponding target. The rest of the table identifies the relationships that can be made from this object type to another object type by way of the Relationship object. The reverse relationships section illustrates the relationships targeting this object type from another object type. They are included here for convenience. For their definitions, please see the “Source” object. Relationships are not restricted to those listed below. Relationships can be created between any objects using the related-to relationship type or, as with open vocabularies, user-defined names.', 'vec_doc-10-oasis-stix21-p51-158', 0, 225, 'v2.1.0', 'a3634779a0ba3f84355ce68c473020ec97f967a4e23f74628f6722fc11ed0226', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"4.3 Course of Action","subsection":"UNKNOWN","table_id":null,"page":51,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":158,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"4.3 Course of Action"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p51-159', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '4.3 Course of Action', 51, 'Embedded Relationships created_by_ref identifier (of type identity) object_marking_refs list of type identifier (of type marking- definition) Common Relationships duplicate-of, derived-from, related-to Source Relationship Type Target Description course-of- action investigates indicator This Relationship describes that the Course of Action can be used to investigate the Indicator. course-of- action mitigates attack- pattern, indicator, malware, tool, vulnerability This Relationship describes that the Course of Action can mitigate (e.g. respond to a threat) the related Attack Pattern, Indicator, Malware, Vulnerability, or Tool. For example, a mitigates Relationship from a Course of Action object to a Malware object indicates that the course of action mitigates the malware. course-of- action remediates malware, vulnerability This Relationship describes that the Course of Action can be used to remediate (e.g. clean up) the malware or vulnerability Reverse Relationships — — — — Example [ {', 'vec_doc-10-oasis-stix21-p51-159', 0, 250, 'v2.1.0', 'dcf3f6231d89418160ba2984cdac7d6dba4bc26417a52bba5ec77fbd7073c3da', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"4.3 Course of Action","subsection":"UNKNOWN","table_id":null,"page":51,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":159,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"4.3 Course of Action"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p52-160', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '4.3 Course of Action', 52, 'Standards Track Work Product 02 April 2025 - Page 52 of 276Copyright © OASIS Open 2025. All Rights Reserved. "type": "course-of-action", "spec_version": "2.1", "id": "course-of-action--8e2e2d2b-17d4-4cbf-938f-98ee46b3cd3f", "created_by_ref": "identity--f431f809-377b-45e0-aa1c-6a4751cae5ff", "created": "2016-04-06T20:03:48.000Z", "modified": "2016-04-06T20:03:48.000Z", "name": "Add TCP port 80 Filter Rule to the existing Block UDP 1434 Filter", "description": "This is how to add a filter rule to block inbound access to TCP port 80 to the existing UDP 1434 filter ..." }, { "type": "relationship", "spec_version": "2.1", "id": "relationship--44298a74-ba52-4f0c-87a3-1824e67d7fad", "created_by_ref": "identity--f431f809-377b-45e0-aa1c-6a4751cae5ff", "created": "2016-04-06T20:07:10.000Z", "modified": "2016-04-06T20:07:10.000Z", "relationship_type": "mitigates", "source_ref": "course-of-action--8e2e2d2b-17d4-4cbf-938f-98ee46b3cd3f", "target_ref": "malware--31b940d4-6f7f-459a-80ea-9c1f17b5891b" }, { "type": "malware", "spec_version": "2.1", "id": "malware--31b940d4-6f7f-459a-80ea-9c1f17b5891b", "created_by_ref": "identity--f431f809-377b-45e0-aa1c-6a4751cae5ff", "created": "2016-04-06T20:07:09.000Z", "modified": "2016-04-06T20:07:09.000Z", "name": "Poison Ivy", ... } ]', 'vec_doc-10-oasis-stix21-p52-160', 0, 320, 'v2.1.0', 'e68fd5b083d1287c36645ea76b5d630a2c44fdc2d53bb05cd17f02f39ec4e7dc', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"4.3 Course of Action","subsection":"UNKNOWN","table_id":null,"page":52,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":160,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"4.3 Course of Action"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p52-161', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '4.4 Grouping', 52, 'Type Name: grouping A Grouping object explicitly asserts that the referenced STIX Objects have a shared context, unlike a STIX Bundle (which explicitly conveys no context). A Grouping object should not be confused with an intelligence product, which should be conveyed via a STIX Report. A STIX Grouping object might represent a set of data that, in time, given sufficient analysis, would mature to convey an incident or threat report as a STIX Report object. For example, a Grouping could be used to characterize an ongoing investigation into a security event or incident. A Grouping object could also be used to assert that the referenced STIX Objects are related to an ongoing analysis process, such as when a threat analyst is collaborating with others in their trust community to examine a series of Campaigns and Indicators. The Grouping SDO contains a list of references to SDOs, SCOs, SROs, and SMOs, along with an explicit statement of the context shared by the content, a textual description, and the name of the grouping. 4.4.1 Properties Required Common Properties type, spec_version, id, created, modified Optional Common Properties created_by_ref, revoked, labels, confidence, lang, external_references, object_marking_refs, granular_markings, extensions Not Applicable Common Properties', 'vec_doc-10-oasis-stix21-p52-161', 0, 326, 'v2.1.0', '1d045786f57ae524b8c4f3c0fa140a552db1993aafc8daab673616c27f03c895', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"4.4 Grouping","subsection":"UNKNOWN","table_id":null,"page":52,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":161,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"4.4 Grouping"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p53-162', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '4.4 Grouping', 53, 'Standards Track Work Product 02 April 2025 - Page 53 of 276Copyright © OASIS Open 2025. All Rights Reserved. defanged Grouping Specific Properties name, description, context, object_refs Property Name</span Type</span Description</span type (required) string The value of this property MUST be grouping. name (required) string A name used to identify the Grouping. description (optional) string A description that provides more details and context about the Grouping, potentially including its purpose and its key characteristics. context (required) open-vocab A short descriptor of the particular context shared by the content referenced by the Grouping. The value for this property SHOULD come from the grouping-context-ov open vocabulary. object_refs (required) list of type identifier Specifies the STIX Objects that are referred to by this Grouping. 4.4.2 Relationships There are no relationships explicitly defined between the Grouping object and other STIX Objects, other than those defined as common relationships. The first section lists the embedded relationships by property name along with their corresponding target. Relationships are not restricted to those listed below. Relationships can be created between any objects using the related-to relationship type or, as with open vocabularies, user-defined names. Embedded Relationships created_by_ref identifier (of type identity) object_marking_refs list of type identifier (of type marking- definition) object_refs list of type identifier (of type STIX Object) Common Relationships duplicate-of, derived-from, related-to Source Relationship Type Target Description — — — — Example', 'vec_doc-10-oasis-stix21-p53-162', 0, 411, 'v2.1.0', 'f5d08657d251a0799281d717a1940f2792efab3b4358656b6e74539e26c747ea', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"4.4 Grouping","subsection":"UNKNOWN","table_id":null,"page":53,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":162,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"4.4 Grouping"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p54-163', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '4.4 Grouping', 54, 'Standards Track Work Product 02 April 2025 - Page 54 of 276Copyright © OASIS Open 2025. All Rights Reserved. A standalone Grouping; the consumer may or may not already have access to the referenced STIX Objects. { "type": "grouping", "spec_version": "2.1", "id": "grouping--84e4d88f-44ea-4bcd-bbf3-b2c1c320bcb3", "created_by_ref": "identity--a463ffb3-1bd9-4d94-b02d-74e4f1658283", "created": "2015-12-21T19:59:11.000Z", "modified": "2015-12-21T19:59:11.000Z", "name": "The Black Vine Cyberespionage Group", "description": "A simple collection of Black Vine Cyberespionage Group attributed intel", "context": "suspicious-activity", "object_refs": [ "indicator--26ffb872-1dd9-446e-b6f5-d58527e5b5d2", "campaign--83422c77-904c-4dc1-aff5-5c38f3a2c55c", "relationship--f82356ae-fe6c-437c-9c24-6b64314ae68a", "file--0203b5c8-f8b6-4ddb-9ad0-527d727f968b" ] }', 'vec_doc-10-oasis-stix21-p54-163', 0, 213, 'v2.1.0', '79368786bebfeb2d2f663f67d2272a7c4b018ee9227276923adf73e3e30b9825', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"4.4 Grouping","subsection":"UNKNOWN","table_id":null,"page":54,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":163,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"4.4 Grouping"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p54-164', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '4.5 Identity', 54, 'Type Name: identity Identities can represent actual individuals, organizations, or groups (e.g., ACME, Inc.) as well as classes of individuals, organizations, systems or groups (e.g., the finance sector). The Identity SDO can capture basic identifying information, contact information, and the sectors that theIdentity belongs to. Identity is used in STIX to represent, among other things, targets of attacks, information sources, object creators, and threat actor identities. 4.5.1 Properties Required Common Properties type, spec_version, id, created, modified Optional Common Properties created_by_ref, revoked, labels, confidence, lang, external_references, object_marking_refs, granular_markings, extensions Not Applicable Common Properties defanged Identity Specific Properties name, description, roles, identity_class, sectors, contact_information Property Name</span Type</span Description</span type (required) string The value of this property MUST be identity. name (required) string A name used to identify the Identity. When referring to a specific entity (e.g., an individual or organization), this property SHOULD', 'vec_doc-10-oasis-stix21-p54-164', 0, 282, 'v2.1.0', '0056342f452bb7bf2de9dfc1bfa495273d964b98e790d2014e04fcec7caba5a3', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"4.5 Identity","subsection":"UNKNOWN","table_id":null,"page":54,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":164,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"4.5 Identity"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p55-165', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '4.5 Identity', 55, 'Standards Track Work Product 02 April 2025 - Page 55 of 276Copyright © OASIS Open 2025. All Rights Reserved. contain the canonical name of the specific entity. description (optional) string A description that provides more details and context about the Identity, potentially including its purpose and its key characteristics. roles (optional) list of type string The list of roles that this Identity performs (e.g., CEO, Domain Administrators, Doctors, Hospital, or Retailer). No open vocabulary is yet defined for this property. identity_class (optional) open-vocab The type of entity that this Identity describes, e.g., an individual or organization. The value for this property SHOULD come from the identity-class-ov open vocabulary. sectors (optional) list of type open-vocab The list of industry sectors that this Identity belongs to. The value for this property SHOULD come from the industry-sector-ov open vocabulary.', 'vec_doc-10-oasis-stix21-p55-165', 0, 231, 'v2.1.0', 'b9f11c52ac1710c19e4a92bca2d4703a4c562eac807fe609bcabd22d7fe6a6c6', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"4.5 Identity","subsection":"UNKNOWN","table_id":null,"page":55,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":165,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"4.5 Identity"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p55-166', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '4.5 Identity', 55, 'contact_information (optional) string The contact information (e-mail, phone number, etc.) for this Identity. No format for this information is currently defined by this specification. 4.5.2 Relationships These are the relationships explicitly defined between the Identity object and other STIX Objects. The first section lists the embedded relationships by property name along with their corresponding target. The rest of the table identifies the relationships that can be made from this object type to another object type by way of the Relationship object. The reverse relationships section illustrates the relationships targeting this object type from another object type. They are included here for convenience. For their definitions, please see the “Source” object. Relationships are not restricted to those listed below. Relationships can be created between any objects using the related-to relationship type or, as with open vocabularies, user-defined names.', 'vec_doc-10-oasis-stix21-p55-166', 0, 242, 'v2.1.0', '5cc1bba304d3b309eb1351ca5dd61e7ee59eeb1564289c48ea6b72e7621344a3', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"4.5 Identity","subsection":"UNKNOWN","table_id":null,"page":55,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":166,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"4.5 Identity"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p56-167', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '4.5 Identity', 56, 'Standards Track Work Product 02 April 2025 - Page 56 of 276Copyright © OASIS Open 2025. All Rights Reserved. identity located-at location This Relationship describes that theIdentity is located at or in the related Location. For example, a located-at relationship from the ACME Corporation to a Location representing the United States means that ACME Corporation is located in the United States. Reverse Relationships attack- pattern, campaign, intrusion- set, malware, threat-actor, tool targets identity See forward relationship for definition. threat-actor attributed- to, impersonates identity See forward relationship for definition. Examples An Identity for an individual named John Smith { "type": "identity", "spec_version": "2.1", "id": "identity--023d105b-752e-4e3c-941c-7d3f3cb15e9e", "created_by_ref": "identity--f431f809-377b-45e0-aa1c-6a4751cae5ff", "created": "2016-04-06T20:03:00.000Z", "modified": "2016-04-06T20:03:00.000Z", "name": "John Smith", "identity_class": "individual" } An Identity for a company named ACME Widget, Inc. { "type": "identity", "spec_version": "2.1", "id": "identity--e5f1b90a-d9b6-40ab-81a9-8a29df4b6b65", "created_by_ref": "identity--f431f809-377b-45e0-aa1c-6a4751cae5ff", "created": "2016-04-06T20:03:00.000Z", "modified": "2016-04-06T20:03:00.000Z", "name": "ACME Widget, Inc.", "identity_class": "organization" }', 'vec_doc-10-oasis-stix21-p56-167', 0, 340, 'v2.1.0', 'f9b01c83c7ca648e1161f43c31d749524b36585e6bac009bc34f7a07500bcb22', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"4.5 Identity","subsection":"UNKNOWN","table_id":null,"page":56,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":167,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"4.5 Identity"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p57-168', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '4.6 Incident', 57, 'Standards Track Work Product 02 April 2025 - Page 57 of 276Copyright © OASIS Open 2025. All Rights Reserved. NOTE: The Incident object in STIX 2.1 is a stub. It is included to support basic use cases but does not contain properties to represent metadata about incidents. Future STIX 2 releases will expand it to include these capabilities. It is suggested that it is used as an extension point for an Incident object defined using the extension facility described in', 'vec_doc-10-oasis-stix21-p57-168', 0, 117, 'v2.1.0', '18035db2f3d7bb9b92ce2aaf7e8ffa9620f1f93afb8bb72bf7f5219cda25b697', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"4.6 Incident","subsection":"UNKNOWN","table_id":null,"page":57,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":168,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"4.6 Incident"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p57-169', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', 'section 7.3.', 57, '4.6.1 Properties Required Common Properties type, spec_version, id, created, modified Optional Common Properties created_by_ref, revoked, labels, confidence, lang, external_references, object_marking_refs, granular_markings, extensions Not Applicable Common Properties defanged Incident Specific Properties name, description Property Name</span Type</span Description</span type (required) string The value of this property MUST be incident. name (required) string A name used to identify the Incident. description (optional) string A description that provides more details and context about the Incident, potentially including its purpose and its key characteristics. 4.6.2 Relationships These are the relationships explicitly defined between the Incident object and other STIX Objects. The first section lists the embedded relationships by property name along with their corresponding target. The rest of the table identifies the relationships that can be made from this object type to another object type by way of the Relationship object. The reverse relationships section illustrates the relationships targeting this object type from another object type. They are included here for convenience. For their definitions, please see the “Source” object. Relationships are not restricted to those listed below. Relationships can be created between any objects using the related-to relationship type or, as with open vocabularies, user-defined names. This table is left intentionally blank and will be fleshed out in a future release. Embedded Relationships created_by_ref identifier (of type identity) object_marking_refs list of type identifier (of type marking- definition)', 'vec_doc-10-oasis-stix21-p57-169', 0, 419, 'v2.1.0', 'ca84895e5463669a2db24052c1afd2ba6492bca7c4df6aee74792b9e40e8c595', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"section 7.3.","subsection":"UNKNOWN","table_id":null,"page":57,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":169,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"section 7.3."}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p58-170', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', 'section 7.3.', 58, 'Standards Track Work Product 02 April 2025 - Page 58 of 276Copyright © OASIS Open 2025. All Rights Reserved. Common Relationships duplicate-of, derived-from, related-to Source Relationship Type Target Description — — — — Example { "type": "incident", "spec_version": "2.1", "id": "incident--8e2e2d2b-17d4-4cbf-938f-98ee46b3cd3f", "created_by_ref": "identity--f431f809-377b-45e0-aa1c-6a4751cae5ff", "created": "2016-04-06T20:03:48.000Z", "modified": "2016-04-06T20:03:48.000Z", "name": "Incident 43", "description": "This incident addresses APT 28 ..." }', 'vec_doc-10-oasis-stix21-p58-170', 0, 139, 'v2.1.0', 'f5557a338d6367d5be80263dd1d7f0c51e920131d13de1d88626ecf0d8462a77', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"section 7.3.","subsection":"UNKNOWN","table_id":null,"page":58,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":170,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"section 7.3."}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p58-171', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '4.7 Indicator', 58, 'Type Name: indicator Indicators contain a pattern that can be used to detect suspicious or malicious cyber activity. For example, an Indicator may be used to represent a set of malicious domains and use the STIX Patterning Language (see section 9) to specify these domains. The Indicator SDO contains a simple textual description, the Kill Chain Phases that it detects behavior in, a time window for when the Indicator is valid or useful, and a required pattern property to capture a structured detection pattern. Conforming STIX implementations MUST support the STIX Patterning Language as defined in section 9. Relationships from the Indicator can describe the malicious or suspicious behavior that it directly detects (Malware, Tool, and Attack Pattern). In addition, it may also imply the presence of a Campaigns, Intrusion Sets, and Threat Actors, etc. 4.7.1 Properties Required Common Properties type, spec_version, id, created, modified Optional Common Properties created_by_ref, revoked, labels, confidence, lang, external_references, object_marking_refs, granular_markings, extensions Not Applicable Common Properties defanged Indicator Specific Properties', 'vec_doc-10-oasis-stix21-p58-171', 0, 292, 'v2.1.0', 'aa361d1d8e461ebbb8f2a66303e98f78598647fa9122772fb6f84e1b4970fb60', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"4.7 Indicator","subsection":"UNKNOWN","table_id":null,"page":58,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":171,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"4.7 Indicator"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p59-172', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '4.7 Indicator', 59, 'Standards Track Work Product 02 April 2025 - Page 59 of 276Copyright © OASIS Open 2025. All Rights Reserved. name, description, indicator_types, pattern, pattern_type, pattern_version, valid_from,valid_until, kill_chain_phases Property Name</span Type</span Description</span type (required) string The value of this property MUST be indicator. name (optional) string A name used to identify the Indicator. Producers SHOULD provide this property to help products and analysts understand what this Indicator actually does. description (optional) string A description that provides more details and context about the Indicator, potentially including its purpose and its key characteristics. Producers SHOULD provide this property to help products and analysts understand what this Indicator actually does. indicator_types (optional) list of type open-vocab A set of categorizations for this indicator. The values for this property SHOULD come from the indicator-type-ov open vocabulary. pattern (required) string The detection pattern for this Indicator MAY be expressed as a STIX Pattern as specified in section 9 or another appropriate language such as SNORT, YARA, etc. pattern_type (required) open-vocab The pattern language used in this indicator. The value for this property SHOULD come from the pattern-type-ov open vocabulary. The value of this property MUST match the type of pattern data included in the pattern property. pattern_version (optional) string The version of the pattern language that is used for the data in the pattern property which MUST match the type of pattern data included in the pattern property. For patterns that do not have a formal specification, the build or code version', 'vec_doc-10-oasis-stix21-p59-172', 0, 427, 'v2.1.0', '2d0b5eb9ff942dcea8648e3db1122041c3787064abb913ad4d0c711c10dd678c', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"4.7 Indicator","subsection":"UNKNOWN","table_id":null,"page":59,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":172,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"4.7 Indicator"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p60-173', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '4.7 Indicator', 60, 'Standards Track Work Product 02 April 2025 - Page 60 of 276Copyright © OASIS Open 2025. All Rights Reserved. that the pattern is known to work with SHOULD be used. For the STIX Pattern language, the default value is determined by the specification version of the object. For other languages, the default value SHOULD be the latest version of the patterning language at the time of this object’s creation. valid_from (required) timestamp The time from which this Indicator is considered a valid indicator of the behaviors it is related or represents. valid_until (optional) timestamp The time at which this Indicator should no longer be considered a valid indicator of the behaviors it is related to or represents. If the valid_until property is omitted, then there is no constraint on the latest time for which the Indicator is valid. This MUST be greater than the timestamp in the valid_from property.', 'vec_doc-10-oasis-stix21-p60-173', 0, 226, 'v2.1.0', 'dbbc1bd28b2f93b677f5545b02f1f2afc6591a5b4eba6d68e676cadc2812d3ca', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"4.7 Indicator","subsection":"UNKNOWN","table_id":null,"page":60,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":173,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"4.7 Indicator"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p60-174', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '4.7 Indicator', 60, 'kill_chain_phases (optional) list of type kill-chain-phase The kill chain phase(s) to which this Indicator corresponds. 4.7.2 Relationships These are the relationships explicitly defined between the Indicator object and other STIX Objects. The first section lists the embedded relationships by property name along with their corresponding target. The rest of the table identifies the relationships that can be made from this object type to another object type by way of the Relationship object. The reverse relationships section illustrates the relationships targeting this object type from another object type. They are included here for convenience. For their definitions, please see the “Source” object. Relationships are not restricted to those listed below. Relationships can be created between any objects using the related-to relationship type or, as with open vocabularies, user-defined names.', 'vec_doc-10-oasis-stix21-p60-174', 0, 226, 'v2.1.0', 'e188758de1bb8dfecfd28be880694201b5d4b12c11096012cb06dfd9122c165c', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"4.7 Indicator","subsection":"UNKNOWN","table_id":null,"page":60,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":174,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"4.7 Indicator"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p61-175', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '4.7 Indicator', 61, 'Standards Track Work Product 02 April 2025 - Page 61 of 276Copyright © OASIS Open 2025. All Rights Reserved. indicator indicates attack-pattern, campaign, infrastructure, intrusion-set, malware, threat-actor, tool This Relationship describes that theIndicator can detect evidence of the related Attack Pattern, Campaign, Infrastructure, Intrusion Set, Malware, Threat Actor, or Tool. This evidence may not be direct: for example, the Indicator may detect secondary evidence of the Campaign, such as malware or behavior commonly used by that Campaign. For example, an indicates Relationship from an Indicator to a Campaign object representing Glass Gazelle means that the Indicator is capable of detecting evidence of Glass Gazelle, such as command and control IPs commonly used by that Campaign. indicator based-on observed-data This relationship describes that the indicator was created based on information from an observed-data object.', 'vec_doc-10-oasis-stix21-p61-175', 0, 235, 'v2.1.0', '5adf55005b887c1aeff150ca9a6f9ac547dddb5f2d7c7946aa830e1766c09f9c', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"4.7 Indicator","subsection":"UNKNOWN","table_id":null,"page":61,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":175,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"4.7 Indicator"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p61-176', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '4.7 Indicator', 61, 'For example, an indicator may be created based upon the observation of a spearphishing email or created based upon analysis performed on a piece of malware or adversary infrastructure. Reverse Relationships course-of- action investigates, mitigates indicastor See forward relationship for definition. Example Indicator itself, with context [ { "type": "indicator", "spec_version": "2.1", "id": "indicator--8e2e2d2b-17d4-4cbf-938f-98ee46b3cd3f", "created_by_ref": "identity--f431f809-377b-45e0-aa1c-6a4751cae5ff", "created": "2016-04-06T20:03:48.000Z", "modified": "2016-04-06T20:03:48.000Z", "indicator_types": ["malicious-activity"], "name": "Poison Ivy Malware", "description": "This file is part of Poison Ivy", "pattern": "[ file:hashes.''SHA-256'' = ''4bac27393bdd9777ce02453256c5577cd02275510b2227f473d03f533924f877'' ]", "pattern_type": "stix", "valid_from": "2016-01-01T00:00:00Z" }, { "type": "relationship",', 'vec_doc-10-oasis-stix21-p61-176', 0, 229, 'v2.1.0', '58a28a7ef5a57a087a21c141b9f9a1a6290b9342c41bb7befa6d0b4c156ed314', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"4.7 Indicator","subsection":"UNKNOWN","table_id":null,"page":61,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":176,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"4.7 Indicator"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p62-177', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '4.7 Indicator', 62, 'Standards Track Work Product 02 April 2025 - Page 62 of 276Copyright © OASIS Open 2025. All Rights Reserved. "spec_version": "2.1", "id": "relationship--44298a74-ba52-4f0c-87a3-1824e67d7fad", "created_by_ref": "identity--f431f809-377b-45e0-aa1c-6a4751cae5ff", "created": "2016-04-06T20:06:37.000Z", "modified": "2016-04-06T20:06:37.000Z", "relationship_type": "indicates", "source_ref": "indicator--8e2e2d2b-17d4-4cbf-938f-98ee46b3cd3f", "target_ref": "malware--31b940d4-6f7f-459a-80ea-9c1f17b5891b" }, { "type": "malware", "spec_version": "2.1", "id": "malware--31b940d4-6f7f-459a-80ea-9c1f17b5891b", "is_family": true, "created": "2016-04-06T20:07:09.000Z", "modified": "2016-04-06T20:07:09.000Z", "created_by_ref": "identity--f431f809-377b-45e0-aa1c-6a4751cae5ff", "name": "Poison Ivy", "malware_types": ["trojan"] } ]', 'vec_doc-10-oasis-stix21-p62-177', 0, 206, 'v2.1.0', '7fb574e8a2070d4a1dd1fde3820b50be8eadbc86033bb6cba1565ea5d8448986', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"4.7 Indicator","subsection":"UNKNOWN","table_id":null,"page":62,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":177,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"4.7 Indicator"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p62-178', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '4.8 Infrastructure', 62, 'Type Name: infrastructure The Infrastructure SDO represents a type of TTP and describes any systems, software services and any associated physical or virtual resources intended to support some purpose (e.g., C2 servers used as part of an attack, device or server that are part of defense, database servers targeted by an attack, etc.). While elements of an attack can be represented by other SDOs or SCOs, the Infrastructure SDO represents a named group of related data that constitutes the infrastructure. 4.8.1 Properties Required Common Properties type, spec_version, id, created, modified Optional Common Properties created_by_ref, revoked, labels, confidence, lang, external_references, object_marking_refs, granular_markings, extensions Not Applicable Common Properties defanged Infrastructure Specific Properties name, description, infrastructure_types, aliases, kill_chain_phases, first_seen, last_seen Property Name Type Description type (required) string The value of this property MUST be infrastructure. name (required) string A name or characterizing text used to identify the Infrastructure.', 'vec_doc-10-oasis-stix21-p62-178', 0, 277, 'v2.1.0', 'a94504410157c0c9fdcdcd45094a1c33fbe152950f2415fa2bc761f73f53744b', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"4.8 Infrastructure","subsection":"UNKNOWN","table_id":null,"page":62,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":178,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"4.8 Infrastructure"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p63-179', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '4.8 Infrastructure', 63, 'Standards Track Work Product 02 April 2025 - Page 63 of 276Copyright © OASIS Open 2025. All Rights Reserved. description (optional) string A description that provides moredetails and context about the Infrastructure, potentially including its purpose, how it is being used, how it relates to other intelligence activities captured in related objects, and its key characteristics. infrastructure_types (optional) list of type open-vocab The type of infrastructure being described. The values for this property SHOULD come from the infrastructure- type-ov open vocabulary. aliases (optional) list of type string Alternative names used to identify this Infrastructure. kill_chain_phases (optional) list of type kill-chain-phase The list of Kill Chain Phases for which this Infrastructure is used. first_seen (optional) timestamp The time that this Infrastructure was first seen performing malicious activities.', 'vec_doc-10-oasis-stix21-p63-179', 0, 227, 'v2.1.0', '2f1474e4fe0e475ea5527dadcbe77a705bc616c9be23dc7e6562ba9f5e57302e', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"4.8 Infrastructure","subsection":"UNKNOWN","table_id":null,"page":63,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":179,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"4.8 Infrastructure"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p63-180', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '4.8 Infrastructure', 63, 'last_seen (optional) timestamp The time that this Infrastructure was last seen performing malicious activities. If this property and the first_seen property are both defined, then this property MUST be greater than or equal to the timestamp in the first_seen property. 4.8.2 Relationships These are the relationships explicitly defined between the Infrastructure object and other STIX Objects. The first section lists the embedded relationships by property name along with their corresponding target. The rest of the table identifies the relationships that can be made from this object type to another object type by way of the Relationship object. The reverse relationships section illustrates the relationships targeting this object type from another object type. They are included here for convenience. For their definitions, please see the “Source” object. Relationships are not restricted to those listed below.', 'vec_doc-10-oasis-stix21-p63-180', 0, 229, 'v2.1.0', 'c6428a4bbd97a3fc1f26a9c6a4d59f2e91b6a56666caec3e72bcfe41990599ee', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"4.8 Infrastructure","subsection":"UNKNOWN","table_id":null,"page":63,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":180,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"4.8 Infrastructure"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p63-181', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '4.8 Infrastructure', 63, 'Relationships can be created between any objects using the related-to relationship type or, as with open vocabularies, user-defined names. Embedded Relationships created_by_ref identifier (of type identity) object_marking_refs list of type identifier (of type marking- definition) Common Relationships', 'vec_doc-10-oasis-stix21-p63-181', 0, 76, 'v2.1.0', '49bb045d710bb4bd02f9a02cba80f7bf8ef94d45b9015c9cf59778b4400b4d2e', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"4.8 Infrastructure","subsection":"UNKNOWN","table_id":null,"page":63,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":181,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"4.8 Infrastructure"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p64-182', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '4.8 Infrastructure', 64, 'Standards Track Work Product 02 April 2025 - Page 64 of 276Copyright © OASIS Open 2025. All Rights Reserved. duplicate-of, derived-from, related-to Source Relationship Type Target Description infrastructure communicates- with infrastructure, ipv4-addr, ipv6-addr, domain-name, url This Relationship documents that this infrastructure instance communicates with the defined network addressable resource. For example, a botnet could communicate with a crypto-currency mining pool. This does not mean that the pool is a part of this infrastructure. infrastructure consists-of infrastructure, observed-data, <All STIX Cyber- observable Objects&gt This Relationship documents the objects that are used to make up an infrastructure instance, such as ipv4-addr, ipv6-addr, domain- name, url. An infrastructure instance consists of zero or more objects. While not all SCO types will make sense as infrastructure, allowing any type of SCO prevents artificially restricting what could be used.', 'vec_doc-10-oasis-stix21-p64-182', 0, 246, 'v2.1.0', '67d1567b45f8d03379ff62875ec873620d048b201c93aa287dc07d1ed4d568f3', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"4.8 Infrastructure","subsection":"UNKNOWN","table_id":null,"page":64,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":182,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"4.8 Infrastructure"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p64-183', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '4.8 Infrastructure', 64, 'infrastructure controls infrastructure, malware This Relationship describes that this infrastructure controls some other infrastructure or a malware instance (or family). infrastructure delivers malware This Relationship describes that this infrastructure is used to actively deliver a malware instance (or family). infrastructure has vulnerability This Relationship describes that this specific Infrastructure has this specific Vulnerability. For example, a web server may not have been patched and currently is impacted by a CVE. infrastructure hosts tool, malware This Relationship describes that this infrastructure has a tool running on it or is used to passively host the tool / malware. For example, an SSH server may be hosted on a piece of infrastructure. infrastructure located-at location This Relationship describes that the infrastructure originates from the', 'vec_doc-10-oasis-stix21-p64-183', 0, 218, 'v2.1.0', 'a4b0c445887c7389b2cc2d5d5082d8e23a85b75e9dfa394b17970716261d5ad9', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"4.8 Infrastructure","subsection":"UNKNOWN","table_id":null,"page":64,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":183,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"4.8 Infrastructure"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p65-184', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '4.8 Infrastructure', 65, 'Standards Track Work Product 02 April 2025 - Page 65 of 276Copyright © OASIS Open 2025. All Rights Reserved. related location. For example, a located-at relationship from the Red Orca C2 infrastructure to a Location representing North America means that the Red Orca C2 Infrastructure appears to originate from or is located in North America. infrastructure uses infrastructure This Relationship describes that this infrastructure uses this other infrastructure to achieve its objectives. Reverse Relationships campaign, intrusion- set, threat- actor compromises infrastructure See forward relationship for definition. malware beacons-to, exfiltrates- to infrastructure See forward relationship for definition. intrusion- set, threat- actor hosts infrastructure See forward relationship for definition. indicator indicates infrastructure See forward relationship for definition. intrusion- set, threat- actor owns infrastructure See forward relationship for definition. malware, tool targets infrastructure See forward relationship for definition. campaign, intrusion- set, malware, threat-actor, tool uses infrastructure See forward relationship for definition. Example (additional example can be found in Appendix C) Malware C2 Infrastructure', 'vec_doc-10-oasis-stix21-p65-184', 0, 311, 'v2.1.0', 'd2108dd608454415e287960baa969483c04e2a205156bd2b13f8bd1096a969b3', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"4.8 Infrastructure","subsection":"UNKNOWN","table_id":null,"page":65,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":184,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"4.8 Infrastructure"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p66-185', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '4.8 Infrastructure', 66, 'Standards Track Work Product 02 April 2025 - Page 66 of 276Copyright © OASIS Open 2025. All Rights Reserved. [ { "type":"infrastructure", "spec_version": "2.1", "id":"infrastructure--38c47d93-d984-4fd9-b87b-d69d0841628d", "created":"2016-05-07T11:22:30.000Z", "modified":"2016-05-07T11:22:30.000Z", "name":"Poison Ivy C2", "infrastructure_types": ["command-and-control"] }, { "type": "relationship", "spec_version": "2.1", "id": "relationship--7aebe2f0-28d6-48a2-9c3e-b0aaa60266ed", "created": "2016-05-09T08:17:27.000Z", "modified": "2016-05-09T08:17:27.000Z", "relationship_type": "controls", "source_ref": "infrastructure--38c47d93-d984-4fd9-b87b-d69d0841628d", "target_ref": "malware--16f4f3f9-1b68-4abb-bb66-7639d49f1e30" }, { "type": "malware", "spec_version": "2.1", "id": "malware--16f4f3f9-1b68-4abb-bb66-7639d49f1e30", "created": "2016-05-08T14:31:09.000Z", "modified": "2016-05-08T14:31:09.000Z", "is_family": true, "malware_types":[ "remote-access-trojan" ], "name": "Poison Ivy" }, { "type": "relationship", "spec_version": "2.1", "id": "relationship--7aebe2f0-28d6-48a2-9c3e-b0aaa60266ef", "created": "2016-05-09T08:17:27.000Z", "modified": "2016-05-09T08:17:27.000Z", "relationship_type": "consists-of", "source_ref": "infrastructure--38c47d93-d984-4fd9-b87b-d69d0841628d", "target_ref": "ipv4-addr--28bb3599-77cd-5a82-a950-b5bc3caf07c4" }, { "type": "relationship", "spec_version": "2.1", "id": "relationship--b82b2819-3b86-4bd5-afb3-fa36cfbc3f18", "created": "2016-05-09T08:17:27.000Z", "modified": "2016-05-09T08:17:27.000Z", "relationship_type": "consists-of", "source_ref": "infrastructure--38c47d93-d984-4fd9-b87b-d69d0841628d", "target_ref": "ipv4-addr--84445275-e371-444b-baea-ac7d07a180fd" },', 'vec_doc-10-oasis-stix21-p66-185', 0, 429, 'v2.1.0', 'd55cb5908b639017be33c51ef1eb8e0763105b0e59119fe4a3c3862661238930', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"4.8 Infrastructure","subsection":"UNKNOWN","table_id":null,"page":66,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":185,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"4.8 Infrastructure"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p67-186', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '4.8 Infrastructure', 67, 'Standards Track Work Product 02 April 2025 - Page 67 of 276Copyright © OASIS Open 2025. All Rights Reserved. { "type": "ipv4-addr", "spec_version": "2.1", "id": "ipv4-addr--28bb3599-77cd-5a82-a950-b5bc3caf07c4", "value": "198.51.100.3" }, { "type": "ipv4-addr", "spec_version": "2.1", "id": "ipv4-addr--055987b7-7d94-5326-8e20-c3dad8241976", "value": "198.52.200.4" } ]', 'vec_doc-10-oasis-stix21-p67-186', 0, 93, 'v2.1.0', '503329ccaa721d908c226fcc71d1073c823ed0e7ab3a5fa21a25880d05d1b2b6', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"4.8 Infrastructure","subsection":"UNKNOWN","table_id":null,"page":67,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":186,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"4.8 Infrastructure"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p67-187', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '4.9 Intrusion Set', 67, 'Type Name: intrusion-set An Intrusion Set is a grouped set of adversarial behaviors and resources with common properties that is believed to be orchestrated by a single organization. An Intrusion Set may capture multiple Campaigns or other activities that are all tied together by shared attributes indicating a commonly known or unknown Threat Actor. New activity can be attributed to an Intrusion Set even if the Threat Actors behind the attack are not known. Threat Actors can move from supporting one Intrusion Set to supporting another, or they may support multiple Intrusion Sets. Where a Campaign is a set of attacks over a period of time against a specific set of targets to achieve some objective, an Intrusion Set is the entire attack package and may be used over a very long period of time in multiple Campaigns to achieve potentially multiple purposes. While sometimes an Intrusion Set is not active, or changes focus, it is usually difficult to know if it has truly disappeared or ended. Analysts may have varying level of fidelity on attributing an Intrusion Set back to Threat Actors. 4.9.1 Properties Required Common Properties type, spec_version, id, created, modified Optional Common Properties created_by_ref, revoked, labels, confidence, lang, external_references, object_marking_refs, granular_markings, extensions Not Applicable Common Properties defanged Intrusion Set Specific Properties name, description, aliases, first_seen, last_seen, goals, resource_level, primary_motivation, secondary_motivations Property Name Type Description type (required) string The value of this property MUST be intrusion-set.', 'vec_doc-10-oasis-stix21-p67-187', 0, 408, 'v2.1.0', '784603b53d7d47381ae59b97cde15967b28b16b8a6a51888e07ca5cbc517680a', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"4.9 Intrusion Set","subsection":"UNKNOWN","table_id":null,"page":67,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":187,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"4.9 Intrusion Set"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p68-188', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '4.9 Intrusion Set', 68, 'Standards Track Work Product 02 April 2025 - Page 68 of 276Copyright © OASIS Open 2025. All Rights Reserved. name (required) string A name or characterizing text used toidentify the Intrusion Set. description (optional) string A description that provides more details and context about the Intrusion Set, potentially including its purpose and its key characteristics. aliases (optional) list of type string Alternative names used to identify this Intrusion Set. first_seen (optional) timestamp The time that this Intrusion Set was first seen. A summary property of data from sightings and other data that may or may not be available in STIX. If new sightings are received that are earlier than the first seen timestamp, the object may be updated to account for the new data. last_seen (optional) timestamp The time that this Intrusion Set was last seen. This property is a summary property of data from sightings and other data that may or may not be available in STIX.', 'vec_doc-10-oasis-stix21-p68-188', 0, 243, 'v2.1.0', '75212d8bd20c4ad66edff2655fd0d5e39b906fcd4d656d29bc2f3b9d3b8aec19', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"4.9 Intrusion Set","subsection":"UNKNOWN","table_id":null,"page":68,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":188,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"4.9 Intrusion Set"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p68-189', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '4.9 Intrusion Set', 68, 'If new sightings are received that are later than the last seen timestamp, the object may be updated to account for the new data. If this property and the first_seen property are both defined, then this property MUST be greater than or equal to the timestamp in the first_seen property. goals (optional) list of type string The high-level goals of this Intrusion Set, namely, what are they trying to do. For example, they may be motivated by personal gain, but their goal is to steal credit card numbers. To do this, they may execute specific Campaigns that have detailed objectives like compromising point of sale systems at a large retailer. Another example: to gain information about latest merger and IPO information from ACME Bank. resource_level (optional) open-vocab This property specifies the organizational level at which this Intrusion Set typically works, which in turn determines the resources available to this Intrusion Set for use in an attack. The value for this property SHOULD come', 'vec_doc-10-oasis-stix21-p68-189', 0, 250, 'v2.1.0', 'ba1574643ce9a10ce1f55a707324fdabb4fae8d840e7e73eb0dee665072c54f9', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"4.9 Intrusion Set","subsection":"UNKNOWN","table_id":null,"page":68,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":189,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"4.9 Intrusion Set"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p69-190', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '4.9 Intrusion Set', 69, 'Standards Track Work Product 02 April 2025 - Page 69 of 276Copyright © OASIS Open 2025. All Rights Reserved. from the attack-resource-level-ov open vocabulary. primary_motivation (optional) open-vocab The primary reason, motivation, or purpose behind this Intrusion Set. The motivation is why the Intrusion Set wishes to achieve the goal (what they are trying to achieve). The value for this property SHOULD come from the attack-motivation-ov open vocabulary. secondary_motivations (optional) list of type open-vocab The secondary reasons, motivations, or purposes behind this Intrusion Set. These motivations can exist as an equal or near- equal cause to the primary motivation. However, it does not replace or necessarily magnify the primary motivation, but it might indicate additional context. The position in the list has no significance. The values for this property SHOULD come from the attack-motivation-ov open vocabulary.', 'vec_doc-10-oasis-stix21-p69-190', 0, 233, 'v2.1.0', 'be9015a716d0d342482c72e1349b2274bfd6c756b408aa90c69661499c2b18c9', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"4.9 Intrusion Set","subsection":"UNKNOWN","table_id":null,"page":69,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":190,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"4.9 Intrusion Set"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p69-191', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '4.9 Intrusion Set', 69, '4.9.2 Relationships These are the relationships explicitly defined between the Intrusion Set object and other STIX Objects. The first section lists the embedded relationships by property name along with their corresponding target. The rest of the table identifies the relationships that can be made from this object type to another object type by way of the Relationship object. The reverse relationships section illustrates the relationships targeting this object type from another object type. They are included here for convenience. For their definitions, please see the “Source” object. Relationships are not restricted to those listed below. Relationships can be created between any objects using the related-to relationship type or, as with open vocabularies, user-defined names.', 'vec_doc-10-oasis-stix21-p69-191', 0, 197, 'v2.1.0', '63785332db5d366d83f5ae48e4d170da02ae087dcbef971cdff6671db3a3af9a', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"4.9 Intrusion Set","subsection":"UNKNOWN","table_id":null,"page":69,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":191,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"4.9 Intrusion Set"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p69-192', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '4.9 Intrusion Set', 69, 'Embedded Relationships created_by_ref identifier (of type identity) object_marking_refs list of type identifier (of type marking- definition) Common Relationships duplicate-of, derived-from, related-to Source Relationship Type Target Description intrusion-set attributed-to threat-actor This Relationship describes that the related Threat Actor is involved in carrying out the Intrusion Set. For example, an attributed-to', 'vec_doc-10-oasis-stix21-p69-192', 0, 106, 'v2.1.0', '3db2046b338d9c690e11325075b173e3c651abae2fbc080fa4a423cae6351973', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"4.9 Intrusion Set","subsection":"UNKNOWN","table_id":null,"page":69,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":192,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"4.9 Intrusion Set"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p70-193', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '4.9 Intrusion Set', 70, 'Standards Track Work Product 02 April 2025 - Page 70 of 276Copyright © OASIS Open 2025. All Rights Reserved. Relationship from the Red Orca Intrusion Set to the Urban Fowl Threat Actor means that the actor carried out or was involved in some of the activity described by the Intrusion Set. intrusion-set compromises infrastructure This Relationship describes that the Intrusion Set compromises the related Infrastructure. intrusion-set hosts, owns infrastructure This Relationship describes that the Intrusion Set hosts or owns the related Infrastructure (e.g. an actor that rents botnets to other threat actors). intrusion-set originates- from location This Relationship describes that the Intrusion Set originates from the related location and SHOULD NOT be used to define attribution. For example, an originates-from relationship from the Red Orca Intrusion Set to a Location representing North America means that the Red Orca Intrusion Set appears to originate from or is located in North America.', 'vec_doc-10-oasis-stix21-p70-193', 0, 251, 'v2.1.0', 'c03ff296f494e31224719ed8727dfd3518b7ebe9025c8f27f3b4f41c5a1fcb36', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"4.9 Intrusion Set","subsection":"UNKNOWN","table_id":null,"page":70,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":193,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"4.9 Intrusion Set"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p70-194', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '4.9 Intrusion Set', 70, 'intrusion-set targets identity, location, vulnerability This Relationship describes that the Intrusion Set uses exploits of the related Vulnerability or targets the type of victims described by the related Identity or Location. For example, a targetsRelationship from the Red Orca Intrusion Set to a Vulnerability in a blogging platform indicates that attacks performed as part of Red Orca often exploit that Vulnerability. Similarly, a targets Relationship from the Red Orca Intrusion Set to an Identity describing the energy sector in the United States means that the Intrusion Set typically carries out attacks against targets in that sector. intrusion-set uses attack-pattern, infrastructure, malware, tool This Relationship describes that attacks carried out as part of the Intrusion Set typically use the related Attack Pattern, Infrastructure, Malware, or Tool. For example, a uses Relationship from the Red Orca Intrusion Set to', 'vec_doc-10-oasis-stix21-p70-194', 0, 234, 'v2.1.0', '7a9adbb3b998128728498b490ebe2c836a0fb686f41d2262095f1e3752ba21bd', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"4.9 Intrusion Set","subsection":"UNKNOWN","table_id":null,"page":70,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":194,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"4.9 Intrusion Set"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p71-195', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '4.9 Intrusion Set', 71, 'Standards Track Work Product 02 April 2025 - Page 71 of 276Copyright © OASIS Open 2025. All Rights Reserved. the xInject Malware indicates that xInject is often used during attacks attributed to that Intrusion Set. Reverse Relationships campaign attributed-to intrusion-set See forward relationship for definition. malware authored-by intrusion-set See forward relationship for definition. indicator indicates intrusion-set See forward relationship for definition. Example { "type": "intrusion-set", "spec_version": "2.1", "id": "intrusion-set--4e78f46f-a023-4e5f-bc24-71b3ca22ec29", "created_by_ref": "identity--f431f809-377b-45e0-aa1c-6a4751cae5ff", "created": "2016-04-06T20:03:48.000Z", "modified": "2016-04-06T20:03:48.000Z", "name": "Bobcat Breakin", "description": "Incidents usually feature a shared TTP of a bobcat being released within the building containing network access, scaring users to leave their computers without locking them first. Still determining where the threat actors are getting the bobcats.", "aliases": ["Zookeeper"], "goals": ["acquisition-theft", "harassment", "damage"] }', 'vec_doc-10-oasis-stix21-p71-195', 0, 276, 'v2.1.0', '508bad083a46344f896850bd0b32629e8aaa5783469d56b86bc3835abe065b61', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"4.9 Intrusion Set","subsection":"UNKNOWN","table_id":null,"page":71,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":195,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"4.9 Intrusion Set"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p71-196', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '4.10 Location', 71, 'Type Name: location A Location represents a geographic location. The location may be described as any, some or all of the following: region (e.g., North America), civic address (e.g. New York, US), latitude and longitude. Locations are primarily used to give context to other SDOs. For example, a Location could be used in a relationship to describe that the Bourgeois Swallow intrusion set originates from Eastern Europe. The Location SDO can be related to an Identity or Intrusion Set to indicate that the identity or intrusion set is located in that location. It can also be related from a malware or attack pattern to indicate that they target victims in that location. The Location object describes geographic areas, not governments, even in cases where that area might have a government. For example, a Location representing the United States describes the United States as a geographic area, not the federal government of the United States. At least one of the following properties/sets of properties MUST be provided: region country latitude and longitude When a combination of properties is provided (e.g. a region and a latitude and longitude) the more precise properties are what the location describes. In other words, if a location contains both a region of northern-america and a country of us, then the location describes the United States, not all of North America. In cases where a latitude and longitude are specified without a precision, the location describes the most precise other value. If precision is specified, then the datum for latitude and longitude MUST be WGS 84. Organizations specifying a designated location using latitude and longitude SHOULD specify the precision which is', 'vec_doc-10-oasis-stix21-p71-196', 0, 427, 'v2.1.0', '233a038f2341def431739b2c546a869839f6c6f452a5b89bfa36a1f290f04b9b', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"4.10 Location","subsection":"UNKNOWN","table_id":null,"page":71,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":196,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"4.10 Location"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p72-197', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '4.10 Location', 72, 'Standards Track Work Product 02 April 2025 - Page 72 of 276Copyright © OASIS Open 2025. All Rights Reserved. appropriate for the scope of the location being identified. The scope is defined by the boundary as outlined by the precision around the coordinates. 4.10.1 Properties Required Common Properties type, spec_version, id, created, modified Optional Common Properties created_by_ref, revoked, labels, confidence, lang, external_references, object_marking_refs,granular_markings, extensions Not Applicable Common Properties defanged Location Specific Properties name, description, latitude, longitude, precision, region, country, administrative_area, city, street_address, postal_code Property Name Type Description type (required) string The value of this property MUST be location. name (optional) string A name used to identify the Location. description (optional) string A textual description of the Location. latitude (optional) float The latitude of the Location in decimal degrees.', 'vec_doc-10-oasis-stix21-p72-197', 0, 248, 'v2.1.0', '2b808d36d0ce2672122b3e7a3ca94e3b015e9040e0592071f3a045c1aa4ccacf', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"4.10 Location","subsection":"UNKNOWN","table_id":null,"page":72,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":197,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"4.10 Location"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p72-198', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '4.10 Location', 72, 'Positive numbers describe latitudes north of the equator, and negative numbers describe latitudes south of the equator. The value of this property MUST be between -90.0 and 90.0, inclusive. If the longitude property is present, this property MUST be present. longitude (optional) float The longitude of the Location in decimal degrees. Positive numbers describe longitudes east of the prime meridian and negative numbers describe longitudes west of the prime meridian. The value of this property MUST be between -180.0 and 180.0, inclusive. If the latitude property is present, this property MUST be present. precision (optional) float Defines the precision of the coordinates specified by the latitude and longitude properties. This is measured in meters. The actual Location may be anywhere up to precision meters from the defined point. If this property is not present, then the precision is unspecified.', 'vec_doc-10-oasis-stix21-p72-198', 0, 227, 'v2.1.0', '6f75c1ec05267c1e773fece127eb2bee7dbac23fce0df90335a75fd536894115', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"4.10 Location","subsection":"UNKNOWN","table_id":null,"page":72,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":198,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"4.10 Location"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p73-199', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '4.10 Location', 73, 'Standards Track Work Product 02 April 2025 - Page 73 of 276Copyright © OASIS Open 2025. All Rights Reserved. If this property is present, the latitude and longitude properties MUST be present. region (optional) open-vocab The region that this Location describes. The value for this property SHOULD come from the region-ov open vocabulary. country (optional) string The country that this Location describes. This property SHOULD contain a valid ISO 3166-1 ALPHA-2 Code [ISO3166-1]. administrative_area (optional) string The state, province, or other sub-national administrative area that this Location describes. This property SHOULD contain a valid ISO 3166-2 Code [ISO3166-2]. city (optional) string The city that this Location describes. street_address (optional) string The street address that this Location describes. This property includes all aspects or parts of the street address. For example, some addresses may have multiple lines including a mailstop or apartment number.', 'vec_doc-10-oasis-stix21-p73-199', 0, 246, 'v2.1.0', '8ab00c517e95b85a7df4037f8880074bcd556e1dba16206ac85f1d38367c28c4', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"4.10 Location","subsection":"UNKNOWN","table_id":null,"page":73,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":199,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"4.10 Location"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p73-200', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '4.10 Location', 73, 'postal_code (optional) string The postal code for the Location. 4.10.2 Relationships These are the relationships explicitly defined between the Location object and other STIX Objects. The first section lists the embedded relationships by property name along with their corresponding target. The rest of the table identifies the relationships that can be made from this object type to another object type by way of the Relationship object. The reverse relationships section illustrates the relationships targeting this object type from another object type. They are included here for convenience. For their definitions, please see the “Source” object. Relationships are not restricted to those listed below. Relationships can be created between any objects using the related-to relationship type or, as with open vocabularies, user-defined names.', 'vec_doc-10-oasis-stix21-p73-200', 0, 212, 'v2.1.0', 'c489d60eb48ed51624b93cd1ae53fcdbd01101c50d3837be239defeaf0a339dd', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"4.10 Location","subsection":"UNKNOWN","table_id":null,"page":73,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":200,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"4.10 Location"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p73-201', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '4.10 Location', 73, 'Embedded Relationships created_by_ref identifier (of type identity) object_marking_refs list of type identifier (of type marking- definition) Common Relationships duplicate-of, derived-from, related-to Source Relationship Type Target Description — — — —', 'vec_doc-10-oasis-stix21-p73-201', 0, 64, 'v2.1.0', '2cde9d759bb979082aaeb00f3a88caf74196af12445f6f2dec7c9623bcd17733', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"4.10 Location","subsection":"UNKNOWN","table_id":null,"page":73,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":201,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"4.10 Location"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p74-202', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '4.10 Location', 74, 'Standards Track Work Product 02 April 2025 - Page 74 of 276Copyright © OASIS Open 2025. All Rights Reserved. Reverse Relationships identity, infrastructure, threat-actor located-at location See forward relationship for definition. campaign, intrusion-set, malware originates- from location See forward relationship for definition. attack-pattern, campaign, intrusion-set, malware, threat-actor, tool targets location See forward relationship for definition. Example [ { "type": "location", "spec_version": "2.1", "id": "location--a6e9345f-5a15-4c29-8bb3-7dcc5d168d64", "created_by_ref": "identity--f431f809-377b-45e0-aa1c-6a4751cae5ff", "created": "2016-04-06T20:03:00.000Z", "modified": "2016-04-06T20:03:00.000Z", "region": "northern-america" } { "type": "location", "spec_version": "2.1", "id": "location--a6e9345f-5a15-4c29-8bb3-7dcc5d168d64", "created_by_ref": "identity--f431f809-377b-45e0-aa1c-6a4751cae5ff", "created": "2016-04-06T20:03:00.000Z", "modified": "2016-04-06T20:03:00.000Z", "region": "south-eastern-asia", "country": "th", "administrative_area": "Tak", "postal_code": "63170" } { "type": "location", "spec_version": "2.1", "id": "location--a6e9345f-5a15-4c29-8bb3-7dcc5d168d64", "created_by_ref": "identity--f431f809-377b-45e0-aa1c-6a4751cae5ff", "created": "2016-04-06T20:03:00.000Z", "modified": "2016-04-06T20:03:00.000Z", "latitude": "48.8566", "longitude": "2.3522" } ]', 'vec_doc-10-oasis-stix21-p74-202', 0, 349, 'v2.1.0', '31709eb5d17c3f1cb2923e02c486c29c12a2414fe77e4ab234dd9f0311eab54a', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"4.10 Location","subsection":"UNKNOWN","table_id":null,"page":74,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":202,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"4.10 Location"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p74-203', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '4.11 Malware', 74, 'Type Name: malware Malware is a type of TTP that represents malicious code. It generally refers to a program that is inserted into a system, usually covertly. The intent is to compromise the confidentiality, integrity, or availability of the victim’s data, applications, or operating system (OS) or otherwise annoy or disrupt the victim.', 'vec_doc-10-oasis-stix21-p74-203', 0, 85, 'v2.1.0', '98060ceaef1e106ef1766da901a47b93cf8139476ee9de76420f44377c44db2b', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"4.11 Malware","subsection":"UNKNOWN","table_id":null,"page":74,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":203,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"4.11 Malware"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p75-204', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '4.11 Malware', 75, 'Standards Track Work Product 02 April 2025 - Page 75 of 276Copyright © OASIS Open 2025. All Rights Reserved. The Malware SDO characterizes, identifies, and categorizes malware instances and families from data that may be derived from analysis. This SDO captures detailed information about how the malware works and what it does. This SDO captures contextual data relevant to sharing Malware data without requiring the full analysis provided by the Malware Analysis SDO. The Indicator SDO provides intelligence producers with the ability to define, using the STIX Pattern Grammar in a standard way to identify and detect behaviors associated with malicious activities. Although the Malware SDO provides vital intelligence on a specific instance or malware family, it does not provide a standard grammar that the Indicator SDO provides to identify those properties in security detection systems designed to process the STIX Pattern grammar.', 'vec_doc-10-oasis-stix21-p75-204', 0, 235, 'v2.1.0', 'dd93ff177fd36614daf317e3afc845366db5f57ede40b0e9372fc6f43be3f061', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"4.11 Malware","subsection":"UNKNOWN","table_id":null,"page":75,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":204,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"4.11 Malware"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p75-205', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '4.11 Malware', 75, 'We strongly encourage the use of STIX Indicators for the detection of actual malware, due to its use of the STIX Patterning language and the clear semantics that it provides. To minimize the risk of a consumer compromising their system in parsing malware samples, producers SHOULD consider sharing defanged content (archive and password-protected samples) instead of raw, base64-encoded malware samples.', 'vec_doc-10-oasis-stix21-p75-205', 0, 101, 'v2.1.0', '4a60b487ba3c0dbcb95b5adeaacc2331bab9485d8d2bb7beea79d2b27781698e', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"4.11 Malware","subsection":"UNKNOWN","table_id":null,"page":75,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":205,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"4.11 Malware"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p75-206', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '4.11 Malware', 75, '4.11.1 Properties Required Common Properties type, spec_version, id, created, modified Optional Common Properties created_by_ref, revoked, labels, confidence, lang, external_references, object_marking_refs, granular_markings, extensions Not Applicable Common Properties defanged Malware Specific Properties name, description, malware_types, is_family, aliases, kill_chain_phases, first_seen, last_seen, operating_system_refs, architecture_execution_envs, implementation_languages, capabilities, sample_refs Property Name Type Description type (required) string The value of this property MUST be malware. name (optional) string A name used to identify the Malware instance or family, as specified by the producer of the SDO. For a malware family the name MUST be defined. If a name for a malware instance is not available, the SHA-256 hash value or sample’s filename MAY be used instead.', 'vec_doc-10-oasis-stix21-p75-206', 0, 222, 'v2.1.0', 'b9979e35565a65f3c45355b8f42cb88f32bb438316f2866835083d9d65e2afbf', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"4.11 Malware","subsection":"UNKNOWN","table_id":null,"page":75,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":206,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"4.11 Malware"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p75-207', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '4.11 Malware', 75, 'description (optional) string A description that provides more details and context about the Malware instance or family, potentially including', 'vec_doc-10-oasis-stix21-p75-207', 0, 36, 'v2.1.0', 'b19ba700b399963dbd136d303529ba4960d37cdc3b0882c23e857a186aca8ad8', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"4.11 Malware","subsection":"UNKNOWN","table_id":null,"page":75,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":207,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"4.11 Malware"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p76-208', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '4.11 Malware', 76, 'Standards Track Work Product 02 April 2025 - Page 76 of 276Copyright © OASIS Open 2025. All Rights Reserved. its purpose and its key characteristics. malware_types (optional) list of type open-vocab A set of categorizations for the malware being described. The values for this property SHOULD come from the malware-type-ov open vocabulary. is_family (optional) boolean Whether the object represents a malware family (if true) or a malware instance (if false). aliases (optional) list of type string Alternative names used to identify this malware or malware family. kill_chain_phases (optional) list of type kill-chain-phase The list of Kill Chain Phases for which this malware can be used. first_seen (optional) timestamp The time that the malware instance or family was first seen. This property is a summary property of data from sightings and other data that may or may not be available in STIX. If new sightings are received that are earlier than the first seen timestamp, the object may be updated to account for the new data. last_seen (optional) timestamp The time that the malwarefamily or malware instance was last seen. This property is a summary property of data from sightings and other data that may or may not be available in STIX. If new sightings are received that are later than the last_seen timestamp, the object may be updated to account for the new data. If this property and the first_seen property are both defined, then this property MUST be greater than or equal to the timestamp in the first_seen property.', 'vec_doc-10-oasis-stix21-p76-208', 0, 384, 'v2.1.0', '9c2e08ee806e53c577f8e5d5da8803e544b656eef4b19d6720bee501d896f62c', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"4.11 Malware","subsection":"UNKNOWN","table_id":null,"page":76,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":208,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"4.11 Malware"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p77-209', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '4.11 Malware', 77, 'Standards Track Work Product 02 April 2025 - Page 77 of 276Copyright © OASIS Open 2025. All Rights Reserved. operating_system_refs(optional) list of type identifier The operating systems thatthe malware family or malware instance is executable on. This applies to virtualized operating systems as well as those running on bare metal. The value of this property MUST be the identifier for a SCO software object. architecture_execution_envs (optional) list of type open-vocab The processor architectures (e.g., x86, ARM, etc.) that the malware instance or family is executable on. The values for this property SHOULD come from the processor- architecture-ov open vocabulary. implementation_languages (optional) list of type open-vocab The programming language(s) used to implement the malware instance or family. The values for this property SHOULD come from the implementation- language-ov open vocabulary. capabilities (optional) list of type open-vocab Any of the capabilities identified for the malware instance or family. The values for this property SHOULD come from the malware-capabilities- ov open vocabulary. sample_refs (optional) list of type identifier The sample_refs property specifies a list of identifiers of the SCO file or artifact objects associated with this malware instance(s) or family. If is_family is false, then all samples listed in sample_refs MUST refer to the same binary data.', 'vec_doc-10-oasis-stix21-p77-209', 0, 352, 'v2.1.0', '9f28c9ea574a8957e2e5cd8996a1299eaee13c3e8b42035d2f8e600f7f0c73b9', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"4.11 Malware","subsection":"UNKNOWN","table_id":null,"page":77,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":209,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"4.11 Malware"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p78-210', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '4.11 Malware', 78, 'Standards Track Work Product 02 April 2025 - Page 78 of 276Copyright © OASIS Open 2025. All Rights Reserved. 4.11.2 Relationships These are the relationships explicitly defined between the Malware object and other STIX Objects. The first section lists the embedded relationships by property name along with their corresponding target. The rest of the table identifies the relationships that can be made from this object type to another object type by way of the Relationship object. The reverse relationships section illustrates the relationships targeting this object type from another object type. They are included here for convenience. For their definitions, please see the “Source” object. Relationships are not restricted to those listed below. Relationships can be created between any objects using the related-to relationship type or, as with open vocabularies, user-defined names.', 'vec_doc-10-oasis-stix21-p78-210', 0, 223, 'v2.1.0', 'e22ded1fa06326cc26f707cb21a81743d3b0d6df4a7611ecd029641d5504db40', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"4.11 Malware","subsection":"UNKNOWN","table_id":null,"page":78,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":210,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"4.11 Malware"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p78-211', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '4.11 Malware', 78, 'Embedded Relationships created_by_ref identifier (of type identity) object_marking_refs list of type identifier (of type marking- definition) operating_system_refs list of type identifier (of type software) sample_refs list of type identifier (of type file or artifact) Common Relationships duplicate-of, derived-from, related-to Source Relationship Type Target Description malware authored-by threat-actor, intrusion-set This Relationship describes that the malware instance or family was developed by the related threat actor or intrusion set. malware beacons-to, exfiltrates- to infrastructure This Relationship describes that the malware instance or family beacons to or exfiltrates data to the related Infrastructure. malware communicates- with ipv4-addr, ipv6-addr, domain-name, url This Relationship documents that this malware instance (or family) communicates with (beacons to, connects to, or exfiltrated data to) the defined network addressable resource.', 'vec_doc-10-oasis-stix21-p78-211', 0, 242, 'v2.1.0', 'bb84a4442ac02a1d623e84e5e28e564e625bed105f91cdc657f292b384762243', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"4.11 Malware","subsection":"UNKNOWN","table_id":null,"page":78,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":211,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"4.11 Malware"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p78-212', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '4.11 Malware', 78, 'malware controls malware This Relationship documents that this malware instance (or family) can control other malware which may be resident on the same system on which it is executing. Note that this is not meant to imply or state that the malware instance or', 'vec_doc-10-oasis-stix21-p78-212', 0, 65, 'v2.1.0', '2f1bb7fc71445ab5bc025794bc9e9773e146e43764643905b933d7189e81b8eb', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"4.11 Malware","subsection":"UNKNOWN","table_id":null,"page":78,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":212,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"4.11 Malware"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p79-213', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '4.11 Malware', 79, 'Standards Track Work Product 02 April 2025 - Page 79 of 276Copyright © OASIS Open 2025. All Rights Reserved. family drops other malware (which is covered by the drops relationship). Rather, it is meant to state that the malware instance or family is able to subvert or control other malware to achieve its goals. malware downloads, drops malware, tool, file These Relationships document that this malware instance (or family) downloads or drops another malware instance, tool or file. This is especially common with “first-stage” malware instances such as downloaders and droppers. malware exploits vulnerability This Relationship documents that this malware instance or family exploits or attempts to exploit a particular vulnerability. For example, an exploits Relationship linking a malware instance or family representing a downloader to a Vulnerability for CVE-2016-0001 means that the malware instance or family exploits that vulnerability.', 'vec_doc-10-oasis-stix21-p79-213', 0, 237, 'v2.1.0', '62c42ec6e77c327c7cb2565add5c9e41eb442cdd11af3aa286a5fa44f03ae878', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"4.11 Malware","subsection":"UNKNOWN","table_id":null,"page":79,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":213,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"4.11 Malware"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p79-214', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '4.11 Malware', 79, 'malware originates- from location This Relationship documents that this malware instance or family originates from a particular location. malware targets identity, infrastructure, location, vulnerability This Relationship documents that a malware instance or family is being used to target an Identity, Infrastructure, or Location. For malware families, this can be used tocapture the full set of identities, infrastructures, or locations targeted by the family. Similarly, a targets Relationship linking a malware instance or family representing a downloader to an Identity representing the energy sector means that downloader is typically used against targets in the energy sector. malware uses attack-pattern, infrastructure, malware, tool This Relationship documents that this malware instance or family uses the attack pattern, infrastructure, malware, or tool to achieve its objectives. For example, a uses Relationship from the jay-sm17h Threat Actor to', 'vec_doc-10-oasis-stix21-p79-214', 0, 240, 'v2.1.0', '57aadd2880687a1f8f4166453985fcaaf59baefc4263a643b438c851a5c0af5f', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"4.11 Malware","subsection":"UNKNOWN","table_id":null,"page":79,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":214,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"4.11 Malware"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p80-215', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '4.11 Malware', 80, 'Standards Track Work Product 02 April 2025 - Page 80 of 276Copyright © OASIS Open 2025. All Rights Reserved. the xInject Malware indicates that xInject is often used by jay-sm17h. malware variant-of malware This Relationship is used to document that one malware instance or family is a variant of another malware instance or family. Only the following uses of this relationship are valid: Malware instance → Malware family: a Malware instance is a variant of a Malware family. For example, a particular Zeus version 2 sample is a variant of the broader Zeus family. Malware family → Malware family: a Malware family is a variant of another Malware family. For example, the Gameover Zeus family is a variant of the broader Zeus family. Malware instance → Malware instance: a Malware instance is a variant of another Malware instance. For example, a particular Cryptolocker instance that is based on an another Cryptolocker instance with minor changes. Malware family → Malware instance: this relationship MUST NOT be used as it is not semantically valid. Reverse Relationships attack-pattern, infrastructure, tool delivers malware See forward relationship for definition. indicator indicates malware See forward relationship for definition. course-of- action mitigates, remediates malware See forward relationship for definition. attack-pattern, campaign, intrusion-set, threat-actor uses malware See forward relationship for definition. tool drops malware See forward relationship for definition. infrastructure controls malware See forward relationship for definition.', 'vec_doc-10-oasis-stix21-p80-215', 0, 393, 'v2.1.0', '954df61c7d374a16d53cf5fee11b7dfd885200d7019118c5a8d3f45add93d64e', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"4.11 Malware","subsection":"UNKNOWN","table_id":null,"page":80,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":215,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"4.11 Malware"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p81-216', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '4.11 Malware', 81, 'Standards Track Work Product 02 April 2025 - Page 81 of 276Copyright © OASIS Open 2025. All Rights Reserved. malware- analysis characterizes, av-analysis- of, static- analysis-of, dynamic- analysis-of malware See forward relationship fordefinition. Example { "type": "malware", "spec_version": "2.1", "id": "malware--0c7b5b88-8ff7-4a4d-aa9d-feb398cd0061", "created": "2016-05-12T08:17:27.000Z", "modified": "2016-05-12T08:17:27.000Z", "name": "Cryptolocker", "description": "A variant of the cryptolocker family", "malware_types": ["ransomware"], "is_family": false }', 'vec_doc-10-oasis-stix21-p81-216', 0, 142, 'v2.1.0', '68e567b7807b45efeeb709eba99bd8da17bdef02973e2dd1e8fe3bee1312f897', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"4.11 Malware","subsection":"UNKNOWN","table_id":null,"page":81,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":216,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"4.11 Malware"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p81-217', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '4.12 Malware Analysis', 81, 'Type Name: malware-analysis Malware Analysis captures the metadata and results of a particular static or dynamic analysis performed on a malware instance or family. One of result or analysis_sco_refs properties MUST be provided. 4.12.1 Properties Required Common Properties type, spec_version, id, created, modified Optional Common Properties created_by_ref, revoked, labels, confidence, lang, external_references, object_marking_refs, granular_markings, extensions Not Applicable Common Properties defanged Malware Analysis Specific Properties product, version, host_vm_ref, operating_system_ref, installed_software_refs, configuration_version, modules, analysis_engine_version, analysis_definition_version, submitted, analysis_started, analysis_ended, result_name, result, analysis_sco_refs, sample_ref Property Name Type Description type (required) string The value of this property MUST be malware-analysis.', 'vec_doc-10-oasis-stix21-p81-217', 0, 228, 'v2.1.0', 'b04cc203d512da5d7b8ad6ab5bb27d49fa50fad0e9f3c652ee9373e4a6f23d93', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"4.12 Malware Analysis","subsection":"UNKNOWN","table_id":null,"page":81,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":217,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"4.12 Malware Analysis"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p82-218', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '4.12 Malware Analysis', 82, 'Standards Track Work Product 02 April 2025 - Page 82 of 276Copyright © OASIS Open 2025. All Rights Reserved. product (required) string The name of the analysis engine orproduct that was used. Product names SHOULD be all lowercase with words separated by a dash “-”. For cases where the name of a product cannot be specified, a value of “anonymized” MUST be used. version (optional) string The version of the analysis product that was used to perform the analysis. host_vm_ref (optional) identifier A description of the virtual machine environment used to host the guest operating system (if applicable) that was used for the dynamic analysis of the malware instance or family. If this value is not included in conjunction with the operating_system_ref property, this means that the dynamic analysis may have been performed on bare metal (i.e. without virtualization) or the information was redacted. The value of this property MUST be the identifier for a SCO software object.', 'vec_doc-10-oasis-stix21-p82-218', 0, 244, 'v2.1.0', '07a6f66ef7d9e25f2144e1718e4e5a7faf2cdd86242f5721e10afdeed62adebf', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"4.12 Malware Analysis","subsection":"UNKNOWN","table_id":null,"page":82,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":218,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"4.12 Malware Analysis"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p82-219', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '4.12 Malware Analysis', 82, 'operating_system_ref (optional) identifier The operating system used for the dynamic analysis of the malware instance or family. This applies to virtualized operating systems as well as those running on bare metal. The value of this property MUST be the identifier for a SCO software object. installed_software_refs (optional) list of type identifier Any non-standard software installed on the operating system (specified through the operating-system value) used for the dynamic analysis of the malware instance or family. The value of this property MUST be the identifier for a SCO software object. configuration_version (optional) string The named configuration of additional product configuration parameters for this analysis run. For example, when a product is configured to do full depth analysis of Window™ PE files. This configuration may have a named version and that', 'vec_doc-10-oasis-stix21-p82-219', 0, 219, 'v2.1.0', 'bf806483567811429f809dcf007009b586f7714905127da2cb8162c9227e6340', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"4.12 Malware Analysis","subsection":"UNKNOWN","table_id":null,"page":82,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":219,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"4.12 Malware Analysis"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p83-220', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '4.12 Malware Analysis', 83, 'Standards Track Work Product 02 April 2025 - Page 83 of 276Copyright © OASIS Open 2025. All Rights Reserved. named version can be captured in this property. This will ensure additional runs can be configured in the same way. modules (optional) list of type string The specific analysis modules that were used and configured in the product during this analysis run. For example, configuring a product to support analysis of Dridex. analysis_engine_version (optional) string The version of the analysis engine or product (including AV engines) that was used to perform the analysis. analysis_definition_version (optional) string The version of the analysis definitions used by the analysis tool (including AV tools). submitted (optional) timestamp The date and time that the malware was first submitted for scanning or analysis. This value will stay constant while the scanned date can change. For example, when Malware was submitted to a virus analysis tool.', 'vec_doc-10-oasis-stix21-p83-220', 0, 240, 'v2.1.0', 'a6ad1b0c4127bbf199c780666f9f205385894edef90464022e68c9d833ce0caa', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"4.12 Malware Analysis","subsection":"UNKNOWN","table_id":null,"page":83,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":220,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"4.12 Malware Analysis"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p83-221', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '4.12 Malware Analysis', 83, 'analysis_started (optional) timestamp The date and time that the malware analysis was initiated. analysis_ended (optional) timestamp The date and time that the malware analysis ended. result_name (optional) string The classification result or name assigned to the malware instance by the scanner tool. result (optional) open-vocab The classification result as determined by the scanner or tool analysis process. The value for this property SHOULD come from the malware-result-ov open vocabulary. analysis_sco_refs (optional) list of type identifier This property contains the references to the STIX Cyber-observable Objects that were captured during the analysis process. sample_ref (optional) identifier This property contains the reference to the SCO file, network traffic or artifact object that this malware analysis was performed against. Caution should be observed when creating an SRO between Malware and Malware Analysis objects when', 'vec_doc-10-oasis-stix21-p83-221', 0, 236, 'v2.1.0', '1345ade1826f91e0b8647b8fc1389c45546da98b27add2ec84b96a8d6e15884b', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"4.12 Malware Analysis","subsection":"UNKNOWN","table_id":null,"page":83,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":221,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"4.12 Malware Analysis"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p84-222', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '4.12 Malware Analysis', 84, 'Standards Track Work Product 02 April 2025 - Page 84 of 276Copyright © OASIS Open 2025. All Rights Reserved. the Malware sample_refs property does not contain the SCO that is included in the Malware Analysis sample_ref property. Note, this property can also contain a reference to an SCO which is not associated with Malware (i.e., some SCO which was scanned and found to be benign.) 4.12.2 Relationships These are the relationships explicitly defined between the Malware Analysis object and other STIX Objects. The first section lists the embedded relationships by property name along with their corresponding target. The rest of the table identifies the relationships that can be made from this object type to another object type by way of the Relationship object. The reverse relationships section illustrates the relationships targeting this object type from another object type. They are included here for convenience. For their definitions, please see the “Source” object.', 'vec_doc-10-oasis-stix21-p84-222', 0, 245, 'v2.1.0', 'ee5dcbf6e5a48d1231ae021287e5963a3cd438390262ce003c87a7b5d64b31e3', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"4.12 Malware Analysis","subsection":"UNKNOWN","table_id":null,"page":84,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":222,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"4.12 Malware Analysis"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p84-223', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '4.12 Malware Analysis', 84, 'Relationships are not restricted to those listed below. Relationships can be created between any objects using the related-to relationship type or, as with open vocabularies, user-defined names. Embedded Relationships created_by_ref identifier (of type identity) object_marking_refs list of type identifier (of type marking- definition) host_vm_ref identifier (of type software) operating_system_ref identifier (of type software) installed_software_refs list of type identifier (of type software) analysis_sco_refs list of type identifier (of type STIX Object) sample_ref identifier (of type file, network- traffic, and artifact) Common Relationships duplicate-of, derived-from, related-to Source Relationship Type Target Description malware- analysis characterizes malware This Relationship describes that the malware analysis describes the related malware. malware- analysis av-analysis- of malware This Relationship describes that the malware analysis is results for the related malware.', 'vec_doc-10-oasis-stix21-p84-223', 0, 248, 'v2.1.0', 'b2f1a6064c5e9c594957eaba0e30027ccd0a21522edff77ef9163be0a1e37d04', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"4.12 Malware Analysis","subsection":"UNKNOWN","table_id":null,"page":84,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":223,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"4.12 Malware Analysis"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p85-224', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '4.12 Malware Analysis', 85, 'Standards Track Work Product 02 April 2025 - Page 85 of 276Copyright © OASIS Open 2025. All Rights Reserved. malware- analysis static- analysis-of malware This Relationship describes that themalware analysis is static analysis results for the related malware. malware- analysis dynamic- analysis-of malware This Relationship describes that the malware analysis is dynamic analysis results for the related malware.', 'vec_doc-10-oasis-stix21-p85-224', 0, 104, 'v2.1.0', 'd8d3c0bb1f31251853a4e27570bfccb96f9ea0254652126050f1b65f4d8fa48b', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"4.12 Malware Analysis","subsection":"UNKNOWN","table_id":null,"page":85,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":224,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"4.12 Malware Analysis"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p85-225', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '4.12 Malware Analysis', 85, 'Reverse Relationships — — — — Example [ { "type": "malware", "spec_version": "2.1", "id": "malware--8bcf14e9-2ba2-44ef-9e32-fbbc9d2608b2", "created": "2020-01-16T18:52:24.277Z", "modified": "2020-01-16T18:52:24.277Z", "name": "a92e5b2bae.exe", "malware_types": [ "unknown" ], "is_family": false, "sample_refs": [ "file--ba8965d8-e4ec-5f9c-a4df-1c460994ca58" ] } { "type": "malware-analysis", "spec_version": "2.1", "id": "malware-analysis--d25167b7-fed0-4068-9ccd-a73dd2c5b07c", "created": "2020-01-16T18:52:24.277Z", "modified": "2020-01-16T18:52:24.277Z", "product": "microsoft", "analysis_engine_version": "5.1.0", "analysis_definition_version": "053514-0062", "analysis_started": "2012-02-11T08:36:14Z", "analysis_ended": "2012-02-11T08:36:14Z", "result": "malicious" } { "type": "relationship", "spec_version": "2.1", "id": "relationship--014841f8-eb38-4673-9904-70f67c92dd8b", "created": "2020-01-16T18:52:24.277Z", "modified": "2020-01-16T18:52:24.277Z", "relationship_type": "av-analysis-of", "source_ref": "malware-analysis--d25167b7-fed0-4068-9ccd-a73dd2c5b07c", "target_ref": "malware--8bcf14e9-2ba2-44ef-9e32-fbbc9d2608b2" } { "type": "file", "id": "file--ba8965d8-e4ec-5f9c-a4df-1c460994ca58", "spec_version": "2.1", "hashes": { "MD5": "a92e5b2bae0b4b3a3d81c85610b95cd4", "SHA-1": "5374e08903744ceeaedd8f5e1bfc06b2c4688e76" }, "size": 77312, "name": "a92e5b2bae.exe", "parent_directory_ref": "directory--ab82f84a-5afc-5ea7-8d98-9fcbc277eda6"', 'vec_doc-10-oasis-stix21-p85-225', 0, 364, 'v2.1.0', 'ca6db4b876ef38a5f0b418dc053fd8af8e790ad1acd5c502a74abe21a204f87b', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"4.12 Malware Analysis","subsection":"UNKNOWN","table_id":null,"page":85,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":225,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"4.12 Malware Analysis"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p86-226', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '4.13 Note', 86, 'Type Name: note A Note is intended to convey informative text to provide further context and/or to provide additional analysis not contained in the STIX Objects, Marking Definition objects, or Language Content objects which the Note relates to. Notes can be created by anyone (not just the original object creator). For example, an analyst may add a Note to a Campaign object created by another organization indicating that they’ve seen posts related to that Campaign on a hacker forum. Because Notes are typically (though not always) created by human analysts and are comprised of human-oriented text, they contain an additional property to capture the analyst(s) that created the Note. This is distinct from the created_by_ref property, which is meant to capture the organization that createdthe object. 4.13.1 Properties Required Common Properties type, spec_version, id, created, modified Optional Common Properties created_by_ref, revoked, labels, confidence, lang, external_references, object_marking_refs, granular_markings, extensions Not Applicable Common Properties defanged Note Specific Properties abstract, content, authors, object_refs Property Name Type Description type (required) string The value of this property MUST be note. abstract (optional) string A brief summary of the note content. content (required) string The content of the note. authors (optional) list of type string The name of the author(s) of this note (e.g., the analyst(s) that created it). object_refs (required) list of type identifier The STIX Objects that the note is being applied to.', 'vec_doc-10-oasis-stix21-p86-226', 0, 394, 'v2.1.0', '5e459aee9c68afe3e83ec5a72d2dcf9a2211773676864099884b28aa2e63e6cc', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"4.13 Note","subsection":"UNKNOWN","table_id":null,"page":86,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":226,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"4.13 Note"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p87-227', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '4.13 Note', 87, 'Standards Track Work Product 02 April 2025 - Page 87 of 276Copyright © OASIS Open 2025. All Rights Reserved. 4.13.2 Relationships There are no relationships explicitly defined between the Note object and other STIX Objects, other than the embedded relationships listed below. These embedded relationships are listed by property name along with their corresponding target. Embedded Relationships created_by_ref identifier (of type identity) object_marking_refs list of type identifier (of type marking- definition) object_refs list of type identifier (of type STIX Object) Example A generic Note defining additional context and shows an optional external reference to a ticketing system. { "type": "note", "spec_version": "2.1", "id": "note--0c7b5b88-8ff7-4a4d-aa9d-feb398cd0061", "created": "2016-05-12T08:17:27.000Z", "modified": "2016-05-12T08:17:27.000Z", "external_references": [ { "source_name": "job-tracker", "external_id": "job-id-1234" } ], "abstract": "Tracking Team Note#1", "content": "This note indicates the various steps taken by the threat analyst team to investigate this specific campaign. Step 1) Do a scan 2) Review scanned results for identified hosts not known by external intel…etc.", "authors": ["John Doe"], "object_refs": ["campaign--8e2e2d2b-17d4-4cbf-938f-98ee46b3cd3f"] }', 'vec_doc-10-oasis-stix21-p87-227', 0, 325, 'v2.1.0', '598700457c87542fc7c62fbde49a01519e4673500f3905dea4dce53e738f8490', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"4.13 Note","subsection":"UNKNOWN","table_id":null,"page":87,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":227,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"4.13 Note"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p87-228', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '4.14 Observed Data', 87, 'Type Name: observed-data Observed Data conveys information about cyber security related entities such as files, systems, and networks using the STIX Cyber-observable Objects (SCOs). For example, Observed Data can capture information about an IP address, a network connection, a file, or a registry key. Observed Data is not an intelligence assertion, it is simply the raw information without any context for what it means. Observed Data can capture that a piece of information was seen one or more times. Meaning, it can capture both a single observation of a single entity (file, network connection) as well as the aggregation of multiple observations of an entity. When the number_observed property is 1 the Observed Data represents a single entity. When the number_observed property is greater than 1, the Observed Data represents several instances of an entity potentially collected over a period of time. If a time window is known, that can be captured using the first_observed and last_observed properties. When used to collect aggregate data, it is likely that some properties in the SCO (e.g., timestamp properties) will be omitted because they would differ for each of the individual observations. Observed Data may be used by itself (without relationships) to convey raw data collected from any source including analyst reports, sandboxes, and network and host-based detection tools. An intelligence producer conveying Observed Data SHOULD include as much context (e.g. SCOs) as possible that', 'vec_doc-10-oasis-stix21-p87-228', 0, 376, 'v2.1.0', '8ae38afd10d3bef5703cd2895376402c64087e2b8a2c8672e4616f77d3182d8a', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"4.14 Observed Data","subsection":"UNKNOWN","table_id":null,"page":87,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":228,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"4.14 Observed Data"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p88-229', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '4.14 Observed Data', 88, 'Standards Track Work Product 02 April 2025 - Page 88 of 276Copyright © OASIS Open 2025. All Rights Reserved. supports the use of the observed data set in systems expecting to utilize the Observed Data for improved security. This includes all SCOs that matched on an Indicator pattern and are represented in the collected observed event (or events) being conveyed in the Observed Data object. For example, a firewall could emit a single Observed Data instance containing a single Network Traffic object for each connection it sees. The firewall could also aggregate data and instead send out an Observed Data instance every ten minutes with an IP address and an appropriate number_observed value to indicate the number of times that IP address was observed in that window. A sandbox could emit an Observed Data instance containing a file hash that it discovered. Observed Data may also be related to other SDOs to represent raw data that is relevant to those objects.', 'vec_doc-10-oasis-stix21-p88-229', 0, 242, 'v2.1.0', 'b795a50f65621b91e6b55ed2cebc7e6824a012ba23a35b9b4fceba76387d9ba9', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"4.14 Observed Data","subsection":"UNKNOWN","table_id":null,"page":88,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":229,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"4.14 Observed Data"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p88-230', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '4.14 Observed Data', 88, 'For example, the Sighting Relationship object, can relate an Indicator, Malware, or other SDO to a specific Observed Data to represent the raw information that led to the creation of the Sighting (e.g., what was actually seen that suggested that a particular instance of malware was active). To support backwards compatibility, related SCOs can still be specified using the objects properties, either the objects property or the object_refs property MUST be provided, but both MUST NOT be present at the same time. 4.14.1 Properties Required Common Properties type, spec_version, id, created, modified Optional Common Properties created_by_ref, revoked, labels, confidence, lang, external_references, object_marking_refs, granular_markings, extensions Not Applicable Common Properties defanged Observed Data Specific Properties first_observed, last_observed, number_observed, objects, object_refs Property Name Type Description type (required) string The value of this property MUST be observed- data.', 'vec_doc-10-oasis-stix21-p88-230', 0, 251, 'v2.1.0', '3fc174415c2b1a4289c4ad3a2d9008bcf69d17413a8ab6f9d0c328806381ede5', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"4.14 Observed Data","subsection":"UNKNOWN","table_id":null,"page":88,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":230,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"4.14 Observed Data"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p88-231', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '4.14 Observed Data', 88, 'first_observed (required) timestamp The beginning of the time window during which the data was seen. last_observed (required) timestamp The end of the time window during which the data was seen. This MUST be greater than or equal to the timestamp in the first_observed property. number_observed (required) integer The number of times that each Cyber- observable object represented in the objects or object_refs property was seen. If present, this MUST be an integer between 1 and 999,999,999 inclusive. If the number_observed property is greater', 'vec_doc-10-oasis-stix21-p88-231', 0, 137, 'v2.1.0', '674c8b518e41b4f12ef9c936263f39451f12c83ce40be5aad414c512af3a3064', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"4.14 Observed Data","subsection":"UNKNOWN","table_id":null,"page":88,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":231,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"4.14 Observed Data"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p89-232', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '4.14 Observed Data', 89, 'Standards Track Work Product 02 April 2025 - Page 89 of 276Copyright © OASIS Open 2025. All Rights Reserved. than 1, the data contained in the objects or object_refs property was seen multiple times. In these cases, object creators MAY omit properties of the SCO (such as timestamps) that are specific to a single instance of that observed data. objects (optional - deprecated) observable-container A dictionary of SCO representing the observation. The dictionary MUST contain at least one object. The cyber observable content MAY include multiple objects if those objects are related as part of a single observation. Multiple objects not related to each other via cyber observable Relationships MUST NOT be contained within the same Observed Data instance. This property MUST NOT be present if object_refs is provided.', 'vec_doc-10-oasis-stix21-p89-232', 0, 205, 'v2.1.0', '3a2d871585926450fb376a5dd2c0fadc2450cb261f645953be319c41301f1d61', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"4.14 Observed Data","subsection":"UNKNOWN","table_id":null,"page":89,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":232,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"4.14 Observed Data"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p89-233', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '4.14 Observed Data', 89, 'For example, a Network Traffic object and two IPv4 Address objects related via the src_ref and dst_ref properties can be contained in the same Observed Data because they are all related and used to characterize that single entity. NOTE: this property is now deprecated in favor of object_refs and will be removed in a future version. object_refs (optional) list of type identifier A list of SCOs and SROs representing the observation. The object_refs MUST contain at least one SCO reference if defined. The object_refs MAY include multiple SCOs and their corresponding SROs, if those SCOs are related as part of a single observation. For example, a Network Traffic object and two IPv4 Address objects related via the src_ref and dst_ref properties can be contained in the same Observed Data because they are all related and used to characterize that single entity. This property MUST NOT be present if objects is provided.', 'vec_doc-10-oasis-stix21-p89-233', 0, 231, 'v2.1.0', '9a6049111bcd014800ca099464712951f237d6d7f20d43b8f29533c8dff71695', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"4.14 Observed Data","subsection":"UNKNOWN","table_id":null,"page":89,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":233,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"4.14 Observed Data"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p89-234', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '4.14 Observed Data', 89, '4.14.2 Relationships There are no forward relationships explicitly defined between the Observed Data object and other STIX Objects, other than those defined as common relationships. The first section lists the embedded relationships by property name along with their corresponding target. The reverse relationships section illustrates the relationships targeting this object type from another object type. They are included here for convenience. For their definitions, please see the “Source” object. In addition to the relationships created using the generic Relationship object, Observed Data is also a direct target of the Sighting SRO. Sightings represent a relationship between some intelligence entity that', 'vec_doc-10-oasis-stix21-p89-234', 0, 178, 'v2.1.0', 'c74f9b63e6d05e32cbae5b4de763ab352a77bb3e4a2abf526209b5a4e4a65705', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"4.14 Observed Data","subsection":"UNKNOWN","table_id":null,"page":89,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":234,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"4.14 Observed Data"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p90-235', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '4.14 Observed Data', 90, 'Standards Track Work Product 02 April 2025 - Page 90 of 276Copyright © OASIS Open 2025. All Rights Reserved. was seen (e.g., an Indicator or Malware instance), where it was seen, and what evidence was actually seen. The evidence (or raw data) in that relationship is captured as Observed Data. Relationships are not restricted to those listed below. Relationships can be created between any objects using the related-to relationship type or, as with open vocabularies, user-defined names. Embedded Relationships created_by_ref identifier (of type identity) object_marking_refs list of type identifier (of type marking- definition) object_refs list of type identifier (of type SCO or SRO) Common Relationships duplicate-of, derived-from, related-to Source Relationship Type Target Description — — — — Reverse Relationships indicator based-on observed-data See forward relationship for definition. infrastructure consists-of observed-data See forward relationship for definition Example Observed Data that references two SCOs { "type": "observed-data", "spec_version": "2.1", "id": "observed-data--b67d30ff-02ac-498a-92f9-32f845f448cf", "created_by_ref": "identity--f431f809-377b-45e0-aa1c-6a4751cae5ff", "created": "2016-04-06T19:58:16.000Z", "modified": "2016-04-06T19:58:16.000Z", "first_observed": "2015-12-21T19:00:00Z", "last_observed": "2015-12-21T19:00:00Z", "number_observed": 50, "object_refs": [ "ipv4-addr--28bb3599-77cd-5a82-a950-b5bc3caf07c4", "domain-name--bedb4899-d24b-5401-bc86-8f6b4cc18ec7" ] } { "type": "domain-name", "spec_version": "2.1", "id": "domain-name--bedb4899-d24b-5401-bc86-8f6b4cc18ec7", "value": "example.com", "resolves_to_refs": ["ipv4-addr--28bb3599-77cd-5a82-a950-b5bc3caf07c4"] } { "type": "ipv4-addr", "spec_version": "2.1",', 'vec_doc-10-oasis-stix21-p90-235', 0, 441, 'v2.1.0', '7ba6416b0d1bc22193a82ffd29e24023875ed4eeb2c6c23a21a3b101ab1d8c60', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"4.14 Observed Data","subsection":"UNKNOWN","table_id":null,"page":90,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":235,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"4.14 Observed Data"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p91-236', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '4.15 Opinion', 91, 'Type Name: opinion An Opinion is an assessment of the correctness of the information in a STIX Object produced by a different entity. The primary property is the opinion property, which captures the level of agreement or disagreement using a fixed scale. That fixed scale also supports a numeric mapping to allow forconsistent statistical operations across opinions. For example, an analyst from a consuming organization might say that they “strongly disagree” with a Campaign object and provide an explanation about why. In a more automated workflow, a SOC operator might give an Indicator “one star” in their TIP (expressing “strongly disagree”) because it is considered to be a false positive within their environment. Opinions are subjective, and the specification does not address how best to interpret them. Sharing communities are encouraged to provide clear guidelines to their constituents regarding best practice for the use of Opinion objects within the community.', 'vec_doc-10-oasis-stix21-p91-236', 0, 244, 'v2.1.0', 'd170adccd5abac7a37e9497c2bc345339527c08d5889e8d878ddee033a9b2578', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"4.15 Opinion","subsection":"UNKNOWN","table_id":null,"page":91,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":236,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"4.15 Opinion"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p91-237', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '4.15 Opinion', 91, 'Because Opinions are typically (though not always) created by human analysts and are comprised of human-oriented text, they contain an additional property to capture the analyst(s) that created the Opinion. This is distinct from the created_by_ref property, which is meant to capture the organization that created the object. 4.15.1 Properties Required Common Properties type, spec_version, id, created, modified Optional Common Properties created_by_ref, revoked, labels, confidence, lang, external_references, object_marking_refs,granular_markings, extensions Not Applicable Common Properties defanged Opinion Specific Properties explanation, authors, opinion, object_refs Property Name Type Description type (required) string The value of this property MUST be opinion. explanation (optional) string An explanation of why the producer has this Opinion.', 'vec_doc-10-oasis-stix21-p91-237', 0, 214, 'v2.1.0', '9451a8e1e7a08854e2350cc16ea564d0a05794764ec46ea72ec4d999a14a22b1', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"4.15 Opinion","subsection":"UNKNOWN","table_id":null,"page":91,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":237,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"4.15 Opinion"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p91-238', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '4.15 Opinion', 91, 'For example, if an Opinion of strongly-disagree is given, the explanation can contain an explanation of why the Opinion producer disagrees and what evidence they have for their disagreement.', 'vec_doc-10-oasis-stix21-p91-238', 0, 48, 'v2.1.0', '1f26834576dc75b6cbd8280b901fd7ef32ffca13322bf260b3d69684651b85ef', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"4.15 Opinion","subsection":"UNKNOWN","table_id":null,"page":91,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":238,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"4.15 Opinion"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p92-239', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '4.15 Opinion', 92, 'Standards Track Work Product 02 April 2025 - Page 92 of 276Copyright © OASIS Open 2025. All Rights Reserved. authors(optional) list of type string The name of the author(s) of this Opinion (e.g., theanalyst(s) that created it). opinion (required) enum The opinion that the producer has about all of the STIX Object(s) listed in the object_refs property. The values of this property MUST come from the opinion-enum enumeration. object_refs (required) list of type identifier The STIX Objects that the Opinion is being applied to. 4.15.2 Relationships There are no relationships explicitly defined between the Opinion object and other STIX Objects, other than those defined as common relationships. The first section lists the embedded relationships by property name along with their corresponding target. Relationships are not restricted to those listed below. Relationships can be created between any objects using the related-to relationship name or, as with open vocabularies, user-defined names.', 'vec_doc-10-oasis-stix21-p92-239', 0, 250, 'v2.1.0', '24f239b3167e39bb2d27bd07aad78f5a3017040272ddd74fda3c94c293a144c3', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"4.15 Opinion","subsection":"UNKNOWN","table_id":null,"page":92,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":239,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"4.15 Opinion"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p92-240', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '4.15 Opinion', 92, 'Embedded Relationships created_by_ref identifier (of type identity) object_marking_refs list of type identifier (of type marking- definition) object_refs list of type identifier (of type any STIX Object type) Common Relationships duplicate-of, derived-from, related-to Source Relationship Type Target Description — — — — Example { "type": "opinion", "spec_version": "2.1", "id": "opinion--b01efc25-77b4-4003-b18b-f6e24b5cd9f7", "created_by_ref": "identity--f431f809-377b-45e0-aa1c-6a4751cae5ff", "created": "2016-05-12T08:17:27.000Z", "modified": "2016-05-12T08:17:27.000Z", "object_refs": ["relationship--16d2358f-3b0d-4c88-b047-0da2f7ed4471"], "opinion": "strongly-disagree", "explanation": "This doesn''t seem like it is feasible. We''ve seen how PandaCat has attacked Spanish infrastructure over the last 3 years, so this change in targeting seems too great to be viable. The methods used are more commonly associated with the FlameDragonCrew." }', 'vec_doc-10-oasis-stix21-p92-240', 0, 237, 'v2.1.0', '2766489ee10a871d2a2ec46018f7386b1b802ee0ac888f4f6aebb1d332705f3a', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"4.15 Opinion","subsection":"UNKNOWN","table_id":null,"page":92,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":240,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"4.15 Opinion"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p93-241', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '4.16 Report', 93, 'Type Name: report Reports are collections of threat intelligence focused on one or more topics, such as a description of a threat actor, malware, or attack technique, including context and related details. They are used to group related threat intelligence together so that it can be published as a comprehensive cyber threat story. The Report SDO contains a list of references to STIX Objects (the CTI objects included in the report) along with a textual description and the name of the report. For example, a threat report produced by ACME Defense Corp. discussing the Glass Gazelle campaign should be represented using Report. The Report itself would contain the narrative of the report while the Campaign SDO and any related SDOs (e.g., Indicators for the Campaign, Malware it uses, and the associated Relationships) would be referenced in the report contents. 4.16.1 Properties Required Common Properties type, spec_version, id, created, modified Optional Common Properties created_by_ref, revoked, labels, confidence, lang, external_references, object_marking_refs, granular_markings, extensions Not Applicable Common Properties defanged Report Specific Properties name, description, report_types, published, object_refs Property Name Type Description type (required) string The value of this property MUST be report. name (required) string A name or characterizing text used to identify the Report. description (optional) string A description that provides more details and context about the Report, potentially including its purpose and its key characteristics. report_types (optional) list of type open-vocab The primary type(s) of content found in this report. The values for this property SHOULD come from the report-type-ov open vocabulary.', 'vec_doc-10-oasis-stix21-p93-241', 0, 438, 'v2.1.0', 'c331c45ee6060a911d49e7740852d6465c04293364eeb8504f2bd093d5664c3e', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"4.16 Report","subsection":"UNKNOWN","table_id":null,"page":93,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":241,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"4.16 Report"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p94-242', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '4.16 Report', 94, 'Standards Track Work Product 02 April 2025 - Page 94 of 276Copyright © OASIS Open 2025. All Rights Reserved. published(required) timestamp The date that this Report object was officiallypublished by the creator of this report. The publication date (public release, legal release, etc.) may be different than the date the report was created or shared internally (the date in the created property). object_refs (required) list of type identifier Specifies the STIX Objects that are referred to by this Report. 4.16.2 Relationships There are no relationships explicitly defined between the Report object and other STIX Objects, other than those defined as common relationships. The first section lists the embedded relationships by property name along with their corresponding target. Relationships are not restricted to those listed below. Relationships can be created between any objects using the related-to relationship name or, as with open vocabularies, user-defined names.', 'vec_doc-10-oasis-stix21-p94-242', 0, 244, 'v2.1.0', 'c522285a53ec11495d6ba5e57f210ec2cc532e7128a965eba432a7793ea6cb58', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"4.16 Report","subsection":"UNKNOWN","table_id":null,"page":94,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":242,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"4.16 Report"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p94-243', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '4.16 Report', 94, 'Embedded Relationships created_by_ref identifier (of type identity) object_marking_refs list of type identifier (of type marking- definition) object_refs list of type identifier (of type any STIX Object type) Common Relationships duplicate-of, derived-from, related-to Source Relationship Type Target Description — — — — Examples A standalone Report; the consumer may or may not already have access to the referenced STIX Objects. { "type": "report", "spec_version": "2.1", "id": "report--84e4d88f-44ea-4bcd-bbf3-b2c1c320bcb3", "created_by_ref": "identity--a463ffb3-1bd9-4d94-b02d-74e4f1658283", "created": "2015-12-21T19:59:11.000Z", "modified": "2015-12-21T19:59:11.000Z", "name": "The Black Vine Cyberespionage Group", "description": "A simple report with an indicator and campaign", "published": "2016-01-20T17:00:00.000Z", "report_types": ["campaign"], "object_refs": [ "indicator--26ffb872-1dd9-446e-b6f5-d58527e5b5d2", "campaign--83422c77-904c-4dc1-aff5-5c38f3a2c55c",', 'vec_doc-10-oasis-stix21-p94-243', 0, 244, 'v2.1.0', '0dbd634b34737573d004f9286ff302bddbaa227ff23cdc057b5e17d89f6d84c3', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"4.16 Report","subsection":"UNKNOWN","table_id":null,"page":94,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":243,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"4.16 Report"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p95-244', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '4.16 Report', 95, 'Standards Track Work Product 02 April 2025 - Page 95 of 276Copyright © OASIS Open 2025. All Rights Reserved.', 'vec_doc-10-oasis-stix21-p95-244', 0, 27, 'v2.1.0', 'c61f615f2744f6b580485d603a9d49a4d032518f7852d92cfec4b24e80ce2fef', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"4.16 Report","subsection":"UNKNOWN","table_id":null,"page":95,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":244,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"4.16 Report"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p95-245', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '4.16 Report', 95, '"relationship--f82356ae-fe6c-437c-9c24-6b64314ae68a" ] } A Bundle with a Report and the STIX Objects that are referred to by the Report { "type": "bundle", "id": "bundle--44af6c39-c09b-49c5-9de2-394224b04982", "objects": [ { "type": "identity", "spec_version": "2.1", "id": "identity--a463ffb3-1bd9-4d94-b02d-74e4f1658283", "created": "2015-01-21T19:59:17.000Z", "modified": "2015-01-21T19:59:17.000Z", "name": "Acme Cybersecurity Solutions" }, { "type": "report", "spec_version": "2.1", "id": "report--84e4d88f-44ea-4bcd-bbf3-b2c1c320bcbd", "created_by_ref": "identity--a463ffb3-1bd9-4d94-b02d-74e4f1658283", "created": "2015-12-21T19:59:11.000Z", "modified": "2016-05-21T19:59:11.000Z", "name": "The Black Vine Cyberespionage Group", "description": "A simple report with an indicator and campaign", "published": "2016-01-20T17:00:00.000Z", "report_types": ["campaign"], "object_refs": [ "indicator--26ffb872-1dd9-446e-b6f5-d58527e5b5d2", "campaign--83422c77-904c-4dc1-aff5-5c38f3a2c55c", "relationship--f82356ae-fe6c-437c-9c24-6b64314ae68a" ] }, { "type": "indicator", "spec_version": "2.1", "id": "indicator--26ffb872-1dd9-446e-b6f5-d58527e5b5d2", "created": "2015-12-21T19:59:17.000Z", "modified": "2016-05-21T19:59:17.000Z", "name": "Some indicator", "indicator_types": ["malicious-activity"], "pattern": "[ file:hashes.MD5 = ''3773a88f65a5e780c8dff9cdc3a056f3'' ]", "valid_from": "2015-12-21T19:59:17Z", "created_by_ref": "identity--a463ffb3-1bd9-4d94-b02d-74e4f1658283" }, { "type": "campaign", "spec_version": "2.1", "id": "campaign--83422c77-904c-4dc1-aff5-5c38f3a2c55c", "created_by_ref": "identity--a463ffb3-1bd9-4d94-b02d-74e4f1658283", "created": "2015-12-21T19:59:17.000Z", "modified": "2016-05-21T19:59:17.000Z", "name": "Some Campaign" }, { "type": "relationship", "spec_version": "2.1", "id": "relationship--f82356ae-fe6c-437c-9c24-6b64314ae68a", "created_by_ref": "identity--a463ffb3-1bd9-4d94-b02d-74e4f1658283", "created": "2015-12-21T19:59:17.000Z", "modified": "2015-12-21T19:59:17.000Z", "source_ref": "indicator--26ffb872-1dd9-446e-b6f5-d58527e5b5d2", "target_ref": "campaign--83422c77-904c-4dc1-aff5-5c38f3a2c55c", "relationship_type": "indicates"', 'vec_doc-10-oasis-stix21-p95-245', 0, 543, 'v2.1.0', '23c765fc3d08d2bc5e1ea8f002b726c5151f0630ea59c65480ee8ea7d7d4aba6', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"4.16 Report","subsection":"UNKNOWN","table_id":null,"page":95,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":245,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"4.16 Report"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p96-246', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '4.17 Threat Actor', 96, 'Type Name: threat-actor Threat Actors are actual individuals, groups, or organizations believed to be operating with malicious intent. A Threat Actor is not an Intrusion Set but may support or be affiliated with various Intrusion Sets, groups, or organizations over time. Threat Actors leverage their resources, and possibly the resources of an Intrusion Set, to conduct attacks and run Campaigns against targets. Threat Actors can be characterized by their motives, capabilities, goals, sophistication level, past activities, resources they have access to, and their role in the organization. 4.17.1 Properties Required Common Properties type, spec_version, id, created, modified Optional Common Properties created_by_ref, revoked, labels, confidence, lang, external_references, object_marking_refs, granular_markings, extensions Not Applicable Common Properties defanged Threat Actor Specific Properties name, description, threat_actor_types, aliases, first_seen, last_seen, roles, goals, sophistication, resource_level, primary_motivation, secondary_motivations, personal_motivations Property Name Type Description type (required) string The value of this property MUST be threat-actor. name (required) string A name or characterizing text used to identify the Threat Actor or Threat Actor group. description (optional) string A description that provides more details and context about the Threat Actor, potentially including its purpose and its key characteristics. threat_actor_types (optional) list of type open-vocab The type(s) of this threat actor. The values for this property SHOULD come', 'vec_doc-10-oasis-stix21-p96-246', 0, 400, 'v2.1.0', '24b4286ee3508c29aafce16bf487aa373446c8c4ba7860803b9f5b5f3321b680', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"4.17 Threat Actor","subsection":"UNKNOWN","table_id":null,"page":96,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":246,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"4.17 Threat Actor"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p97-247', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '4.17 Threat Actor', 97, 'Standards Track Work Product 02 April 2025 - Page 97 of 276Copyright © OASIS Open 2025. All Rights Reserved. from the threat-actor-type-ov open vocabulary. aliases (optional) list of type string A list of other names that this Threat Actor is believed to use. first_seen (optional) timestamp The time that this Threat Actor was first seen. This property is a summary property of data from sightings and other data that may or may not be available in STIX. If new sightings are received that are earlier than the first seen timestamp, the object may be updated to account for the new data. last_seen (optional) timestamp The time that this Threat Actor was last seen. This property is a summary property of data from sightings and other data that may or may not be available in STIX. If new sightings are received that are later than the last seen timestamp, the object may be updated to account for the new data.', 'vec_doc-10-oasis-stix21-p97-247', 0, 228, 'v2.1.0', 'a2b257443e525bd6c70d45997fb139fee74523f3b076842893686fd4e0e1d71a', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"4.17 Threat Actor","subsection":"UNKNOWN","table_id":null,"page":97,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":247,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"4.17 Threat Actor"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p97-248', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '4.17 Threat Actor', 97, 'If this property and the first_seen property are both defined, then this property MUST be greater than or equal to the timestamp in the first_seen property. roles (optional) list of type open-vocab A list of roles the Threat Actor plays. The values for this property SHOULD come from the threat-actor-role-ov open vocabulary. goals (optional) list of type string The high-level goals of this Threat Actor, namely, what are they trying to do. Forexample, they may be motivated by personal gain, but their goal is to steal credit card numbers. To do this, they may execute specific Campaigns that have detailed objectives like compromising point of sale systems at a large retailer. sophistication (optional) open-vocab The skill, specific knowledge, special training, or expertise a Threat Actor must have to perform the attack. The value for this property SHOULD come from the threat-actor- sophistication-ov open vocabulary.', 'vec_doc-10-oasis-stix21-p97-248', 0, 232, 'v2.1.0', '3e9f6b2270cc639e3d9020a342e7bc831bc090347ce62e54dcff415fb2aa623a', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"4.17 Threat Actor","subsection":"UNKNOWN","table_id":null,"page":97,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":248,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"4.17 Threat Actor"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p97-249', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '4.17 Threat Actor', 97, 'resource_level (optional) open-vocab The organizational level at which this Threat Actor typically works, which in turn determines the resources available to this Threat Actor for use in an attack. This attribute is linked to the sophistication', 'vec_doc-10-oasis-stix21-p97-249', 0, 61, 'v2.1.0', '6241f8a4d1ee609516d2617f43c7768e1f59b25204eac26947d3ca64b1dbe9d1', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"4.17 Threat Actor","subsection":"UNKNOWN","table_id":null,"page":97,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":249,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"4.17 Threat Actor"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p98-250', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '4.17 Threat Actor', 98, 'Standards Track Work Product 02 April 2025 - Page 98 of 276Copyright © OASIS Open 2025. All Rights Reserved. property — a specific resource level implies that the Threat Actor has access to at least a specific sophistication level. The value for this property SHOULD come from the attack-resource-level-ov open vocabulary. primary_motivation (optional) open-vocab The primary reason, motivation, or purpose behind this Threat Actor. The motivation is why the Threat Actor wishes to achieve the goal (what they are trying to achieve). The value for this property SHOULD come from the attack-motivation-ov open vocabulary. secondary_motivations (optional) list of type open-vocab This property specifies the secondary reasons, motivations, or purposes behind this Threat Actor. These motivations can exist as an equal or near-equal cause to the primary motivation. However, it does not replace or necessarily magnify the primary motivation, but it might indicate additional context.', 'vec_doc-10-oasis-stix21-p98-250', 0, 245, 'v2.1.0', '1d4c7199fede6dd04aa09af708a55f43c2294f9d01a75cabfa14774c363903c4', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"4.17 Threat Actor","subsection":"UNKNOWN","table_id":null,"page":98,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":250,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"4.17 Threat Actor"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p98-251', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '4.17 Threat Actor', 98, 'The position in the list has no significance. The value for this property SHOULD come from the attack-motivation-ov open vocabulary. personal_motivations (optional) list of type open-vocab The personal reasons, motivations, or purposes of the Threat Actor regardless of organizational goals. Personal motivation, which is independent of the organization’s goals, describes what impels an individual to carry out an attack. Personal motivation may align with the organization’s motivation — as is common with activists — but more often it supports personal goals. For example, an individual analyst may join a Data Miner corporation because his or her skills may align with the corporation’s objectives. But the analyst most likely performs his or her daily work toward those objectives for personal reward in the form of a paycheck.', 'vec_doc-10-oasis-stix21-p98-251', 0, 208, 'v2.1.0', 'bd92071be6b7c7b023ff34cad6b62cd01fe98be3ec76aa9fc27eb8d42abcadc8', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"4.17 Threat Actor","subsection":"UNKNOWN","table_id":null,"page":98,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":251,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"4.17 Threat Actor"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p98-252', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '4.17 Threat Actor', 98, 'The motivation of personal reward may be even stronger for Threat Actors who commit illegal acts, as it is more difficult for someone to cross that line purely for altruistic reasons. The position in the list has no significance. The values for this property SHOULD come from the attack-motivation-ov open vocabulary.', 'vec_doc-10-oasis-stix21-p98-252', 0, 80, 'v2.1.0', '3fdef7002176e277d1a76ee7f773d4d5a96521a037a344751c79efd8b1863d8b', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"4.17 Threat Actor","subsection":"UNKNOWN","table_id":null,"page":98,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":252,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"4.17 Threat Actor"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p99-253', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '4.17 Threat Actor', 99, 'Standards Track Work Product 02 April 2025 - Page 99 of 276Copyright © OASIS Open 2025. All Rights Reserved. 4.17.2 Relationships These are the relationships explicitly defined between the Threat Actor object and other STIX Objects. The first section lists the embedded relationships by property name along with their corresponding target. The rest of the table identifies the relationships that can be made from this object type to another object type by way of the Relationship object. The reverse relationships section illustrates the relationships targeting this object type from another object type. They are included here for convenience. For their definitions, please see the “Source” object. Relationships are not restricted to those listed below. Relationships can be created between any objects using the related-to relationship type or, as with open vocabularies, user-defined names.', 'vec_doc-10-oasis-stix21-p99-253', 0, 224, 'v2.1.0', 'c59ec76742a82e9d2bf7ad1bbfd8b3e1842fd2604bb8f9dc717b04f51206fa51', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"4.17 Threat Actor","subsection":"UNKNOWN","table_id":null,"page":99,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":253,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"4.17 Threat Actor"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p99-254', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '4.17 Threat Actor', 99, 'Embedded Relationships created_by_ref identifier (of type identity) object_marking_refs list of type identifier (of type marking- definition) Common Relationships duplicate-of, derived-from, related-to Source Relationship Type Target Description threat-actor attributed-to identity This Relationship describes that the Threat Actor’s real identity is the related Identity. For example, an attributed-to Relationship from the jay-sm17h Threat Actor to the John Smith Identity means that the actor known as jay-sm17h is John Smith. threat-actor compromises infrastructure This Relationship describes that the Threat Actor compromises the related Infrastructure. threat-actor hosts, owns infrastructure This Relationship describes that the Threat Actor hosts or owns the related Infrastructure (e.g. an actor that rents botnets to other threat actors). threat-actor impersonates identity This Relationship describes that the Threat Actor impersonates the related Identity.', 'vec_doc-10-oasis-stix21-p99-254', 0, 243, 'v2.1.0', '11a67bac2ec7ffc3bed31b1875b00f5a8eebee2d3a16764511a62c7e90dcad13', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"4.17 Threat Actor","subsection":"UNKNOWN","table_id":null,"page":99,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":254,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"4.17 Threat Actor"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p99-255', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '4.17 Threat Actor', 99, 'For example, an impersonates Relationship from the gh0st Threat Actor to the ACME Corp. Identity means that the actor known as gh0st impersonates ACME Corp.', 'vec_doc-10-oasis-stix21-p99-255', 0, 39, 'v2.1.0', '183ede3470311f67791512ab46ea6e4020a30b6d8ccdda8e37c6891d8b27174d', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"4.17 Threat Actor","subsection":"UNKNOWN","table_id":null,"page":99,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":255,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"4.17 Threat Actor"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p100-256', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '4.17 Threat Actor', 100, 'Standards Track Work Product 02 April 2025 - Page 100 of 276Copyright © OASIS Open 2025. All Rights Reserved. threat-actor located-at location This Relationship describes that theThreat Actor is located at or in the related Location. For example, a located-at relationship from the gh0st Threat Actor to a Location representing the United States means that ACME Corporation is located in the United States. threat-actor targets identity, location, vulnerability This Relationship describes that the Threat Actor uses exploits of the related Vulnerability or targets the type of victims described by the related Identity or Location. For example, a targets Relationship from the jay-sm17h Threat Actor to a Vulnerability in a blogging platform indicates that attacks performed by John Smith often exploit that Vulnerability. Similarly, a targets Relationship from the jay-sm17h Threat Actor to an Identity describing the energy sector in the United States means that John Smith often carries out attacks against targets in that sector. threat-actor uses attack-pattern, infrastructure, malware, tool This Relationship describes that attacks carried out as part of the Threat Actor typically use the related Attack Pattern, Infrastructure, Malware, or Tool. For example, a uses Relationship from the jay-sm17h Threat Actor to the xInject Malware indicates that xInject is often used by John Smith. A campaign, threat actor, intrusion set, malware, or tool takes infrastructure and compromises and/or uses it for their own. Reverse Relationships campaign, intrusion-set attributed-to threat-actor See forward relationship for definition. malware authored-by threat-actor See forward relationship for definition. indicator indicates threat-actor See forward relationship for definition.', 'vec_doc-10-oasis-stix21-p100-256', 0, 446, 'v2.1.0', '010507e9618d8d6f3a5d5642920e80bd3a5365221ab5f4b5ed0f4605865bbc9f', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"4.17 Threat Actor","subsection":"UNKNOWN","table_id":null,"page":100,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":256,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"4.17 Threat Actor"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p101-257', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '4.17 Threat Actor', 101, 'Standards Track Work Product 02 April 2025 - Page 101 of 276Copyright © OASIS Open 2025. All Rights Reserved. Example { "type": "threat-actor", "spec_version": "2.1", "id": "threat-actor--8e2e2d2b-17d4-4cbf-938f-98ee46b3cd3f", "created_by_ref": "identity--f431f809-377b-45e0-aa1c-6a4751cae5ff", "created": "2016-04-06T20:03:48.000Z", "modified": "2016-04-06T20:03:48.000Z", "threat_actor_types": [ "crime-syndicate"], "name": "Evil Org", "description": "The Evil Org threat actor group", "aliases": ["Syndicate 1", "Evil Syndicate 99"], "roles": ["director"], "goals": ["Steal bank money", "Steal credit cards"], "sophistication": "advanced", "resource_level": "team", "primary_motivation": "organizational-gain" }', 'vec_doc-10-oasis-stix21-p101-257', 0, 179, 'v2.1.0', '8dba1f7173ba6566d95b048eb83f54d550b9d364a36d5ce47d653146b89ce6ee', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"4.17 Threat Actor","subsection":"UNKNOWN","table_id":null,"page":101,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":257,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"4.17 Threat Actor"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p101-258', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '4.18 Tool', 101, 'Type Name: tool Tools are legitimate software that can be used by threat actors to perform attacks. Knowing how and when threat actors use such tools can be important for understanding how campaigns are executed. Unlike malware, these tools or software packages are often found on a system and have legitimate purposes for power users, system administrators, network administrators, or even normal users. Remote access tools (e.g., RDP) and network scanning tools (e.g., Nmap) are examples of Tools that may be used by a Threat Actor during an attack. The Tool SDO characterizes the properties of these software tools and can be used as a basis for making an assertion about how a Threat Actor uses them during an attack. It contains properties to name and describe the tool, a list of Kill Chain Phases the tool can be used to carry out, and the version of the tool. This SDO MUST NOT be used to characterize malware. Further, Tool MUST NOT be used to characterize tools used as part of a course of action in response to an attack. 4.18.1 Properties Required Common Properties type, spec_version, id, created, modified Optional Common Properties created_by_ref, revoked, labels, confidence, lang, external_references, object_marking_refs, granular_markings, extensions Not Applicable Common Properties defanged Tool Specific Properties name, description, tool_types, aliases, kill_chain_phases, tool_version Property Name Type Description', 'vec_doc-10-oasis-stix21-p101-258', 0, 360, 'v2.1.0', '019c4046b160a8689b3265795b65f1757fb2f3fb6235cdcfeb42f74095d66038', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"4.18 Tool","subsection":"UNKNOWN","table_id":null,"page":101,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":258,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"4.18 Tool"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p102-259', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '4.18 Tool', 102, 'Standards Track Work Product 02 April 2025 - Page 102 of 276Copyright © OASIS Open 2025. All Rights Reserved. type (required) string The value of this property MUST be tool. name (required) string A name or characterizing text used to identify the Tool. description (optional) string A description that provides more details and context about the Tool, potentially including its purpose and its key characteristics. tool_types (optional) list of type open-vocab The kind(s) of tool(s) being described. The values for this property SHOULD come from the tool-type-ov open vocabulary. aliases (optional) list of type string Alternative names used to identify this Tool. kill_chain_phases (optional) list of type kill-chain-phase The list of kill chain phases for which this Tool can be used. tool_version (optional) string The version identifier associated with the Tool. 4.18.2 Relationships These are the relationships explicitly defined between the Tool object and other STIX Objects.', 'vec_doc-10-oasis-stix21-p102-259', 0, 246, 'v2.1.0', '25a54868788ea5aae8343fafcf2170d3901d8b060500a0c1e5e991de11b299d9', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"4.18 Tool","subsection":"UNKNOWN","table_id":null,"page":102,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":259,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"4.18 Tool"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p102-260', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '4.18 Tool', 102, 'The first section lists the embedded relationships by property name along with their corresponding target. The rest of the table identifies the relationships that can be made from this object type to another object type by way of the Relationship object. The reverse relationships section illustrates the relationships targeting this object type from another object type. They are included here for convenience. For their definitions, please see the “Source” object. Relationships are not restricted to those listed below. Relationships can be created between any objects using the related-to relationship type or, as with open vocabularies, user-defined names.', 'vec_doc-10-oasis-stix21-p102-260', 0, 166, 'v2.1.0', 'f47dfb9a27cde64d872db952c3176700c31e944527b63af35954e8d755713f1c', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"4.18 Tool","subsection":"UNKNOWN","table_id":null,"page":102,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":260,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"4.18 Tool"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p102-261', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '4.18 Tool', 102, 'Embedded Relationships created_by_ref identifier (of type identity) object_marking_refs list of type identifier (of type marking- definition) Common Relationships duplicate-of, derived-from, related-to Source Relationship Type Target Description tool delivers malware This Relationship describes that this Tool is used to deliver a malware instance (or family).', 'vec_doc-10-oasis-stix21-p102-261', 0, 91, 'v2.1.0', '900d70be05d4f3fcd592b41c3a04d3efd9805919294ef1ed6c0c1d9560b48538', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"4.18 Tool","subsection":"UNKNOWN","table_id":null,"page":102,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":261,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"4.18 Tool"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p103-262', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '4.18 Tool', 103, 'Standards Track Work Product 02 April 2025 - Page 103 of 276Copyright © OASIS Open 2025. All Rights Reserved. tool drops malware This Relationship documents that thisTool drops a malware instance (or family). tool has vulnerability This Relationship describes that this specific Tool has this specific Vulnerability. For example, a tool may not have been patched and currently is impacted by a CVE. tool targets identity, infrastructure, location, vulnerability This Relationship documents that this Tool is being used to target this Identity, Infrastructure, Location, or exploit the Vulnerability. For example, a targets Relationship linking an exploit Tool to a Vulnerability for CVE-2016-0001 means that the tool exploits that vulnerability. Similarly, a targets Relationship linking a DDoS Tool to an Identity representing the energy sector means that Tool is typically used against targets in the energy sector. tool uses infrastructure This Relationship describes that this Tool uses the related Infrastructure. Reverse Relationships infrastructure hosts tool See forward relationship for definition. malware downloads, drops tool See forward relationship for definition indicator indicates tool See forward relationship for definition course-of- action mitigates tool See forward relationship for definition attack- pattern, campaign, intrusion-set, malware, threat-actor uses tool See forward relationship for definition Example { "type": "tool",', 'vec_doc-10-oasis-stix21-p103-262', 0, 364, 'v2.1.0', '7b2adb79dfc30fc19935594c4866fb88ef578b13be4a5125480afa60bffe858d', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"4.18 Tool","subsection":"UNKNOWN","table_id":null,"page":103,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":262,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"4.18 Tool"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p104-263', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '4.18 Tool', 104, 'Standards Track Work Product 02 April 2025 - Page 104 of 276Copyright © OASIS Open 2025. All Rights Reserved. "spec_version": "2.1", "id": "tool--8e2e2d2b-17d4-4cbf-938f-98ee46b3cd3f", "created_by_ref": "identity--f431f809-377b-45e0-aa1c-6a4751cae5ff", "created": "2016-04-06T20:03:48.000Z", "modified": "2016-04-06T20:03:48.000Z", "tool_types": [ "remote-access"], "name": "VNC" }', 'vec_doc-10-oasis-stix21-p104-263', 0, 96, 'v2.1.0', '5868a75ddde6e17ef87c16b3e9383cbeac91a8d3cbeb73817626a9261016f3b8', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"4.18 Tool","subsection":"UNKNOWN","table_id":null,"page":104,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":263,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"4.18 Tool"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p104-264', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '4.19 Vulnerability', 104, 'Type Name: vulnerability A Vulnerability is a weakness or defect in the requirements, designs, or implementations of the computational logic (e.g., code) found in software and some hardware components (e.g., firmware) that can be directly exploited to negatively impact the confidentiality, integrity, or availability of that system. CVE is a list of information security vulnerabilities and exposures that provides common names for publicly known problems [CVE]. For example, if a piece of malware exploits CVE-2015-12345, a Malware object could be linked to a Vulnerability object that references CVE-2015-12345. The Vulnerability SDO is primarily used to link to external definitions of vulnerabilities or to describe 0-day vulnerabilities that do not yet have an external definition. Typically, other SDOs assert relationships toVulnerability objects when a specific vulnerability is targeted and exploited as part of malicious cyber activity. As such, Vulnerability objects can be used as a linkage to the asset management and compliance process. 4.19.1 Properties Required Common Properties type, spec_version, id, created, modified Optional Common Properties created_by_ref, revoked, labels, confidence, lang, external_references, object_marking_refs, granular_markings, extensions Not Applicable Common Properties defanged Vulnerability Specific Properties name, description Property Name Type Description type (required) string The value of this property MUST be vulnerability. external_references (optional) list of type external-reference A list of external references which refer to non-STIX information. This property MAY be used to provide one or more Vulnerability identifiers, such as a CVE ID [CVE]. When specifying a CVE ID, the source_name property of the', 'vec_doc-10-oasis-stix21-p104-264', 0, 444, 'v2.1.0', '0cc92e497ec45476f8a5bc6e4822a0a68661ce0178c6c9e435b637359a57fa57', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"4.19 Vulnerability","subsection":"UNKNOWN","table_id":null,"page":104,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":264,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"4.19 Vulnerability"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p105-265', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '4.19 Vulnerability', 105, 'Standards Track Work Product 02 April 2025 - Page 105 of 276Copyright © OASIS Open 2025. All Rights Reserved. external reference MUST be set to cve and the external_id property MUST be the exact CVE identifier. name (required) string A name or characterizing text used to identify the Vulnerability. description (optional) string A description that provides more details and context about the Vulnerability, potentially including its purpose and its key characteristics. 4.19.2 Relationships These are the relationships explicitly defined between the Vulnerability object and other STIX Objects. The first section lists the embedded relationships by property name along with their corresponding target. The rest of the table identifies the relationships that can be made from this object type to another object type by way of the Relationship object. The reverse relationships section illustrates the relationships targeting this object type from another object type. They are included here for convenience.', 'vec_doc-10-oasis-stix21-p105-265', 0, 252, 'v2.1.0', 'c5f721756456298fc3682c8ff6b3bf685cd0094e72aa89b1065f94de4f786004', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"4.19 Vulnerability","subsection":"UNKNOWN","table_id":null,"page":105,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":265,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"4.19 Vulnerability"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p105-266', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '4.19 Vulnerability', 105, 'For their definitions, please see the “Source” object. Relationships are not restricted to those listed below. Relationships can be created between any objects using the related-to relationship type or, as with open vocabularies, user-defined names. Embedded Relationships created_by_ref identifier (of type identity) object_marking_refs list of type identifier (of type marking- definition) Common Relationships duplicate-of, derived-from, related-to Source Relationship Type Target Description — — — — Reverse Relationships attack- pattern, campaign, intrusion-set, malware, threat-actor, tool targets vulnerability See forward relationship for definition. malware exploits vulnerability See forward relationship for definition. course-of- action mitigates, remediates vulnerability See forward relationship for definition.', 'vec_doc-10-oasis-stix21-p105-266', 0, 207, 'v2.1.0', '1bc6dafa1e22eb47e52b4d242cff76fa042a1e214024c069c0f7c47a31174ed0', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"4.19 Vulnerability","subsection":"UNKNOWN","table_id":null,"page":105,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":266,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"4.19 Vulnerability"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p106-267', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '4.19 Vulnerability', 106, 'Standards Track Work Product 02 April 2025 - Page 106 of 276Copyright © OASIS Open 2025. All Rights Reserved. infrastructure has vulnerability See forward relationship for definition. Example { "type": "vulnerability", "spec_version": "2.1", "id": "vulnerability--0c7b5b88-8ff7-4a4d-aa9d-feb398cd0061", "created": "2016-05-12T08:17:27.000Z", "modified": "2016-05-12T08:17:27.000Z", "created_by_ref": "identity--f431f809-377b-45e0-aa1c-6a4751cae5ff", "name": "CVE-2016-1234", "external_references": [ { "source_name": "cve", "external_id": "CVE-2016-1234" } ] }', 'vec_doc-10-oasis-stix21-p106-267', 0, 140, 'v2.1.0', 'f8e1b7ea95d362a582a4889b271c4b108d3c41c6eb58f3d04af8f15c31ad24c8', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"4.19 Vulnerability","subsection":"UNKNOWN","table_id":null,"page":106,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":267,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"4.19 Vulnerability"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p107-268', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '5. STIX Relationship Objects', 107, 'STIX Relationship Objects (SROs) represent types of relationships used to describe CTI. The Generic Relationship SRO is used to describe many varied types of relationships, while the specific Sighting SRO contains additional properties to represent Sighting relationships. Property information, relationship information, and examples are provided for each SRO defined below. Property information includes common properties as well as properties that are specific to each SRO. Because SROs cannot be the source or target of other SROs, relationship information is included but only to describe embedded relationships (e.g., created_by_ref).', 'vec_doc-10-oasis-stix21-p107-268', 0, 160, 'v2.1.0', 'e26f64906feb2875e647254e6466ec9da45579c251bd45d642621dad6bcab015', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"5. STIX Relationship Objects","subsection":"UNKNOWN","table_id":null,"page":107,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":268,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"5. STIX Relationship Objects"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p107-269', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '5.1 Relationship', 107, 'Type Name: relationship The Relationship object is used to link together two SDOs or SCOs in order to describe how they are related to each other. If SDOs and SCOs are considered “nodes” or “vertices” in the graph, the Relationship Objects (SROs) represent “edges”. STIX defines many relationship types to link together SDOs and SCOs. These relationships are contained in the “Relationships” table under each SDO and SCO definition. Relationship types defined in the specification SHOULD be used to ensure consistency. An example of a specification-defined relationship is that an indicator indicates a campaign. That relationship type is listed in the Relationships section of the Indicator SDO definition. STIX also allows relationships from any SDO or SCO to any SDO or SCO that have not been defined in this specification. These relationships MAY use the related-to relationship type or MAY use a user- defined relationship type. As an example, a user might want to link malware directly to a tool.', 'vec_doc-10-oasis-stix21-p107-269', 0, 251, 'v2.1.0', '98ad329dedb0724aa019d7d3514e34a4942217f1bfe0a8b7561e9494ee919e96', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"5.1 Relationship","subsection":"UNKNOWN","table_id":null,"page":107,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":269,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"5.1 Relationship"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p107-270', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '5.1 Relationship', 107, 'They can do so using related-to to say that the Malware is related to the Tool but not describe how, or they could use delivered-by (a user-defined name they determined) to indicate more detail. Note that some relationships in STIX may seem like “shortcuts”. For example, an Indicator doesn’t really detect a Campaign: it detects activity (Attack Patterns, Malware, Infrastructure, etc.) that are often used by that campaign. While some analysts might want all of the source data and think that shortcuts are misleading, in many cases it’s helpful to provide just the key points (shortcuts) and leave out the low-level details. In other cases, the low-level analysis may not be known or sharable, while the high-level analysis is. For these reasons, relationships that might appear to be “shortcuts” are not excluded from STIX. 5.1.1 Specification-Defined Relationships Summary A relationship summary table for all specification-defined relationships can be found in Appendix B of this document.', 'vec_doc-10-oasis-stix21-p107-270', 0, 249, 'v2.1.0', 'bd93b4e86555c3475422cd9872b2828073fe10dc8201834b17f665090c3ab5e8', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"5.1 Relationship","subsection":"UNKNOWN","table_id":null,"page":107,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":270,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"5.1 Relationship"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p107-271', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '5.1 Relationship', 107, 'The relationship summary table is provided as a convenience. If there is a discrepancy between the table and the relationships defined with each of the SDOs, then the relationships defined with the SDOs MUST be viewed as authoritative. 5.1.2 Properties Required Common Properties type, spec_version, id, created, modified Optional Common Properties created_by_ref, revoked, labels, confidence, lang, external_references, object_marking_refs, granular_markings, extensions Not Applicable Common Properties', 'vec_doc-10-oasis-stix21-p107-271', 0, 126, 'v2.1.0', 'bfa4f296efa1992bd3139fff0375902c838147fc5c82aa9a9d7db56c221d6d67', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"5.1 Relationship","subsection":"UNKNOWN","table_id":null,"page":107,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":271,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"5.1 Relationship"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p108-272', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '5.1 Relationship', 108, 'Standards Track Work Product 02 April 2025 - Page 108 of 276Copyright © OASIS Open 2025. All Rights Reserved. defanged Relationship Specific Properties relationship_type, description, source_ref, target_ref, start_time, stop_time Property Name Type Description type (required) string The value of this property MUST be relationship. relationship_type (required) string The name used to identify the type of Relationship. This value SHOULD be an exact value listed in the relationships for the source and target SDO, but MAY be any string. The value of this property MUST be in ASCII and is limited to characters a-z (lowercase ASCII), 0-9, and hyphen (-). description (optional) string A description that provides more details and context about the Relationship, potentially including its purpose and its key characteristics. source_ref (required) identifier The id of the source (from) object.', 'vec_doc-10-oasis-stix21-p108-272', 0, 224, 'v2.1.0', '2da03f105b9fd9a2361c9371838e093a347b05d2c04c235e740b70719d63d8f5', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"5.1 Relationship","subsection":"UNKNOWN","table_id":null,"page":108,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":272,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"5.1 Relationship"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p108-273', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '5.1 Relationship', 108, 'The value MUST be an ID reference to an SDO or SCO (i.e., it cannot point to an SRO, Bundle, Language Content, or Marking Definition). target_ref (required) identifier The id of the target (to) object. The value MUST be an ID reference to an SDO or SCO (i.e., it cannot point to an SRO, Bundle, Language Content, or Marking Definition). start_time (optional) timestamp This optional timestamp represents the earliest time at which the Relationship between the objects exists. If this property is a future timestamp, at the time the start_time property is defined, then this represents an estimate by the producer of the intelligence of the earliest time at which relationship will be asserted to be true. If it is not specified, then the earliest time at which the relationship between the objects exists is not defined. stop_time (optional) timestamp The latest time at which the Relationship between the objects exists.', 'vec_doc-10-oasis-stix21-p108-273', 0, 231, 'v2.1.0', 'cdbcef76644a97950bab6c00a5bf2df3c81b4cfbc44bb807dce111c8d5dfe238', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"5.1 Relationship","subsection":"UNKNOWN","table_id":null,"page":108,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":273,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"5.1 Relationship"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p108-274', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '5.1 Relationship', 108, 'If this property is a future timestamp, at the time the stop_time property is defined, then this represents an estimate by the producer of the intelligence of the latest time at which relationship will be asserted to be true. If start_time and stop_time are both defined, then stop_time MUST be later than the start_time value. If stop_time is not specified, then the latest time at which the relationship between the objects exists is either not known, not disclosed, or has no defined stop time. 5.1.3 Relationships There are no relationships explicitly defined between the Relationship object and other STIX Objects, other than the embedded relationships listed below. These embedded relationships are listed by property name along with their corresponding target.', 'vec_doc-10-oasis-stix21-p108-274', 0, 192, 'v2.1.0', '3c5af7e6c5f4396ca2650b05e94d02304da517f4607fd9fd14da4913b69abe42', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"5.1 Relationship","subsection":"UNKNOWN","table_id":null,"page":108,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":274,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"5.1 Relationship"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p109-275', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '5.1 Relationship', 109, 'Standards Track Work Product 02 April 2025 - Page 109 of 276Copyright © OASIS Open 2025. All Rights Reserved. The only type of relationship that can point to a Relationship Object is the embedded relationship on the Note, Opinion, and Language Content Objects. Embedded Relationships created_by_ref identifier (of type identity) object_marking_refs list of type identifier (of type marking- definition)', 'vec_doc-10-oasis-stix21-p109-275', 0, 101, 'v2.1.0', 'c9fed7435b1688e693eb2e4e415198fb8b1b33b3740c206a7d7cb5ae49ee18de', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"5.1 Relationship","subsection":"UNKNOWN","table_id":null,"page":109,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":275,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"5.1 Relationship"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p109-276', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '5.2 Sighting', 109, 'Type Name: sighting A Sighting denotes the belief that something in CTI (e.g., an indicator, malware, tool, threat actor, etc.) was seen. Sightings are used to track who and what are being targeted, how attacks are carried out, and to track trends in attack behavior. The Sighting relationship object is a special type of SRO; it is a relationship that contains extra properties not present on the Generic Relationship object. These extra properties are included to represent data specific to sighting relationships (e.g., count, representing how many times something was seen), but for other purposes a Sighting can be thought of as a Relationship with a name of “sighting-of”. Sighting is captured as a relationship because you cannot have a sighting unless you have something that has been sighted. Sighting does not make sense without the relationship to what was sighted.', 'vec_doc-10-oasis-stix21-p109-276', 0, 219, 'v2.1.0', '418e6bf629654a13006a001ad65ec9f8f219941685c213cea6575d8d7906e72e', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"5.2 Sighting","subsection":"UNKNOWN","table_id":null,"page":109,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":276,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"5.2 Sighting"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p109-277', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '5.2 Sighting', 109, 'Sighting relationships relate three aspects of the sighting: - What was sighted, such as the Indicator, Malware, Campaign, or other SDO (sighting_of_ref) - Who sighted it and/or where it was sighted, represented as an Identity (where_sighted_refs) - What was actually seen on systems and networks, represented as Observed Data (observed_data_refs) What was sighted is required; a sighting does not make sense unless you say what you saw. Whosighted it, where it was sighted, and what was actually seen are optional. In many cases it is not necessary to provide that level of detail in order to provide value. Sightings are used whenever any SDO has been “seen”. In some cases, the object creator wishes to convey very little information about the sighting; the details might be sensitive, but the fact that they saw a malware instance or threat actor could still be very useful.', 'vec_doc-10-oasis-stix21-p109-277', 0, 220, 'v2.1.0', 'b82da98b1a4b8f8aacd7e5f03d069c3cf843a9cb6fbb3551cb95f558d4ada249', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"5.2 Sighting","subsection":"UNKNOWN","table_id":null,"page":109,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":277,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"5.2 Sighting"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p109-278', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '5.2 Sighting', 109, 'In other cases, providing the details may be helpful or even necessary; saying exactly which of the 1000 IP addresses in an indicator were sighted is helpful when tracking which of those IPs is still malicious. Sighting is distinct from Observed Data in that Sighting is an intelligence assertion (“I saw this threat actor”) while Observed Data is simply information (“I saw this file”). When you combine them by including the linked Observed Data (observed_data_refs) from a Sighting, you can say “I saw this file, and that makes me think I saw this threat actor”. 5.2.1 Properties Required Common Properties type, spec_version, id, created, modified Optional Common Properties created_by_ref, revoked, labels, confidence, lang, external_references, object_marking_refs,granular_markings, extensions Not Applicable Common Properties', 'vec_doc-10-oasis-stix21-p109-278', 0, 209, 'v2.1.0', '0a1455f9d4617b71f563c9f2f514cd6928479780868f43092f018c687eae9992', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"5.2 Sighting","subsection":"UNKNOWN","table_id":null,"page":109,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":278,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"5.2 Sighting"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p110-279', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '5.2 Sighting', 110, 'Standards Track Work Product 02 April 2025 - Page 110 of 276Copyright © OASIS Open 2025. All Rights Reserved. defanged Sighting Specific Properties description, first_seen, last_seen, count, sighting_of_ref, observed_data_refs, where_sighted_refs, summary Property Name Type Description type (required) string The value of this property MUST be sighting. description (optional) string A description that provides more details and context about the Sighting. first_seen (optional) timestamp The beginning of the time window during which the SDO referenced by the sighting_of_ref property was sighted. last_seen (optional) timestamp The end of the time window during which the SDO referenced by the sighting_of_ref property was sighted. If this property and the first_seen property are both defined, then this property MUST be greater than or equal to the timestamp in the first_seen property.', 'vec_doc-10-oasis-stix21-p110-279', 0, 223, 'v2.1.0', '18aa09bef3d4f7887904003a715fd669e3286cc26b4f0d71425fd43973fff851', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"5.2 Sighting","subsection":"UNKNOWN","table_id":null,"page":110,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":279,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"5.2 Sighting"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p110-280', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '5.2 Sighting', 110, 'count (optional) integer If present, this MUST be an integer between 0 and 999,999,999 inclusive and represents the number of times the SDO referenced by the sighting_of_ref property was sighted. Observed Data has a similar property called number_observed, which refers to the number of times the data was observed. These counts refer to different concepts and are distinct. For example, a single sighting of a DDoS bot might have many millions of observations of the network traffic that it generates. Thus, the Sighting count would be 1 (the bot was observed once) but the Observed Data number_observed would be much higher. As another example, a sighting with a count of 0 can be used to express that an indicator was not seen at all. sighting_of_ref (required) identifier An ID reference to the SDO that was sighted (e.g., Indicator or Malware). For example, if this is a Sighting of an Indicator, that Indicator’s ID would be the value of this property.', 'vec_doc-10-oasis-stix21-p110-280', 0, 240, 'v2.1.0', '7fb7823f7ef090c17baaaf9823926994215fd56bd26fa82e137f44f7e45fc5c3', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"5.2 Sighting","subsection":"UNKNOWN","table_id":null,"page":110,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":280,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"5.2 Sighting"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p111-281', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '5.2 Sighting', 111, 'Standards Track Work Product 02 April 2025 - Page 111 of 276Copyright © OASIS Open 2025. All Rights Reserved. This property MUST reference only an SDO. observed_data_refs (optional) list of type identifier A list of ID references to the Observed Data objects that contain the raw cyber data for this Sighting. For example, a Sighting of an Indicator with an IP address could include the Observed Data for the network connection that the Indicator was used to detect. This property MUST reference only Observed Data SDOs. where_sighted_refs (optional) list of type identifier A list of ID references to the Identity or Location objects describing the entities or types of entities that saw the sighting. Omitting the where_sighted_refs property does not imply that the sighting was seen by the object creator. To indicate that the sighting was seen by the object creator, an Identity representing the object creator should be listed in where_sighted_refs.', 'vec_doc-10-oasis-stix21-p111-281', 0, 239, 'v2.1.0', '0ba0283834d0ac3378b8a73503e77b0e749b5279e1593ed1826f0dd539bc8d98', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"5.2 Sighting","subsection":"UNKNOWN","table_id":null,"page":111,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":281,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"5.2 Sighting"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p111-282', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '5.2 Sighting', 111, 'This property MUST reference only Identity or Location SDOs. summary (optional) string The summary property indicates whether the Sighting should be considered summary data. Summary data is an aggregation of previous Sightings reports and should not be considered primary source data. Default value is false. 5.2.2 Relationships There are no relationships explicitly defined between the Sighting object and other STIX Objects, other than the embedded relationships listed below. These embedded relationships are listed by property name along with their corresponding target. The only type of relationship that can point to a Sighting Object is the embedded relationship on the Note, Opinion, and Language Content Objects. Embedded Relationships created_by_ref identifier (of type identity) object_marking_refs list of type identifier (of type marking- definition) sighting_of_ref identifier (of type SDO) observed_data_refs list of type identifier (of type observed- data)', 'vec_doc-10-oasis-stix21-p111-282', 0, 243, 'v2.1.0', '6c99fb5cb67ebe323d5e86847ab3508290fef7d76181df42464d12d7d376b40c', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"5.2 Sighting","subsection":"UNKNOWN","table_id":null,"page":111,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":282,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"5.2 Sighting"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p112-283', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '5.2 Sighting', 112, 'Standards Track Work Product 02 April 2025 - Page 112 of 276Copyright © OASIS Open 2025. All Rights Reserved. where_sighted_refs list of type identifier (of type identity) Examples Sighting of Indicator, without Observed Data { "type": "sighting", "spec_version": "2.1", "id": "sighting--ee20065d-2555-424f-ad9e-0f8428623c75", "created_by_ref": "identity--f431f809-377b-45e0-aa1c-6a4751cae5ff", "created": "2016-04-06T20:08:31.000Z", "modified": "2016-04-06T20:08:31.000Z", "sighting_of_ref": "indicator--8e2e2d2b-17d4-4cbf-938f-98ee46b3cd3f" } Sighting of Indicator, with Observed Data (what exactly was seen) and where it was seen [ { "type": "sighting", "spec_version": "2.1", "id": "sighting--ee20065d-2555-424f-ad9e-0f8428623c75", "created_by_ref": "identity--f431f809-377b-45e0-aa1c-6a4751cae5ff", "created": "2016-04-06T20:08:31.000Z", "modified": "2016-04-06T20:08:31.000Z", "first_seen": "2015-12-21T19:00:00Z", "last_seen": "2015-12-21T19:00:00Z", "count": 50, "sighting_of_ref": "indicator--8e2e2d2b-17d4-4cbf-938f-98ee46b3cd3f", "observed_data_refs": ["observed-data--b67d30ff-02ac-498a-92f9-32f845f448cf"], "where_sighted_refs": ["identity--b67d30ff-02ac-498a-92f9-32f845f448ff"] }, { "type": "observed-data", "spec_version": "2.1", "id": "observed-data--b67d30ff-02ac-498a-92f9-32f845f448cf", "created_by_ref": "identity--f431f809-377b-45e0-aa1c-6a4751cae5ff", "created": "2016-04-06T19:58:16.000Z", "modified": "2016-04-06T19:58:16.000Z", "first_observed": "2015-12-21T19:00:00Z", "last_observed": "2016-04-06T19:58:16Z", "number_observed": 50, "object_refs": [ "file--30038539-3eb6-44bc-a59e-d0d3fe84695a" ] } ]', 'vec_doc-10-oasis-stix21-p112-283', 0, 407, 'v2.1.0', 'e32a078763af0ad0271664f1e7da0365eea7501b3bea3c8fefdfe8cf38d02236', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"5.2 Sighting","subsection":"UNKNOWN","table_id":null,"page":112,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":283,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"5.2 Sighting"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p113-284', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '6.1 Artifact Object', 113, 'Type Name: artifact The Artifact object permits capturing an array of bytes (8-bits)…, as a base64-encoded string, or linking to a file-like payload. One of payload_bin or url MUST be provided. It is incumbent on sharing communities to ensure that the URL is accessible for downstream consumers. 6.1.1 Properties Required Common Properties type, id Optional Common Properties spec_version, object_marking_refs, granular_markings, defanged, extensions Not Applicable Common Properties created_by_ref, revoked, labels, confidence, lang, external_references Artifact Object Specific Properties mime_type, payload_bin, url, hashes, encryption_algorithm, decryption_key ID Contributing Properties hashes, payload_bin If the hashes property is present, include only one hash. The selected hash SHOULD come from this ordered list (based on the following order of preference) [ MD5, SHA-1, SHA-256, SHA-512 ]. Property Name Type Description type (required) string The value of this property MUST be artifact. mime_type (optional) string Whenever feasible, this value SHOULD be one of the values defined in the Template column in the IANA media type registry [Media Types]. Maintaining a comprehensive universal catalog of all extant file types is obviously not possible. When specifying a MIME Type not included in the IANA registry, implementers should use their best judgement so as to facilitate interoperability. payload_bin (optional) binary Specifies the binary data contained in the artifact as a base64- encoded string. This property MUST NOT be present if url is provided. url (optional) string The value of this property MUST be a valid URL that resolves to the unencoded content.', 'vec_doc-10-oasis-stix21-p113-284', 0, 421, 'v2.1.0', 'ae9619639e4c0e8ae712957f33ec8225a4b003903e40bf73dce1bad2a61a1de1', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"6.1 Artifact Object","subsection":"UNKNOWN","table_id":null,"page":113,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":284,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"6.1 Artifact Object"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p114-285', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '6.1 Artifact Object', 114, 'Standards Track Work Product 02 April 2025 - Page 114 of 276Copyright © OASIS Open 2025. All Rights Reserved. This property MUST NOT be present if payload_bin is provided. hashes (optional) hashes Specifies a dictionary of hashes for the contents of the url or the payload_bin. This property MUST be present when the url property is present. Dictionary keys MUST come from the hash-algorithm-ov open vocabulary. encryption_algorithm (optional) enum If the artifact is encrypted, specifies the type of encryption algorithm the binary data (either via payload_bin or url) is encoded in. The value of this property MUST come from the encryption- algorithm-enum enumeration. If both mime_type and encryption_algorithm are included, this signifies that the artifact represents an encrypted archive. decryption_key (optional) string Specifies the decryption key for the encrypted binary data (either via payload_bin or url). For example, this may be useful in cases of sharing malware samples, which are often encoded in an encrypted archive. This property MUST NOT be present when the encryption_algorithm property is absent. Examples Basic Image Artifact { "type": "artifact", "spec_version": "2.1", "id": "artifact--a785c567-cc53-52a1-abeb-026bb7ddf8ba", "mime_type": "image/jpeg", "payload_bin": "VBORw0KGgoAAAANSUhEUgAAADI== ..." } Encrypted Zip Archive Artifact { "type": "artifact", "spec_version": "2.1", "id": "artifact--6be1fbcb-fd03-5ec3-b05f-4329746e9d2b", "mime_type": "application/zip", "payload_bin": "ZX7HIBWPQA99NSUhEUgAAADI== ...", "encryption_algorithm": "mime-type-indicated", "decryption_key": "My voice is my passport" }', 'vec_doc-10-oasis-stix21-p114-285', 0, 409, 'v2.1.0', '8fccff40cdf6aabc750d4df206a6d762e32aa61e4305e404e88352e1b53bd72a', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"6.1 Artifact Object","subsection":"UNKNOWN","table_id":null,"page":114,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":285,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"6.1 Artifact Object"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p115-286', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '6.2 Autonomous System (AS) Object', 115, 'Type Name: autonomous-system This object represents the properties of an Autonomous System (AS). 6.2.1 Properties Required Common Properties type, id Optional Common Properties spec_version, object_marking_refs, granular_markings, defanged, extensions Not Applicable Common Properties created_by_ref, revoked, labels, confidence, lang, external_references AS Object Specific Properties number, name, rir ID Contributing Properties number Property Name Type Description type (required) string The value of this property MUST be autonomous-system. number (required) integer Specifies the number assigned to the AS. Such assignments are typically performed by a Regional Internet Registry (RIR). name (optional) string Specifies the name of the AS. rir (optional) string Specifies the name of the Regional Internet Registry (RIR) that assigned the number to the AS. Example Basic AS object { "type": "autonomous-system", "spec_version": "2.1", "id": "autonomous-system--3aa27478-50b5-5ab8-9da9-cdc12b657fff", "number": 15139, "name": "Slime Industries", "rir": "ARIN" }', 'vec_doc-10-oasis-stix21-p115-286', 0, 267, 'v2.1.0', 'fa2bfa135b22e7a0af21f1a7cc806513c3148e12d20278d174ebcfab1a25e417', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"6.2 Autonomous System (AS) Object","subsection":"UNKNOWN","table_id":null,"page":115,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":286,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"6.2 Autonomous System (AS) Object"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p116-287', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '6.3 Directory Object', 116, 'Type Name: directory The Directory object represents the properties common to a file system directory. 6.3.1 Properties Required Common Properties type, id Optional Common Properties spec_version, object_marking_refs, granular_markings, defanged, extensions Not Applicable Common Properties created_by_ref, revoked, labels, confidence, lang, external_references Directory Object Specific Properties path, path_enc, ctime, mtime, atime, contains_refs ID Contributing Properties path Property Name Type Description type (required) string The value of this property MUST be directory. path (required) string Specifies the path, as originally observed, to the directory on the file system. path_enc (optional) string Specifies the observed encoding for the path. The value MUST be specified if the path is stored in a non-Unicode encoding. This value MUST be specified using the corresponding name from the 2013-12-20 revision of the IANA character set registry [Character Sets]. If the preferred MIME name for a character set is defined, this value MUST be used; if it is not defined, then the Name value from the registry MUST be used instead. ctime (optional) timestamp Specifies the date/time the directory was created. mtime (optional) timestamp Specifies the date/time the directory was last written to/modified. atime (optional) timestamp Specifies the date/time the directory was last accessed.', 'vec_doc-10-oasis-stix21-p116-287', 0, 350, 'v2.1.0', '87485c555ce2bcaa7823b550af24dee8d12be1592564b5113de2bf88a3bd4787', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"6.3 Directory Object","subsection":"UNKNOWN","table_id":null,"page":116,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":287,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"6.3 Directory Object"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p117-288', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '6.3 Directory Object', 117, 'Standards Track Work Product 02 April 2025 - Page 117 of 276Copyright © OASIS Open 2025. All Rights Reserved. contains_refs(optional) list of type identifier Specifies a list of references to other File and/orDirectory objects contained within the directory. The objects referenced in this list MUST be of type file or directory. Example Basic directory { "type": "directory", "spec_version": "2.1", "id": "directory--0a58d0c1-59e6-5afd-8252-dcd3f13e5622", "path": "C:\\Windows\\System32" }', 'vec_doc-10-oasis-stix21-p117-288', 0, 123, 'v2.1.0', '06737e272d9945ab59accfd827d11010af80c4e35b96a7997c0796ecf15cbdc5', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"6.3 Directory Object","subsection":"UNKNOWN","table_id":null,"page":117,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":288,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"6.3 Directory Object"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p117-289', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '6.4 Domain Name Object', 117, 'Type Name: domain-name The Domain Name object represents the properties of a network domain name. 6.4.1 Properties Required Common Properties type, id Optional Common Properties spec_version, object_marking_refs, granular_markings, defanged, extensions Not Applicable Common Properties created_by_ref, revoked, labels, confidence, lang, external_references Domain Name Object Specific Properties value, resolves_to_refs ID Contributing Properties value Property Name Type Description type (required) string The value of this property MUST be domain- name. value (required) string Specifies the value of the domain name. The value of this property MUST conform to [RFC1034], and each domain and sub-domain contained within the domain name MUST conform to [RFC5890].', 'vec_doc-10-oasis-stix21-p117-289', 0, 191, 'v2.1.0', 'fe9bdbd9578bdb7c506ba2b3c0e0882e4e47c487a603f988fe12900b6a4ad7f0', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"6.4 Domain Name Object","subsection":"UNKNOWN","table_id":null,"page":117,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":289,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"6.4 Domain Name Object"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p118-290', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '6.4 Domain Name Object', 118, 'Standards Track Work Product 02 April 2025 - Page 118 of 276Copyright © OASIS Open 2025. All Rights Reserved. resolves_to_refs(optional) list of type identifier Specifies a list of references to one or more IPaddresses or domain names that the domain name resolves to. The objects referenced in this list MUST be of type ipv4-addr or ipv6-addr or domain- name (for cases such as CNAME records). 6.4.2 Relationships These are the relationships explicitly defined between the Domain Name object and other STIX Objects. The table identifies the relationships that can be made from this object type to another object type by way of the Relationship object. Source Relationship Type Target Description domain-name resolves-to domain-name, ipv4-addr, ipv6-addr This Relationship describes that this Domain Name resolves to one or more IP addresses or domain names. Example Basic FQDN [ { "type": "domain-name", "spec_version": "2.1", "id": "domain-name--bedb4899-d24b-5401-bc86-8f6b4cc18ec7", "value": "example.com", "resolves_to_refs": ["ipv4-addr--28bb3599-77cd-5a82-a950-b5bc3caf07c4"] }, { "type": "ipv4-addr", "spec_version": "2.1", "id": "ipv4-addr--28bb3599-77cd-5a82-a950-b5bc3caf07c4", "value": "198.51.100.3" } ]', 'vec_doc-10-oasis-stix21-p118-290', 0, 304, 'v2.1.0', '5cc11be6b905e63e39dc97f856efc50d4439e89c458cd524582498da381342e8', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"6.4 Domain Name Object","subsection":"UNKNOWN","table_id":null,"page":118,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":290,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"6.4 Domain Name Object"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p118-291', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '6.5 Email Address Object', 118, 'Type Name: email-addr The Email Address object represents a single email address. 6.5.1 Properties Required Common Properties type, id Optional Common Properties spec_version, object_marking_refs, granular_markings, defanged, extensions', 'vec_doc-10-oasis-stix21-p118-291', 0, 59, 'v2.1.0', '35b1462cbcf247ea496a36f44468a7febfdba389470393d9eec640a30de573ba', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"6.5 Email Address Object","subsection":"UNKNOWN","table_id":null,"page":118,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":291,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"6.5 Email Address Object"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p119-292', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '6.5 Email Address Object', 119, 'Standards Track Work Product 02 April 2025 - Page 119 of 276Copyright © OASIS Open 2025. All Rights Reserved. Not Applicable Common Properties created_by_ref, revoked, labels, confidence, lang, external_references Email Address Object Specific Properties value, display_name, belongs_to_ref ID Contributing Properties value Property Name Type Description type (required) string The value of this property MUST be email-addr. value (required) string Specifies the value of the email address. This MUST NOT include the display name. This property corresponds to the addr-spec construction in', 'vec_doc-10-oasis-stix21-p119-292', 0, 148, 'v2.1.0', '57674b0939e18b3bb8dc1002f22aff8beedc715ba5a99f648268fa6e43c27deb', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"6.5 Email Address Object","subsection":"UNKNOWN","table_id":null,"page":119,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":292,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"6.5 Email Address Object"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p119-293', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', 'section 3.4 of [RFC5322], for example,', 119, 'jane.smith@example.com. display_name (optional) string Specifies a single email display name, i.e., the name that is displayed to the human user of a mail application. This property corresponds to the display-name construction in', 'vec_doc-10-oasis-stix21-p119-293', 0, 58, 'v2.1.0', '9ab5d50b3366e5cfa15f936c41b23fd36b8469b4b6ca545435f364207de62b46', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"section 3.4 of [RFC5322], for example,","subsection":"UNKNOWN","table_id":null,"page":119,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":293,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"section 3.4 of [RFC5322], for example,"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p119-294', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', 'section 3.4 of [RFC5322], for example, Jane Smith.', 119, 'belongs_to_ref (optional) identifier Specifies the user account that the email address belongs to, as a reference to a User Account object. The object referenced in this property MUST be of type user- account. Example Basic Email Address { "type": "email-addr", "spec_version": "2.1", "id": "email-addr--7165e2a9-671f-585d-b1e1-ca59c671d934", "value": "john@example.com", "display_name": "John Doe" }', 'vec_doc-10-oasis-stix21-p119-294', 0, 100, 'v2.1.0', '0377d2cf256b4f2b972467ec01f6283cb894389478405077d1d049758805d04b', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"section 3.4 of [RFC5322], for example, Jane Smith.","subsection":"UNKNOWN","table_id":null,"page":119,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":294,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"section 3.4 of [RFC5322], for example, Jane Smith."}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p119-295', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '6.6 Email Message Object', 119, 'Type Name: email-message The Email Message object represents an instance of an email message, corresponding to the internet message format described in [RFC5322] and related RFCs. Header field values that have been encoded as described in section 2 of [RFC2047] MUST be decoded before inclusion in Email Message object properties. For example, this is some text MUST be', 'vec_doc-10-oasis-stix21-p119-295', 0, 93, 'v2.1.0', '27a753c3af84a7efab3a3c397ccc9329e6f2c8d12531aef3c54d77d92a4e8763', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"6.6 Email Message Object","subsection":"UNKNOWN","table_id":null,"page":119,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":295,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"6.6 Email Message Object"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p120-296', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '6.6 Email Message Object', 120, 'Standards Track Work Product 02 April 2025 - Page 120 of 276Copyright © OASIS Open 2025. All Rights Reserved. used instead of =?iso-8859-1?q?this=20is=20some=20text?=. Any characters in the encoded value which cannot be decoded into Unicode SHOULD be replaced with the ‘REPLACEMENT CHARACTER’ (U+FFFD). If it is necessary to capture the header value as observed, this can be achieved by referencing an Artifact object through the raw_email_ref property. 6.6.1 Properties Required Common Properties type, id Optional Common Properties spec_version, object_marking_refs, granular_markings, defanged, extensions Not Applicable Common Properties created_by_ref, revoked, labels, confidence, lang, external_references Email Message Object Specific Properties is_multipart, date, content_type, from_ref, sender_ref, to_refs, cc_refs, bcc_refs, subject, received_lines, additional_header_fields, body, body_multipart, raw_email_ref ID Contributing Properties from_ref, subject, body Property Name Type Description type (required) string The value of this property MUST be email-message. is_multipart (required) boolean Indicates whether the email body contains multiple MIME parts. date (optional) timestamp Specifies the date/time that the email message was sent. content_type (optional) string Specifies the value of the “Content-Type” header of the email message. from_ref (optional) identifier Specifies the value of the “From:” header of the email message. The “From:” field specifies the author of the message, that is, the mailbox(es) of the person or system responsible for the writing of the message. The object referenced in this property MUST be of type email-addr.', 'vec_doc-10-oasis-stix21-p120-296', 0, 418, 'v2.1.0', 'a509512c632f23701a49693ced58f48d6153f0a727986664311144f26bc47569', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"6.6 Email Message Object","subsection":"UNKNOWN","table_id":null,"page":120,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":296,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"6.6 Email Message Object"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p121-297', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '6.6 Email Message Object', 121, 'Standards Track Work Product 02 April 2025 - Page 121 of 276Copyright © OASIS Open 2025. All Rights Reserved. sender_ref (optional) identifier Specifies the value of the“Sender” field of the email message. The “Sender:” field specifies the mailbox of the agent responsible for the actual transmission of the message. The object referenced in this property MUST be of type email-addr. to_refs (optional) list of type identifier Specifies the mailboxes that are “To:” recipients of the email message. The objects referenced in this list MUST be of type email-addr. cc_refs (optional) list of type identifier Specifies the mailboxes that are “CC:” recipients of the email message. The objects referenced in this list MUST be of type email-addr. bcc_refs (optional) list of type identifier Specifies the mailboxes that are “BCC:” recipients of the email message. As per [RFC5322], the absence of this property should not be interpreted as semantically equivalent to an absent BCC header on the message being characterized. The objects referenced in this list MUST be of type email-addr. message_id (optional) string Specifies the Message-ID field of the email message. subject (optional) string Specifies the subject of the email message.', 'vec_doc-10-oasis-stix21-p121-297', 0, 309, 'v2.1.0', 'e1f8100420dbcf6deca2f1f7f4c3e92019a76e1dc43a4b61810ed4c2e1e9cc06', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"6.6 Email Message Object","subsection":"UNKNOWN","table_id":null,"page":121,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":297,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"6.6 Email Message Object"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p122-298', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '6.6 Email Message Object', 122, 'Standards Track Work Product 02 April 2025 - Page 122 of 276Copyright © OASIS Open 2025. All Rights Reserved. received_lines (optional) list of type string Specifies one or more“Received” header fields that may be included in the email headers. List values MUST appear in the same order as present in the email message. additional_header_fields (optional) dictionary Specifies any other header fields (except for date, received_lines, content_type, from_ref, sender_ref, to_refs, cc_refs, bcc_refs, and subject) found in the email message, as a dictionary. Each key/value pair in the dictionary represents the name/value of a single header field or names/values of a header field that occurs more than once. Each dictionary key SHOULD be a case-preserved version of the header field name. The corresponding value for each dictionary key MUST always be a list of type string to support when a header field is repeated. body (optional) string Specifies a string containing the email body. This property MUST NOT be used if is_multipart is true. body_multipart (optional) list of type email-mime-part-type Specifies a list of the MIME parts that make up the email body. This property MUST NOT be used if is_multipart is false. raw_email_ref (optional) identifier Specifies the raw binary contents of the email message, including both the headers and body, as a reference to an Artifact object. The object referenced in this property MUST be of type artifact. 6.6.2 Email MIME Component Type Type Name: email-mime-part-type', 'vec_doc-10-oasis-stix21-p122-298', 0, 380, 'v2.1.0', 'a50d0e83070edaf17a3ee7b1cbd5ee06b3219a818a979f0fe446cc617b5cb417', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"6.6 Email Message Object","subsection":"UNKNOWN","table_id":null,"page":122,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":298,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"6.6 Email Message Object"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p123-299', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '6.6 Email Message Object', 123, 'Standards Track Work Product 02 April 2025 - Page 123 of 276Copyright © OASIS Open 2025. All Rights Reserved. Specifies one component of a multi-part email body. There is no property to capture the value of the “Content-Transfer-Encoding” header field, since the body MUST be decoded before being represented in the body property. One of body OR body_raw_ref MUST be included. Properties Property Name Type Description body (optional) string Specifies the contents of the MIME part if the content_type is not provided or starts with text/ (e.g., in the case of plain text or HTML email). For inclusion in this property, the contents MUST be decoded to Unicode. Note that the charset provided in content_type is for informational usage and not for decoding of this property. body_raw_ref (optional) identifier Specifies the contents of non-textual MIME parts, that is those whose content_type does not start with text/, as a reference to an Artifact object or File object.', 'vec_doc-10-oasis-stix21-p123-299', 0, 243, 'v2.1.0', 'c928976c0f7226d06ca46012233b09b1c62503c2e6348a2b0537b13235444a99', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"6.6 Email Message Object","subsection":"UNKNOWN","table_id":null,"page":123,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":299,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"6.6 Email Message Object"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p123-300', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '6.6 Email Message Object', 123, 'The object referenced in this property MUST be of type artifact or file. For use cases where conveying the actual data contained in the MIME part is of primary importance, artifact SHOULD be used. Otherwise, for use cases where conveying metadata about the file-like properties of the MIME part is of primary importance, file SHOULD be used. content_type (optional) string Specifies the value of the “Content-Type” header field of the MIME part. Any additional “Content-Type” header field parameters such as charset SHOULD be included in this property. Example: text/html; charset=UTF-8 content_disposition (optional) string Specifies the value of the “Content-Disposition” header field of the MIME part.', 'vec_doc-10-oasis-stix21-p123-300', 0, 176, 'v2.1.0', '5be23cd27b9dc538c5258df5ad56bdc07b31b438c622d7686a3674dc2ae37857', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"6.6 Email Message Object","subsection":"UNKNOWN","table_id":null,"page":123,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":300,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"6.6 Email Message Object"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p123-301', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '6.6 Email Message Object', 123, 'Examples Simple Email Message [ { "type": "email-message", "spec_version": "2.1", "id": "email-message--92fa1bfd-2c62-5a30-8b7c-5b91ea73cf29", "from_ref": "email-addr--6deb37bd-12b7-54ae-805f-5f7146f3d171", "to_refs": ["email-addr--2aeeb98c-9db4-525e-874d-221fdfe9f76e"], "is_multipart": false, "date": "1997-11-21T15:55:06.000Z",', 'vec_doc-10-oasis-stix21-p123-301', 0, 83, 'v2.1.0', '26af5d5155efea572041c0f6a5b25a2e171856266c622da9462e2845fdc02ca2', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"6.6 Email Message Object","subsection":"UNKNOWN","table_id":null,"page":123,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":301,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"6.6 Email Message Object"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p124-302', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '6.6 Email Message Object', 124, 'Standards Track Work Product 02 April 2025 - Page 124 of 276Copyright © OASIS Open 2025. All Rights Reserved. "subject": "Saying Hello" }, { "type": "email-addr", "spec_version": "2.1", "id": "email-addr--6deb37bd-12b7-54ae-805f-5f7146f3d171", "value": "jdoe@example.com", "display_name": "John Doe" }, { "type": "email-addr", "spec_version": "2.1", "id": "email-addr--2aeeb98c-9db4-525e-874d-221fdfe9f76e", "value": "mary@example.com", "display_name": "Mary Smith" } ] Simple Email Message with Additional Header Properties [ { "type": "email-message", "spec_version": "2.1", "id": "email-message--0c57a381-2a17-5e61-8754-5ef96efb286c", "from_ref": "email-addr--9b7e29b3-fd8d-562e-b3f0-8fc8134f5dda", "to_refs": ["email-addr--3734e66b-c4e8-5d0b-bca9-befdd5699746"], "is_multipart": false, "date": "2004-04-19T12:22:23.000Z", "subject": "Did you see this?", "additional_header_fields": { "Reply-To": [ "steve@example.com", "jane@example.com" ] } }, { "type": "email-addr", "spec_version": "2.1", "id": "email-addr--9b7e29b3-fd8d-562e-b3f0-8fc8134f5dda", "value": "joe@example.com", "display_name": "Joe Smith" }, { "type": "email-addr", "spec_version": "2.1", "id": "email-addr--3734e66b-c4e8-5d0b-bca9-befdd5699746", "value": "bob@example.com", "display_name": "Bob Smith" } ] Complex MIME Email Message [ { "type": "email-message", "spec_version": "2.1", "id": "email-message--d7d69ead-3347-5772-815a-7766dc29c72c", "is_multipart": true, "received_lines": [', 'vec_doc-10-oasis-stix21-p124-302', 0, 365, 'v2.1.0', '0e0e1f8f7d1d52b9c4a47b736f9cdd7ff490a5408cb571fa1a28e3563aca456f', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"6.6 Email Message Object","subsection":"UNKNOWN","table_id":null,"page":124,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":302,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"6.6 Email Message Object"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p125-303', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '6.6 Email Message Object', 125, 'Standards Track Work Product 02 April 2025 - Page 125 of 276Copyright © OASIS Open 2025. All Rights Reserved.', 'vec_doc-10-oasis-stix21-p125-303', 0, 28, 'v2.1.0', '6e1cf9a402b2d0789d453a9ed2ac1dd625dd8f199b3d6a3733d3460cba90c69d', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"6.6 Email Message Object","subsection":"UNKNOWN","table_id":null,"page":125,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":303,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"6.6 Email Message Object"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p125-304', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '6.6 Email Message Object', 125, '"from mail.example.com ([198.51.100.3]) by smtp.gmail.com with ESMTPSA id q23sm23309939wme.17.2016.07.19.07.20.32 (version=TLS1_2 cipher=ECDHE-RSA-AES128-GCM-SHA256 bits=128/128); Tue, 19 Jul 2016 07:20:40 -0700 (PDT)" ], "content_type": "multipart/mixed", "date": "2016-06-19T14:20:40.000Z", "from_ref": "email-addr--6deb37bd-12b7-54ae-805f-5f7146f3d171", "to_refs": ["email-addr--3734e66b-c4e8-5d0b-bca9-befdd5699746"], "cc_refs": ["email-addr--2aeeb98c-9db4-525e-874d-221fdfe9f76e"], "subject": "Check out this picture of a cat!", "additional_header_fields": { "Content-Disposition": "inline", "X-Mailer": "Mutt/1.5.23", "X-Originating-IP": "198.51.100.3" }, "body_multipart": [ { "content_type": "text/plain; charset=utf-8", "content_disposition": "inline", "body": "Cats are funny!" }, { "content_type": "image/png", "content_disposition": "attachment; filename=\"tabby.png\"", "body_raw_ref": "artifact--0682152c-646a-513b-bc07-e516494ed178" }, { "content_type": "application/zip", "content_disposition": "attachment; filename=\"tabby_pics.zip\"", "body_raw_ref": "file--cfebcece-2336-51b0-baf1-d94daae5e1d1" } ] }, { "type": "email-addr", "spec_version": "2.1", "id": "email-addr--6deb37bd-12b7-54ae-805f-5f7146f3d171", "value": "jdoe@example.com", "display_name": "John Doe" }, { "type": "email-addr", "spec_version": "2.1", "id": "email-addr--3734e66b-c4e8-5d0b-bca9-befdd5699746", "value": "bob@example.com", "display_name": "Bob Smith" }, { "type": "email-addr", "spec_version": "2.1", "id": "email-addr--2aeeb98c-9db4-525e-874d-221fdfe9f76e", "value": "mary@example.com", "display_name": "Mary Smith" }, { "type": "artifact", "spec_version": "2.1", "id": "artifact--0682152c-646a-513b-bc07-e516494ed178" "mime_type": "image/jpeg", "payload_bin": "VBORw0KGgoAAAANSUhEUgAAADI== ...", "hashes": { "SHA-256": "effb46bba03f6c8aea5c653f9cf984f170dcdd3bbbe2ff6843c3e5da0e698766" } }, { "type": "file", "spec_version": "2.1", "id": "file--cfebcece-2336-51b0-baf1-d94daae5e1d1", "name": "tabby_pics.zip", "magic_number_hex": "504B0304",', 'vec_doc-10-oasis-stix21-p125-304', 0, 510, 'v2.1.0', 'eebe9f576d68110fc4b3a55e4694a6e45ed21cbc9f56919ed93be91831e8fa59', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"6.6 Email Message Object","subsection":"UNKNOWN","table_id":null,"page":125,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":304,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"6.6 Email Message Object"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p126-305', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '6.7 File Object', 126, 'Type Name: file The File object represents the properties of a file. A File object MUST contain at least one of hashes orname. 6.7.1 Properties Required Common Properties type, id Optional Common Properties spec_version, object_marking_refs, granular_markings, defanged, extensions Not Applicable Common Properties created_by_ref, revoked, labels, confidence, lang, external_references File Object Specific Properties hashes, size, name, name_enc, magic_number_hex, mime_type, ctime, mtime, atime, parent_directory_ref, contains_refs, content_ref ID Contributing Properties hashes, name, extensions, parent_directory_ref If the hashes property is present, include only one hash. The selected hash SHOULD come from this ordered list (based on the following order of preference) [ MD5, SHA-1, SHA-256, SHA-512 ]. Property Name Type Description type (required) string The value of this property MUST be file. extensions (optional) dictionary The File object defines the following extensions. In addition to these, producers MAY create their own. ntfs-ext, raster-image-ext, pdf-ext, archive-ext, windows-pebinary-ext Dictionary keys MUST use the specification defined name (examples above) or be the id of a STIX Extension object, depending on the type of extension being used. The corresponding dictionary values MUST contain the contents of the extension instance.', 'vec_doc-10-oasis-stix21-p126-305', 0, 341, 'v2.1.0', '20cf2b9d471cc34dfbc1c23e0da0e903f1a34ef5ef66c1f5b50f07db695bd834', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"6.7 File Object","subsection":"UNKNOWN","table_id":null,"page":126,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":305,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"6.7 File Object"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p127-306', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '6.7 File Object', 127, 'Standards Track Work Product 02 April 2025 - Page 127 of 276Copyright © OASIS Open 2025. All Rights Reserved. hashes (optional) hashes Specifies a dictionary of hashes for the file. (When used with the Archive File Extension, this refers to the hash of the entire archive file, not its contents.) Dictionary keys MUST come from the hash- algorithm-ov open vocabulary. size (optional) integer Specifies the size of the file, in bytes. The value of this property MUST NOT be negative. name (optional) string Specifies the name of the file. name_enc (optional) string Specifies the observed encoding for the name of the file. This value MUST be specified using the corresponding name from the 2013-12-20 revision of the IANA character set registry [Character Sets]. If the value from the Preferred MIME Name column for a character set is defined, this value MUST be used; if it is not defined, then the value from the Name column in the registry MUST be used instead.', 'vec_doc-10-oasis-stix21-p127-306', 0, 241, 'v2.1.0', 'cdfa87f5def5fcb4bfcdcf550a7aca4da689ae5ffdcfa59a48ae52a531112867', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"6.7 File Object","subsection":"UNKNOWN","table_id":null,"page":127,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":306,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"6.7 File Object"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p127-307', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '6.7 File Object', 127, 'This property allows for the capture of the original text encoding for the file name, which may be forensically relevant; for example, a file on an NTFS volume whose name was created using the windows-1251 encoding, commonly used for languages based on Cyrillic script. magic_number_hex (optional) hex Specifies the hexadecimal constant (“magic number”) associated with a specific file format that corresponds to the file, if applicable. mime_type (optional) string Specifies the MIME type name specified for the file, e.g., application/msword. Whenever feasible, this value SHOULD be one of the values defined in the Template column in the IANA media type registry [Media Types]. Maintaining a comprehensive universal catalog of all extant file types is obviously not possible. When specifying a MIME Type not included in the IANA registry, implementers should use their best judgement so as to facilitate interoperability. ctime (optional) timestamp Specifies the date/time the file was created.', 'vec_doc-10-oasis-stix21-p127-307', 0, 250, 'v2.1.0', '56bc81403d7dffdb43a0be00d36e248b19d1d42221a59864efd545c3804dea49', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"6.7 File Object","subsection":"UNKNOWN","table_id":null,"page":127,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":307,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"6.7 File Object"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p127-308', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '6.7 File Object', 127, 'mtime (optional) timestamp Specifies the date/time the file was last written to/modified.', 'vec_doc-10-oasis-stix21-p127-308', 0, 23, 'v2.1.0', 'ae9d41462ac81a3986de04b59b2497ac952be4fac0066512fe3dd1e64a831507', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"6.7 File Object","subsection":"UNKNOWN","table_id":null,"page":127,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":308,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"6.7 File Object"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p128-309', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '6.7 File Object', 128, 'Standards Track Work Product 02 April 2025 - Page 128 of 276Copyright © OASIS Open 2025. All Rights Reserved. atime (optional) timestamp Specifies the date/time the file was lastaccessed. parent_directory_ref (optional) identifier Specifies the parent directory of the file, as a reference to a Directory object. The object referenced in this property MUST be of type directory. contains_refs (optional) list of type identifier Specifies a list of references to other Cyber- observable Objects contained within the file, such as another file that is appended to the end of the file, or an IP address that is contained somewhere in the file. This is intended for use cases other than those targeted by the Archive extension. content_ref (optional) identifier Specifies the content of the file, represented as an Artifact object. The object referenced in this property MUST be of type artifact. Examples Basic file with file system properties without observed encoding { "type": "file", "spec_version": "2.1", "id": "file--949eb97a-da1e-5292-8959-03c4249dc9f3", "hashes": { "SHA-256": "fe90a7e910cb3a4739bed9180e807e93fa70c90f25a8915476f5e4bfbac681db" }, "size": 25536, "name": "foo.dll" } Basic file with file system properties with observed encoding { "type": "file", "spec_version": "2.1", "id": "file--7d1e3a18-89e7-5bc5-be36-9879f5b7f5c8", "hashes": { "SHA-256": "841a8921140aba50671ebb0770fecc4ee308c4952cfeff8de154ab14eeef4649" }, "name": "quêry.dll", "name_enc": "windows-1252" } In this example, the file name would have originally appeared using the bytes 71 75 ea 72 79 2e 64 6c 6c. Representing it in UTF-8, as required for JSON, would use the bytes 71 75 c3 aa 72 79 2e 64 6c 6c. Basic file with parent directory', 'vec_doc-10-oasis-stix21-p128-309', 0, 431, 'v2.1.0', '001a9d8edfc416cb28d2708d4b625420f865dd8bff17c87b5507eb6ad9411bbf', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"6.7 File Object","subsection":"UNKNOWN","table_id":null,"page":128,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":309,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"6.7 File Object"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p129-310', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '6.7 File Object', 129, 'Standards Track Work Product 02 April 2025 - Page 129 of 276Copyright © OASIS Open 2025. All Rights Reserved. [ { "type": "directory", "spec_version": "2.1", "id": "directory--0a58d0c1-59e6-5afd-8252-dcd3f13e5622", "path": "C:\\Windows\\System32" }, { "type": "file", "spec_version": "2.1", "id": "file--39643577-13b7-5f21-9584-df7e7c33f357", "hashes": { "SHA-256": "ceafbfd424be2ca4a5f0402cae090dda2fb0526cf521b60b60077c0f622b285a" }, "parent_directory_ref": "directory--0a58d0c1-59e6-5afd-8252-dcd3f13e5622", "name": "qwerty.dll" } ] 6.7.2 Archive File Extension Type Name: archive-ext The Archive File extension specifies a default extension for capturing properties specific to archive files. The key for this extension when used in the extensions dictionary MUST be archive-ext. Note that this predefined extension does not use the extension facility described in section 7.3. Properties Property Name Type Description contains_refs (required) list of type identifier This property specifies the files that are contained in the archive. It MUST contain references to one or more File objects. The objects referenced in this list MUST be of type file or directory. comment (optional) string Specifies a comment included as part of the archive file. Example Basic unencrypted ZIP Archive [ { "type": "file", "spec_version": "2.1", "id": "file--70221dbf-52fd-5377-9619-c0ce6b3ffc8c", "hashes": { "SHA-256": "ceafbfd424be2ca4a5f0402cae090dda2fb0526cf521b60b60077c0f622b285a" } } { "type": "file", "spec_version": "2.1", "id": "file--c0e2b1c9-232d-5b64-8b74-b6aee5bb9c47", "hashes": { "SHA-256": "19c549ec2628b989382f6b280cbd7bb836a0b461332c0fe53511ce7d584b89d3" }', 'vec_doc-10-oasis-stix21-p129-310', 0, 416, 'v2.1.0', '0ec3d00046133a54920b761be17196c4b315438bdbd3d70cc192d526b7e18d54', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"6.7 File Object","subsection":"UNKNOWN","table_id":null,"page":129,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":310,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"6.7 File Object"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p130-311', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '6.7 File Object', 130, 'Standards Track Work Product 02 April 2025 - Page 130 of 276Copyright © OASIS Open 2025. All Rights Reserved. } { "type": "file", "spec_version": "2.1", "id": "file--5d0833b7-065e-571f-8bf2-657cb9569570", "hashes": { "SHA-256": "0969de02ecf8a5f003e3f6d063d848c8a193aada092623f8ce408c15bcb5f038" } } { "type": "file", "spec_version": "2.1", "id": "file--9a1f834d-2506-5367-baec-7aa63996ac43", "name": "foo.zip", "hashes": { "SHA-256": "35a01331e9ad96f751278b891b6ea09699806faedfa237d40513d92ad1b7100f" }, "mime_type": "application/zip", "extensions": { "archive-ext": { "contains_refs": [ "file--70221dbf-52fd-5377-9619-c0ce6b3ffc8c", "file--c0e2b1c9-232d-5b64-8b74-b6aee5bb9c47", "file--5d0833b7-065e-571f-8bf2-657cb9569570" ] } } } ] 6.7.3 NTFS File Extension Type Name: ntfs-ext The NTFS File extension specifies a set of properties specific to files stored on NTFS file systems. The key for this extension when used in the extensions dictionary MUST be ntfs-ext. Note that this predefined extension does not use the extension facility described in section 7.3. An object using the NTFS File Extension MUST contain at least one property from this extension. Properties Property Name Type Description sid (optional) string Specifies the security ID (SID) value assigned to the file. alternate_data_streams (optional) list of type alternate-data-stream-type Specifies a list of NTFS alternate data streams that exist for the file. Alternate Data Stream Type Type Name: alternate-data-stream-type The Alternate Data Stream type represents an NTFS alternate data stream. Properties Property Name Type Description', 'vec_doc-10-oasis-stix21-p130-311', 0, 403, 'v2.1.0', 'c9620f102a5bbcf75e05110191a0477c5af275dc3897c0786c4cd3272f998cd6', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"6.7 File Object","subsection":"UNKNOWN","table_id":null,"page":130,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":311,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"6.7 File Object"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p131-312', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '6.7 File Object', 131, 'Standards Track Work Product 02 April 2025 - Page 131 of 276Copyright © OASIS Open 2025. All Rights Reserved. name(required) string Specifies the name of the alternate data stream. hashes (optional) hashes Specifies a dictionary of hashes for the data contained in the alternate data stream. Dictionary keys MUST come from the hash-algorithm-ov open vocabulary. size (optional) integer Specifies the size of the alternate data stream, in bytes. The value of this property MUST NOT be negative. Example NTFS File with a single alternate data stream { "type": "file", "spec_version": "2.1", "id": "file--ba04c974-3cef-5f42-adc7-084d467874e2", "hashes": { "SHA-256": "35a01331e9ad96f751278b891b6ea09699806faedfa237d40513d92ad1b7100f" }, "extensions": { "ntfs-ext": { "alternate_data_streams": [ { "name": "second.stream", "size": 25536 } ] } } } 6.7.4 PDF File Extension Type Name: pdf-ext The PDF file extension specifies a default extension for capturing properties specific to PDF files. The key for this extension when used in the extensions dictionary MUST be pdf-ext. Note that this predefined extension does not use the extension facility described in section 7.3. An object using the PDF File Extension MUST contain at least one property from this extension. Properties Property Name Type Description version (optional) string Specifies the decimal version number of the string from the PDF header that specifies the version of the PDF specification to which the PDF file conforms. E.g 1.4 is_optimized (optional) boolean Specifies whether the PDF file has been optimized. document_info_dict (optional) dictionary Specifies details of the PDF document information dictionary (DID), which includes properties like the document creation date and producer, as a dictionary. Each key in the', 'vec_doc-10-oasis-stix21-p131-312', 0, 448, 'v2.1.0', '1698fcd0f8986d1adea00fb2d8f32dfd1475d2f0225d36decff064f46f153c3d', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"6.7 File Object","subsection":"UNKNOWN","table_id":null,"page":131,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":312,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"6.7 File Object"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p132-313', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '6.7 File Object', 132, 'Standards Track Work Product 02 April 2025 - Page 132 of 276Copyright © OASIS Open 2025. All Rights Reserved. dictionary SHOULD be a case-preserved version of the corresponding entry in the document information dictionary without the prepended forward slash, e.g., Title. The corresponding value for the key MUST be the value specified for the document information dictionary entry, as a string. pdfid0 (optional) string Specifies the first file identifier found for the PDF file. pdfid1 (optional) string Specifies the second file identifier found for the PDF file. Example Basic PDF file { "type": "file", "spec_version": "2.1", "id": "file--965aa96f-d90a-506a-8317-d38d44b235f9", "name": "example.pdf", "extensions": { "pdf-ext": { "version": "1.7", "document_info_dict": { "Title": "Sample document", "Author": "Adobe Systems Incorporated", "Creator": "Adobe FrameMaker 5.5.3 for Power Macintosh", "Producer": "Acrobat Distiller 3.01 for Power Macintosh", "CreationDate": "20070412090123-02" }, "pdfid0": "DFCE52BD827ECF765649852119D", "pdfid1": "57A1E0F9ED2AE523E313C" } } } 6.7.5 Raster Image File Extension Type Name: raster-image-ext The Raster Image file extension specifies a default extension for capturing properties specific to raster image files. The key for this extension when used in the extensions dictionary MUST be raster- image-ext. Note that this predefined extension does not use the extension facility described in section 7.3. An object using the Raster Image File Extension MUST contain at least one property from this extension. Properties Property Name Type Description image_height (optional) integer Specifies the height of the image in the image file, in pixels. image_width (optional) integer Specifies the width of the image in the image file, in pixels.', 'vec_doc-10-oasis-stix21-p132-313', 0, 447, 'v2.1.0', 'd9d034db5762c4eaf9681ac381217af7c18a6bdad323a99cd7183a0a6451ee7a', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"6.7 File Object","subsection":"UNKNOWN","table_id":null,"page":132,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":313,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"6.7 File Object"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p133-314', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '6.7 File Object', 133, 'Standards Track Work Product 02 April 2025 - Page 133 of 276Copyright © OASIS Open 2025. All Rights Reserved. bits_per_pixel(optional) integer Specifies the sum of bits used for each color channel in the imagefile, and thus the total number of pixels used for expressing the color depth of the image. exif_tags (optional) dictionary Specifies the set of EXIF tags found in the image file, as a dictionary. Each key/value pair in the dictionary represents the name/value of a single EXIF tag. Accordingly, each dictionary key MUST be a case-preserved version of the EXIF tag name, e.g., XResolution. Each dictionary value MUST be either an integer (for int* EXIF datatypes) or a string (for all other EXIF datatypes).', 'vec_doc-10-oasis-stix21-p133-314', 0, 179, 'v2.1.0', '99dda34686afebaabe21d4f9f62a96eb0ebf95c8d48c1f501d41dbf4854a9928', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"6.7 File Object","subsection":"UNKNOWN","table_id":null,"page":133,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":314,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"6.7 File Object"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p133-315', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '6.7 File Object', 133, 'Example Simple Image File with EXIF Data { "type": "file", "spec_version": "2.1", "id": "file--66772174-3442-5e0d-b577-4bd7be55fb87", "name": "picture.jpg", "hashes": { "SHA-256": "4bac27393bdd9777ce02453256c5577cd02275510b2227f473d03f533924f877" }, "extensions": { "raster-image-ext": { "exif_tags": { "Make": "Nikon", "Model": "D7000", "XResolution": 4928, "YResolution": 3264 } } } } 6.7.6 Windows™ PE Binary File Extension Type Name:: windows-pebinary-ext The Windows™ PE Binary File extension specifies a default extension for capturing properties specific to Windows portable executable (PE) files. The key for this extension when used in the extensions dictionary MUST be windows-pebinary-ext. Note that this predefined extension does not use the extension facility described in section 7.3. An object using the Windows™ PE Binary File Extension MUST contain at least one property other than the required pe_type property from this extension.', 'vec_doc-10-oasis-stix21-p133-315', 0, 238, 'v2.1.0', '27290188166d10010bc4a349ad14faed6b110778f44ad27a01f2b734401bcae0', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"6.7 File Object","subsection":"UNKNOWN","table_id":null,"page":133,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":315,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"6.7 File Object"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p133-316', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '6.7 File Object', 133, 'Properties Property Name Type Description pe_type (required) open-vocab Specifies the type of the PE binary. This is an open vocabulary and values SHOULD come from the windows-', 'vec_doc-10-oasis-stix21-p133-316', 0, 44, 'v2.1.0', '4f18ca6c16df0af4b8b1874100eb45d0fb9efe886118a6cc5516f8d6d309fe75', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"6.7 File Object","subsection":"UNKNOWN","table_id":null,"page":133,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":316,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"6.7 File Object"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p134-317', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '6.7 File Object', 134, 'Standards Track Work Product 02 April 2025 - Page 134 of 276Copyright © OASIS Open 2025. All Rights Reserved. pebinary-type-ov open vocabulary. imphash (optional) string Specifies the special import hash, or ‘imphash’, calculated for the PE Binary based on its imported libraries and functions. machine_hex (optional) hex Specifies the type of target machine. number_of_sections (optional) integer Specifies the number of sections in the PE binary, as a non- negative integer. time_date_stamp (optional) timestamp Specifies the time when the PE binary was created. The timestamp value MUST be precise to the second. pointer_to_symbol_table_hex (optional) hex Specifies the file offset of the COFF symbol table. number_of_symbols (optional) integer Specifies the number of entries in the symbol table of the PE binary, as a non- negative integer. size_of_optional_header (optional) integer Specifies the size of the optional header of the PE binary. The value of this propertyMUST NOT be negative. characteristics_hex (optional) hex Specifies the flags that indicate the file’s characteristics. file_header_hashes (optional) hashes Specifies any hashes that were computed for the file header. Dictionary keys MUST come from the hash-algorithm- ov open vocabulary. optional_header (optional) windows-pe-optional-header-type Specifies the PE optional header of the', 'vec_doc-10-oasis-stix21-p134-317', 0, 341, 'v2.1.0', '1ff1ced1a46401af55c9a38465c94c730aeb5b0b5d2a344d97573e270a926c8d', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"6.7 File Object","subsection":"UNKNOWN","table_id":null,"page":134,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":317,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"6.7 File Object"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p135-318', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '6.7 File Object', 135, 'Standards Track Work Product 02 April 2025 - Page 135 of 276Copyright © OASIS Open 2025. All Rights Reserved. PE binary. When used, at least one property from the windows-pe- optional-header- type MUST be included. sections (optional) list of type windows-pe-section-type Specifies metadata about the sections in the PE file. Windows™ PE Optional Header Type Type Name: windows-pe-optional-header-type The Windows PE Optional Header type represents the properties of the PE optional header. An object using the Windows PE Optional Header Type MUST contain at least one property from this type. Properties Property Name Type Description magic_hex (optional) hex Specifies the hex value that indicates the type of the PE binary. major_linker_version (optional) integer Specifies the linker major version number. minor_linker_version (optional) integer Specifies the linker minor version number. size_of_code (optional) integer Specifies the size of the code (text) section.', 'vec_doc-10-oasis-stix21-p135-318', 0, 243, 'v2.1.0', '80a35c90dc789165243c76b36cb1b45b5f9c167bd80a85e8bc417e5b6a2b34a5', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"6.7 File Object","subsection":"UNKNOWN","table_id":null,"page":135,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":318,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"6.7 File Object"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p135-319', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '6.7 File Object', 135, 'If there are multiple such sections, this refers to the sum of the sizes of each section. The value of this property MUST NOT be negative. size_of_initialized_data (optional) integer Specifies the size of the initialized data section. If there are multiple such sections, this refers to the sum of the sizes of each section. The value of this property MUST NOT be negative. size_of_uninitialized_data (optional) integer Specifies the size of the uninitialized data section. If there are multiple such sections, this refers to the sum of the sizes of each section. The value of this property MUST NOT be negative. address_of_entry_point (optional) integer Specifies the address of the entry point relative to the image base when the executable is loaded into memory. base_of_code (optional) integer Specifies the address that is relative to the image base of the beginning-of-code section when it is loaded into memory.', 'vec_doc-10-oasis-stix21-p135-319', 0, 230, 'v2.1.0', '367c488876ae7f57f82e5bd98f9e284c86979b93e010557303083ddbb74eb134', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"6.7 File Object","subsection":"UNKNOWN","table_id":null,"page":135,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":319,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"6.7 File Object"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p135-320', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '6.7 File Object', 135, 'base_of_data (optional) integer Specifies the address that is relative to the image base of the beginning-of-data section when it is loaded into memory.', 'vec_doc-10-oasis-stix21-p135-320', 0, 38, 'v2.1.0', 'bedb2bc48963d341ccd94dbd06924eb4fb5f0d8c740fd41632b01dce3dbcb2c3', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"6.7 File Object","subsection":"UNKNOWN","table_id":null,"page":135,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":320,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"6.7 File Object"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p136-321', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '6.7 File Object', 136, 'Standards Track Work Product 02 April 2025 - Page 136 of 276Copyright © OASIS Open 2025. All Rights Reserved. image_base (optional) integer Specifies the preferred address of the first byte of theimage when loaded into memory. section_alignment (optional) integer Specifies the alignment (in bytes) of PE sections when they are loaded into memory. file_alignment (optional) integer Specifies the factor (in bytes) that is used to align the raw data of sections in the image file. major_os_version (optional) integer Specifies the major version number of the required operating system. minor_os_version (optional) integer Specifies the minor version number of the required operating system. major_image_version (optional) integer Specifies the major version number of the image. minor_image_version (optional) integer Specifies the minor version number of the image. major_subsystem_version (optional) integer Specifies the major version number of the subsystem.', 'vec_doc-10-oasis-stix21-p136-321', 0, 241, 'v2.1.0', '68bec8c4685468b5897f5aa12feb0862d6e4bd8d46624c034f314780321b24da', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"6.7 File Object","subsection":"UNKNOWN","table_id":null,"page":136,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":321,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"6.7 File Object"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p136-322', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '6.7 File Object', 136, 'minor_subsystem_version (optional) integer Specifies the minor version number of the subsystem. win32_version_value_hex (optional) hex Specifies the reserved win32 version value. size_of_image (optional) integer Specifies the size of the image in bytes, including all headers, as the image is loaded in memory. The value of this property MUST NOT be negative. size_of_headers (optional) integer Specifies the combined size of the MS-DOS, PE header, and section headers, rounded up to a multiple of the value specified in the file_alignment header. The value of this property MUST NOT be negative. checksum_hex (optional) hex Specifies the checksum of the PE binary. subsystem_hex (optional) hex Specifies the subsystem (e.g., GUI, device driver, etc.) that is required to run this image. dll_characteristics_hex (optional) hex Specifies the flags that characterize the PE binary. size_of_stack_reserve (optional) integer Specifies the size of the stack to reserve, in bytes.', 'vec_doc-10-oasis-stix21-p136-322', 0, 244, 'v2.1.0', 'a3201357256d025ed6b49141fc1c66ba00bb870e7443047ab8e98cdb60490762', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"6.7 File Object","subsection":"UNKNOWN","table_id":null,"page":136,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":322,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"6.7 File Object"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p136-323', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '6.7 File Object', 136, 'The value of this property MUST NOT be negative. size_of_stack_commit (optional) integer Specifies the size of the stack to commit, in bytes. The value of this property MUST NOT be negative. size_of_heap_reserve (optional) integer Specifies the size of the local heap space to reserve, in bytes. The value of this property MUST NOT be negative.', 'vec_doc-10-oasis-stix21-p136-323', 0, 86, 'v2.1.0', '139a219b8d6841d07ff58c9951814e872680499a6e1cca028d57c3c9c0c2e75e', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"6.7 File Object","subsection":"UNKNOWN","table_id":null,"page":136,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":323,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"6.7 File Object"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p137-324', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '6.7 File Object', 137, 'Standards Track Work Product 02 April 2025 - Page 137 of 276Copyright © OASIS Open 2025. All Rights Reserved. size_of_heap_commit(optional) integer Specifies the size of the local heap space to commit, inbytes. The value of this property MUST NOT be negative. loader_flags_hex (optional) hex Specifies the reserved loader flags. number_of_rva_and_sizes (optional) integer Specifies the number of data-directory entries in the remainder of the optional header. hashes (optional) hashes Specifies any hashes that were computed for the optional header. Dictionary keys MUST come from the hash- algorithm-ov open vocabulary. Windows™ PE Section Type Type Name: windows-pe-section-type The Windows PE Section type specifies metadata about a PE file section. Properties Property Name Type Description name (required) string Specifies the name of the section. size (optional) integer Specifies the size of the section, in bytes. The value of this property MUST NOT be negative. entropy (optional) float Specifies the calculated entropy for the section, as calculated using the Shannon algorithm [Shannon Entropy]. The size of each input character is defined as a byte, resulting in a possible range of 0 through 8. hashes (optional) hashes Specifies any hashes computed over the section. Dictionary keys MUST come from the hash-algorithm-ov open vocabulary. Example Typical EXE File { "type": "file", "spec_version": "2.1", "id": "file--9af228db-9a04-5787-ad43-ccadc137a0e2", "name": "example.exe", "extensions": { "windows-pebinary-ext": { "pe_type": "exe", "machine_hex": "014c", "number_of_sections": 4, "time_date_stamp": "2016-01-22T12:31:12Z", "pointer_to_symbol_table_hex": "74726144", "number_of_symbols": 4542568, "size_of_optional_header": 224,', 'vec_doc-10-oasis-stix21-p137-324', 0, 437, 'v2.1.0', '8c8ba870735c33c540afa928d0fbb12eb952e68ffb1891e7113e9f8c660d006a', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"6.7 File Object","subsection":"UNKNOWN","table_id":null,"page":137,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":324,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"6.7 File Object"}');
