INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p138-326', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '6.8 IPv4 Address Object', 138, 'Type Name: ipv4-addr The IPv4 Address object represents one or more IPv4 addresses expressed using CIDR notation. 6.8.1 Properties Required Common Properties type, id', 'vec_doc-10-oasis-stix21-p138-326', 0, 42, 'v2.1.0', '618945f2f930bfa669eadf09db3aa4e1476045928c8034a5c24b174f323628cc', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"6.8 IPv4 Address Object","subsection":"UNKNOWN","table_id":null,"page":138,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":326,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"6.8 IPv4 Address Object"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p139-327', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '6.8 IPv4 Address Object', 139, 'Standards Track Work Product 02 April 2025 - Page 139 of 276Copyright © OASIS Open 2025. All Rights Reserved. Optional Common Properties spec_version, object_marking_refs, granular_markings, defanged, extensions Not Applicable Common Properties created_by_ref, revoked, labels, confidence, lang, external_references IPv4 Address Object Specific Properties value, resolves_to_refs, belongs_to_refs ID Contributing Properties value Property Name Type Description type (required) string The value of this property MUST be ipv4-addr. value (required) string Specifies the values of one or more IPv4 addresses expressed using CIDR notation. If a given IPv4 Address object represents a single IPv4 address, the CIDR /32 suffix MAY be omitted. Example: 10.2.4.5/24 resolves_to_refs (optional) list of type identifier Specifies a list of references to one or more Layer 2 Media Access Control (MAC) addresses that the IPv4 address resolves to. The objects referenced in this list MUST be of type mac-addr belongs_to_refs (optional) list of type identifier Specifies a list of references to one or more autonomous systems (AS) that the IPv4 address belongs to. The objects referenced in this list MUST be of type autonomous-system 6.8.2 Relationships These are the relationships explicitly defined between the IPv4 Address object and other STIX Objects. The table identifies the relationships that can be made from this object type to another object type by way of the Relationship object. Source Relationship Type Target Description', 'vec_doc-10-oasis-stix21-p139-327', 0, 381, 'v2.1.0', '5e5b3755111fe6afd0e8229f85f460a449769ff91f8c69f14a89ba3fba8ddca4', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"6.8 IPv4 Address Object","subsection":"UNKNOWN","table_id":null,"page":139,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":327,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"6.8 IPv4 Address Object"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p140-328', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '6.8 IPv4 Address Object', 140, 'Standards Track Work Product 02 April 2025 - Page 140 of 276Copyright © OASIS Open 2025. All Rights Reserved. ipv4-addr resolves-to mac-addr This Relationship describes that thisIPv4 Address resolves to one or more Layer 2 Media Access Control (MAC) addresses. ipv4-addr belongs-to autonomous- system This Relationship describes that this IPv4 Address belongs to one or more autonomous systems (AS). Examples IPv4 Single Address { "type": "ipv4-addr", "spec_version": "2.1", "id": "ipv4-addr--28bb3599-77cd-5a82-a950-b5bc3caf07c4", "value": "198.51.100.3" } IPv4 CIDR Block { "type": "ipv4-addr", "spec_version": "2.1", "id": "ipv4-addr--1ea47840-aa39-5aa8-b4a2-cd203eb6662a", "value": "198.51.100.0/24" }', 'vec_doc-10-oasis-stix21-p140-328', 0, 177, 'v2.1.0', 'aa67980543ad07a83adb16799839532d72d8398175746358e26ec13a59b55fbd', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"6.8 IPv4 Address Object","subsection":"UNKNOWN","table_id":null,"page":140,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":328,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"6.8 IPv4 Address Object"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p140-329', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '6.9 IPv6 Address Object', 140, 'Type Name: ipv6-addr The IPv6 Address object represents one or more IPv6 addresses expressed using CIDR notation. 6.9.1 Properties Required Common Properties type, id Optional Common Properties spec_version, object_marking_refs, granular_markings, defanged, extensions Not Applicable Common Properties created_by_ref, revoked, labels, confidence, lang, external_references IPv6 Address Object Specific Properties value, resolves_to_refs, belongs_to_refs ID Contributing Properties', 'vec_doc-10-oasis-stix21-p140-329', 0, 120, 'v2.1.0', '951699f2792eb31c67296c1d7cb7a29ada9060f7a04213bfb11799ecb6f2e1a2', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"6.9 IPv6 Address Object","subsection":"UNKNOWN","table_id":null,"page":140,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":329,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"6.9 IPv6 Address Object"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p141-330', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '6.9 IPv6 Address Object', 141, 'Standards Track Work Product 02 April 2025 - Page 141 of 276Copyright © OASIS Open 2025. All Rights Reserved. value Property Name Type Description type (required) string The value of this property MUST be ipv6- addr. value (required) string Specifies the values of one or more IPv6 addresses expressed using CIDR notation. If a given IPv6 Address object represents a single IPv6 address, the CIDR /128 suffix MAY be omitted. resolves_to_refs (optional) list of type identifier Specifies a list of references to one or more Layer 2 Media Access Control (MAC) addresses that the IPv4 address resolves to. The objects referenced in this list MUST be of type mac-addr belongs_to_refs (optional) list of type identifier Specifies a list of references to one or more autonomous systems (AS) that the IPv6 address belongs to. The objects referenced in this list MUST be of type autonomous-system 6.9.2 Relationships These are the relationships explicitly defined between the IPv6 Address object and other STIX Objects. The table identifies the relationships that can be made from this object type to another object type by way of the Relationship object. Source Relationship Type Target Description ipv6-addr resolves-to mac-addr This Relationship describes that this IPv6 Address resolves to one or more Layer 2 Media Access Control (MAC) addresses. ipv6-addr belongs-to autonomous- system This Relationship describes that this IPv6 Address belongs to one or more autonomous systems (AS). Examples IPv6 Single Address { "type": "ipv6-addr", "spec_version": "2.1", "id": "ipv6-addr--85a85a8c-ee99-5722-946d-3c3a3270fc6f", "value": "2001:0db8:85a3:0000:0000:8a2e:0370:7334" }', 'vec_doc-10-oasis-stix21-p141-330', 0, 417, 'v2.1.0', '15b8906eef7080ebbf127fe72df42ddd09bbba21914a888f838fdbda88cad571', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"6.9 IPv6 Address Object","subsection":"UNKNOWN","table_id":null,"page":141,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":330,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"6.9 IPv6 Address Object"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p142-331', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '6.10 MAC Address Object', 142, 'Type Name: mac-addr The MAC Address object represents a single Media Access Control (MAC) address. 6.10.1 Properties Required Common Properties type, id Optional Common Properties spec_version, object_marking_refs, granular_markings, defanged, extensions Not Applicable Common Properties created_by_ref, revoked, labels, confidence, lang, external_references MAC Address Object Specific Properties value ID Contributing Properties value Property Name Type Description type (required) string The value of this property MUST be mac-addr. value (required) string Specifies the value of a single MAC address. The MAC address value MUST be represented as a single colon-delimited, lowercase MAC-48 address, which MUST include leading zeros for each octet. Example: 00:00:ab:cd:ef:01', 'vec_doc-10-oasis-stix21-p142-331', 0, 195, 'v2.1.0', '95bf59e415635b8c6f47a50c70d20a6d54208bbe8750d997e551180aaaf88fac', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"6.10 MAC Address Object","subsection":"UNKNOWN","table_id":null,"page":142,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":331,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"6.10 MAC Address Object"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p143-332', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '6.11 Mutex Object', 143, 'Type Name: mutex The Mutex object represents the properties of a mutual exclusion (mutex) object. 6.11.1 Properties Required Common Properties type, id Optional Common Properties spec_version, object_marking_refs, granular_markings, defanged, extensions Not Applicable Common Properties created_by_ref, revoked, labels, confidence, lang, external_references Mutex Object Specific Properties name ID Contributing Properties name Property Name Type Description type (required) string The value of this property MUST be mutex. name (required) string Specifies the name of the mutex object. Example Malware mutex { "type": "mutex", "spec_version": "2.1", "id": "mutex--f93fe911-e545-5239-b9b0-597840d0c871", "name": "__CLEANSWEEP__" }', 'vec_doc-10-oasis-stix21-p143-332', 0, 183, 'v2.1.0', '7c28edc407a866d52f4983af1bf4e235f942b0db410b213b4fe9fbdc3864b833', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"6.11 Mutex Object","subsection":"UNKNOWN","table_id":null,"page":143,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":332,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"6.11 Mutex Object"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p144-333', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '6.12 Network Traffic Object', 144, 'Type Name: network-traffic The Network Traffic object represents arbitrary network traffic that originates from a source and is addressed to a destination. The network traffic MAY or MAY NOT constitute a valid unicast, multicast, or broadcast network connection. This MAY also include traffic that is not established, such as a SYN flood. To allow for use cases where a source or destination address may be sensitive and not suitable for sharing, such as addresses that are internal to an organization’s network, the source and destination properties (src_ref and dst_ref, respectively) are defined as optional in the properties table below. However, a Network Traffic object MUST contain the protocols property and at least one of the src_ref or dst_ref properties and SHOULD contain the src_port and dst_port properties.', 'vec_doc-10-oasis-stix21-p144-333', 0, 206, 'v2.1.0', '9cf357b969de78ed8eca667754361a3672b77b378695a141f8cc6ce7a205a710', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"6.12 Network Traffic Object","subsection":"UNKNOWN","table_id":null,"page":144,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":333,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"6.12 Network Traffic Object"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p144-334', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '6.12 Network Traffic Object', 144, '6.12.1 Properties Required Common Properties type, id Optional Common Properties spec_version, object_marking_refs, granular_markings, defanged, extensions Not Applicable Common Properties created_by_ref, revoked, labels, confidence, lang, external_references Network Traffic Specific Properties start, end, is_active, src_ref, dst_ref, src_port, dst_port, protocols, src_byte_count,dst_byte_count, src_packets, dst_packets, ipfix, src_payload_ref, dst_payload_ref, encapsulates_refs, encapsulated_by_ref ID Contributing Properties start, end, src_ref, dst_ref, src_port, dst_port, protocols, extensions Property Name Type Description type (required) string The value of this property MUST be network-traffic. extensions (optional) dictionary The Network Traffic object defines the following extensions. In addition to these, producers MAY create their own.', 'vec_doc-10-oasis-stix21-p144-334', 0, 215, 'v2.1.0', '5ce189ad1e002f4b4d5a12c03b1f0ffd29eac5d4423f78297d9ed230f0e9ca36', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"6.12 Network Traffic Object","subsection":"UNKNOWN","table_id":null,"page":144,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":334,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"6.12 Network Traffic Object"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p144-335', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '6.12 Network Traffic Object', 144, 'http-request-ext, tcp-ext, icmp-ext, socket-ext Dictionary keys MUST use the specification defined name (examples above) or be the id of a STIX Extension object, depending on the type of extension being used. The corresponding dictionary values MUST', 'vec_doc-10-oasis-stix21-p144-335', 0, 63, 'v2.1.0', 'd9a1636c7a5b0d06e3ca8fab08f8c2cc9fac0c32203c0801eb58e090852c944f', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"6.12 Network Traffic Object","subsection":"UNKNOWN","table_id":null,"page":144,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":335,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"6.12 Network Traffic Object"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p145-336', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '6.12 Network Traffic Object', 145, 'Standards Track Work Product 02 April 2025 - Page 145 of 276Copyright © OASIS Open 2025. All Rights Reserved. contain the contents of the extension instance. start (optional) timestamp Specifies the date/time the network traffic was initiated, if known. end (optional) timestamp Specifies the date/time the network traffic ended, if known. If the is_active property is true, then the end property MUST NOT be included. If this property and the start property are both defined, then this property MUST be greater than or equal to the timestamp in the start property. is_active (optional) boolean Indicates whether the network traffic is still ongoing. If the end property is provided, this property MUST be false. src_ref (optional) identifier Specifies the source of the network traffic, as a reference to a Cyber-observable Object. The object referenced MUST be of type ipv4-addr, ipv6-addr, mac-addr, or domain-name (for cases where the IP address for a domain name is unknown).', 'vec_doc-10-oasis-stix21-p145-336', 0, 245, 'v2.1.0', 'b9c00741a6131f1c5aca7dc155a487bb4e2afdb0ed65a844da4b784b2d98ff7e', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"6.12 Network Traffic Object","subsection":"UNKNOWN","table_id":null,"page":145,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":336,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"6.12 Network Traffic Object"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p145-337', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '6.12 Network Traffic Object', 145, 'dst_ref (optional) identifier Specifies the destination of the network traffic, as a reference to a Cyber-observable Object. The object referenced MUST be of type ipv4-addr, ipv6-addr, mac-addr, or domain-name (for cases where the IP address for a domain name is unknown). src_port (optional) integer Specifies the source port used in the network traffic, as an integer. The port value MUST be in the range of 0 - 65535. dst_port (optional) integer Specifies the destination port used in the network traffic, as an integer. The port value MUST be in the range of 0 - 65535. protocols (required) list of type string Specifies the protocols observed in the network traffic, along with their corresponding state. Protocols MUST be listed in low to high order, from outer to inner in terms of packet encapsulation. That is, the protocols in the outer level of the packet, such as IP, MUST be listed first. The protocol names SHOULD come from the', 'vec_doc-10-oasis-stix21-p145-337', 0, 236, 'v2.1.0', '6b1ae7aacea45c6d65ba0a69eda91539f7b97353c33f6af8a78012e830278b15', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"6.12 Network Traffic Object","subsection":"UNKNOWN","table_id":null,"page":145,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":337,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"6.12 Network Traffic Object"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p146-338', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '6.12 Network Traffic Object', 146, 'Standards Track Work Product 02 April 2025 - Page 146 of 276Copyright © OASIS Open 2025. All Rights Reserved. service names defined in the Service Name column of the IANA Service Name and Port Number Registry [Port Numbers]. In cases where there is variance in the name of a network protocol not included in the IANA Registry, content producers should exercise their best judgement, and it is recommended that lowercase names be used for consistency with the IANA registry. If the protocol extension is present, the corresponding protocol value for that extension SHOULD be listed in this property. Examples: ipv4, tcp, http ipv4, udp ipv6, tcp, http ipv6, tcp, ssl, https src_byte_count (optional) integer Specifies the number of bytes, as a positive integer, sent from the source to the destination. dst_byte_count (optional) integer Specifies the number of bytes, as a positive integer, sent from the destination to the source.', 'vec_doc-10-oasis-stix21-p146-338', 0, 233, 'v2.1.0', '64b7b7ba461031c8de59f7c0a919a38752a037215c771aa862cab31c2bbf60dc', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"6.12 Network Traffic Object","subsection":"UNKNOWN","table_id":null,"page":146,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":338,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"6.12 Network Traffic Object"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p146-339', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '6.12 Network Traffic Object', 146, 'src_packets (optional) integer Specifies the number of packets, as a positive integer, sent from the source to the destination. dst_packets (optional) integer Specifies the number of packets, as a positive integer, sent from the destination to the source. ipfix (optional) dictionary Specifies any IP Flow Information Export [IPFIX] data for the traffic, as a dictionary. Each key/value pair in the dictionary represents the name/value of a single IPFIX element. Accordingly, each dictionary key SHOULD be a case-preserved version of the IPFIX element name, e.g., octetDeltaCount. Each dictionary value MUST be either an integer or a string, as well as a valid IPFIX property. src_payload_ref (optional) identifier Specifies the bytes sent from the source to the destination. The object referenced in this property MUST be of type artifact. dst_payload_ref (optional) identifier Specifies the bytes sent from the destination to the source.', 'vec_doc-10-oasis-stix21-p146-339', 0, 235, 'v2.1.0', 'be812f60f859e0d0e2f4bcf5a538d70bfa9badea9420672636a7adb674e3133f', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"6.12 Network Traffic Object","subsection":"UNKNOWN","table_id":null,"page":146,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":339,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"6.12 Network Traffic Object"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p147-340', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '6.12 Network Traffic Object', 147, 'Standards Track Work Product 02 April 2025 - Page 147 of 276Copyright © OASIS Open 2025. All Rights Reserved. The object referenced in this property MUST be of type artifact. encapsulates_refs (optional) list of type identifier Links to other network-traffic objects encapsulated by this network-traffic object. The objects referenced in this property MUST be of type network-traffic. encapsulated_by_ref (optional) identifier Links to another network-traffic object which encapsulates this object. The objects referenced in this property MUST be of type network-traffic. Examples Basic TCP Network Traffic [ { "type": "ipv4-addr", "spec_version": "2.1", "id": "ipv4-addr--9cf4a8ec-7640-5f40-a006-79942896168b", "value": "198.51.100.2" }, { "type": "ipv4-addr", "spec_version": "2.1", "id": "ipv4-addr--28bb3599-77cd-5a82-a950-b5bc3caf07c4", "value": "198.51.100.3" }, { "type": "network-traffic", "spec_version": "2.1", "id": "network-traffic--6e0cb830-0305-57d4-8536-7be874d42005", "src_ref": "ipv4-addr--9cf4a8ec-7640-5f40-a006-79942896168b", "dst_ref": "ipv4-addr--28bb3599-77cd-5a82-a950-b5bc3caf07c4", "protocols": [ "tcp" ] } ] Basic HTTP Network Traffic [ { "type": "domain-name", "spec_version": "2.1", "id": "domain-name--bedb4899-d24b-5401-bc86-8f6b4cc18ec7", "value": "example.com" }, { "type": "network-traffic", "spec_version": "2.1", "id": "network-traffic--c695ada6-5d5d-5446-a661-935874e1d058", "dst_ref": "domain-name--bedb4899-d24b-5401-bc86-8f6b4cc18ec7", "protocols": [', 'vec_doc-10-oasis-stix21-p147-340', 0, 373, 'v2.1.0', 'cd4a77fce24d638f76debddd5aa333dda66dc1adaf0f7b7abc3cf300c5b89ddc', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"6.12 Network Traffic Object","subsection":"UNKNOWN","table_id":null,"page":147,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":340,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"6.12 Network Traffic Object"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p148-341', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '6.12 Network Traffic Object', 148, 'Standards Track Work Product 02 April 2025 - Page 148 of 276Copyright © OASIS Open 2025. All Rights Reserved. "ipv4", "tcp", "http" ] } ] Network Traffic with Netflow Data [ { "type": "ipv4-addr", "spec_version": "2.1", "id": "ipv4-addr--ad74bc22-43d2-52ed-890e-7d382f58e1eb", "value": "203.0.113.1" }, { "type": "ipv4-addr", "spec_version": "2.1", "id": "ipv4-addr--826fe3cb-56b0-5620-9d30-4c17ed7b24e3", "value": "203.0.113.5" }, { "type": "network-traffic", "spec_version": "2.1", "id": "network-traffic--44eb3012-751d-5c12-b9ba-1506e42e26ef", "src_ref": "ipv4-addr--ad74bc22-43d2-52ed-890e-7d382f58e1eb", "dst_ref": "ipv4-addr--826fe3cb-56b0-5620-9d30-4c17ed7b24e3", "protocols": [ "ipv4", "tcp" ], "src_byte_count": 147600, "src_packets": 100, "ipfix": { "minimumIpTotalLength": 32, "maximumIpTotalLength": 2556 } } ] Basic Tunneled Network Traffic [ { "type": "ipv4-addr", "spec_version": "2.1", "id": "ipv4-addr--9cf4a8ec-7640-5f40-a006-79942896168b", "value": "198.51.100.2" }, { "type": "ipv4-addr", "spec_version": "2.1", "id": "ipv4-addr--ad74bc22-43d2-52ed-890e-7d382f58e1eb", "value": "203.0.113.1" }, { "type": "ipv4-addr", "spec_version": "2.1", "id": "ipv4-addr--a2935766-2522-5939-9513-cc3536f212a3", "value": "203.0.113.2" },', 'vec_doc-10-oasis-stix21-p148-341', 0, 311, 'v2.1.0', '8e6cc196fd0aec706e01670a4e373795e0e05092e2f97e4ea00e9920d069c2db', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"6.12 Network Traffic Object","subsection":"UNKNOWN","table_id":null,"page":148,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":341,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"6.12 Network Traffic Object"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p149-342', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '6.12 Network Traffic Object', 149, 'Standards Track Work Product 02 April 2025 - Page 149 of 276Copyright © OASIS Open 2025. All Rights Reserved. { "type": "network-traffic", "spec_version": "2.1", "id": "network-traffic--372c0c73-777a-50de-bc3a-92cc72fcf7dd", "src_ref": "ipv4-addr--9cf4a8ec-7640-5f40-a006-79942896168b", "dst_ref": "ipv4-addr--ad74bc22-43d2-52ed-890e-7d382f58e1eb", "src_port": 2487, "dst_port": 1723, "protocols": [ "ipv4", "pptp" ], "src_byte_count": 35779, "dst_byte_count": 935750, "encapsulates_refs": [ "network-traffic--8dce0dc4-f5ea-5313-8e6c-03646d419b6a" ] }, { "type": "network-traffic", "spec_version": "2.1", "id": "network-traffic--8dce0dc4-f5ea-5313-8e6c-03646d419b6a", "src_ref": "ipv4-addr--9cf4a8ec-7640-5f40-a006-79942896168b", "dst_ref": "ipv4-addr--a2935766-2522-5939-9513-cc3536f212a3", "src_port": 24678, "dst_port": 80, "protocols": [ "ipv4", "tcp", "http" ], "src_packets": 14356, "dst_packets": 14356, "encapsulated_by_ref": "network-traffic--372c0c73-777a-50de-bc3a-92cc72fcf7dd" } ] Web traffic tunneled over DNS [ { "type": "ipv4-addr", "spec_version": "2.1", "id": "ipv4-addr--ad74bc22-43d2-52ed-890e-7d382f58e1eb", "value": "203.0.113.1" }, { "type": "ipv4-addr", "spec_version": "2.1", "id": "ipv4-addr--13cba85b-1780-5517-b600-7b6546cfd760", "value": "198.51.100.34" }, { "type": "ipv4-addr", "spec_version": "2.1", "id": "ipv4-addr--23476ffc-8715-5eee-bd37-2f204b7db486", "value": "198.51.100.54" }, { "type": "network-traffic", "spec_version": "2.1", "id": "network-traffic--fc1686c0-b36e-5041-9ce4-c8df9cf10d6d", "src_ref": "ipv4-addr--ad74bc22-43d2-52ed-890e-7d382f58e1eb", "dst_ref": "ipv4-addr--13cba85b-1780-5517-b600-7b6546cfd760", "src_port": 2487, "dst_port": 53,', 'vec_doc-10-oasis-stix21-p149-342', 0, 423, 'v2.1.0', '1623a48bfc8b3f32d47c4a0d2905d4773504595d741bde64ef291ec6e69e2327', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"6.12 Network Traffic Object","subsection":"UNKNOWN","table_id":null,"page":149,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":342,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"6.12 Network Traffic Object"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p150-343', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '6.12 Network Traffic Object', 150, 'Standards Track Work Product 02 April 2025 - Page 150 of 276Copyright © OASIS Open 2025. All Rights Reserved. "protocols": [ "ipv4", "udp", "dns" ], "src_byte_count": 35779, "dst_byte_count": 935750, "encapsulates_refs": [ "network-traffic--27ed09d5-f85a-5a8e-8590-49a91d7e510e" ] }, { "type": "network-traffic", "spec_version": "2.1", "id": "network-traffic--27ed09d5-f85a-5a8e-8590-49a91d7e510e", "src_ref": "ipv4-addr--13cba85b-1780-5517-b600-7b6546cfd760", "dst_ref": "ipv4-addr--23476ffc-8715-5eee-bd37-2f204b7db486", "src_port": 24678, "dst_port": 443, "protocols": [ "ipv4", "tcp", "ssl", "http" ], "src_packets": 14356, "dst_packets": 14356, "encapsulated_by_ref": "network-traffic--fc1686c0-b36e-5041-9ce4-c8df9cf10d6d" } ] 6.12.2 HTTP Request Extension Type Name: http-request-ext The HTTP request extension specifies a default extension for capturing network traffic properties specific to HTTP requests. The key for this extension when used in the extensions dictionary MUST be http- request-ext. Note that this predefined extension does not use the extension facility described in', 'vec_doc-10-oasis-stix21-p150-343', 0, 274, 'v2.1.0', '4fca4d919ad1527f96f003423c784caa4ff080c697aff3ee7dca502620850200', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"6.12 Network Traffic Object","subsection":"UNKNOWN","table_id":null,"page":150,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":343,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"6.12 Network Traffic Object"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p150-344', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', 'section 7.3. The corresponding protocol value for this extension is http.', 150, 'Properties Property Name Type Description request_method (required) string Specifies the HTTP method portion of the HTTP request line, as a lowercase string. request_value (required) string Specifies the value (typically a resource path) portion of the HTTP request line. request_version (optional) string Specifies the HTTP version portion of the HTTP request line, as a lowercase string. request_header (optional) dictionary Specifies all of the HTTP header fields that may be found in the HTTP client request, as a dictionary. Each key in the dictionary MUST be the name of the header field and SHOULD preserve case, e.g., User- Agent. The corresponding value for each dictionary key MUST always be a list of type string to support when a header field is repeated.', 'vec_doc-10-oasis-stix21-p150-344', 0, 192, 'v2.1.0', '6e5aab3748d1760d82ffb8b232fceaab72bf21e50a55caee3f1553c072ea7b48', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"section 7.3. The corresponding protocol value for this extension is http.","subsection":"UNKNOWN","table_id":null,"page":150,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":344,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"section 7.3. The corresponding protocol value for this extension is http."}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p151-345', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', 'section 7.3. The corresponding protocol value for this extension is http.', 151, 'Standards Track Work Product 02 April 2025 - Page 151 of 276Copyright © OASIS Open 2025. All Rights Reserved. message_body_length(optional) integer Specifies the length of the HTTP message body, ifincluded, in bytes. message_body_data_ref (optional) identifier Specifies the data contained in the HTTP message body, if included. The object referenced in this property MUST be of type artifact. Example Basic HTTP Request [ { "type": "ipv4-addr", "spec_version": "2.1", "id": "ipv4-addr--165070a8-c561-58a8-8659-fce2f255c2c0", "value": "198.51.100.53" }, { "type": "network-traffic", "spec_version": "2.1", "id": "network-traffic--fdd6dbda-a206-52fe-b19b-64d908748850", "dst_ref": "ipv4-addr--165070a8-c561-58a8-8659-fce2f255c2c0", "protocols": [ "tcp", "http" ], "extensions": { "http-request-ext": { "request_method": "get", "request_value": "/download.html", "request_version": "http/1.1", "request_header": { "Accept-Encoding": ["gzip,deflate"], "User-Agent": ["Mozilla/5.0 (Windows; U; Windows NT 5.1; en-US; rv:1.6) Gecko/20040113"], "Host": ["www.example.com"] } } } } ] 6.12.3 ICMP Extension Type Name: icmp-ext The ICMP extension specifies a default extension for capturing network traffic properties specific to ICMP. The key for this extension when used in the extensions dictionary MUST be icmp-ext. Note that this predefined extension does not use the extension facility described in section 7.3. The corresponding protocol value for this extension is icmp. Properties Property Name Type Description icmp_type_hex (required) hex Specifies the ICMP type byte.', 'vec_doc-10-oasis-stix21-p151-345', 0, 393, 'v2.1.0', '2ec43c4d947edbe93931ea7f4b2b6115f388cf6e126f29be8fafb8a33b970721', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"section 7.3. The corresponding protocol value for this extension is http.","subsection":"UNKNOWN","table_id":null,"page":151,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":345,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"section 7.3. The corresponding protocol value for this extension is http."}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p152-346', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', 'section 7.3. The corresponding protocol value for this extension is http.', 152, 'Standards Track Work Product 02 April 2025 - Page 152 of 276Copyright © OASIS Open 2025. All Rights Reserved. icmp_code_hex (required) hex Specifies the ICMP code byte. Example Basic ICMP Traffic [ { "type": "ipv4-addr", "spec_version": "2.1", "id": "ipv4-addr--4b8ed646-46df-5a9c-b5a6-b3ae128f35a6", "value": "198.51.100.9" }, { "type": "ipv4-addr", "spec_version": "2.1", "id": "ipv4-addr--826fe3cb-56b0-5620-9d30-4c17ed7b24e3", "value": "203.0.113.5" }, { "type": "network-traffic", "spec_version": "2.1", "id": "network-traffic--4f156a67-4efc-58fb-b0a7-f2612927a37d", "src_ref": "ipv4-addr--4b8ed646-46df-5a9c-b5a6-b3ae128f35a6", "dst_ref": "ipv4-addr--826fe3cb-56b0-5620-9d30-4c17ed7b24e3", "protocols": [ "icmp" ], "extensions": { "icmp-ext": { "icmp_type_hex": "08", "icmp_code_hex": "00" } } } ] 6.12.4 Network Socket Extension Type Name: socket-ext The Network Socket extension specifies a default extension for capturing network traffic properties associated with network sockets. The key for this extension when used in the extensions dictionary MUST be socket-ext. Note that this predefined extension does not use the extension facility described in section 7.3. Properties Property Name Type Description address_family (required) enum Specifies the address family (AF_*) that the socket is configured for. The values of this property MUST come from the network- socket-address-family-enum enumeration. is_blocking (optional) boolean Specifies whether the socket is in blocking mode.', 'vec_doc-10-oasis-stix21-p152-346', 0, 374, 'v2.1.0', '4029e01099124c7fb7a1037ac44c97f4204e073e3818435e5c87bcece4233238', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"section 7.3. The corresponding protocol value for this extension is http.","subsection":"UNKNOWN","table_id":null,"page":152,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":346,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"section 7.3. The corresponding protocol value for this extension is http."}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p153-347', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', 'section 7.3. The corresponding protocol value for this extension is http.', 153, 'Standards Track Work Product 02 April 2025 - Page 153 of 276Copyright © OASIS Open 2025. All Rights Reserved. is_listening(optional) boolean Specifies whether the socket is in listening mode. options (optional) dictionary Specifies any options (e.g., SO_*) that may be used by the socket, as a dictionary. Each key in the dictionary SHOULD be a case-preserved version of the option name, e.g., SO_ACCEPTCONN. Each key value in the dictionary MUST be the value for the corresponding options key. Each dictionary value MUST be an integer. For SO_RCVTIMEO, SO_SNDTIMEO and SO_LINGER the value represents the number of milliseconds. If the SO_LINGER key is present, it indicates that the SO_LINGER option is active. socket_type (optional) enum Specifies the type of the socket. The values of this property MUST come from the network- socket-type-enum enumeration. socket_descriptor (optional) integer Specifies the socket file descriptor value associated with the socket, as a non-negative integer. socket_handle (optional) integer Specifies the handle or inode value associated with the socket. Examples Basic Stream Socket [ { "type": "ipv4-addr", "spec_version": "2.1", "id": "ipv4-addr--9cf4a8ec-7640-5f40-a006-79942896168b", "value": "198.51.100.2" }, { "type": "network-traffic", "spec_version": "2.1", "id": "network-traffic--59d8852c-0c68-5e0c-8ae2-f3c46bd7b1df", "src_ref": "ipv4-addr--9cf4a8ec-7640-5f40-a006-79942896168b", "src_port": 223, "protocols": [ "ip", "tcp" ], "extensions": { "socket-ext": { "is_listening": true, "address_family": "AF_INET", "socket_type": "SOCK_STREAM" } } } ] 6.12.5 TCP Extension Type Name: tcp-ext', 'vec_doc-10-oasis-stix21-p153-347', 0, 409, 'v2.1.0', '5728d910f7a530537c9d18359b8d43dee0bdc06ccc9719c2b31c18de5f5ff46b', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"section 7.3. The corresponding protocol value for this extension is http.","subsection":"UNKNOWN","table_id":null,"page":153,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":347,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"section 7.3. The corresponding protocol value for this extension is http."}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p154-348', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', 'section 7.3. The corresponding protocol value for this extension is http.', 154, 'Standards Track Work Product 02 April 2025 - Page 154 of 276Copyright © OASIS Open 2025. All Rights Reserved. The TCP extension specifies a default extension for capturing network traffic properties specific to TCP. The key for this extension when used in the extensions dictionary MUST be tcp-ext. Note that this predefined extension does not use the extension facility described in section 7.3. The corresponding protocol value for this extension is tcp. An object using the TCP Extension MUST contain at least one property from this extension. Properties Property Name Type Description src_flags_hex (optional) hex Specifies the source TCP flags, as the union of all TCP flags observed between the start of the traffic (as defined by the start property) and the end of the traffic (as defined by the end property).', 'vec_doc-10-oasis-stix21-p154-348', 0, 205, 'v2.1.0', '0f0f40136bab6960ecdb097267cba076e6f7140e829c226917f307cb7a170e1d', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"section 7.3. The corresponding protocol value for this extension is http.","subsection":"UNKNOWN","table_id":null,"page":154,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":348,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"section 7.3. The corresponding protocol value for this extension is http."}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p154-349', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', 'section 7.3. The corresponding protocol value for this extension is http.', 154, 'If the start and end times of the traffic are not specified, this property SHOULD be interpreted as the union of all TCP flags observed over the entirety of the network traffic being reported upon. dst_flags_hex (optional) hex Specifies the destination TCP flags, as the union of all TCP flags observed between the start of the traffic (as defined by the start property) and the end of the traffic (as defined by the end property). If the start and end times of the traffic are not specified, this property SHOULD be interpreted as the union of all TCP flags observed over the entirety of the network traffic being reported upon.', 'vec_doc-10-oasis-stix21-p154-349', 0, 158, 'v2.1.0', '12391d5367ddb54ab69cb2dd030b5328a83a71b8387848637d7f3866bc479bde', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"section 7.3. The corresponding protocol value for this extension is http.","subsection":"UNKNOWN","table_id":null,"page":154,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":349,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"section 7.3. The corresponding protocol value for this extension is http."}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p154-350', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', 'section 7.3. The corresponding protocol value for this extension is http.', 154, 'Example Basic TCP Traffic [ { "type": "ipv4-addr", "spec_version": "2.1", "id": "ipv4-addr--f85034be-e4ad-5153-aa6b-79c450eb25b3", "value": "198.51.100.5" }, { "type": "ipv4-addr", "spec_version": "2.1", "id": "ipv4-addr--72073c96-1246-5058-8e5c-6ca59d656dee", "value": "198.51.100.6" }, { "type": "network-traffic", "spec_version": "2.1", "id": "network-traffic--47b27c77-4272-563f-91ca-87e2a4afd6ef", "src_ref": "ipv4-addr--f85034be-e4ad-5153-aa6b-79c450eb25b3", "dst_ref": "ipv4-addr--72073c96-1246-5058-8e5c-6ca59d656dee", "src_port": 3372, "dst_port": 80, "protocols": [ "tcp" ], "extensions": { "tcp-ext": { "src_flags_hex": "00000002" } } } ]', 'vec_doc-10-oasis-stix21-p154-350', 0, 163, 'v2.1.0', 'b47e45f84aeb7ed5374ad15d6616d9583ecd8b2765264625689233067f0d175f', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"section 7.3. The corresponding protocol value for this extension is http.","subsection":"UNKNOWN","table_id":null,"page":154,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":350,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"section 7.3. The corresponding protocol value for this extension is http."}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p155-351', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '6.13 Process Object', 155, 'Type Name: process The Process object represents common properties of an instance of a computer program as executed on an operating system. A Process object MUST contain at least one property (other than type) from this object (or one of its extensions). 6.13.1 Properties Required Common Properties type, id Optional Common Properties spec_version, object_marking_refs, granular_markings, defanged, extensions Not Applicable Common Properties created_by_ref, revoked, labels, confidence, lang, external_references Process Object Specific Properties is_hidden, pid, created_time, cwd, command_line, environment_variables,opened_connection_refs, creator_user_ref, image_ref, parent_ref, child_refs ID Contributing Properties Since all properties on this object are optional, please use a UUIDv4 for the ID of this object. Property Name Type Description type (required) string The value of this property MUST be process. extensions (optional) dictionary The Process object defines the following extensions. In addition to these, producers MAY create their own. windows-process-ext, windows- service-ext Dictionary keys MUST use the specification defined name (examples above) or be the id of a STIX Extension object, depending on the type of extension being used. The corresponding dictionary values MUST contain the contents of the extension instance. is_hidden (optional) boolean Specifies whether the process is hidden.', 'vec_doc-10-oasis-stix21-p155-351', 0, 355, 'v2.1.0', '814839a5e4daa1562d25f385337ba29ed550104fafbd9cd83ef296e0937ed0d0', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"6.13 Process Object","subsection":"UNKNOWN","table_id":null,"page":155,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":351,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"6.13 Process Object"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p156-352', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '6.13 Process Object', 156, 'Standards Track Work Product 02 April 2025 - Page 156 of 276Copyright © OASIS Open 2025. All Rights Reserved. pid (optional) integer Specifies the Process ID, or PID, of theprocess. created_time (optional) timestamp Specifies the date/time at which the process was created. cwd (optional) string Specifies the current working directory of the process. command_line (optional) string Specifies the full command line used in executing the process, including the process name (which may be specified individually via the image_ref.name property) and any arguments. environment_variables (optional) dictionary Specifies the list of environment variables associated with the process as a dictionary. Each key in the dictionary MUST be a case preserved version of the name of the environment variable, and each corresponding value MUST be the environment variable value as a string.', 'vec_doc-10-oasis-stix21-p156-352', 0, 219, 'v2.1.0', 'd9429bffcaaf58e7df2aee88bc6669f74f64a8d6a1c8206b94861361e0f6616a', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"6.13 Process Object","subsection":"UNKNOWN","table_id":null,"page":156,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":352,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"6.13 Process Object"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p156-353', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '6.13 Process Object', 156, 'opened_connection_refs (optional) list of type identifier Specifies the list of network connections opened by the process, as a reference to one or more Network Traffic objects. The objects referenced in this list MUST be of type network-traffic. creator_user_ref (optional) identifier Specifies the user that created the process, as a reference to a User Account object. The object referenced in this property MUST be of type user-account. image_ref (optional) identifier Specifies the executable binary that was executed as the process image, as a reference to a File object. The object referenced in this property MUST be of type file. parent_ref (optional) identifier Specifies the other process that spawned (i.e. is the parent of) this one, as a reference to a Process object. The object referenced in this property MUST be of type process. child_refs (optional) list of type identifier Specifies the other processes that were spawned by (i.e.', 'vec_doc-10-oasis-stix21-p156-353', 0, 238, 'v2.1.0', '8ca946b7b1863d4d048bd6415cb47ad0ca27958e3e9679b1ab92f08d7883cf5e', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"6.13 Process Object","subsection":"UNKNOWN","table_id":null,"page":156,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":353,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"6.13 Process Object"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p156-354', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '6.13 Process Object', 156, 'children of) this process, as a reference to one or more other Process objects.', 'vec_doc-10-oasis-stix21-p156-354', 0, 20, 'v2.1.0', '5e82003be2ab5682975c1c32d61f9df359f5bddcbe043a58a5e6d4f3616f8216', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"6.13 Process Object","subsection":"UNKNOWN","table_id":null,"page":156,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":354,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"6.13 Process Object"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p157-355', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '6.13 Process Object', 157, 'Standards Track Work Product 02 April 2025 - Page 157 of 276Copyright © OASIS Open 2025. All Rights Reserved. The objects referenced in this list MUST be of type process. Example Basic Process [ { "type": "file", "spec_version": "2.1", "id": "file--3eb55c0e-fe96-588b-a7ab-10f55f7ec596", "name": "gedit-bin", "hashes": { "SHA-256": "aec070645fe53ee3b3763059376134f058cc337247c978add178b6ccdfb0019f" } }, { "type": "process", "spec_version": "2.1", "id": "process--8fac80fe-a220-4ba9-8ffe-4f43ce8edff8", "pid": 1221, "created_time": "2016-01-20T14:11:25.55Z", "command_line": "./gedit-bin --new-window", "image_ref": "file--e04f22d1-be2c-59de-add8-10f61d15fe20" } ] 6.13.2 Windows™ Process Extension Type Name: windows-process-ext The Windows Process extension specifies a default extension for capturing properties specific to Windows processes. The key for this extension when used in the extensions dictionary MUST be windows-process-ext. Note that this predefined extension does not use the extension facility described in section 7.3. An object using the Windows Process Extension MUST contain at least one property from this extension. Properties Property Name Type Description aslr_enabled (optional) boolean Specifies whether Address Space Layout Randomization (ASLR) is enabled for the process. dep_enabled (optional) boolean Specifies whether Data Execution Prevention (DEP) is enabled for the process. priority (optional) string Specifies the current priority class of the process in Windows. This value SHOULD be a string that ends in _CLASS. owner_sid (optional) string Specifies the Security ID (SID) value of the owner of the process. windows_title (optional) string Specifies the title of the main window of the process.', 'vec_doc-10-oasis-stix21-p157-355', 0, 434, 'v2.1.0', '76c7ab14c1ad5cfdd19948b0a1cac3dc2eb73661910523a556545237b292cda7', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"6.13 Process Object","subsection":"UNKNOWN","table_id":null,"page":157,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":355,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"6.13 Process Object"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p158-356', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '6.13 Process Object', 158, 'Standards Track Work Product 02 April 2025 - Page 158 of 276Copyright © OASIS Open 2025. All Rights Reserved. startup_info(optional) dictionary Specifies the STARTUP_INFO struct used by the process, as adictionary. Each name/value pair in the struct MUST be represented as a key/value pair in the dictionary, where each key MUST be a case-preserved version of the original name. For example, given a name of “lpDesktop” the corresponding key would be lpDesktop. integrity_level (optional) enum Specifies the Windows integrity level, or trustworthiness, of the process. The values of this property MUST come from the windows- integrity-level-enum enumeration. Example Basic Windows Process { "type": "process", "spec_version": "2.1", "id": "process--65a99d8a-e5b2-44bb-8311-963a580ee9a1", "pid": 314, "extensions": { "windows-process-ext": { "aslr_enabled": true, "dep_enabled": true, "priority": "HIGH_PRIORITY_CLASS", "owner_sid": "S-1-5-21-186985262-1144665072-74031268-1309" } } } 6.13.3 Windows™ Service Extension Type Name: windows-service-ext The Windows Service extension specifies a default extension for capturing properties specific to Windows services. The key for this extension when used in the extensions dictionary MUST be windows-service-ext. Note that this predefined extension does not use the extension facility described in section 7.3. As all properties of this extension are optional, at least one of the properties defined below MUST be included when using this extension. Properties Property Name Type Description service_name (optional) string Specifies the name of the service. descriptions (optional) list of type string Specifies the descriptions defined for the service. display_name (optional) string Specifies the display name of the service in Windows GUI controls.', 'vec_doc-10-oasis-stix21-p158-356', 0, 450, 'v2.1.0', '0feb5c5e43c322245629f45126862cf616f2f2b00a530f79eb28110f55bc5d1a', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"6.13 Process Object","subsection":"UNKNOWN","table_id":null,"page":158,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":356,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"6.13 Process Object"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p159-357', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '6.13 Process Object', 159, 'Standards Track Work Product 02 April 2025 - Page 159 of 276Copyright © OASIS Open 2025. All Rights Reserved. group_name(optional) string Specifies the name of the load ordering group of whichthe service is a member. start_type (optional) enum Specifies the start options defined for the service. The values of this property MUST come from the windows-service-start-type-enum enumeration. service_dll_refs (optional) list of type identifier Specifies the DLLs loaded by the service, as a reference to one or more File objects. The objects referenced in this property MUST be of type file. service_type (optional) enum Specifies the type of the service. The values of this property MUST come from the windows-service-type-enum enumeration. service_status (optional) enum Specifies the current status of the service. The values of this property MUST come from the windows-service-status-enum enumeration. Examples Basic Windows Service [ { "type": "file", "spec_version": "2.1", "id": "file--ca7d6a8a-b79e-5c3b-b736-8d48adcf0c97", "hashes": { "SHA-256": "bf07a7fbb825fc0aae7bf4a1177b2b31fcf8a3feeaf7092761e18c859ee52a9c" }, "name": "sirvizio.exe" } { "type": "process", "spec_version": "2.1", "id": "process--ab1ff083-dc96-4896-8c8d-4e623f6e145e", "pid": 2217, "command_line": "C:\\Windows\\System32\\sirvizio.exe /s", "image_ref": "file--3916128d-69af-5525-be7a-99fac2383a59", "extensions": { "windows-service-ext": { "service_name": "sirvizio", "display_name": "Sirvizio", "start_type": "SERVICE_AUTO_START", "service_type": "SERVICE_WIN32_OWN_PROCESS", "service_status": "SERVICE_RUNNING" } } } ]', 'vec_doc-10-oasis-stix21-p159-357', 0, 400, 'v2.1.0', '618f7364110f0672412b87dfa91f0caee3f8a0f60c53105604e06c20107632d8', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"6.13 Process Object","subsection":"UNKNOWN","table_id":null,"page":159,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":357,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"6.13 Process Object"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p160-358', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '6.14 Software Object', 160, 'Type Name: software The Software object represents high-level properties associated with software, including software products. 6.14.1 Properties Required Common Properties type, id Optional Common Properties spec_version, object_marking_refs, granular_markings, defanged, extensions Not Applicable Common Properties created_by_ref, revoked, labels, confidence, lang, external_references Software Object Specific Properties name, cpe, swid, languages, vendor, version ID Contributing Properties name, cpe, swid, vendor, version Property Name Type Description type (required) string The value of this property MUST be software. name (required) string Specifies the name of the software. cpe (optional) string Specifies the Common Platform Enumeration (CPE) entry for the software, if available. The value for this property MUST be a CPE v2.3 entry from the official NVD CPE Dictionary [NVD]. While the CPE dictionary does not contain entries for all software, whenever it does contain an identifier for a given instance of software, this property SHOULD be present. swid (optional) string Specifies the Software Identification (SWID) Tags [SWID] entry for the software, if available. The tag attribute, tagId, a globally unique identifier, SHOULD be used as a proxy identifier of the tagged product. languages (optional) list of type string Specifies the languages supported by the software. The value of each list member MUST be a language code conformant to [RFC5646].', 'vec_doc-10-oasis-stix21-p160-358', 0, 368, 'v2.1.0', '26d1c4a3ed9023edb777e553711febbbbc1b68cf236b5528bee6ffcd530e79ef', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"6.14 Software Object","subsection":"UNKNOWN","table_id":null,"page":160,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":358,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"6.14 Software Object"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p161-359', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '6.14 Software Object', 161, 'Standards Track Work Product 02 April 2025 - Page 161 of 276Copyright © OASIS Open 2025. All Rights Reserved. vendor(optional) string Specifies the name of the vendor of the software. version (optional) string Specifies the version of the software. Example Typical Software Instance { "type": "software", "spec_version": "2.1", "id": "software--710b0b41-d4d0-5d6c-a400-fc9254554ffc", "name": "Word", "cpe": "cpe:2.3:a:microsoft:word:2000:*:*:*:*:*:*:*", "version": "2002", "vendor": "Microsoft" }', 'vec_doc-10-oasis-stix21-p161-359', 0, 124, 'v2.1.0', '8aa68a1135ead9eafcf10917731673771e4d0e79115eebe75571fdd0747def8d', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"6.14 Software Object","subsection":"UNKNOWN","table_id":null,"page":161,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":359,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"6.14 Software Object"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p161-360', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '6.15 URL Object', 161, 'Type Name: url The URL object represents the properties of a uniform resource locator (URL). 6.15.1 Properties Required Common Properties type, id Optional Common Properties spec_version, object_marking_refs, granular_markings, defanged, extensions Not Applicable Common Properties created_by_ref, revoked, labels, confidence, lang, external_references URL Object Specific Properties value ID Contributing Properties value Property Name Type Description type (required) string The value of this property MUST be url. value (required) string Specifies the value of the URL. The value of this property MUST conform to [RFC3986], more specifically section 1.1.3 with reference to the definition', 'vec_doc-10-oasis-stix21-p161-360', 0, 173, 'v2.1.0', '32e1214efe2d0b3b86a8f4eabf8a98a4c131c81cfb710cb2a8c5828647d60191', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"6.15 URL Object","subsection":"UNKNOWN","table_id":null,"page":161,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":360,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"6.15 URL Object"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p162-361', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '6.16 User Account Object', 162, 'Type Name: user-account The User Account object represents an instance of any type of user account, including but not limited to operating system, device, messaging service, and social media platform accounts. As all properties of this object are optional, at least one of the properties defined below MUST be included when using this object. 6.16.1 Properties Required Common Properties type, id Optional Common Properties spec_version, object_marking_refs, granular_markings, defanged, extensions Not Applicable Common Properties created_by_ref, revoked, labels, confidence, lang, external_references User Account Object Specific Properties user_id, credential, account_login, account_type, display_name, is_service_account, is_privileged, can_escalate_privs, is_disabled, account_created, account_expires, credential_last_changed, account_first_login, account_last_login ID Contributing Properties account_type, user_id, account_login Property Name Type Description type (required) string The value of this property MUST be user-account. extensions (optional) dictionary The User Account object defines the following extensions. In addition to these, producers MAY create their own. unix-account-ext', 'vec_doc-10-oasis-stix21-p162-361', 0, 301, 'v2.1.0', 'ae9928b39b01aedeadd375a883fbfe0b61da6dd232a048e7325fa613c36e245d', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"6.16 User Account Object","subsection":"UNKNOWN","table_id":null,"page":162,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":361,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"6.16 User Account Object"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p163-362', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '6.16 User Account Object', 163, 'Standards Track Work Product 02 April 2025 - Page 163 of 276Copyright © OASIS Open 2025. All Rights Reserved. Dictionary keys MUST use the specification defined name (examples above) or be the id of a STIX Extension object, depending on the type of extension being used. The corresponding dictionary values MUST contain the contents of the extension instance. user_id (optional) string Specifies the identifier of the account. The format of the identifier depends on the system the user account is maintained in, and may be a numeric ID, a GUID, an account name, an email address, etc. The user_id property should be populated with whatever field is the unique identifier for the system the account is a member of. For example, on UNIX systems it would be populated with the UID. credential (optional) string Specifies a cleartext credential.', 'vec_doc-10-oasis-stix21-p163-362', 0, 211, 'v2.1.0', '4362bc9608b9842ad2a64f3a815e5d66b3da680a602de5e45bde3c2302029f4a', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"6.16 User Account Object","subsection":"UNKNOWN","table_id":null,"page":163,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":362,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"6.16 User Account Object"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p163-363', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '6.16 User Account Object', 163, 'This is only intended to be used in capturing metadata from malware analysis (e.g., a hard-coded domain administrator password that the malware attempts to use for lateral movement) and SHOULD NOT be used for sharing of PII. account_login (optional) string Specifies the account login string, used in cases where the user_id property specifies something other than what a user would type when they login. For example, in the case of a Unix account with user_id 0, the account_login might be “root”. account_type (optional) open-vocab Specifies the type of the account. This is an open vocabulary and values SHOULD come from the account-type-ov open vocabulary. display_name (optional) string Specifies the display name of the account, to be shown in user interfaces, if applicable. On Unix, this is equivalent to the GECOS field. is_service_account (optional) boolean Indicates that the account is associated with a network service or system process (daemon), not a specific individual.', 'vec_doc-10-oasis-stix21-p163-363', 0, 247, 'v2.1.0', '32bf3d1da462e1ad396704e1b50f0f02a76ad5e2ab251fd3bd1e274fd1718aa8', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"6.16 User Account Object","subsection":"UNKNOWN","table_id":null,"page":163,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":363,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"6.16 User Account Object"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p163-364', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '6.16 User Account Object', 163, 'is_privileged (optional) boolean Specifies that the account has elevated privileges (i.e., in the case of root on Unix or the Windows Administrator account). can_escalate_privs (optional) boolean Specifies that the account has the ability to escalate privileges (i.e., in the case of sudo on Unix or a Windows Domain Admin account) is_disabled (optional) boolean Specifies if the account is disabled. account_created (optional) timestamp Specifies when the account was created.', 'vec_doc-10-oasis-stix21-p163-364', 0, 120, 'v2.1.0', '0e554fbd67f35693256c31c9b2a7a44334eb6056af0a05eacc6feb35efe6198f', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"6.16 User Account Object","subsection":"UNKNOWN","table_id":null,"page":163,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":364,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"6.16 User Account Object"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p164-365', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '6.16 User Account Object', 164, 'Standards Track Work Product 02 April 2025 - Page 164 of 276Copyright © OASIS Open 2025. All Rights Reserved. account_expires(optional) timestamp Specifies the expiration date of the account. credential_last_changed (optional) timestamp Specifies when the account credential was last changed. account_first_login (optional) timestamp Specifies when the account was first accessed. account_last_login (optional) timestamp Specifies when the account was last accessed. Examples Basic Unix Account { "type": "user-account", "spec_version": "2.1", "id": "user-account--f94d689e-707d-58c3-b803-c720bb6ed096", "user_id": "1001", "account_login": "jdoe", "account_type": "unix", "display_name": "John Doe", "is_service_account": false, "is_privileged": false, "can_escalate_privs": true, "account_created": "2016-01-20T12:31:12Z", "credential_last_changed": "2016-01-20T14:27:43Z", "account_first_login": "2016-01-20T14:26:07Z", "account_last_login": "2016-07-22T16:08:28Z" } Basic Twitter Account { "type": "user-account", "spec_version": "2.1", "id": "user-account--f223e803-846b-591a-aefa-545e938f8a56", "user_id": "thegrugq_ebooks", "account_login": "thegrugq_ebooks", "account_type": "twitter", "display_name": "the grugq" } 6.16.2 UNIX™ Account Extension Type Name: unix-account-ext The UNIX account extension specifies a default extension for capturing the additional information for an account on a UNIX system. The key for this extension when used in the extensions dictionary MUST be unix-account-ext. Note that this predefined extension does not use the extension facility described in', 'vec_doc-10-oasis-stix21-p164-365', 0, 398, 'v2.1.0', '5201ba8d72a4cb170f83c36ede57f10f053b606164c92ba7864c666e657ede40', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"6.16 User Account Object","subsection":"UNKNOWN","table_id":null,"page":164,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":365,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"6.16 User Account Object"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p164-366', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', 'Section 7.3.', 164, 'An object using the UNIX Account Extension MUST contain at least one property from this extension.', 'vec_doc-10-oasis-stix21-p164-366', 0, 25, 'v2.1.0', 'f11fb4591b624b625f33aa5c268fdbc17e29408bc09943c0fcbcc12ce4d27f52', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"Section 7.3.","subsection":"UNKNOWN","table_id":null,"page":164,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":366,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"Section 7.3."}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p165-367', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', 'Section 7.3.', 165, 'Standards Track Work Product 02 April 2025 - Page 165 of 276Copyright © OASIS Open 2025. All Rights Reserved. Properties Property Name Type Description gid (optional) integer Specifies the primary group ID of the account. groups (optional) list of type string Specifies a list of names of groups that the account is a member of. home_dir (optional) string Specifies the home directory of the account. shell (optional) string Specifies the account’s command shell. Example Basic UNIX Account { "type": "user-account", "spec_version": "2.1", "id": "user-account--f94d689e-707d-58c3-b803-c720bb6ed096", "user_id": "1001", "account_login": "jdoe", "account_type": "unix", "display_name": "John Doe", "is_service_account": false, "is_privileged": false, "can_escalate_privs": true, "extensions": { "unix-account-ext": { "gid": 1001, "groups": ["wheel"], "home_dir": "/home/jdoe", "shell": "/bin/bash" } } }', 'vec_doc-10-oasis-stix21-p165-367', 0, 226, 'v2.1.0', '29b1072b2ea121a9a0b102b1eeb4841ae683ee63d2e66a9f07d7697486666d8a', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"Section 7.3.","subsection":"UNKNOWN","table_id":null,"page":165,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":367,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"Section 7.3."}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p165-368', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '6.17 Windows™ Registry Key Object', 165, 'Type Name: windows-registry-key The Registry Key object represents the properties of a Windows registry key. As all properties of this object are optional, at least one of the properties defined below MUST be included when using this object. 6.17.1 Properties Required Common Properties type, id Optional Common Properties spec_version, object_marking_refs, granular_markings, defanged, extensions Not Applicable Common Properties', 'vec_doc-10-oasis-stix21-p165-368', 0, 108, 'v2.1.0', 'b005a2f03e9155330f6e9e602d12af6fccbfd0d69cb6016e6e4adc06a4a59f56', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"6.17 Windows™ Registry Key Object","subsection":"UNKNOWN","table_id":null,"page":165,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":368,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"6.17 Windows™ Registry Key Object"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p166-369', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '6.17 Windows™ Registry Key Object', 166, 'Standards Track Work Product 02 April 2025 - Page 166 of 276Copyright © OASIS Open 2025. All Rights Reserved. created_by_ref, revoked, labels, confidence, lang, external_references WindowsTM Registry Key Object Specific Properties key, values, modified_time, creator_user_ref, number_of_subkeys ID Contributing Properties key, values (all items defined in the values property MUST be included) Property Name Type Description type (required) string The value of this property MUST be windows-registry-key. key (optional) string Specifies the full registry key including the hive. values (optional) list of type windows-registry-value-type Specifies the values found under the registry key. The value of the key, including the hive portion, SHOULD be case- preserved. The hive portion of the key MUST be fully expanded and not truncated; e.g., HKEY_LOCAL_MACHINE must be used instead of HKLM. modified_time (optional) timestamp Specifies the last date/time that the registry key was modified. creator_user_ref (optional) identifier Specifies a reference to the user account that created the registry key. The object referenced in this property MUST be of type user- account. number_of_subkeys (optional) integer Specifies the number of subkeys contained under the registry key. 6.17.2 Windows™ Registry Value Type Type Name: windows-registry-value-type The Windows Registry Value type captures the properties of a Windows Registry Key Value. As all properties of this type are optional, at least one of the properties defined below MUST be included when using this type. Properties Property Name Type Description', 'vec_doc-10-oasis-stix21-p166-369', 0, 403, 'v2.1.0', 'c21caeeef179993e80097830b836a2c16555f397c4828c4466ff5abee211adac', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"6.17 Windows™ Registry Key Object","subsection":"UNKNOWN","table_id":null,"page":166,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":369,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"6.17 Windows™ Registry Key Object"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p167-370', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '6.17 Windows™ Registry Key Object', 167, 'Standards Track Work Product 02 April 2025 - Page 167 of 276Copyright © OASIS Open 2025. All Rights Reserved. name (optional) string Specifies the name of the registry value. For specifying the default valuein a registry key, an empty string MUST be used. data (optional) string Specifies the data contained in the registry value. data_type (optional) enum Specifies the registry (REG_*) data type used in the registry value. The values of this property MUST come from the windows-registry- datatype-enum enumeration. Examples Simple registry key { "type": "windows-registry-key", "spec_version": "2.1", "id": "windows-registry-key--1884b770-b679-522a-a9c7-45fadaaec7bb", "key": "HKEY_LOCAL_MACHINE\\System\\Foo\\Bar" } Registry key with values { "type": "windows-registry-key", "spec_version": "2.1", "id": "windows-registry-key--f6a11ddf-fa2b-54c8-97ab-e7f28413095a", "key": "hkey_local_machine\\system\\bar\\foo", "values": [ { "name": "Foo", "data": "qwerty", "data_type": "REG_SZ" }, { "name": "Bar", "data": "42", "data_type": "REG_DWORD" } ] }', 'vec_doc-10-oasis-stix21-p167-370', 0, 263, 'v2.1.0', '12d0491b694e64eb48cb632792b434d32deb2b87d2eb4b877eeca3caf08b41ed', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"6.17 Windows™ Registry Key Object","subsection":"UNKNOWN","table_id":null,"page":167,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":370,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"6.17 Windows™ Registry Key Object"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p167-371', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '6.18 X.509 Certificate Object', 167, 'Type Name: x509-certificate The X.509 Certificate object represents the properties of an X.509 certificate, as defined by ITU recommendation X.509 [X509]. An X.509 Certificate object MUST contain at least one object specific property (other than type) from this object. 6.18.1 Properties Required Common Properties type, id', 'vec_doc-10-oasis-stix21-p167-371', 0, 81, 'v2.1.0', '20134c5fd5bb8ea7614ae8abea0b10761df49f651ab99c6d719bd0323cf87234', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"6.18 X.509 Certificate Object","subsection":"UNKNOWN","table_id":null,"page":167,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":371,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"6.18 X.509 Certificate Object"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p168-372', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '6.18 X.509 Certificate Object', 168, 'Standards Track Work Product 02 April 2025 - Page 168 of 276Copyright © OASIS Open 2025. All Rights Reserved. Optional Common Properties spec_version, object_marking_refs, granular_markings, defanged, extensions Not Applicable Common Properties created_by_ref, revoked, labels, confidence, lang, external_references X.509 Certificate Object Specific Properties is_self_signed, hashes, version, serial_number, signature_algorithm, issuer, validity_not_before, validity_not_after, subject, subject_public_key_algorithm, subject_public_key_modulus, subject_public_key_exponent, x509_v3_extensions ID Contributing Properties hashes, serial_number If the hashes property is present, include only one hash. The selected hash SHOULD come from this ordered list (based on the following order of preference) [ MD5, SHA-1, SHA-256, SHA-512 ]. Property Name Type Description type (required) string The value of this property MUST be x509- certificate. is_self_signed (optional) boolean Specifies whether the certificate is self-signed, i.e., whether it is signed by the same entity whose identity it certifies. hashes (optional) hashes Specifies any hashes that were calculated for the entire contents of the certificate. Dictionary keys MUST come from the hash-algorithm- ov open vocabulary. version (optional) string Specifies the version of the encoded certificate. serial_number (optional) string Specifies the unique identifier for the certificate, as issued by a specific Certificate Authority. signature_algorithm (optional) string Specifies the name of the algorithm used to sign the certificate. issuer (optional) string Specifies the name of the Certificate Authority that issued the certificate.', 'vec_doc-10-oasis-stix21-p168-372', 0, 424, 'v2.1.0', 'f7134ebfe9a3bf3749eb55dbf915907a2e56a06817e0580dbfd217912ec44f03', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"6.18 X.509 Certificate Object","subsection":"UNKNOWN","table_id":null,"page":168,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":372,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"6.18 X.509 Certificate Object"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p169-373', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '6.18 X.509 Certificate Object', 169, 'Standards Track Work Product 02 April 2025 - Page 169 of 276Copyright © OASIS Open 2025. All Rights Reserved. validity_not_before (optional) timestamp Specifies the date on which thecertificate validity period begins. validity_not_after (optional) timestamp Specifies the date on which the certificate validity period ends. subject (optional) string Specifies the name of the entity associated with the public key stored in the subject public key field of the certificate. subject_public_key_algorithm (optional) string Specifies the name of the algorithm with which to encrypt data being sent to the subject. subject_public_key_modulus (optional) string Specifies the modulus portion of the subject’s public RSA key. subject_public_key_exponent (optional) integer Specifies the exponent portion of the subject’s public RSA key, as an integer. x509_v3_extensions (optional) x509-v3-extensions-type Specifies any standard X.509 v3 extensions that may be used in the certificate.', 'vec_doc-10-oasis-stix21-p169-373', 0, 245, 'v2.1.0', '4641c0bd1cfd617250d890ac4fe7a3f14e08860f2b376643ec8973f5a6bebf9c', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"6.18 X.509 Certificate Object","subsection":"UNKNOWN","table_id":null,"page":169,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":373,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"6.18 X.509 Certificate Object"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p169-374', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '6.18 X.509 Certificate Object', 169, '6.18.2 X.509 v3 Extensions Type Type Name: x509-v3-extensions-type The X.509 v3 Extensions type captures properties associated with X.509 v3 extensions, which serve as a mechanism for specifying additional information such as alternative subject names. An object using the X.509 v3 Extensions type MUST contain at least one property from this type. Note that the use of the term “extensions” in this context refers to the X.509 v3 Extensions type and is not a STIX Cyber Observables extension. Therefore, it is a type that describes X.509 extensions. Properties Property Name Type Description basic_constraints (optional) string Specifies a multi-valued extension which indicates whether a certificate is a CA certificate. The first (mandatory) name is CA followed by TRUE or FALSE. If CA is TRUE, then an optional pathlen name followed by a non-negative value can be included. Also equivalent to the object ID (OID) value of 2.5.29.19.', 'vec_doc-10-oasis-stix21-p169-374', 0, 234, 'v2.1.0', '04363ff5f1c998f320fa348c6914b4216c05cd83f6498ca34aeb4e9371deb7be', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"6.18 X.509 Certificate Object","subsection":"UNKNOWN","table_id":null,"page":169,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":374,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"6.18 X.509 Certificate Object"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p169-375', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '6.18 X.509 Certificate Object', 169, 'name_constraints (optional) string Specifies a namespace within which all subject names in subsequent certificates in a certification path MUST be located. Also equivalent to the object ID (OID) value of 2.5.29.30.', 'vec_doc-10-oasis-stix21-p169-375', 0, 54, 'v2.1.0', '506c4493120b6bc39c9634512812a46057449006382c956b12e9358d0baafd3d', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"6.18 X.509 Certificate Object","subsection":"UNKNOWN","table_id":null,"page":169,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":375,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"6.18 X.509 Certificate Object"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p170-376', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '6.18 X.509 Certificate Object', 170, 'Standards Track Work Product 02 April 2025 - Page 170 of 276Copyright © OASIS Open 2025. All Rights Reserved. policy_constraints (optional) string Specifies any constraints on pathvalidation for certificates issued to CAs. Also equivalent to the object ID (OID) value of 2.5.29.36. key_usage (optional) string Specifies a multi-valued extension consisting of a list of names of the permitted key usages. Also equivalent to the object ID (OID) value of 2.5.29.15. extended_key_usage (optional) string Specifies a list of usages indicating purposes for which the certificate public key can be used for. Also equivalent to the object ID (OID) value of 2.5.29.37. subject_key_identifier (optional) string Specifies the identifier that provides a means of identifying certificates that contain a particular public key. Also equivalent to the object ID (OID) value of 2.5.29.14.', 'vec_doc-10-oasis-stix21-p170-376', 0, 218, 'v2.1.0', 'c17c885c90b0e72ae2970e6ed782d82a83f6512d682963df9b812c87505aece2', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"6.18 X.509 Certificate Object","subsection":"UNKNOWN","table_id":null,"page":170,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":376,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"6.18 X.509 Certificate Object"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p170-377', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '6.18 X.509 Certificate Object', 170, 'authority_key_identifier (optional) string Specifies the identifier that provides a means of identifying the public key corresponding to the private key used to sign a certificate. Also equivalent to the object ID (OID) value of 2.5.29.35. subject_alternative_name (optional) string Specifies the additional identities to be bound to the subject of the certificate. Also equivalent to the object ID (OID) value of 2.5.29.17. issuer_alternative_name (optional) string Specifies the additional identities to be bound to the issuer of the certificate. Also equivalent to the object ID (OID) value of 2.5.29.18. subject_directory_attributes (optional) string Specifies the identification attributes (e.g., nationality) of the subject. Also equivalent to the object ID (OID) value of 2.5.29.9. crl_distribution_points (optional) string Specifies how CRL information is obtained. Also equivalent to the object ID (OID) value of 2.5.29.31.', 'vec_doc-10-oasis-stix21-p170-377', 0, 233, 'v2.1.0', 'c90fd70e8d53c4d6c17c26b390e4e610fb8dd4adab33db906a1ad64834c17000', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"6.18 X.509 Certificate Object","subsection":"UNKNOWN","table_id":null,"page":170,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":377,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"6.18 X.509 Certificate Object"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p170-378', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '6.18 X.509 Certificate Object', 170, 'inhibit_any_policy (optional) string Specifies the number of additional certificates that may appear in the path before anyPolicy is no longer permitted. Also equivalent to the object ID (OID) value of 2.5.29.54. private_key_usage_period_not_before (optional) timestamp Specifies the date on which the validity period begins for the private key, if it is different from the validity period of the certificate.', 'vec_doc-10-oasis-stix21-p170-378', 0, 103, 'v2.1.0', 'c9fcc5f1dcb8f516e7a2e526f2d96867f2827b528cda5095411265b721d7c988', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"6.18 X.509 Certificate Object","subsection":"UNKNOWN","table_id":null,"page":170,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":378,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"6.18 X.509 Certificate Object"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p171-379', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '6.18 X.509 Certificate Object', 171, 'Standards Track Work Product 02 April 2025 - Page 171 of 276Copyright © OASIS Open 2025. All Rights Reserved. private_key_usage_period_not_after(optional) timestamp Specifies the date on which the validityperiod ends for the private key, if it is different from the validity period of the certificate. certificate_policies (optional) string Specifies a sequence of one or more policy information terms, each of which consists of an object identifier (OID) and optional qualifiers. Also equivalent to the object ID (OID) value of 2.5.29.32. policy_mappings (optional) string Specifies one or more pairs of OIDs; each pair includes an issuerDomainPolicy and a subjectDomainPolicy. The pairing indicates whether the issuing CA considers its issuerDomainPolicy equivalent to the subject CA’s subjectDomainPolicy. Also equivalent to the object ID (OID) value of 2.5.29.33.', 'vec_doc-10-oasis-stix21-p171-379', 0, 217, 'v2.1.0', '1f46b85706836655278691c28c5fc9e824254b84e91ed9c47cf42318011cae1f', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"6.18 X.509 Certificate Object","subsection":"UNKNOWN","table_id":null,"page":171,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":379,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"6.18 X.509 Certificate Object"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p171-380', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '6.18 X.509 Certificate Object', 171, 'Examples Basic X.509 certificate { "type": "x509-certificate", "spec_version": "2.1", "id": "x509-certificate--bf86f034-2390-54d7-8426-d08433db3fbe", "issuer": "C=ZA, ST=Western Cape, L=Cape Town, O=Thawte Consulting cc, OU=Certification Services Division, CN=Thawte Server CA/emailAddress=server-certs@thawte.com", "validity_not_before": "2016-03-12T12:00:00Z", "validity_not_after": "2016-08-21T12:00:00Z", "subject": "C=US, ST=Maryland, L=Pasadena, O=Brent Baccala, OU=FreeSoft, CN=www.freesoft.org/emailAddress=baccala@freesoft.org", "serial_number": "36:f7:d4:32:f4:ab:70:ea:d3:ce:98:6e:ea:99:93:49:32:0a:b7:06" } X.509 Certificate w/ V3 Extensions { "type":"x509-certificate", "spec_version": "2.1", "id": "x509-certificate--5adb038a-160d-5d1c-826e-bde4926a0d2d", "issuer":"C=ZA, ST=Western Cape, L=Cape Town, O=Thawte Consulting cc, OU=Certification Services Division, CN=Thawte Server CA/emailAddress=server-certs@thawte.com", "validity_not_before":"2016-03-12T12:00:00Z", "validity_not_after":"2016-08-21T12:00:00Z", "subject":"C=US, ST=Maryland, L=Pasadena, O=Brent Baccala, OU=FreeSoft, CN=www.freesoft.org/emailAddress=baccala@freesoft.org", "serial_number": "02:08:87:83:f2:13:58:1f:79:52:1e:66:90:0a:02:24:c9:6b:c7:dc", "x509_v3_extensions":{ "basic_constraints":"critical,CA:TRUE, pathlen:0", "name_constraints":"permitted;IP:192.168.0.0/255.255.0.0", "policy_constraints":"requireExplicitPolicy:3", "key_usage":"critical, keyCertSign", "extended_key_usage":"critical,codeSigning,1.2.3.4", "subject_key_identifier":"hash",', 'vec_doc-10-oasis-stix21-p171-380', 0, 385, 'v2.1.0', 'd941c666db4f0b20a224c8615bb7b1d14ecd2547c0ac51af74253cba9473e4bb', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"6.18 X.509 Certificate Object","subsection":"UNKNOWN","table_id":null,"page":171,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":380,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"6.18 X.509 Certificate Object"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p172-381', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '6.18 X.509 Certificate Object', 172, 'Standards Track Work Product 02 April 2025 - Page 172 of 276Copyright © OASIS Open 2025. All Rights Reserved. "authority_key_identifier":"keyid,issuer", "subject_alternative_name":"email:my@other.address,RID:1.2.3.4", "issuer_alternative_name":"issuer:copy", "crl_distribution_points":"URI:http://myhost.com/myca.crl", "inhibit_any_policy":"2", "private_key_usage_period_not_before":"2016-03-12T12:00:00Z", "private_key_usage_period_not_after":"2018-03-12T12:00:00Z", "certificate_policies":"1.2.4.5, 1.1.3.4" } }', 'vec_doc-10-oasis-stix21-p172-381', 0, 129, 'v2.1.0', 'e4bdd3b7e5ef11a2c2b50fe85c7feb27f716faf3ba47243e2e94dd14aa402563', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"6.18 X.509 Certificate Object","subsection":"UNKNOWN","table_id":null,"page":172,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":381,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"6.18 X.509 Certificate Object"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p173-382', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '7.1 Language Content', 173, 'The Language Content object represents text content for STIX Objects represented in languages other than that of the original object. Language content may be a translation of the original object by a third- party, a first-source translation by the original publisher, or additional official language content provided at the time of creation. Language Content contains two important sets of properties: - The object_ref and object_modified properties specify the target object that the language content applies to. - For example, to provide additional language content for a Campaign, the object_ref property should be set to the id of the Campaign and the object_modified property set to its modified time. Most relationships in STIX are not specific to a particular version of a STIX object, but because language content provides the translation of specific text, the object_modified property is necessary to provide that specificity.', 'vec_doc-10-oasis-stix21-p173-382', 0, 234, 'v2.1.0', 'be07991c1c6060a74b192f859606318eef2a872348516d27f3247aa75c4edd3b', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"7.1 Language Content","subsection":"UNKNOWN","table_id":null,"page":173,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":382,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"7.1 Language Content"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p173-383', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '7.1 Language Content', 173, '- The content property is a dictionary which maps to properties in the target object in order to provide a translation of them. 7.1.1 Properties Required Common Properties type, spec_version, id, created, modified Optional Common Properties created_by_ref, revoked, labels, confidence, external_references, object_marking_refs,granular_marking_refs, extensions Not Applicable Common Properties lang, defanged Language Content Specific Properties object_ref, object_modified, contents Property Name Type Description type (required) string The type property identifies the type of object. The value of this property MUST be language-content. object_ref (required) identifier The object_ref property identifies the id of the object that this Language Content applies to. It MUST be the identifier for a STIX Object. object_modified (optional) timestamp The object_modified property identifies the modified time of the object that this Language Content applies to.', 'vec_doc-10-oasis-stix21-p173-383', 0, 240, 'v2.1.0', '734f5b122c173256e91ffd6e90c358a827f09059c97ca55bac6a51ae8ee9ea47', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"7.1 Language Content","subsection":"UNKNOWN","table_id":null,"page":173,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":383,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"7.1 Language Content"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p173-384', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '7.1 Language Content', 173, 'It MUST be an exact match for the modified time of the STIX Object being referenced. contents (required) dictionary The contents property contains the actual Language Content (translation). The keys in the dictionary MUST be RFC 5646 language codes for which language content is being provided [RFC5646]. The', 'vec_doc-10-oasis-stix21-p173-384', 0, 77, 'v2.1.0', '02dc668e784e6e1c9e42ed1d9e430b7645bc711ba3acea61656b3539f4952f6e', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"7.1 Language Content","subsection":"UNKNOWN","table_id":null,"page":173,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":384,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"7.1 Language Content"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p174-385', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '7.1 Language Content', 174, 'Standards Track Work Product 02 April 2025 - Page 174 of 276Copyright © OASIS Open 2025. All Rights Reserved. values each consist of a dictionary that mirrors the properties in the target object (identified by object_ref and object_modified). For example, to provide a translation of the name property on the target object the key in the dictionary would be name. For each key in the nested dictionary: If the original property is a string, the corresponding property in the language content object MUST contain a string with the content for that property in the language of the top-level key. If the original property is a list, the corresponding property in the translation object must also be a list. Each item in this list recursively maps to the item at the same position in the list contained in the target object. The lists MUST have the same length. In the event that translations are only provided for some list items, the untranslated list items MUST be represented by an empty string (““).', 'vec_doc-10-oasis-stix21-p174-385', 0, 250, 'v2.1.0', '7c441438224a255c0dd059819d84f792428ab153d826d523b87f64f197cbc328', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"7.1 Language Content","subsection":"UNKNOWN","table_id":null,"page":174,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":385,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"7.1 Language Content"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p174-386', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '7.1 Language Content', 174, 'This indicates to a consumer of the Language Content object that they should interpolate the translated list items in the Language Content object with the corresponding (untranslated) list items from the original object as indicated by the object_ref property. If the original property is an object (including dictionaries), the corresponding location in the translation object must also be an object. Each key/value field in this object recursively maps to the object with the same key in the original. The translation object MAY contain only a subset of the translatable fields of the original. Keys that point to non- translatable properties in the target or to properties that do not exist in the target object MUST be ignored. 7.1.2 Relationships There are no relationships explicitly defined between the Language Content object and other STIX Objects, other than the embedded relationships listed below. These embedded relationships are listed by property name along with their corresponding target.', 'vec_doc-10-oasis-stix21-p174-386', 0, 252, 'v2.1.0', '010a1faa73b9d22819fb1543eb20e1de8fdf8c8683fa73d8c2d912a7b8e31c8f', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"7.1 Language Content","subsection":"UNKNOWN","table_id":null,"page":174,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":386,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"7.1 Language Content"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p174-387', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '7.1 Language Content', 174, 'Note that the object_ref relationship has a companion property, object_modified, that identifies the version of the object that the language content is being provided for. Embedded Relationships created_by_ref identifier (of type identity) object_marking_refs list of type identifier (of type marking- definition) object_ref identifier (of type STIX Object) Examples Translation of a campaign', 'vec_doc-10-oasis-stix21-p174-387', 0, 98, 'v2.1.0', '66233c7e5b910823aef2801a23fa091cf9011e4e6bfa3675a7c4839dc36c9ba5', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"7.1 Language Content","subsection":"UNKNOWN","table_id":null,"page":174,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":387,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"7.1 Language Content"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p175-388', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '7.1 Language Content', 175, 'Standards Track Work Product 02 April 2025 - Page 175 of 276Copyright © OASIS Open 2025. All Rights Reserved. [ { "type": "campaign", "id": "campaign--12a111f0-b824-4baf-a224-83b80237a094", "lang": "en", "spec_version": "2.1", "created": "2017-02-08T21:31:22.007Z", "modified": "2017-02-08T21:31:22.007Z", "name": "Bank Attack", "description": "More information about bank attack" }, { "type": "language-content", "id": "language-content--b86bd89f-98bb-4fa9-8cb2-9ad421da981d", "spec_version": "2.1", "created": "2017-02-08T21:31:22.007Z", "modified": "2017-02-08T21:31:22.007Z", "object_ref": "campaign--12a111f0-b824-4baf-a224-83b80237a094", "object_modified": "2017-02-08T21:31:22.007Z", "contents": { "de": { "name": "Bank Angriff", "description": "Weitere Informationen über Banküberfall" }, "fr": { "name": "Attaque Bank", "description": "Plus d''informations sur la crise bancaire" } } } ] The threat actor defined here, is from the example in section4.17 { "type": "language-content", "id": "language-content--0911f616-727f-48cb-a4c5-9420299562a4", "spec_version": "2.1", "created": "2019-06-08T21:31:22.007Z", "modified": "2019-07-08T21:31:22.007Z", "object_ref": "threat-actor--8e2e2d2b-17d4-4cbf-938f-98ee46b3cd3f", "contents": { "de": { "goals": ["Bankgeld stehlen", "Kreditkarten stehlen"] }, "fr": { "goals": ["Voler de l''argent en banque", ""] } } }', 'vec_doc-10-oasis-stix21-p175-388', 0, 341, 'v2.1.0', 'ac87a81125dcb4b9541969cb46e53defe6bf63490b9364ce344a169ddd230169', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"7.1 Language Content","subsection":"UNKNOWN","table_id":null,"page":175,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":388,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"7.1 Language Content"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p175-389', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '7.2 Data Markings', 175, 'Data markings represent restrictions, permissions, and other guidance for how data can be used and shared. For example, data may be shared with the restriction that it must not be re-shared, or that it must be encrypted at rest. In STIX, data markings are specified using the marking-definition object. These definitions are applied to complete STIX Objects using object markings and to individual properties of STIX Objects via granular markings. Multiple markings can be added to the same object, including both object and granular markings. Some types of marking definitions or trust groups have rules about which markings override other markings or', 'vec_doc-10-oasis-stix21-p175-389', 0, 163, 'v2.1.0', 'a66500d2e6d2f5d1319295f846650c4db736a19a48aadce786262b8c21b09f7d', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"7.2 Data Markings","subsection":"UNKNOWN","table_id":null,"page":175,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":389,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"7.2 Data Markings"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p176-390', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '7.2 Data Markings', 176, 'Standards Track Work Product 02 April 2025 - Page 176 of 276Copyright © OASIS Open 2025. All Rights Reserved. which markings can be additive to other markings. This specification does not define rules for how multiple markings applied to the same object or property should be interpreted. Granular data markings are also used to mark individual fields on an object with which language their text content is in. For example, granular markings can be used to indicate that while the rest of the object is in English, the description field is in Japanese. This mechanism does not use the marking-definition object to represent language, rather a separate lang field that can also be applied via granular markings. 7.2.1 Marking Definition Type Name: marking-definition The marking-definition object represents a specific marking.', 'vec_doc-10-oasis-stix21-p176-390', 0, 207, 'v2.1.0', '84497522275b198e17394e26760d8384314a46f536416edce67ac4f27913485a', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"7.2 Data Markings","subsection":"UNKNOWN","table_id":null,"page":176,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":390,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"7.2 Data Markings"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p176-391', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '7.2 Data Markings', 176, 'Data markings typically represent handling or sharing requirements for data and are applied in the object_marking_refs and granular_markings properties on STIX Objects, which reference a list of IDs for marking-definition objects. Two marking definition types are defined in this specification: TLP, to capture TLP markings, and Statement, to capture text marking statements. In addition, it is expected that the FIRST Information Exchange Policy (IEP) will be included in a future version once a machine-usable specification for it has been defined. Unlike other STIX Objects, Marking Definition objects cannot be versioned because it would allow for indirect changes to the markings on a STIX Object. For example, if a Statement marking is changed from “Reuse Allowed” to “Reuse Prohibited”, all STIX Objects marked with that Statement marking would effectively have an updated marking without being updated themselves.', 'vec_doc-10-oasis-stix21-p176-391', 0, 231, 'v2.1.0', 'cb54b7e4d4a1e8af4f0ce8b9512253ef46f4233a89f2a857d4cf15861b5f775e', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"7.2 Data Markings","subsection":"UNKNOWN","table_id":null,"page":176,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":391,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"7.2 Data Markings"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p176-392', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '7.2 Data Markings', 176, 'Instead, a new Statement marking with the new text should be created and the marked objects updated to point to the new marking. The JSON MTI serialization uses the JSON Object type [RFC8259] when representing marking- definition. Properties Required Common Properties type, spec_version, id, created Optional Common Properties created_by_ref, external_references, object_marking_refs, granular_marking_refs, extensions Not Applicable Common Properties modified, revoked, labels, confidence, lang, defanged Marking Definition Specific Properties name, definition_type, definition Property Name Type Description type (required) string The type property identifies the type of object. The value of this property MUST be marking-definition. name (optional) string A name used to identify the Marking Definition. definition_type (optional - open-vocab The definition_type property identifies the type of Marking Definition. The value of the definition_type', 'vec_doc-10-oasis-stix21-p176-392', 0, 238, 'v2.1.0', 'f394e7665f1a02b92f2e7cfe82fb3aa5a67cb5200e3f68cefedda38947a39ba1', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"7.2 Data Markings","subsection":"UNKNOWN","table_id":null,"page":176,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":392,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"7.2 Data Markings"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p177-393', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '7.2 Data Markings', 177, 'Standards Track Work Product 02 April 2025 - Page 177 of 276Copyright © OASIS Open 2025. All Rights Reserved. deprecated) property SHOULD be one of the types defined in the subsections below: statement or tlp (see section 7.2.1.3 and section 7.2.1.4). Any new marking definitions SHOULD be specified using the extension facility described in section 7.3. If the extensions property is not present, this property MUST be present. definition (optional - deprecated) <marking object> The definition property contains the marking object itself (e.g., the TLP marking as defined in section 7.2.1.4, the Statement marking as defined in section 7.2.1.3). Any new marking definitions SHOULD be specified using the extension facility described in section 7.3. If the extensions property is not present, this property MUST be present. Relationships There are no relationships explicitly defined between the Marking Definition object and other STIX Objects, other than the embedded relationships listed below.', 'vec_doc-10-oasis-stix21-p177-393', 0, 250, 'v2.1.0', 'acb4b970288689b6754982576c3e883c6b9c2a4497b64859903c7feaaea7fb85', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"7.2 Data Markings","subsection":"UNKNOWN","table_id":null,"page":177,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":393,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"7.2 Data Markings"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p177-394', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '7.2 Data Markings', 177, 'These embedded relationships are listed by property name along with their corresponding target. Embedded Relationships created_by_ref identifier (of type identity) object_marking_refs list of type identifier (of type marking- definition) Statement Marking Object Type The Statement marking type defines the representation of a textual marking statement (e.g., copyright, terms of use, etc.) in a definition. The value of the definition_type property MUST be statement when using this marking type. Statement markings are generally not machine-readable, and this specification does not define any behavior or actions based on their values. Content may be marked with multiple statements of use. In other words, the same content can be marked both with a statement saying “Copyright 2019” and a statement saying, “Terms of use are … ” and both statements apply.', 'vec_doc-10-oasis-stix21-p177-394', 0, 215, 'v2.1.0', '8c443315ef58f7fb5c1cbe22f5b04f16142c33af9cb4733296484508bb1a3755', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"7.2 Data Markings","subsection":"UNKNOWN","table_id":null,"page":177,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":394,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"7.2 Data Markings"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p177-395', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '7.2 Data Markings', 177, 'Property Name Type Description statement (required) string A Statement (e.g., copyright, terms of use) applied to the content marked by this marking definition. Example { "type": "marking-definition", "spec_version": "2.1", "id": "marking-definition--4a0042fe-8b88-40fe-9600-dfa128ce6fbd", "created": "2016-08-01T00:00:00.000Z", "definition_type": "statement",', 'vec_doc-10-oasis-stix21-p177-395', 0, 90, 'v2.1.0', '9df06e543bd74caef4f81bfb12bfb9faedc4cec7cd9c44ae1d10b811eea7d97a', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"7.2 Data Markings","subsection":"UNKNOWN","table_id":null,"page":177,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":395,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"7.2 Data Markings"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p178-396', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '7.2 Data Markings', 178, 'Standards Track Work Product 02 April 2025 - Page 178 of 276Copyright © OASIS Open 2025. All Rights Reserved. "definition": { "statement": "Copyright 2019, Example Corp" } } TLP Marking Object Type The TLP marking type defines how you would represent a Traffic Light Protocol (TLP) marking in a definition property. The value of the definition_type property MUST be tlp when using this marking type. Property Name Type Description tlp (required) string The TLP level [TLP] of the content marked by this marking definition, as defined in this section. The following standard marking definitions MUST be used to reference or represent TLP markings. Other instances of tlp-marking MUST NOT be used or created (the only instances of TLP marking definitions permitted are those defined here). white { "type": "marking-definition", "spec_version": "2.1", "id": "marking-definition--613f2e26-407d-48c7-9eca-b8e91df99dc9", "created": "2017-01-20T00:00:00.000Z", "definition_type": "tlp", "name": "TLP:WHITE", "definition": { "tlp": "white" } } green { "type": "marking-definition", "spec_version": "2.1", "id": "marking-definition--34098fce-860f-48ae-8e50-ebd3cc5e41da", "created": "2017-01-20T00:00:00.000Z", "definition_type": "tlp", "name": "TLP:GREEN", "definition": { "tlp": "green" } } amber { "type": "marking-definition", "spec_version": "2.1", "id": "marking-definition--f88d31f6-486f-44da-b317-01333bde0b82", "created": "2017-01-20T00:00:00.000Z", "definition_type": "tlp", "name": "TLP:AMBER", "definition": { "tlp": "amber" } }', 'vec_doc-10-oasis-stix21-p178-396', 0, 383, 'v2.1.0', '88411b6c4853d0fd1eb900583c7126c51a9c5806d60899df3d5b438c63e8b765', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"7.2 Data Markings","subsection":"UNKNOWN","table_id":null,"page":178,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":396,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"7.2 Data Markings"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p179-397', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '7.2 Data Markings', 179, 'Standards Track Work Product 02 April 2025 - Page 179 of 276Copyright © OASIS Open 2025. All Rights Reserved. red { "type": "marking-definition", "spec_version": "2.1", "id": "marking-definition--5e57c739-391a-4eb3-b6be-7d15ca92d5ed", "created": "2017-01-20T00:00:00.000Z", "definition_type": "tlp", "name": "TLP:RED", "definition": { "tlp": "red" } } 7.2.2 Object Markings Object Markings apply data markings to an entire STIX Object and all of its contents. Object Markings are specified as embedded relationships in the object_marking_refs property, which is an optional list of IDs for Marking Definition objects. The referenced markings apply to that STIX Object or Marking Definition and all of its contents. Changes to the object_marking_refs property (and therefore the markings applied to the object) are treated the same as changes to any other properties on the object and follow the same rules for versioning.', 'vec_doc-10-oasis-stix21-p179-397', 0, 231, 'v2.1.0', '684d4497c8495bbeeb31fae6f168fb60d0c38217920b43a524e8d20d48fcfb19', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"7.2 Data Markings","subsection":"UNKNOWN","table_id":null,"page":179,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":397,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"7.2 Data Markings"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p179-398', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '7.2 Data Markings', 179, 'Example This example marks the Indicator and all its properties with the Marking Definition referenced by the ID. { "type": "indicator", "spec_version": "2.1", "id": "indicator--b346b4b3-f4b7-4235-b659-f985f65f0009", ... "object_marking_refs": ["marking-definition--34098fce-860f-48ae-8e50-ebd3cc5e41da"], ... } 7.2.3 Granular Markings Whereas object markings apply to an entire STIX Object or Marking Definition and all its properties, granular markings allow both data markings and language markings to be applied to individual portions of STIX Objects and Marking Definitions. Granular markings are specified in the granular_markings property, which is a list of granular-marking instances. Each of those instances contains a list of selectors to indicate what is marked and either a reference to the marking-definition object to be applied or a language code to be applied.', 'vec_doc-10-oasis-stix21-p179-398', 0, 220, 'v2.1.0', 'bf4cc07dd5b1f239c335d638ec53cac8e1767d53290ee2a8767554bd4cf7c573', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"7.2 Data Markings","subsection":"UNKNOWN","table_id":null,"page":179,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":398,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"7.2 Data Markings"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p179-399', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '7.2 Data Markings', 179, 'Granular markings can be used, for example, to indicate that the name property of an indicator should be handled as TLP:GREEN, the description property as TLP:AMBER, and the pattern property as TLP:RED. The granular_markings property can also be used for language markings. To support applying both data markings and language markings to an object, the granular-marking type has a choice of two properties in addition to the selector: the lang property is used to apply language markings, and the marking_ref property is used to apply data markings. Because each granular marking instance applies to either a language or a marking, one and only one of these properties MUST be present on each instance of a granular marking. Granular Marking Type The granular-marking type defines how the marking-definition object referenced by the marking_ref property or a language specified by the lang property applies to a set of content identified by the list of selectors in the selectors property.', 'vec_doc-10-oasis-stix21-p179-399', 0, 248, 'v2.1.0', '15102f2ec2e6734336b7fe2d04fea9226112e95a6c00c7666031bc23acd869ee', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"7.2 Data Markings","subsection":"UNKNOWN","table_id":null,"page":179,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":399,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"7.2 Data Markings"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p180-400', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '7.2 Data Markings', 180, 'Standards Track Work Product 02 April 2025 - Page 180 of 276Copyright © OASIS Open 2025. All Rights Reserved. Property Name Type Description lang (optional) string The lang property identifies the language of the text identified by this marking. The value of the lang property, if present, MUST be an RFC5646 language code. If the marking_ref property is not present, this property MUST be present. If the marking_ref property is present, this property MUST NOT be present. marking_ref (optional) identifier The marking_ref property specifies the ID of the marking-definition object that describes the marking. If the lang property is not present, this property MUST be present. If the lang property is present, this property MUST NOT be present. selectors (required) list of type string The selectors property specifies a list of selectors for content contained within the STIX Object in which this property appears. Selectors MUST conform to the syntax defined below.', 'vec_doc-10-oasis-stix21-p180-400', 0, 243, 'v2.1.0', '19e62bc533a258187d8c97244ffe4d38c471158261f15642108e62d777a18f9f', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"7.2 Data Markings","subsection":"UNKNOWN","table_id":null,"page":180,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":400,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"7.2 Data Markings"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p180-401', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '7.2 Data Markings', 180, 'The marking-definition referenced in the marking_ref property is applied to the content selected by the selectors in this list. The RFC5646 language code specified by the lang property is applied to the content selected by the selectors in this list. Selector Syntax Selectors contained in the selectors list are strings that consist of multiple components that MUST be separated by the . character. Each component MUST be one of: - A property name or dictionary key, e.g., description, or; - A zero-based list index, specified as a non-negative integer in square brackets, e.g., [4] Selectors denote path traversals: the root of each selector is the STIX Object that the granular_markings property appears in. Starting from that root, for each component in the selector, properties and list items are traversed. When the complete list has been traversed, the value of the content is considered selected. Selectors MUST refer to properties or list items that are actually present on the marked object.', 'vec_doc-10-oasis-stix21-p180-401', 0, 251, 'v2.1.0', 'af05f6bb415886a81c51141c741e61afcb8b5d20ccb48ecc11f8497d39400bee', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"7.2 Data Markings","subsection":"UNKNOWN","table_id":null,"page":180,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":401,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"7.2 Data Markings"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p180-402', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '7.2 Data Markings', 180, 'As an example, consider the following STIX Object: { "id": "vulnerability--ee916c28-c7a4-4d0d-ad56-a8d357f89fef", "spec_version": "2.1", "created": "2016-02-14T00:00:00.000Z", "modified": "2016-02-14T00:00:00.000Z", "type": "vulnerability", "name": "CVE-2014-0160", "description": "The (1) TLS...", "external_references": [ { "source_name": "cve", "external_id": "CVE-2014-0160"', 'vec_doc-10-oasis-stix21-p180-402', 0, 95, 'v2.1.0', 'aac084a3539fa1568fabb506b3917b739f5e68dd4e42989f1bd714d302088289', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"7.2 Data Markings","subsection":"UNKNOWN","table_id":null,"page":180,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":402,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"7.2 Data Markings"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p181-403', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '7.2 Data Markings', 181, 'Standards Track Work Product 02 April 2025 - Page 181 of 276Copyright © OASIS Open 2025. All Rights Reserved. } ], "labels": ["heartbleed", "has-logo"] } Valid selectors: - description selects the description property (“The (1) TLS… ”). - external_references.[0].source_name selects the source_name property of the first value of the external_references list (“cve”). - labels.[0] selects the first item contained within the labels list (“heartbleed”). - labels selects the list contained in the labels property. Due to the recursive nature of the selector, that includes all items in the list ([“heartbleed”, “has-logo”]). - external_references selects the list contained in the external_references property. Due to the recursive nature of the selector, that includes all list items and all properties of those list items. Invalid selectors: - pattern and external_references.[3] are invalid selectors because they refer to content not present in that object.', 'vec_doc-10-oasis-stix21-p181-403', 0, 240, 'v2.1.0', 'd474db12456b95619b3e5a93d939137fa94b7ab9ac54b77764220fdd87643489', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"7.2 Data Markings","subsection":"UNKNOWN","table_id":null,"page":181,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":403,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"7.2 Data Markings"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p181-404', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '7.2 Data Markings', 181, '- description.[0] is an invalid selector because the description property is a string and not a list. - labels.name is an invalid selector because labels property is a list and not an object. This syntax is inspired by JSONPath [Goessner 2007] and is in fact a strict subset of allowable JSONPath expressions (with the exception that the ‘$’ to indicate the root is implicit). Care should be taken when passing selectors to JSONPath evaluators to ensure that the root of the query is the individual STIX Object. It is expected, however, that selectors can be easily evaluated in programming languages that implement list and key/value mapping types (dictionaries, hashmaps, etc.) without resorting to an external library. Examples This example marks the description and labels properties with the marking-definition referenced in the granular_markings property however the name property uses the object marking. { ...', 'vec_doc-10-oasis-stix21-p181-404', 0, 230, 'v2.1.0', '4af84522b71e1f50555950640b96abd40eed090d1cec8889456013d79257f37d', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"7.2 Data Markings","subsection":"UNKNOWN","table_id":null,"page":181,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":404,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"7.2 Data Markings"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p181-405', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '7.2 Data Markings', 181, '"granular_markings": [ { "marking_ref": "marking-definition--089a6ecb-cc15-43cc-9494-767639779123", "selectors": ["description", "labels"] } ], "object_marking_refs": ["marking-definition--79e2fa14-02c6-40d7-aa4b-ebf281dd78ef"], "description": "Some description", "name": "Some name", "labels": ["first", "second"] } This example marks the default language for this object as English (in this case, the name property) and the description as German. { "type": "campaign", "spec_version": "2.1", "id": "campaign--12a111f0-b824-4baf-a224-83b80237a094", "lang": "en", "created": "2017-02-08T21:31:22.007Z", "modified": "2017-02-08T21:31:22.007Z", "name": "Bank Attack", "description": "Weitere Informationen über Banküberfall", "granular_markings": [ {', 'vec_doc-10-oasis-stix21-p181-405', 0, 187, 'v2.1.0', '5c10ff3fdfed94b48c7651bb359cb361a4f5ea6f15c2305bfdeedf75ef4d4f2e', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"7.2 Data Markings","subsection":"UNKNOWN","table_id":null,"page":181,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":405,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"7.2 Data Markings"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p182-406', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '7.3 Extension Definition', 182, 'The STIX Extension Definition object allows producers of threat intelligence to extend existing STIX objects or to create entirely new STIX objects in a standardized way. This object contains detailed information about the extension and any additional properties and or objects that it defines. This extension mechanism MUST NOT be used to redefine existing standardized objects or properties. If a producer does not include the STIX Extension Definition object with the STIX objects that use it, consumers should refer to section 3.3 for information in resolving references. There are three ways to extend STIX using STIX Extensions. - Define one or more new STIX Object types. - Define additional properties for an existing STIX Object type as a nested property extension. This is typically done to represent a sub-component or module of one or more STIX Object types. - Define additional properties for an existing STIX Object type at the object’s top-level.', 'vec_doc-10-oasis-stix21-p182-406', 0, 241, 'v2.1.0', '2b4e793c21004e7f00ecf918de92019cf2266e2bf4629bd8f2b002d68125fbc5', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"7.3 Extension Definition","subsection":"UNKNOWN","table_id":null,"page":182,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":406,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"7.3 Extension Definition"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p182-407', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '7.3 Extension Definition', 182, 'This can be done to represent properties that form an inherent part of the definition of an object type. When defining a new STIX Object (e.g., SDO, SCO, or SRO) all common properties associated with that type of object (SDO, SCO, SRO) MUST be included in the schema or definition of that new STIX Object type. Extensions that create new STIX objects MUST follow all conformance requirements for that object type (SDO, SCO, SRO) including all of the requirements for the common properties associated with that object type. When defining a STIX extension using the nested property extension mechanism the extensions property (as defined in section 3.2) MUST include the extension definition’s UUID that defines the extension definition object and the extension_type property.', 'vec_doc-10-oasis-stix21-p182-407', 0, 194, 'v2.1.0', 'd8b9d8423b020e045e9a1cefff5dd814df50f60d28bc9c6ee817c51ebd3217b7', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"7.3 Extension Definition","subsection":"UNKNOWN","table_id":null,"page":182,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":407,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"7.3 Extension Definition"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p182-408', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '7.3 Extension Definition', 182, 'IMPORTANT NOTE: Producers using top-level property extensions should be mindful that another producer could also define a top-level property extension using the same property names but for different purposes causing name conflicts when both extensions are used in the same environment. This standarddoes not define any name conflict resolution for new STIX Objects or for top-level properties created by this extension mechanism. However, producers SHOULD follow industry best practices such as using unique property names that are guaranteed to avoid duplicates across all organizations to avoid naming conflicts. IMPORTANT NOTE: Producers using STIX extensions should be mindful that future versions of the STIX specification MAY define objects and or properties that conflict with existing non-standardized extensions. In these cases the meaning as defined in the STIX specification will override any and all conflicting extensions.', 'vec_doc-10-oasis-stix21-p182-408', 0, 234, 'v2.1.0', '364803c1fc3f5248aa9e2e4a0baaf8558f6f9a5d11791f3f6ab2a0dedacc8380', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"7.3 Extension Definition","subsection":"UNKNOWN","table_id":null,"page":182,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":408,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"7.3 Extension Definition"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p182-409', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '7.3 Extension Definition', 182, 'Specific extensions, as with specific Custom Properties, MAY NOT be supported across implementations. A consumer that receives STIX content containing a STIX extension that it does not understand MAY refuse to process the content or MAY ignore that extension and continue processing the content. The three uses of this extension facility MAY be combined into a single Extension Definition object when appropriate. The following example highlights where this may be useful. Hybrid Extension Example An intelligence producer has a monitoring network of sensors that collect a variety of cybersecurity telemetry from each sensor where those sensors have unique data not currently defined in STIX 2.1. The producer wishes to create an extension that other downstream consumers can receive both the high-level summarization object but also the individual categorized telemetry from each sensor. - A new SDO representing the statistical summarization object. - A list of new properties to be added to the standard', 'vec_doc-10-oasis-stix21-p182-409', 0, 252, 'v2.1.0', 'e908219006f8fcf4aa309dbcd99f498001a3962e3f7b094c340faf061d163c5d', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"7.3 Extension Definition","subsection":"UNKNOWN","table_id":null,"page":182,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":409,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"7.3 Extension Definition"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p183-410', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '7.3 Extension Definition', 183, 'Standards Track Work Product 02 April 2025 - Page 183 of 276Copyright © OASIS Open 2025. All Rights Reserved. Observed Data object representing additional meta-data information associated with the telemetry. - A new SCO representing a new cyber observable data type. In this case, the producer creates a single extension that contains the following extension types: "extension_types": [ "new-sdo", "new-sco", "property-extension" ] Therefore, producers MAY use the hybrid extension mechanism when they wish to define a single extension that encompasses new SDO and/or sub-component or top-level property extension properties in a related extension. Producers SHOULD NOT use the hybrid extension mechanism if the extensions are not related to each other. If the extensions are independent features then a producer SHOULD consider creating separate extension definitions.', 'vec_doc-10-oasis-stix21-p183-410', 0, 218, 'v2.1.0', '9d59615f6c2defec78efb5d716e21a0f3175c34ed5945834da1de72133cf0305', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"7.3 Extension Definition","subsection":"UNKNOWN","table_id":null,"page":183,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":410,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"7.3 Extension Definition"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p183-411', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '7.3 Extension Definition', 183, '7.3.1 Extension Definition Properties Required Common Properties type, spec_version, id, created, modified, created_by_ref Optional Common Properties revoked, labels, external_references, object_marking_refs, granular_marking_refs Not Applicable Common Properties confidence, lang, defanged, extensions Specific Properties name, description, schema, version, extension_types, extension_properties Property Name Type Description type (required) string The value of this property MUST be extension- definition. name (required) string A name used for display purposes during execution, development, or debugging. description (optional) string A detailed explanation of what data the extension conveys and how it is intended to be used. While the description property is optional this property SHOULD be populated. Note that the schema property is the normative definition of the extension, and this property, if present, is for documentation purposes only.', 'vec_doc-10-oasis-stix21-p183-411', 0, 239, 'v2.1.0', '23c403d4690da6808f3a25009bb4a6b16b7d0320c487db2fbd493c8936bc5579', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"7.3 Extension Definition","subsection":"UNKNOWN","table_id":null,"page":183,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":411,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"7.3 Extension Definition"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p183-412', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '7.3 Extension Definition', 183, 'schema (required) string The normative definition of the extension, either as a URL or as plain text explaining the definition. A URL SHOULD point to a JSON schema or a location', 'vec_doc-10-oasis-stix21-p183-412', 0, 45, 'v2.1.0', '883969608433a5fea0391de912a654e501f41ef862a2a0ab6b75ea4839459739', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"7.3 Extension Definition","subsection":"UNKNOWN","table_id":null,"page":183,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":412,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"7.3 Extension Definition"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p184-413', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '7.3 Extension Definition', 184, 'Standards Track Work Product 02 April 2025 - Page 184 of 276Copyright © OASIS Open 2025. All Rights Reserved. that contains information about the schema. NOTE: It is recommended that an external reference be provided to the comprehensive documentation of the extension-definition. version (required) string The version of this extension. Producers of STIX extensions are encouraged to follow standard semantic versioning procedures where the version number follows the pattern, MAJOR.MINOR.PATCH. This will allow consumers to distinguish between the three different levels of compatibility typically identified by such versioning strings. As with all STIX Objects, changing a STIX extension definition could involve STIX versioning. See section 3.6.2 for more information on versioning an object versus creating a new one. extension_types (required) list of type enum This property specifies one or more extension types contained within this extension.', 'vec_doc-10-oasis-stix21-p184-413', 0, 238, 'v2.1.0', '223c9514d24b432cfd3052142a27e349936268f54587a2662dea50b767bc1bf8', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"7.3 Extension Definition","subsection":"UNKNOWN","table_id":null,"page":184,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":413,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"7.3 Extension Definition"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p184-414', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '7.3 Extension Definition', 184, 'The values for this property MUST come from the extension-type-enum enumeration. When this property includes toplevel-property- extension then the extension_properties property SHOULD include one or more property names. extension_properties (optional) list of type string This property contains the list of new property names that are added to an object by an extension. This property MUST only be used when the extension_types property includes a value of toplevel-property-extension. In other words, when new properties are being added at the top-level ofan existing object. 7.3.2 Requirements for STIX Extension Schemas The requirements listed below apply to the extension schema referred to by the schema property. These requirements are not for the Extension Definition object itself. Requirements for Extension Properties A STIX Object MAY have any number of Extensions containing one or more properties.', 'vec_doc-10-oasis-stix21-p184-414', 0, 228, 'v2.1.0', 'a374260eb618823e6fb308591e5b9a0e9fc5b125a91a5672b026e9a28966a638', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"7.3 Extension Definition","subsection":"UNKNOWN","table_id":null,"page":184,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":414,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"7.3 Extension Definition"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p184-415', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '7.3 Extension Definition', 184, 'Extension property names MUST be in ASCII and MUST only contain the characters a–z (lowercase ASCII), 0–9, and underscore (_). Extension property names MUST have a minimum length of 3 ASCII characters. Extension property names MUST be no longer than 250 ASCII characters in length. Extension properties SHOULD only be used when there are no existing properties defined by the STIX specification that fulfils that need. Requirements for Extension STIX Objects Producers MAY include any number of STIX Extensions in STIX content. Extension STIX Objects MUST support the Common Properties as defined in section 3.2. Common property names MUST NOT be reused to represent the custom properties in the object.', 'vec_doc-10-oasis-stix21-p184-415', 0, 176, 'v2.1.0', '2516d0ec1448969544803b7697498c0369c8def97b3d1a28e2ee06bc2b029917', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"7.3 Extension Definition","subsection":"UNKNOWN","table_id":null,"page":184,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":415,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"7.3 Extension Definition"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p185-416', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '7.3 Extension Definition', 185, 'Standards Track Work Product 02 April 2025 - Page 185 of 276Copyright © OASIS Open 2025. All Rights Reserved. An Extension STIX Object MUST have one or more properties. The property names used in Extension STIX Object MUST be in ASCII and MUST only contain the characters a-z (lowercase ASCII), 0-9, and underscore (_). The name of a property of a Extension STIX Object MUST have a minimum length of 3 ASCII characters. The name of a property of a Extension STIX Object MUST be no longer than 250 ASCII characters in length. The type property in an Extension STIX Object MUST be in ASCII and MUST only contain the characters a-z (lowercase ASCII), 0-9, and hyphen (-). The type property MUST NOT contain a hyphen (-) character immediately following another hyphen (-) character. Extension STIX Object names MUST have a minimum length of 3 ASCII characters. Extension STIX Object names MUST be no longer than 250 ASCII characters in length.', 'vec_doc-10-oasis-stix21-p185-416', 0, 235, 'v2.1.0', 'ca33f991f8ef64e3a572ccb611ef6f9ef5dc5a54887e20047c46d0b61e3af60a', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"7.3 Extension Definition","subsection":"UNKNOWN","table_id":null,"page":185,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":416,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"7.3 Extension Definition"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p185-417', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '7.3 Extension Definition', 185, 'The value of the id property in a Extension STIX Object MUST use the same format as the identifier type, namely, [object-type]–[UUID]. Extension STIX Objects SHOULD only be used when there is no existing STIX Object defined by the STIX specification that fulfils that need. Examples (additional examples can be found in Appendix C) Create a new object type This is an example of a new SDO object type being created with the STIX Extension mechanism.', 'vec_doc-10-oasis-stix21-p185-417', 0, 113, 'v2.1.0', 'c60c73d6600e2fd4cfd2fb12c99a9ed668fac213b09e396df084269e2bdd698e', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"7.3 Extension Definition","subsection":"UNKNOWN","table_id":null,"page":185,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":417,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"7.3 Extension Definition"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p185-418', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '7.3 Extension Definition', 185, '[ { "id": "extension-definition--9c59fd79-4215-4ba2-920d-3e4f320e1e62", "type": "extension-definition", "spec_version": "2.1", "name": "New SDO 1", "description": "This schema creates a new object type called my-favorite-sdo-1", "created": "2014-02-20T09:16:08.989000Z", "modified": "2014-02-20T09:16:08.989000Z", "created_by_ref": "identity--11b76a96-5d2b-45e0-8a5a-f6994f370731", "schema": "https://www.example.com/schema-my-favorite-sdo-1/v1/", "version": "1.2.1", "extension_types": [ "new-sdo" ] }, { "type": "my-favorite-sdo", "spec_version": "2.1", "id": "my-favorite-sdo--ac97aae4-83f1-46ca-a351-7aeb76678189", "created": "2014-02-20T09:16:08.989000Z", "modified": "2014-02-20T09:16:08.989000Z", "name": "This is the name of my favorite", "some_property_name1": "value1", "some_property_name2": "value2", "extensions": { "extension-definition--9c59fd79-4215-4ba2-920d-3e4f320e1e62" : { "extension_type" : "new-sdo" } } } ] Adding properties to an existing STIX object instance', 'vec_doc-10-oasis-stix21-p185-418', 0, 246, 'v2.1.0', '2a4eb1a3c4e0c0bb272b5f0f8c0d96ee9874c3587a3e8a1fd913f0683c56326c', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"7.3 Extension Definition","subsection":"UNKNOWN","table_id":null,"page":185,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":418,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"7.3 Extension Definition"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p186-419', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '7.3 Extension Definition', 186, 'Standards Track Work Product 02 April 2025 - Page 186 of 276Copyright © OASIS Open 2025. All Rights Reserved. This example adds the properties rank and toxicity to the indicator object.', 'vec_doc-10-oasis-stix21-p186-419', 0, 47, 'v2.1.0', 'aa87e92bca3b0a968e1639e461b921c755a62a93eca065e23644bd73733fd069', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"7.3 Extension Definition","subsection":"UNKNOWN","table_id":null,"page":186,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":419,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"7.3 Extension Definition"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p186-420', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '7.3 Extension Definition', 186, '[ { "id": "extension-definition--d83fce45-ef58-4c6c-a3f4-1fbc32e98c6e", "type": "extension-definition", "spec_version": "2.1", "name": "Extension Foo 1", "description": "This schema adds two properties to a STIX object", "created": "2014-02-20T09:16:08.989000Z", "modified": "2014-02-20T09:16:08.989000Z", "created_by_ref": "identity--11b76a96-5d2b-45e0-8a5a-f6994f370731", "schema": "https://www.example.com/schema-foo-1/v1/", "version": "1.2.1", "extension_types": [ "property-extension" ] }, { "type": "indicator", "spec_version": "2.1", "id": "indicator--e97bfccf-8970-4a3c-9cd1-5b5b97ed5d0c", "created": "2014-02-20T09:16:08.989000Z", "modified": "2014-02-20T09:16:08.989000Z", "name": "File hash for Poison Ivy variant", "description": "This file hash indicates that a sample of Poison Ivy is present.", "labels": [ "malicious-activity" ], "pattern": "[file:hashes.''SHA-256'' = ''ef537f25c895bfa782526529a9b63d97aa631564d5d789c2b765448c8635fb6c'']", "pattern_type": "stix", "valid_from": "2014-02-20T09:00:00.000000Z", "extensions": { "extension-definition--d83fce45-ef58-4c6c-a3f4-1fbc32e98c6e" : { "extension_type": "property-extension", "rank": 5, "toxicity": 8 } } } ] Adding properties at the top-level to an existing STIX object instance NOTE: There is an example above using the preferred way, property-extension, of adding properties to an object.', 'vec_doc-10-oasis-stix21-p186-420', 0, 340, 'v2.1.0', '325eecac4a9d77616a5ef579e669801ebe6e5af75d2cfe187433df8fb24146c7', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"7.3 Extension Definition","subsection":"UNKNOWN","table_id":null,"page":186,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":420,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"7.3 Extension Definition"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p186-421', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '7.3 Extension Definition', 186, 'This example is similar to the previous example, but uses the toplevel-property-extension to add the properties rank and toxicity to a STIX object. [ { "id": "extension-definition--71736db5-10db-43d3-b0e3-65cf81601fe1", "type": "extension-definition", "spec_version": "2.1", "name": "Extension Foo 1a", "description": "This schema adds two properties to a STIX object at the toplevel", "created": "2014-02-20T09:16:08.989000Z",', 'vec_doc-10-oasis-stix21-p186-421', 0, 107, 'v2.1.0', '30db1eda0176421ce981944915b3fd8935bcbf928a17683783a3ee9d25a886cf', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"7.3 Extension Definition","subsection":"UNKNOWN","table_id":null,"page":186,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":421,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"7.3 Extension Definition"}');
