INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p187-423', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '7.3 Extension Definition', 187, '"modified": "2014-02-20T09:16:08.989000Z", "created_by_ref": "identity--11b76a96-5d2b-45e0-8a5a-f6994f370731", "schema": "https://www.example.com/schema-foo-1a/v1/", "version": "1.2.1", "extension_types": [ "toplevel-property-extension" ], "extension_properties" : [ "toxicity", "rank" ] }, { "type": "indicator", "spec_version": "2.1", "id": "indicator--66a63e16-92d7-4b2f-bd3d-21540d6b3fc7", "created": "2014-02-20T09:16:08.989000Z", "modified": "2014-02-20T09:16:08.989000Z", "name": "File hash for Poison Ivy variant", "description": "This file hash indicates that a sample of Poison Ivy is present.", "labels": [ "malicious-activity" ], "pattern": "[file:hashes.''SHA-256'' = ''ef537f25c895bfa782526529a9b63d97aa631564d5d789c2b765448c8635fb6c'']", "pattern_type": "stix", "valid_from": "2014-02-20T09:00:00.000000Z", "rank": 1, "toxicity": 2, "extensions": { "extension-definition--71736db5-10db-43d3-b0e3-65cf81601fe1" : { "extension_type": "toplevel-property-extension" } } } ] Adding two new STIX objects and properties to an existing STIX object instance In this example, the extension introduces a new SDO, SCO, and some properties to be added to the indicator object.', 'vec_doc-10-oasis-stix21-p187-423', 0, 294, 'v2.1.0', '99a34b4e8a1fb0a9a2222fd9aba4e769c16687512f65a3976d0013bb246474b4', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"7.3 Extension Definition","subsection":"UNKNOWN","table_id":null,"page":187,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":423,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"7.3 Extension Definition"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p187-424', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '7.3 Extension Definition', 187, '[ { "id": "extension-definition--c5333451-c08c-4c48-be5e-9ad4c947776a", "type": "extension-definition", "spec_version": "2.1", "name": "Extension My Favorite SDO and Sub-Comp", "description": "This schema adds a new object my-favorite-sdo and some sub-component to existing objects", "created": "2014-02-20T09:16:08.989000Z", "modified": "2014-02-20T09:16:08.989000Z", "created_by_ref": "identity--c1694394-c150-4f80-a69a-59ca5e850df4", "schema": "https://www.example.com/schema-newobj-subcomp/v1/schema.json", "version": "1.2.1", "extension_types": [ "new-sdo", "new-sco", "property-extension" ] }, {', 'vec_doc-10-oasis-stix21-p187-424', 0, 151, 'v2.1.0', '5d8b201a5aee5f3c9312ffd20f9a3e367a4d188ce1607231795663ebaa759201', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"7.3 Extension Definition","subsection":"UNKNOWN","table_id":null,"page":187,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":424,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"7.3 Extension Definition"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p188-425', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '7.3 Extension Definition', 188, 'Standards Track Work Product 02 April 2025 - Page 188 of 276Copyright © OASIS Open 2025. All Rights Reserved. "type": "my-favorite-sdo", "spec_version": "2.1", "id": "my-favorite-sdo--a5461d2e-7ba9-43ef-9b3e-11471d1ad8da", "created": "2014-02-20T09:16:08.989000Z", "modified": "2014-02-20T09:16:08.989000Z", "name": "This is the name of my favorite", "some_field": "value", "extensions": { "extension-definition--c5333451-c08c-4c48-be5e-9ad4c947776a" : { "extension_type": "new-sdo" } } }, { "type": "my-favorite-sco", "spec_version": "2.1", "id": "my-favorite-sco--f9dbe89c-0030-4a9d-8b78-0dcd0a0de874", "name": "This is the name of my favorite SCO", "some_network_protocol_field": "value", "extensions": { "extension-definition--c5333451-c08c-4c48-be5e-9ad4c947776a" : { "extension_type": "new-sco" } } }, { "type": "indicator", "spec_version": "2.1", "id": "indicator--50a77dab-ccc6-439c-b142-92786c394b43", "created": "2014-02-20T09:16:08.989000Z", "modified": "2014-02-20T09:16:08.989000Z", "name": "File hash for Poison Ivy variant", "description": "This file hash indicates that a sample of Poison Ivy is present.", "labels": [ "malicious-activity" ], "pattern": "[file:hashes.''SHA-256'' = ''ef537f25c895bfa782526529a9b63d97aa631564d5d789c2b765448c8635fb6c'']", "pattern_type": "stix", "valid_from": "2014-02-20T09:00:00.000000Z", "extensions": { "extension-definition--c5333451-c08c-4c48-be5e-9ad4c947776a" : { "extension_type": "property-extension", "rank" : 5, "toxicity": 8 } } } ]', 'vec_doc-10-oasis-stix21-p188-425', 0, 373, 'v2.1.0', '13ccf390fdd2d9ad68cd861238578019cd6a599803123d9ccbd13edc627d72ae', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"7.3 Extension Definition","subsection":"UNKNOWN","table_id":null,"page":188,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":425,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"7.3 Extension Definition"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p189-426', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '8. STIX Bundle Object', 189, 'Type Name: bundle A Bundle is a collection of arbitrary STIX Objects grouped together in a single container. A Bundle does not have any semantic meaning and the objects contained within the Bundle are not considered related by virtue of being in the same Bundle. A STIX Bundle Object is not a STIX Object but makes use of the type and id Common Properties. A Bundle is transient, and implementations SHOULD NOT assume that other implementations will treat it as a persistent object or keep any custom properties found on the bundle itself. The JSON MTI serialization uses the JSON Object type [RFC8259] when representing bundle.', 'vec_doc-10-oasis-stix21-p189-426', 0, 157, 'v2.1.0', 'c28825202c29f3a308196515cbaf642ea40e6531aa847e111033a9b7f2a61852', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"8. STIX Bundle Object","subsection":"UNKNOWN","table_id":null,"page":189,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":426,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"8. STIX Bundle Object"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p189-427', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '8.1 Properties', 189, 'Property Name Type Description type (required) string The value of this property MUST be bundle. id (required) identifier An identifier for this Bundle. The id property for the Bundle is designed to help tools that may need it for processing, however, tools are not required to store or track it. Tools that consume STIX should not rely on the ability to refer to bundles by ID. objects (optional) list of type <STIX Object> Specifies a set of one or more STIX Objects. Objects in this list MUST be a STIX Object.', 'vec_doc-10-oasis-stix21-p189-427', 0, 129, 'v2.1.0', '5953c330e6741aca0d6510eb698f2c3aabc4aca7246839c44d3140c1a23a9dae', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"8.1 Properties","subsection":"UNKNOWN","table_id":null,"page":189,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":427,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"8.1 Properties"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p189-428', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '8.2 Relationships', 189, 'STIX Bundle Object is not a STIX Object and MUST NOT have any relationships to or from it. Example { "type": "bundle", "id": "bundle--5d0092c5-5f74-4287-9642-33f4c354e56d", "objects": [ { "type": "indicator", "spec_version": "2.1", "id": "indicator--8e2e2d2b-17d4-4cbf-938f-98ee46b3cd3f", "created_by_ref": "identity--f431f809-377b-45e0-aa1c-6a4751cae5ff", "created": "2016-04-29T14:09:00.000Z", "modified": "2016-04-29T14:09:00.000Z", "object_marking_refs": ["marking-definition--089a6ecb-cc15-43cc-9494-767639779123"], "name": "Poison Ivy Malware", "description": "This file is part of Poison Ivy", "pattern": "[file:hashes.''SHA-256'' = ''aec070645fe53ee3b3763059376134f058cc337247c978add178b6ccdfb0019f'']" } ] }', 'vec_doc-10-oasis-stix21-p189-428', 0, 178, 'v2.1.0', '138fd0c759bb06ed811b3f3f516be6a1cf222b1edb0f4465d9068c862f3853bb', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"8.2 Relationships","subsection":"UNKNOWN","table_id":null,"page":189,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":428,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"8.2 Relationships"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p190-429', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '9.1 Definitions', 190, 'The terms defined below are used throughout this document. Terms Definitions Example whitespace Any Unicode code point that has WSpace set as a property, for example, line feeds, carriage returns, tabs, and spaces. n/a Observation Observations represent data about systems or networks that is observed at a particular point in time - for example, information about a file that existed, a process that was observed running, or network traffic that was transmitted between two IPs. In STIX, Observations are represented by Observed Data SDOs, with number_observed observations occurring between their first_observed and last_observed timestamps. It is not defined when the observations occur within that time window. For additional background, refer to the STIX Observed Data object definition in section 4.14. n/a Comparison Expression Comparison Expressions are the basic components of Observation Expressions.', 'vec_doc-10-oasis-stix21-p190-429', 0, 228, 'v2.1.0', '107a4e206a0a11d364d37690552764fbd1ac3491310c2709cb0a38822e8a43a8', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"9.1 Definitions","subsection":"UNKNOWN","table_id":null,"page":190,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":429,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"9.1 Definitions"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p190-430', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '9.1 Definitions', 190, 'They consist of an Object Path and a constant joined by a Comparison Operator (listed in section 9.6.1, Comparison Operators). user-account:value = ‘Peter’ Comparison Operator Comparison Operators are used within Comparison Expressions to compare an Object Path against a constant or set of constants. n/a Object Path Object Paths define which properties of STIX Cyber-observable Objects (SCO) should be evaluated as part of a Comparison Expression. SCOs and their properties are defined in section 6. ipv6-addr:value Observation Expression Observation Expressions consist of one or more Comparison Expressions joined with Boolean Operators and surrounded by square brackets. An Observation Expression may consist of two Observation Expressions joined by an Observation Operator. This may be applied recursively to compose multiple Observation Expressions into a single Observation Expression. Observation Expressions may optionally be followed by one or more Qualifiers further constraining the result set.', 'vec_doc-10-oasis-stix21-p190-430', 0, 252, 'v2.1.0', '47ad3aea773e2633d0be4dcc8a6bb6da36a4337a31541f65fd812c6644b590f9', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"9.1 Definitions","subsection":"UNKNOWN","table_id":null,"page":190,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":430,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"9.1 Definitions"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p190-431', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '9.1 Definitions', 190, 'Qualifiers may be [ipv4-addr:value = ‘203.0.113.1’ OR ipv4-addr:value = ‘203.0.113.2’] or (with Observation Operator): ([ipv4-addr:value = ‘198.51.100.5’] FOLLOWEDBY [ipv4-addr:value = ‘198.51.100.10’])', 'vec_doc-10-oasis-stix21-p190-431', 0, 51, 'v2.1.0', '3f7133a1aaa57f6cc0f3a36da2d5582d77a79f5f2a611192137f45ea96262f20', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"9.1 Definitions","subsection":"UNKNOWN","table_id":null,"page":190,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":431,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"9.1 Definitions"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p191-432', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '9.1 Definitions', 191, 'Standards Track Work Product 02 April 2025 - Page 191 of 276Copyright © OASIS Open 2025. All Rights Reserved. applied to all of the Observation Expressions joined with Observation Operators; in this case, parentheses should be used to group the set of Observation Expressions, with the Qualifier following the closing parenthesis. or (with Observation Operator and Qualifier): ([ipv4-addr:value = ‘198.51.100.5’ ] AND [ipv4- addr:value = ‘198.51.100.10’]) WITHIN 300 SECONDS Boolean Operator Boolean Operators are used to combineComparison Expressions within an Observation Expression. user-account:value = ‘Peter’ OR user- account:value = ‘Mary’ Qualifier Qualifiers provide a restriction on the Observations that are considered valid for matching the preceding Observation Expression. [file:name = ‘foo.dll’] START t’2016-06- 01T00:00:00Z’ STOP t’2016-07- 01T00:00:00Z’ Observation Operator Observation Operators are used to combine two Observation Expressions operating on two different Observed Data instances into a single pattern. Note that some Observation Operators have the same name as Boolean Operators. However, the former connects Comparison Expressions and the latter connects Observation Expressions, and therefore each has slightly different semantics. [ipv4-addr:value = ‘198.51.100.5’] AND [ ipv4-addr:value = ‘198.51.100.10’] Pattern Expression A Pattern Expression represents a valid instance of a STIX cyber observable pattern. The most basic Pattern Expression consists of a single Observation Expression containing a single Comparison Expression. [file:size = 25536]', 'vec_doc-10-oasis-stix21-p191-432', 0, 398, 'v2.1.0', '5e744bebdb77b3b80dcf33ddbffd89280dc2bae34e04068b4926fe677fec4c6c', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"9.1 Definitions","subsection":"UNKNOWN","table_id":null,"page":191,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":432,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"9.1 Definitions"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p191-433', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '9.2 Constants', 191, 'The data types enumerated below are supported as operands within Comparison Expressions. This table is included here as a handy reference for implementers. Note that unlike SCOs (which are defined in terms of the MTI JSON serialization), STIX Patterns are Unicode strings, regardless of the underlying serialization, hence the data types defined in the table below in some cases differ from the definitions contained in section 2. Each constant defined in Patterning has a limited set of STIX Data types that they are allowed to be compared against. In some cases, there are multiple STIX Data Types that could be compared against a STIX Patterning Constant; this is due to the fact that certain STIX Data Types are semantically indistinguishable because of their JSON serialization. The STIX Comparable Data Type(s) column in the table below defines these limitations.', 'vec_doc-10-oasis-stix21-p191-433', 0, 218, 'v2.1.0', 'b8b995f0cbb981dfb1e72bfc3346be67d1176cf86017149634bb65d0e2159a36', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"9.2 Constants","subsection":"UNKNOWN","table_id":null,"page":191,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":433,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"9.2 Constants"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p192-434', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '9.2 Constants', 192, 'Standards Track Work Product 02 April 2025 - Page 192 of 276Copyright © OASIS Open 2025. All Rights Reserved. STIX Patterning Constant STIX Comparable Data Type(s) Description boolean boolean A constant of boolean type encodes truth or falsehood. Boolean truth is denoted by the literal true and falsehood by the literal false. binary binary hex string A constant of binary type is a base64 encoded array of octets (8-bit bytes) per [RFC4648]. The base64 string MUST be surrounded by apostrophes (‘ U+0027) and prefixed by a b (U+0062). Line feeds in the base64 encoded data MUST be supported and ignored but are not required to be inserted. Example: b’ABI=’ hex binary hex string A constant of hex type encodes an array of octets (8-bit bytes) as hexadecimal. The string MUST consist of an even number of hexadecimal characters, which are the digits ‘0’ through ‘9’ and the letters ‘a’ through ‘f’. The hex string MUST be surrounded by apostrophes (‘ U+0027) and prefixed by an h (U+0068).', 'vec_doc-10-oasis-stix21-p192-434', 0, 248, 'v2.1.0', 'f070b99870215937cee399b7c14c9d2eb26d558f2d6f2ff99ee84f9ca54cd297', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"9.2 Constants","subsection":"UNKNOWN","table_id":null,"page":192,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":434,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"9.2 Constants"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p192-435', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '9.2 Constants', 192, 'Example: h’ffc3’ integer integer float A constant of integer type encodes a signed decimal number in the usual fashion (e.g., 123). In the case of positive integers, the integer MUST be represented as-is, omitting the plus sign (+ U+002b). Negative integers MUST be represented by prepending a hyphen-minus (- U+002d). When compared against a float, the full value must be compared and must not be truncated. For example, the result of comparing a STIX Patterning constant integer value of 1 to a float value of 1.5 is not equal. The valid range of values is defined in section 2. float integer float A constant of float type encodes a floating-point number in the usual fashion (e.g., 123.456). In the case of positive floating-point number, the floating-point number MUST be represented as-is, omitting the plus sign (+ U+002b). Negative floating point- numbers MUST be represented by prepending a hyphen-minus (- U+002d). The valid range of values is defined in section 2.', 'vec_doc-10-oasis-stix21-p192-435', 0, 244, 'v2.1.0', 'bde9c14f59551d2d4e5f7454297643e9ac5e2b581a74db58621f43b94d79158e', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"9.2 Constants","subsection":"UNKNOWN","table_id":null,"page":192,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":435,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"9.2 Constants"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p192-436', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '9.2 Constants', 192, 'string string binary hex A constant of string type encodes a string as a list of Unicode code points surrounded by apostrophes (’ U+0027). The escape character is the backslash (</code> U+005c). Only the apostrophe or the backslash may follow, and in that case, the respective character is used for the sequence.', 'vec_doc-10-oasis-stix21-p192-436', 0, 78, 'v2.1.0', 'e6901ecdd1692235d3f10cc13eca2daa403cd6038af25351ead2ea80b0abbcfc', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"9.2 Constants","subsection":"UNKNOWN","table_id":null,"page":192,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":436,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"9.2 Constants"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p193-437', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '9.2 Constants', 193, 'Standards Track Work Product 02 April 2025 - Page 193 of 276Copyright © OASIS Open 2025. All Rights Reserved. If a string only contains codepoints less than (U+0100), then the string MAY be converted to a binary type value (if needed for comparison). The mapping is code point U+0000 to 00 through U+00ff to ff. timestamp timestamp A constant of timestamp type encodes a STIX timestamp (as specified in section 2.16) as a string. The timestamp string MUST be surrounded by apostrophes (‘ U+0027) and prefixed with a t (U+0074). Example: t’2014-01-13T07:03:17Z’', 'vec_doc-10-oasis-stix21-p193-437', 0, 140, 'v2.1.0', '49f0ab00b11965750f6ae17d35e38cb1a4f6de733bcb65bd6956b2af18917362', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"9.2 Constants","subsection":"UNKNOWN","table_id":null,"page":193,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":437,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"9.2 Constants"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p193-438', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '9.3 STIX Patterns', 193, 'STIX Patterns are composed of multiple building blocks, ranging from simple key-value comparisons to more complex, context-sensitive expressions. The most fundamental building block is the Comparison Expression, which is a comparison between a single property of a SCO and a given constant using a Comparison Operator. As a simple example, one might use the following Comparison Expression (contained within an Observation Expression) to match against an IPv4 address: [ipv4-addr:value = ''198.51.100.1/32''] Moving up a level of complexity, the next building block of a STIX Pattern is the Observation Expression, which consists of one or more Comparison Expressions joined by Boolean Operators and bounded by square brackets. An Observation Expression refines which set of cyber observable data (i.e., as part of an Observation) will match the pattern, by selecting the set that has the SCOs specified by the Comparison Expressions.', 'vec_doc-10-oasis-stix21-p193-438', 0, 233, 'v2.1.0', '21d5380285059450fe9bd71d300279af5e9ee359a3b1e3b5b6a03d388adca778', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"9.3 STIX Patterns","subsection":"UNKNOWN","table_id":null,"page":193,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":438,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"9.3 STIX Patterns"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p193-439', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '9.3 STIX Patterns', 193, 'An Observation Expression consisting of a single Comparison Expression is the most basic valid STIX Pattern. Building upon the previous example, one might construct an Observation Expression to match against multiple IPv4 addresses and an IPv6 address: [ipv4-addr:value = ''198.51.100.1/32'' OR ipv4-addr:value = ''203.0.113.33/32'' OR ipv6-addr:value = ''2001:0db8:dead:beef:dead:beef:dead:0001/128''] Observation Expressions may be followed by one or more Qualifiers, which allow for the expression of further restrictions on the set of data matching the pattern.', 'vec_doc-10-oasis-stix21-p193-439', 0, 140, 'v2.1.0', '6c1d5b14fb280ca671d30d3a1d172afdcaf550d8888c68228bdb5b8e86b0eba0', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"9.3 STIX Patterns","subsection":"UNKNOWN","table_id":null,"page":193,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":439,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"9.3 STIX Patterns"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p193-440', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '9.3 STIX Patterns', 193, 'Continuing with the above example, one might use a Qualifier to state that the IP addresses must be observed several times in repetition: [ipv4-addr:value = ''198.51.100.1/32'' OR ipv4-addr:value = ''203.0.113.33/32'' OR ipv6-addr:value = ''2001:0db8:dead:beef:dead:beef:dead:0001/128''] REPEATS 5 TIMES The final, highest level building block of STIX Patterning combines two or more Object Expressions via Observation Operators, yielding a STIX Pattern capable of matching across multiple STIX Observed Data SDOs. Building further upon our previous example, one might use an Observation Operator to specify that an observation of a particular domain name must follow the observation of the IP addresses (note the use of parentheses to encapsulate the two Observation Expressions), along with a different Qualifier to state that both the IP address and domain name must be observed within a specific time window:', 'vec_doc-10-oasis-stix21-p193-440', 0, 227, 'v2.1.0', 'd4b498550da90d3c0dba423e6843229af291b168c85416ffdd6be6a469431f0d', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"9.3 STIX Patterns","subsection":"UNKNOWN","table_id":null,"page":193,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":440,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"9.3 STIX Patterns"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p194-441', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '9.3 STIX Patterns', 194, 'Standards Track Work Product 02 April 2025 - Page 194 of 276Copyright © OASIS Open 2025. All Rights Reserved. ([ipv4-addr:value = ''198.51.100.1/32'' OR ipv4-addr:value = ''203.0.113.33/32'' OR ipv6-addr:value = ''2001:0db8:dead:beef:dead:beef:dead:0001/128''] FOLLOWEDBY [domain-name:value = ''example.com'']) WITHIN 600 SECONDS The diagram below depicts a truncated version of the various STIX Patterning components in the above example.', 'vec_doc-10-oasis-stix21-p194-441', 0, 108, 'v2.1.0', 'ce73d6614a4f4fb20756b5c3fdd03583f6501c873adf5e3ac21733a9c0a41cea', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"9.3 STIX Patterns","subsection":"UNKNOWN","table_id":null,"page":194,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":441,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"9.3 STIX Patterns"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p194-442', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '9.4 Pattern Expressions', 194, 'Pattern Expressions evaluate to true or false. They comprise one or more Observation Expressions joined by Observation Operators. Pattern Expressions are evaluated against a set of specific Observations. If one or more of those Observations match the Pattern Expression, then it evaluates to true. If no Observations match, the Pattern Expression evaluates to false. Pattern Expressions MUST be encoded as Unicode strings. Whitespace (i.e., Unicode code points where WSpace=Y)# in the pattern string is used to delimit parts of the pattern, including keywords, constants, and field objects. Whitespace characters between operators, including line feeds and carriage returns, MUST be allowed. Multiple whitespace characters in a row MUST be treated as a single whitespace character. An invalid pattern resulting from parsing error or invalid constants (e.g., an invalid hex or binary constant) MUST NOT match any Observations.', 'vec_doc-10-oasis-stix21-p194-442', 0, 232, 'v2.1.0', '35a4702feb5743ddfcaf82af36da95bcc7d3001e8aa059cbb43b016b1745f97a', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"9.4 Pattern Expressions","subsection":"UNKNOWN","table_id":null,"page":194,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":442,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"9.4 Pattern Expressions"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p194-443', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '9.5 Observation Expressions', 194, 'Observation Expressions comprise one or more Comparison Expressions, joined via Boolean Operators. Observation Expressions MUST be delimited by left square bracket (‘[’ U+005b) and right square bracket (’]’ U+005d). One or more Observation Expression Qualifiers MAY be provided after the closing square bracket or closing parenthesis of an Observation Expression. Observation Expressions MAY be joined by Observation Operators. Individual Observation Expressions (e.g., [a = b]) match against a single Observation, i.e., a single STIX Observed Data instance. In cases where matching against multiple Observations is required, two or more Observation Expressions may be combined via Observation Operators, indicating that the pattern MUST be evaluated against two or more distinct Observations; however, in the case of OR, if the first Observation Expression evaluates to true, then evaluation MUST terminate and return true. When matching an Observation against an Observation Expression, all Comparison Expressions contained within the Observation Expression MUST start matching against the same SCO in the Observation. That is, when resolving object paths of each Comparison Expression, the : MUST start from the same SCO. Different SCO’s may ultimately be used in matching, but they MUST be referenced from the same, single SCO. For example, the following observed data does not match this example observation clause because although these IP addresses are both part of the same observed-data object, there is not a single network-traffic SCO that references each IP address, and therefore does not satisfy the condition in the preceding paragraph:', 'vec_doc-10-oasis-stix21-p194-443', 0, 413, 'v2.1.0', 'd4f14a90eef2fb5bf656c5aaa6b3150f2e556e4460188acd74f21933346c4f71', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"9.5 Observation Expressions","subsection":"UNKNOWN","table_id":null,"page":194,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":443,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"9.5 Observation Expressions"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p195-444', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '9.5 Observation Expressions', 195, 'Standards Track Work Product 02 April 2025 - Page 195 of 276Copyright © OASIS Open 2025. All Rights Reserved. [ network-traffic:src_ref.value = ''203.0.113.10'' AND network-traffic:dst_ref.value = ''198.51.100.58'' ] { "type": "observed-data", "id": "observed-data--0960319a-3cab-4258-a143-4dbb25525bb1", "first_observed": "2019-10-20T00:12:01.000000Z", "last_observed": "2019-10-20T00:51:02.000000Z", "number_observed": 1, "objects": { "0": { "type": "network-traffic", "src_ref": "1" }, "1": { "type": "ipv4-addr", "value": "203.0.113.10" }, "2": { "type": "network-traffic", "dst_ref": "3" }, "3": { "type": "ipv4-addr", "value": "198.51.100.58" } } } An Observation Expression MAY contain Comparison Expressions with Object Paths that start with different object types, but such Comparison Expressions MUST be joined by OR. All operands of AND in an Observation Expression MUST be satisfiable with the same object.', 'vec_doc-10-oasis-stix21-p195-444', 0, 229, 'v2.1.0', '0b7d4effac8ffe22e78560e3bc8d9cd6a7821deb4a56fb1192c49671c3b40fd1', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"9.5 Observation Expressions","subsection":"UNKNOWN","table_id":null,"page":195,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":444,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"9.5 Observation Expressions"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p195-445', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '9.5 Observation Expressions', 195, 'For example, consider the following Pattern Expression: [(type-a:property-j = ''W'' AND type-a:property-k = ''X'') OR (type-b:property-m = ''Y'' AND type-b:property-n = ''Z'')] This expression can match an Observable with an object of either type-a or type-b, but both Comparison Expressions for that specific type must evaluate to true for the same object. Comparison Expressions that are intended to match a single object type can be joined by either AND or OR. For example: [type-a:property-j = ''W'' AND type-a:property-k = ''X'' OR type-a:property-l = ''Z''] As AND has higher precedence than OR, the preceding example requires an Observation to have either both property-j = ‘W’ AND property-k = ‘X’ or just property-l = ‘Z’. Observation Expressions, along with their Observation Operators and optional Qualifiers, MAY be surrounded with parentheses to delineate which Observation Expressions the Qualifiers apply to.', 'vec_doc-10-oasis-stix21-p195-445', 0, 228, 'v2.1.0', 'c9a47d3daa0e11172e0ef5b695274224a5f2839453dd790b5fafd6b410111858', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"9.5 Observation Expressions","subsection":"UNKNOWN","table_id":null,"page":195,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":445,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"9.5 Observation Expressions"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p195-446', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '9.5 Observation Expressions', 195, 'For example: ([ a ] AND [ b ] REPEATS 5 TIMES) WITHIN 5 MINUTES The preceding example results in one a and 5 b’s that all match in a 5-minute period. As another example:', 'vec_doc-10-oasis-stix21-p195-446', 0, 43, 'v2.1.0', 'a455475397f740bcc65c33e76df4f76b3b51041d1dff55eaf5c7f46bc220b804', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"9.5 Observation Expressions","subsection":"UNKNOWN","table_id":null,"page":195,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":446,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"9.5 Observation Expressions"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p196-447', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '9.5 Observation Expressions', 196, 'Standards Track Work Product 02 April 2025 - Page 196 of 276Copyright © OASIS Open 2025. All Rights Reserved. ([ a ] AND [ b ]) REPEATS 5 TIMES WITHIN 5 MINUTES The preceding example results in 5 a’s and 5 b’s (10 Observations) that all match in a 5-minute period. 9.5.1 Observation Expression Qualifiers Each Observation Expression MAY have additional temporal or repetition restrictions using the respective WITHIN, START/STOP, and REPEATS keywords. An Observation Expression MUST NOT have more than one Qualifier of a particular type. Qualifiers Description a REPEATS x TIMES a MUST be an Observation Expression or a preceding Qualifier. a MUST match at least x times, where each match is a different Observation. x MUST be a positive integer. This is purely a shorthand way of writing: “a” followed by “AND a”, x-1 times. Example: [ b ] FOLLOWEDBY [ c ] REPEATS 5 TIMES In this example, the REPEATS applies to c, and it does not apply to b.', 'vec_doc-10-oasis-stix21-p196-447', 0, 236, 'v2.1.0', '0c564e8338b00f8216aaa43c89ee8a78d64ed1661a9486e5dc1c0cc9d29f39a2', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"9.5 Observation Expressions","subsection":"UNKNOWN","table_id":null,"page":196,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":447,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"9.5 Observation Expressions"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p196-448', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '9.5 Observation Expressions', 196, 'The results will be b plus 5 c’s where all 5 c’s were observed after the b. Note that there is only a single Qualifier in this example; more complex patterns may use more than one. a WITHIN x SECONDS a MUST be an Observation Expression or a preceding Qualifier. All Observations matched by a MUST occur, or have been observed, within the specified time window. x MUST be a positive floating-point or integer value. If there is a set of two or more Observations matched by a, the most recent Observation timestamp contained within that set MUST NOT be equal to or later than the delta of the earliest Observation timestamp within the set plus the specified time window. Example: ([file:hashes.''SHA-256'' = ''13987239847...''] AND [windows-registry-key:key = ''hkey'']) WITHIN 120 SECONDS The above Pattern Expression looks for a file hash and a registry key that were observed within 120 seconds of each other. The parentheses are needed to apply the WITHIN Qualifier to both Observation Expressions.', 'vec_doc-10-oasis-stix21-p196-448', 0, 249, 'v2.1.0', '18424655a9a29d3bccaf362165abe30ba15f75b19f99a29e09fca83cf5258137', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"9.5 Observation Expressions","subsection":"UNKNOWN","table_id":null,"page":196,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":448,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"9.5 Observation Expressions"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p196-449', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '9.5 Observation Expressions', 196, 'a START x STOP y a MUST be an Observation Expression or a preceding Qualifier. All Observations that match a MUST have an observation time >= x and < y. x and y MUST be of type timestamp. In the event that the Pattern Expression is being used inside a STIX Indicator pattern property (see section 4.7) x SHOULD be greater than or equal to the value contained in the valid_from Indicator property, and y SHOULD be less than or equal to the value contained in the valid_until Indicator property.', 'vec_doc-10-oasis-stix21-p196-449', 0, 124, 'v2.1.0', '79d58832c2b2d01a176e39a5798c0c3fbfa74c3428c3c43431740ac13e117dbe', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"9.5 Observation Expressions","subsection":"UNKNOWN","table_id":null,"page":196,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":449,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"9.5 Observation Expressions"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p197-450', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '9.5 Observation Expressions', 197, 'Standards Track Work Product 02 April 2025 - Page 197 of 276Copyright © OASIS Open 2025. All Rights Reserved. 9.5.2 Observation Operators Two or more Observation Expressions MAY be combined using an Observation Operator in order to further constrain the set of Observations that match against the Pattern Expression. Observation Operators Description Associativity [ a ] AND [ b ] a and b MUST both be Observation Expressions and MUST both evaluate to true on different Observations. Left to right [ a ] OR [ b ] a and b MUST both be Observation Expressions and one of a or b MUST evaluate to true on different Observations. Left to right [ a ] FOLLOWEDBY [ b ] a and b MUST both be Observation Expressions. Both a and b MUST both evaluate to true, where the observation timestamp associated with b is greater than or equal to the observation timestamp associated with a and MUST evaluate to true on different Observations.', 'vec_doc-10-oasis-stix21-p197-450', 0, 231, 'v2.1.0', 'd1de6999f71e5db9e10719d07454353b5618e5dc9d3ade266898005a8fcba0e0', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"9.5 Observation Expressions","subsection":"UNKNOWN","table_id":null,"page":197,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":450,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"9.5 Observation Expressions"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p197-451', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '9.5 Observation Expressions', 197, 'Left to right For example, consider the following Pattern Expression: [ a = ''b'' ] FOLLOWEDBY [ c = ''d'' ] REPEATS 5 TIMES The preceding expression says to match an Observation with a equal to ‘b’ that precedes 5 occurrences of Observations that have c equal to ‘d’, for a total of 6 Observations matched. This interpretation is due to qualifiers not being greedy and is equivalent to [ a = ‘b’ ] FOLLOWEDBY ( [ c = ‘d’ ] REPEATS 5 TIMES). Alternatively, using parentheses to group the initial portion, we get the following example: ([ a = ''b'' ] FOLLOWEDBY [ c = ''d'' ]) REPEATS 5 TIMES The preceding expression will match 5 pairs of Observations where a equals ‘b’ followed by an Observation where c is equal to ‘d’, for a total of 10 Observations matched. 9.5.3 Operator Precedence Operator associativity and precedence may be overridden by the use of parentheses. Unless otherwise specified, operator associativity (including for parentheses) is left-to-right.', 'vec_doc-10-oasis-stix21-p197-451', 0, 240, 'v2.1.0', '02a942dcb8abe8d63cc45f832e06a7ec84f436e772e1f61c793491fd728ac742', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"9.5 Observation Expressions","subsection":"UNKNOWN","table_id":null,"page":197,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":451,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"9.5 Observation Expressions"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p197-452', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '9.5 Observation Expressions', 197, 'Precedence in the below table is from highest to lowest. Operators Associativity Valid Scope () left to right Observation Expression or Pattern Expression, Observation Expression and Qualifier AND left to right Observation Expression, Pattern Expression OR left to right Observation Expression, Pattern Expression', 'vec_doc-10-oasis-stix21-p197-452', 0, 79, 'v2.1.0', '12ef5148093c3b730a1da50dd18a5a793815a818b084d9923bfdfc5acfe1b0e1', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"9.5 Observation Expressions","subsection":"UNKNOWN","table_id":null,"page":197,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":452,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"9.5 Observation Expressions"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p198-453', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '9.6 Comparison Expressions', 198, 'Comparison Expressions are the most basic components of STIX Patterning, comprising an Object Path and a constant joined by a Comparison Operator. Each Comparison Expression is a singleton, and so they are evaluated from left to right. A Boolean Operator joins two Comparison Expressions together. In the following table, a or b is either a Comparison Expression or a composite expression (which may be composed recursively) consisting of two or more Comparison Expressions joined with Boolean Operators and enclosed by parentheses. Boolean Operator Description Associativity a AND b a and b MUST both be Comparison Expressions or a composite expression (which may be composed recursively) consisting of two or more Comparison Expressions joined with Boolean Operators and enclosed by parentheses. a and b MUST both evaluate to true on the same Observation.', 'vec_doc-10-oasis-stix21-p198-453', 0, 215, 'v2.1.0', '2ed3cd9c8ad392601c0ac3d70586707836188128cc64323ae56c78626f5e9829', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"9.6 Comparison Expressions","subsection":"UNKNOWN","table_id":null,"page":198,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":453,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"9.6 Comparison Expressions"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p198-454', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '9.6 Comparison Expressions', 198, 'Left to right a OR b a and b MUST both be Comparison Expressions or a composite expression (which may be composed recursively) consisting of two or more Comparison Expressions joined with Boolean Operators and enclosed by parentheses. Either a or b MUST evaluate to true. Left to right Comparison Expressions may include one or more Object Path(s) not obtainable within a given Observation, either because the Object Path(s) are not present within the Observation or because the evaluating entity does not have access to the data necessary in order to evaluate the specified Object Path(s). When evaluating a Comparison Expression against one or more Object Path(s) that are not present or whose data cannot be obtained, the Comparison Expression MUST evaluate to FALSE, regardless of the operators included in the expression.', 'vec_doc-10-oasis-stix21-p198-454', 0, 207, 'v2.1.0', 'b4aac54c8a0c43e3bd52938e4c0dfa380db198dc5dc8c54d92d18a55f61df4df', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"9.6 Comparison Expressions","subsection":"UNKNOWN","table_id":null,"page":198,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":454,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"9.6 Comparison Expressions"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p198-455', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '9.6 Comparison Expressions', 198, '9.6.1 Comparison Operators The table below describes the available Comparison Operators for use in Comparison Expressions; in the table, a MUST be an Object Path and b MUST be a constant. If the arguments to the Comparison Operators are of incompatible types (e.g., the Object Path is an integer and the constant is a string), the results are false; the sole exception is the ?= operator in which case the result is true. Some STIX Patterning constants and STIX data types may be comparable in a Comparison Expression. For example, the hex and binary types both represent binary data, and their representative binary data is that which must be compared for equality. See section 2 for type compatibility between STIX Patterning and STIX types. A Comparison Operator MAY be preceded by the modifier NOT, in which case the resultant Comparison Expression is logically negated. Comparison Operator Description Example', 'vec_doc-10-oasis-stix21-p198-455', 0, 229, 'v2.1.0', '97fda2e9d69d6fab6fbc222f3504bf61b9e7307f9739822da7ffa45637574f11', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"9.6 Comparison Expressions","subsection":"UNKNOWN","table_id":null,"page":198,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":455,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"9.6 Comparison Expressions"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p199-456', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '9.6 Comparison Expressions', 199, 'Standards Track Work Product 02 April 2025 - Page 199 of 276Copyright © OASIS Open 2025. All Rights Reserved. a = b a and b MUST be equal (transitive), where a MUST be anObject Path and b MUST be a constant of the same data type as the object property specified by a. file:name = ''foo.dll'' a ?= b a and b MUST NOT be equal (transitive), where a MUST be an Object Path and b MUST be a constant of the same data type as the Object property specified by a. file:size != 4112 a > b a is numerically or lexically greater than b, where a MUST be an Object Path and b MUST be a constant of the same data type as the Object property specified by a. file:size > 256 a < b a is numerically or lexically less than b, where a MUST be an Object Path and b MUST be a constant of the same data type as the Object property specified by a.', 'vec_doc-10-oasis-stix21-p199-456', 0, 206, 'v2.1.0', 'c20109d69261a2976e4b457298a97631bf0f4abfb01d83a30642b747145aa75a', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"9.6 Comparison Expressions","subsection":"UNKNOWN","table_id":null,"page":199,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":456,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"9.6 Comparison Expressions"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p199-457', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '9.6 Comparison Expressions', 199, 'file:size < 1024 a ?= b a is numerically or lexically less than or equal to b, where a MUST be an Object Path and b MUST be a constant of the same data type as the Object property specified by a. file:size <= 25145 a ?= b a is numerically or lexically greater than or equal to b, where a MUST be an Object Path and b MUST be a constant of the same data type as the Object property specified by a. file:size >= 33312 a IN (x,y,… ) a MUST be an Object Path and MUST evaluate to one of the values enumerated in the set of x,y,…  (transitive). The set values in b MUST be constants of homogeneous data type and MUST be valid data types for the Object Property specified by a. The return value is true if a is equal to one of the values in the list. If a is not equal to any of the items in the list, then the Comparison Expression evaluates to false.', 'vec_doc-10-oasis-stix21-p199-457', 0, 212, 'v2.1.0', 'b1d34a90ca5330a9b7514e294d070ccb3ac28101035e8796148bff47dfa9bb18', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"9.6 Comparison Expressions","subsection":"UNKNOWN","table_id":null,"page":199,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":457,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"9.6 Comparison Expressions"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p199-458', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '9.6 Comparison Expressions', 199, 'process:name IN (''proccy'', ''proximus'', ''badproc'') a LIKE b a MUST be an Object Path and MUST match the pattern specified in b where any ‘%’ is 0 or more characters and ’_’ is any one character. This operator is based upon the SQL LIKE clause and makes use of the same wildcards. The string constant b MUST be NFC normalized [Davis] prior to evaluation. directory:path LIKE ''C:\\Windows\\%\\foo'' a MATCHES b a MUST be an Object Path and MUST be matched by the pattern specified in b, where b is a string constant containing a PCRE compliant regular expression. a MUST be NFC normalized [Davis] before comparison if the property is of string type. Regular expressions MUST be conformant to the syntax defined by the Perl-compatible Regular Expression (PCRE) library [PCRE]. The search function MUST be used. The DOTALL option MUST be specified. The standard beginning and end anchors may be used in the pattern to obtain match behavior.', 'vec_doc-10-oasis-stix21-p199-458', 0, 234, 'v2.1.0', '3c4e10fefa834720f40dc37ce73dbdbd17d6194c30dbd4489cc9960f7f82f697', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"9.6 Comparison Expressions","subsection":"UNKNOWN","table_id":null,"page":199,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":458,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"9.6 Comparison Expressions"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p199-459', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '9.6 Comparison Expressions', 199, 'In the case that the property is binary (e.g., the property directory:path MATCHES ''^C:\\\\Windows\\w+$''', 'vec_doc-10-oasis-stix21-p199-459', 0, 26, 'v2.1.0', 'c35fe1af42bfdb8e707f478ac6d306762961ccd44ad94ab62d6dc8e7af89deb3', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"9.6 Comparison Expressions","subsection":"UNKNOWN","table_id":null,"page":199,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":459,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"9.6 Comparison Expressions"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p200-460', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '9.6 Comparison Expressions', 200, 'Standards Track Work Product 02 April 2025 - Page 200 of 276Copyright © OASIS Open 2025. All Rights Reserved. name ends in _bin or _hex), then the UNICODE flag MUST NOT be specified. Set Operator Description Example a ISSUBSET b When a is a set that is wholly contained by the set b, the Comparison Expression evaluates to true. a MUST be an Object Path referring to the value property of an Object of type ipv4-addr or ipv6-addr. b MUST be a valid string representation of the corresponding Object type (as defined in section 6). For example, if ipv4-addr:value was 198.51.100.0/27, ISSUBSET ‘198.51.100.0/24’ would evaluate to true. In the case that both a and b evaluate to an identical single IP address or an identical IP subnet, the Comparison Expression evaluates to true. ipv4-addr:value ISSUBSET ''198.51.100.0/24'' a ISSUPERSET b When a is a set that wholly contains the set specified by b, the Comparison Expression evaluates to true.', 'vec_doc-10-oasis-stix21-p200-460', 0, 236, 'v2.1.0', '8163fda9c0e15c2be1d5c5b68294e9c970ff4e2e0002672456782480baafcc15', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"9.6 Comparison Expressions","subsection":"UNKNOWN","table_id":null,"page":200,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":460,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"9.6 Comparison Expressions"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p200-461', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '9.6 Comparison Expressions', 200, 'a MUST be an Object Path referring either an ipv4-addr or ipv6- addr Object. b MUST be a valid string representation of the corresponding Object type (as defined in section 6). For example, if ipv4-addr:value was 198.51.100.0/24, ISSUPERSET ‘198.51.100.0/27’ would evaluate to true. In the case that both a and b evaluate to an identical single IP address or an identical IP subnet, the Comparison Expression evaluates to true. ipv4-addr:value ISSUPERSET ''198.51.100.0/24'' EXISTS a a MUST be an Object Path which specifies a single property that MUST exist on the Object specified by the Observation Expression in order for the Comparison Expression to evaluate to true. For example, EXISTS windows-registry-key:values would evaluate to true on a registry key that contains a ‘values’ property (regardless of its contents).', 'vec_doc-10-oasis-stix21-p200-461', 0, 206, 'v2.1.0', '7bfbd4eecefaeb96c8452079ca125a0a471ecda8f5d324a92fae6cc707918179', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"9.6 Comparison Expressions","subsection":"UNKNOWN","table_id":null,"page":200,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":461,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"9.6 Comparison Expressions"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p200-462', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '9.6 Comparison Expressions', 200, 'EXISTS windows- registry-key:values 9.6.2 String Comparison For simple string operators, i.e., “=”, “?=”, “<”, “>”, “?=” and “?=”, as collation languages and methods are unspecifiable, a simple code point (binary) comparison MUST be used. If one string is longer than the other, but otherwise equal, the longer string is greater than, but not equal to, the shorter string. Unicode normalization MUST NOT be performed on the string. This means that combining marks [Davis] are sorted by their code point, not the NFC normalized value. E.g. ‘o’ U+006f < ‘oz’ U+006f U+007a < ‘ò’ U+006f U+0300 < ‘z’ U+007a < ‘ò’ U+00f2. Although Unicode recommends normalizing strings for comparisons, the use of combining marks may be significant, and normalizing by default would remove this information. NFC normalization is, however, required for other Comparison Operators, e.g., LIKE and MATCHES.', 'vec_doc-10-oasis-stix21-p200-462', 0, 221, 'v2.1.0', '4e4c654a1efd632cf5b87d64f155a893110ada88a7859c86a82889eaeec602af', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"9.6 Comparison Expressions","subsection":"UNKNOWN","table_id":null,"page":200,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":462,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"9.6 Comparison Expressions"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p200-463', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '9.6 Comparison Expressions', 200, '9.6.3 Binary Type Comparison When the value of two binary object properties are compared, they are compared as unsigned octets. That is, 00 is less than ff. If one value is longer than the other, but they are otherwise equal, the longer', 'vec_doc-10-oasis-stix21-p200-463', 0, 59, 'v2.1.0', '4154bf81e5e173c48b31b41d434529a30522ad60bbda07e101f0fe406054f6f7', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"9.6 Comparison Expressions","subsection":"UNKNOWN","table_id":null,"page":200,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":463,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"9.6 Comparison Expressions"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p201-464', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '9.6 Comparison Expressions', 201, 'Standards Track Work Product 02 April 2025 - Page 201 of 276Copyright © OASIS Open 2025. All Rights Reserved. value is considered greater than, but not equal to, the shorter value. 9.6.4 Native Format Comparison The SCO’s value MUST be in its native format when doing the comparison. For example, Cyber- observable Object properties that use the binary type (defined in section 2.1) must have their value decoded into its constituent bytes prior to comparison. This also means that Object Properties which use the hex type must be decoded into raw octets prior to being evaluated. In cases where a binary SCO property (i.e., one ending with **_bin** or **_hex) is evaluated against astring constant, the string constant MUST** be converted into a binary constant when all of the constituent string code points are less than U+0100. If this conversion is not possible, the comparison MUST evaluate to false, unless the comparison operator is ?=, in which case it MUST evaluate to true. For example, given the following object, where the payload_bin property is of binary type: { "0":{ "type": "artifact", "mime_type": "application/octet-stream", "payload_bin": "dGhpcyBpcyBhIHRlc3Q=" } } The pattern "artifact:payload_bin = ''dGhpcyBpcyBhIHRlc3Q=''" would evaluate to false, while the following patterns would all evaluate to true: "artifact:payload_bin = ''this is a test''", "artifact:payload_bin = b''dGhpcyBpcyBhIHRlc3Q=''", and "artifact:payload_bin = h''7468697320697320612074657374''".', 'vec_doc-10-oasis-stix21-p201-464', 0, 371, 'v2.1.0', 'c126e7258ff4b74272acc5bc3f151c435eaf7493db785fe3698cff707bf11f8a', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"9.6 Comparison Expressions","subsection":"UNKNOWN","table_id":null,"page":201,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":464,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"9.6 Comparison Expressions"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p201-465', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '9.7 Object Path Syntax', 201, 'Defined below is the syntax for addressing properties of SCOs within a STIX Pattern. The following notation is used throughout the definitions below: Notation Definition <object-type> The type of SCO to match against. This MUST be the value of the type field specified for a given SCO in an Observation. <property_name> The name of a SCO property to match against. This MUST be a valid property name as specified in the definition of the SCO type referenced by the <object- type> notation. If the <property_name> contains a hyphen-minus (‘-’ U+002d) or a full stop (‘.’ U+002e), the <property_name> MUST be enclosed in apostrophes (’’’ U+0027).', 'vec_doc-10-oasis-stix21-p201-465', 0, 161, 'v2.1.0', '01103fd389a9aa74a65dfc938349fad8d754200d0b5a540c9aa5451cc165f13f', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"9.7 Object Path Syntax","subsection":"UNKNOWN","table_id":null,"page":201,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":465,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"9.7 Object Path Syntax"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p202-466', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '9.7 Object Path Syntax', 202, 'Standards Track Work Product 02 April 2025 - Page 202 of 276Copyright © OASIS Open 2025. All Rights Reserved. Properties that are nested (i.e., are children of other properties in a SCO) MUST be specified using the syntax <property_name>.<property_name>, where the <property_name> preceding the ’‘.’ is the name of the parent property and the one following is the name of the child property. If the property name is a reference to another SCO, the referenced Object MUST be dereferenced, so that its properties function as if they are nested in the Object that it is referenced by. For example, if the src_ref property of the Network Traffic object references an IPv4 Address object, the value of this IPv4 address would be specified by network-traffic:src_ref.value. NOTE: the STIX Patterning language currently does not support specifying and/or dereferencing top-level relationships between SCOs as part of its object syntax.', 'vec_doc-10-oasis-stix21-p202-466', 0, 232, 'v2.1.0', '5a3f18754f084c98205c4dcac1312104d730632e6a27f8a8ae69ece0b7362807', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"9.7 Object Path Syntax","subsection":"UNKNOWN","table_id":null,"page":202,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":466,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"9.7 Object Path Syntax"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p202-467', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '9.7 Object Path Syntax', 202, 'Therefore, it is recommended to use the deprecated embedded relationships for this purpose, if necessary. 9.7.1 Basic Object Properties Any non-dictionary and non-list property that is directly specified on a SCO. Syntax <object-type>:<property_name> Example file:size 9.7.2 List Object Properties Any property on a SCO that uses the list data type. Syntax <object-type>:<property_name>[list_index].<property_name> Where the first property_name MUST be the name of an Object property of type list and list_index MUST be one of the following: - An integer in the range of 0… N-1, where N is the length of the list. If list_index is out of range, the result of any operation is false. - The literal ’#*’ indicates that all of the items in the list shall be tried as a value to be evaluated with the Comparison Operator and other value. If any of these evaluations are true, then the result is true. Examples file:extensions.''windows-pebinary-ext''.sections[*].entropy network-traffic:protocols[0] 9.7.3.', 'vec_doc-10-oasis-stix21-p202-467', 0, 250, 'v2.1.0', 'b875586ea3b1ad73be1a48c6fd11071957f4c6925044b10c9841c4b4984ea0c8', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"9.7 Object Path Syntax","subsection":"UNKNOWN","table_id":null,"page":202,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":467,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"9.7 Object Path Syntax"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p202-468', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '9.7 Object Path Syntax', 202, 'Dictionary Object Properties Any property on an SCO that uses the dictionary data type. Syntax <object-type>:<property_name>.<key_name> Where MUST be the name of an Object property of type dictionary and MUST be the name of key inthe dictionary.', 'vec_doc-10-oasis-stix21-p202-468', 0, 62, 'v2.1.0', '91314cd0d8fee6ec6160393a4bd8561e9a8e0feefef11346abc6ab9f1eca0f1d', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"9.7 Object Path Syntax","subsection":"UNKNOWN","table_id":null,"page":202,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":468,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"9.7 Object Path Syntax"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p203-469', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '9.7 Object Path Syntax', 203, 'Standards Track Work Product 02 April 2025 - Page 203 of 276Copyright © OASIS Open 2025. All Rights Reserved. Examples file:hashes.ssdeep file:extensions.''raster-image-ext''.image_height 9.7.4. Object Reference Properties Any property on an SCO that represents an embedded relationship and uses the identifier data type, either as a singleton or as a list (i.e., list of type identifier). Syntax <object-type>:<property_name>.<dereferenced_object_property> Where MUST be the name of an Object property that represents an embedded relationships and is of type identifier and MUST be the name of a valid property of the dereferenced Object (i.e., the Object in an Observation that is referenced via ). For example, when processing the Observed Data SDO that uses the object_refs property instead of the deprecated objects property, only those SCO’s that are listed in the object_refs may be followed.', 'vec_doc-10-oasis-stix21-p203-469', 0, 225, 'v2.1.0', '98c6d093287e287e4967055090015d40703954538be8cf5d097919a2dd43e251', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"9.7 Object Path Syntax","subsection":"UNKNOWN","table_id":null,"page":203,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":469,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"9.7 Object Path Syntax"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p203-470', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '9.7 Object Path Syntax', 203, 'This means that if the object identifier is not listed in object_refs property, then that object is considered not found, and any references to properties of that object are considered not present. For cases where represents a list of embedded relationships and is a list of type identifier, the corresponding syntax applies: <object-type>:<property_name>[list_index].<dereferenced_object_property> Accordingly, the same semantics for list indices as defined in section 9.7.2 apply in this case. Examples email-message:from_ref.value directory:contains_refs[*].name 9.8. Examples Note: the examples below are NOT JSON encoded. This means that some characters, like double quotes, are not escaped, though they will be when encoded in a JSON string.', 'vec_doc-10-oasis-stix21-p203-470', 0, 187, 'v2.1.0', '00d2544694701c5ea33b3b3857bdf6848f7ddcc8be675b178449b872119b6d66', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"9.7 Object Path Syntax","subsection":"UNKNOWN","table_id":null,"page":203,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":470,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"9.7 Object Path Syntax"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p203-471', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '9.7 Object Path Syntax', 203, 'Matching a File with a SHA-256 hash [file:hashes.''SHA-256'' = ''aec070645fe53ee3b3763059376134f058cc337247c978add178b6ccdfb0019f''] Matching an Email Message with a particular From Email Address and Attachment File Name Using a Regular Expression [email-message:from_ref.value MATCHES ''.+\\@example\\.com$'' AND email- message:body_multipart[*].body_raw_ref.name MATCHES ''^Final Report.+\\.exe$''] Matching a File with a SHA-256 hash and a PDF MIME type', 'vec_doc-10-oasis-stix21-p203-471', 0, 112, 'v2.1.0', '04a7e636a538cae9081448a87a5b9a2ee8e193959d975d173b62984c1d0a1d81', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"9.7 Object Path Syntax","subsection":"UNKNOWN","table_id":null,"page":203,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":471,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"9.7 Object Path Syntax"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p204-472', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '9.7 Object Path Syntax', 204, 'Standards Track Work Product 02 April 2025 - Page 204 of 276Copyright © OASIS Open 2025. All Rights Reserved.', 'vec_doc-10-oasis-stix21-p204-472', 0, 28, 'v2.1.0', '2a5622832a5f7c1e4525bc153d3e8d952ee580454eef9ce352cf83cf0ad5be9c', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"9.7 Object Path Syntax","subsection":"UNKNOWN","table_id":null,"page":204,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":472,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"9.7 Object Path Syntax"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p204-473', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '9.7 Object Path Syntax', 204, '[file:hashes.''SHA-256'' = ''aec070645fe53ee3b3763059376134f058cc337247c978add178b6ccdfb0019f'' AND file:mime_type = ''application/x-pdf''] Matching a File with SHA-256 or a MD5 hash (e.g., for the case of two different end point tools generating either an MD5 or a SHA-256), and a different File that has a different SHA-256 hash, against two different Observations [file:hashes.''SHA-256'' = ''bf07a7fbb825fc0aae7bf4a1177b2b31fcf8a3feeaf7092761e18c859ee52a9c'' OR file:hashes.MD5 = ''cead3f77f6cda6ec00f57d76c9a6879f''] AND [file:hashes.''SHA-256'' = ''aec070645fe53ee3b3763059376134f058cc337247c978add178b6ccdfb0019f''] Matching a File with a MD5 hash, followed by (temporally) a Registry Key object that matches a value, within 5 minutes ([file:hashes.MD5 = ''79054025255fb1a26e4bc422aef54eb4''] FOLLOWEDBY [windows-registry-key:key = ''HKEY_LOCAL_MACHINE\\foo\\bar'']) WITHIN 300 SECONDS Matching three different, but specific Unix User Accounts [user-account:account_type = ''unix'' AND user-account:user_id = ''1007'' AND user-account:account_login = ''Peter''] AND [user-account:account_type = ''unix'' AND user-account:user_id = ''1008'' AND user- account:account_login = ''Paul''] AND [user-account:account_type = ''unix'' AND user-account:user_id = ''1009'' AND user-account:account_login = ''Mary''] Matching an Artifact object PCAP payload header [artifact:mime_type = ''application/vnd.tcpdump.pcap'' AND artifact:payload_bin MATCHES ''\\xd4\\xc3\\xb2\\xa1\\x02\\x00\\x04\\x00''] Matching a File object with a Windows file path [file:name = ''foo.dll'' AND file:parent_directory_ref.path = ''C:\\Windows\\System32''] Matching on a Windows PE File with high section entropy [file:extensions.''windows-pebinary-ext''.sections[*].entropy > 7.0] Matching on a mismatch between a File object magic number and mime type [file:mime_type = ''image/bmp'' AND file:magic_number_hex = h''ffd8'']', 'vec_doc-10-oasis-stix21-p204-473', 0, 462, 'v2.1.0', '616a756d1c5bb10cde4d805aaa9e83af9b37b35b1a5184758474836b22aba906', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"9.7 Object Path Syntax","subsection":"UNKNOWN","table_id":null,"page":204,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":473,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"9.7 Object Path Syntax"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p205-474', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '9.7 Object Path Syntax', 205, 'Standards Track Work Product 02 April 2025 - Page 205 of 276Copyright © OASIS Open 2025. All Rights Reserved. Matching on Network Traffic with a particular destination [network-traffic:dst_ref.type = ''ipv4-addr'' AND network-traffic:dst_ref.value = ''203.0.113.33/32''] Matching on Malware Beaconing to a Domain Name [network-traffic:dst_ref.type = ''domain-name'' AND network-traffic:dst_ref.value = ''example.com''] REPEATS 5 TIMES WITHIN 1800 SECONDS Matching on a Domain Name with IPv4 Resolution [domain-name:value = ''www.5z8.info'' AND domain-name:resolves_to_refs[*].value = ''198.51.100.1/32''] Matching on a URL [url:value = ''http://example.com/foo'' OR url:value = ''http://example.com/bar''] Matching on an X509 Certificate [x509-certificate:issuer = ''CN=WEBMAIL'' AND x509-certificate:serial_number = ''4c:0b:1d:19:74:86:a7:66:b4:1a:bf:40:27:21:76:28''] Matching on a Windows Registry Key [windows-registry-key:key = ''HKEY_CURRENT_USER\\Software\\CryptoLocker\\Files'' OR windows-registry-key:key = ''HKEY_CURRENT_USER\\Software\\Microsoft\\CurrentVersion\\Run\\CryptoLocker_0388''] Matching on a File with a set of properties [(file:name = ''pdf.exe'' OR file:size = 371712) AND file:created = t''2014-01-13T07:03:17Z''] Matching on an Email Message with specific Sender and Subject [email-message:sender_ref.value = ''jdoe@example.com'' AND email-message:subject = ''Conference Info''] Matching on a Custom USB Device [x-usb-device:usbdrive.serial_number = ''575833314133343231313937'']', 'vec_doc-10-oasis-stix21-p205-474', 0, 368, 'v2.1.0', '4ba8006aa35fafe4ef7855c9fbde9ff7e334db0d7037c1e2dd8a947327300801', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"9.7 Object Path Syntax","subsection":"UNKNOWN","table_id":null,"page":205,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":474,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"9.7 Object Path Syntax"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p206-475', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '9.7 Object Path Syntax', 206, 'Standards Track Work Product 02 April 2025 - Page 206 of 276Copyright © OASIS Open 2025. All Rights Reserved. Matching on Two Processes Launched with a Specific Set of Command Line Arguments Within a Certain Time Window [process:command_line MATCHES ''^.+>-add GlobalSign.cer -c -s -r localMachine Root$''] FOLLOWEDBY [process:command_line MATCHES''^.+>-add GlobalSign.cer -c -s -r localMachineTrustedPublisher$''] WITHIN 300 SECONDS Matching on a Network Traffic IP that is part of a particular Subnet [network-traffic:dst_ref.value ISSUBSET ''2001:0db8:dead:beef:0000:0000:0000:0000/64''] Matching on several different combinations of Malware Artifacts. Note the following pattern requires that both a file and registry key exist, or that one of two processes exist. ([file:name = ''foo.dll''] AND [windows-registry-key:key = ''HKEY_LOCAL_MACHINE\\foo\\bar'']) OR [process:image_ref.name = ''fooproc'' OR process:image_ref.name = ''procfoo'']', 'vec_doc-10-oasis-stix21-p206-475', 0, 233, 'v2.1.0', '97a2c1f8b46ee41d1d1790d4a257efed35b166d384447cccb7398c697737a06a', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"9.7 Object Path Syntax","subsection":"UNKNOWN","table_id":null,"page":206,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":475,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"9.7 Object Path Syntax"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p207-476', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '10. STIX Vocabularies', 207, 'The following sections provide object-specific listings for each of the vocabularies referenced in the object description sections defined in section 4, section 5, section 6, and section 7. STIX vocabularies that have type names ending in ‘-ov’, are “open”: they provide a listing of common and industry accepted terms as a guide to the user but do not limit the user to that defined list. These vocabularies are referenced from the STIX Objects as type open-vocab and have a statement indicating which vocabulary should be used. STIX vocabularies that have type names ending in ‘-enum’ are “closed”: the only valid values are those in the vocabulary. These vocabularies are referenced from the STIX Objects as type enum and have a statement indicating which enumeration must be used.', 'vec_doc-10-oasis-stix21-p207-476', 0, 196, 'v2.1.0', 'bd9550fd3bc3b16c7586dc85f787a9bcf8a8350a07c763c97fbba9210e5801d7', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"10. STIX Vocabularies","subsection":"UNKNOWN","table_id":null,"page":207,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":476,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"10. STIX Vocabularies"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p207-477', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '10.1 Account Type Vocabulary', 207, 'Vocabulary Name: account-type-ov The account type vocabulary is currently used in the following SCOs: - User Account An open vocabulary of User Account types. Vocabulary Summary facebook, ldap, nis, openid, radius, skype, tacacs, twitter, unix, windows-local, windows-domain Vocabulary Value Description facebook Specifies a Facebook account. ldap Specifies an LDAP account. nis Specifies a NIS account. openid Specifies an OpenID account. radius Specifies a RADIUS account. skype Specifies a Skype account. tacacs Specifies a TACACS account. twitter Specifies a Twitter account. unix Specifies a POSIX account. windows-local Specifies a Windows local account. windows-domain Specifies a Windows domain account.', 'vec_doc-10-oasis-stix21-p207-477', 0, 178, 'v2.1.0', 'f23dc532d99f98c2e33296c99db8160d8066c326239610e6fbcbef121a6ffdd6', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"10.1 Account Type Vocabulary","subsection":"UNKNOWN","table_id":null,"page":207,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":477,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"10.1 Account Type Vocabulary"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p207-478', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '10.2 Attack Motivation Vocabulary', 207, 'Vocabulary Name: attack-motivation-ov The attack motivation vocabulary is currently used in the following SDOs: - Intrusion Set - Threat Actor', 'vec_doc-10-oasis-stix21-p207-478', 0, 36, 'v2.1.0', 'c0783c7e25bd65b5beaaf005d998e0289a8d9e249ba45b4ce58dd21764c349ef', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"10.2 Attack Motivation Vocabulary","subsection":"UNKNOWN","table_id":null,"page":207,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":478,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"10.2 Attack Motivation Vocabulary"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p208-479', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '10.2 Attack Motivation Vocabulary', 208, 'Standards Track Work Product 02 April 2025 - Page 208 of 276Copyright © OASIS Open 2025. All Rights Reserved. Knowing a Threat Actor or Intrusion Set’s motivation may allow an analyst or defender to better understand likely targets and behaviors. Motivation shapes the intensity and the persistence of an attack. Threat Actors and Intrusion Sets usually act in a manner that reflects their underlying emotion or situation, and this informs defenders of the manner of attack. For example, a cyber-vandal out for notoriety can create an intense and attention- grabbing attack but may quickly lose interest and move on. Understanding these differences allows defenders to implement controls tailored to each type of attack for greatest efficiency.', 'vec_doc-10-oasis-stix21-p208-479', 0, 186, 'v2.1.0', 'ef935b0dfc4a9430b38af5cd8b818ae351968c35ed4567218bd2d350b467672b', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"10.2 Attack Motivation Vocabulary","subsection":"UNKNOWN","table_id":null,"page":208,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":479,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"10.2 Attack Motivation Vocabulary"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p208-480', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '10.2 Attack Motivation Vocabulary', 208, 'Vocabulary Summary accidental, coercion, dominance, ideology, notoriety, organizational-gain, personal-gain, personal-satisfaction, revenge, unpredictable Vocabulary Value Description accidental A non-hostile actor whose benevolent or harmless intent inadvertently causes harm. For example, a well-meaning and dedicated employee who through distraction or poor training unintentionally causes harm to his or her organization. coercion Being forced to act on someone else’s behalf. Adversaries who are motivated by coercion are often forced through intimidation or blackmail to act illegally for someone else’s benefit. Unlike the other motivations, a coerced person does not act for personal gain, but out of fear of incurring a loss. dominance A desire to assert superiority over someone or something else. Adversaries who are seeking dominance over a target are focused on using their power to force their target into submission or irrelevance.', 'vec_doc-10-oasis-stix21-p208-480', 0, 237, 'v2.1.0', 'e9788cf268bc6d35eefe333e180237cece8c047ab962dc4b2da1f23237035cb7', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"10.2 Attack Motivation Vocabulary","subsection":"UNKNOWN","table_id":null,"page":208,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":480,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"10.2 Attack Motivation Vocabulary"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p208-481', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '10.2 Attack Motivation Vocabulary', 208, 'ideology A passion to express a set of ideas, beliefs, and values that may shape and drive harmful and illegal acts. Adversaries who act for ideological reasons are not usually motivated primarily by the desire for profit; they are acting on their own sense of morality, justice, or political loyalty. For example, an activist group may sabotage a company’s equipment because they believe the company is harming the environment. notoriety Seeking prestige or to become well known through some activity. Adversaries motivated by notoriety are often seeking either personal validation or respect within a community and staying covert is not a priority. In fact, one of the main goals is to garner the respect of their target audience. organizational-gain Seeking advantage over a competing organization. Adversaries motivated by increased profit or other gains through an unfairly obtained competitive advantage are often seeking theft of', 'vec_doc-10-oasis-stix21-p208-481', 0, 234, 'v2.1.0', '3f35cbc71ffcc952921cf87db2e8102259fb3f3230ff3f26ceadb67f6527da0a', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"10.2 Attack Motivation Vocabulary","subsection":"UNKNOWN","table_id":null,"page":208,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":481,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"10.2 Attack Motivation Vocabulary"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p209-482', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '10.2 Attack Motivation Vocabulary', 209, 'Standards Track Work Product 02 April 2025 - Page 209 of 276Copyright © OASIS Open 2025. All Rights Reserved. intellectual property, business processes, or supply chain agreements and thus accelerating their position in a market or capability. personal-gain The desire to improve one’s own financial status. Adversaries motivated by a selfish desire for personal gain are often out for gains that come from financial fraud, hacking for hire, or intellectual property theft. While a Threat Actor or Intrusion Set may be seeking personal gain, this does not mean they are acting alone. Individuals can band together solely to maximize their own personal profits. personal-satisfaction A desire to satisfy a strictly personal goal, including curiosity, thrill- seeking, amusement, etc. Threat Actors or Intrusion Set driven by personal satisfaction may incidentally receive some other gain from their actions, such as a profit, but their primary motivation is to gratify a personal, emotional need.', 'vec_doc-10-oasis-stix21-p209-482', 0, 249, 'v2.1.0', '5c772643ce0cf03e0b93d270e8e79220420a41365f7cf38eb1589356c8bab217', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"10.2 Attack Motivation Vocabulary","subsection":"UNKNOWN","table_id":null,"page":209,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":482,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"10.2 Attack Motivation Vocabulary"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p209-483', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '10.2 Attack Motivation Vocabulary', 209, 'Individuals can band together with others toward a mutual, but not necessarily organizational, objective. revenge A desire to avenge perceived wrongs through harmful actions such as sabotage, violence, theft, fraud, or embarrassing certain individuals or the organization. A disgruntled Threat Actor or Intrusion Set seeking revenge can include current or former employees, who may have extensive knowledge to leverage when conducting attacks. Individuals can band together with others if the individual believes that doing so will enable them to cause more harm. unpredictable Acting without identifiable reason or purpose and creating unpredictable events. Unpredictable is not a miscellaneous or default category. Unpredictable means a truly random and likely bizarre event, whichseems to have no logical purpose to the victims.', 'vec_doc-10-oasis-stix21-p209-483', 0, 208, 'v2.1.0', '6037c7840436b67bde669effa6ce5bdf5e5c23020f9507b78438b943412934dc', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"10.2 Attack Motivation Vocabulary","subsection":"UNKNOWN","table_id":null,"page":209,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":483,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"10.2 Attack Motivation Vocabulary"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p209-484', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '10.3 Attack Resource Level Vocabulary', 209, 'Vocabulary Name: attack-resource-level-ov The attack resource level vocabulary is currently used in the following SDO(s): - Intrusion Set - Threat Actor Attack Resource Level is an open vocabulary that captures the general level of resources that a threat actor, intrusion set, or campaign might have access to. It ranges from individual, a person acting alone, to government, the resources of a national government. Vocabulary Summary individual, club, contest, team, organization, government VocabularyValue Description', 'vec_doc-10-oasis-stix21-p209-484', 0, 131, 'v2.1.0', 'a4739ba519cd1ae89f2507121f1c9baa02c4303fc1998478b007f28f639a0088', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"10.3 Attack Resource Level Vocabulary","subsection":"UNKNOWN","table_id":null,"page":209,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":484,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"10.3 Attack Resource Level Vocabulary"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p210-485', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '10.3 Attack Resource Level Vocabulary', 210, 'Standards Track Work Product 02 April 2025 - Page 210 of 276Copyright © OASIS Open 2025. All Rights Reserved. individual Resources limited to the average individual; Threat Actor acts independently. club Members interact on a social and volunteer basis, often with little personal interest in the specific target. An example might be a core group of unrelated activists who regularly exchange tips on a particular blog. Group persists long term. contest A short-lived and perhaps anonymous interaction that concludes when the participants have achieved a single goal. For example, people who break into systems just for thrills or prestige may hold a contest to see who can break into a specific target first. team A formally organized group with a leader, typically motivated by a specific goal and organized around that goal. Group persists long term and typically operates within a single geography. organization Larger and better resourced than a team; typically, a company or crime syndicate. Usually operates in multiple geographic areas and persists long term. government Controls public assets and functions within a jurisdiction; very well resourced and persists long term.', 'vec_doc-10-oasis-stix21-p210-485', 0, 296, 'v2.1.0', '1f8034d95e1b02832c9bbfcf29ca0d8c05fcaeb21b8b01e1bc8c54f7cad3ab56', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"10.3 Attack Resource Level Vocabulary","subsection":"UNKNOWN","table_id":null,"page":210,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":485,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"10.3 Attack Resource Level Vocabulary"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p210-486', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '10.4 Encryption Algorithm Enumeration', 210, 'Enumeration Name: encryption-algorithm-enum The encryption algorithm enumeration is currently used in the following SCOs: - Artifact An enumeration of encryption algorithms for sharing defanged and/or confidential artifacts. Enumeration Summary AES-256-GCM, ChaCha20-Poly1305, mime-type-indicated Enumeration Value Description AES-256-GCM Specifies the AES-256-GCM cipher, as defined in [NIST SP800-38D]. ChaCha20-Poly1305 Specifies the ChaCha20-Poly1305 stream cipher, as defined in [RFC7539]. mime-type-indicated The encryption algorithm is self-defined by the artifact’s data. The specified mime-type tells you which format it is, e.g., Word Doc or GPG. This is intended for formats like Zip files and Word files which take a simple password, or GPG armored files that contain the key blob along with the file.', 'vec_doc-10-oasis-stix21-p210-486', 0, 204, 'v2.1.0', '26ce159e07fd631f34405445991667b875520d6d28ff6aaf031bca8ac1b031b1', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"10.4 Encryption Algorithm Enumeration","subsection":"UNKNOWN","table_id":null,"page":210,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":486,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"10.4 Encryption Algorithm Enumeration"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p210-487', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '10.5 Extension Type Enumeration', 210, 'Enumeration Name: extension-type-enum The Extensions Type enumeration is used in the Extension meta-object. Enumeration Summary new-sdo, new-sco, new-sro, property-extension, toplevel-property-extension', 'vec_doc-10-oasis-stix21-p210-487', 0, 51, 'v2.1.0', '538aa35ad66ae355e9a8c68ac7dbbe0026236e3ce5f72e1cc6350d335983e99c', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"10.5 Extension Type Enumeration","subsection":"UNKNOWN","table_id":null,"page":210,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":487,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"10.5 Extension Type Enumeration"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p211-488', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '10.5 Extension Type Enumeration', 211, 'Standards Track Work Product 02 April 2025 - Page 211 of 276Copyright © OASIS Open 2025. All Rights Reserved. Enumeration Value Description new-sdo Specifies that the Extension includes a new SDO new-sco Specifies that the Extension includes a new SCO new-sro Specifies that the Extension includes a new SRO property-extension Specifies that the Extension includes additional properties for a given STIX Object. toplevel-property-extension Specifies that the Extension includes additional properties for a given STIX Object at the top-level. Organizations are encouraged to use the property-extension instead of this extension type.', 'vec_doc-10-oasis-stix21-p211-488', 0, 158, 'v2.1.0', 'eba62e37d6ef52563912d6574355fa165d2ce746d348e2ff3cfd05d41060d353', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"10.5 Extension Type Enumeration","subsection":"UNKNOWN","table_id":null,"page":211,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":488,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"10.5 Extension Type Enumeration"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p211-489', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '10.6 Grouping Context Vocabulary', 211, 'Vocabulary Name: grouping-context-ov The Grouping Context open vocabulary is currently used in the following object: - Grouping While the majority of this vocabulary is undefined (producers may use custom vocabulary entries), it has been added specifically to capture the suspicious-activity-event value. That value indicates that the information contained in the Grouping relates to a suspicious event. Vocabulary Summary suspicious-activity, malware-analysis, unspecified Vocabulary Value Description suspicious-activity A set of STIX content related to a particular suspicious activity event. malware-analysis A set of STIX content related to a particular malware instance or family. unspecified A set of STIX content contextually related but without any precise characterization of the contextual relationship between the objects.', 'vec_doc-10-oasis-stix21-p211-489', 0, 209, 'v2.1.0', 'fdd5780a012f62df82184ac4bfebf824df0d5659329495d8adaadc5ad1a5bb4a', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"10.6 Grouping Context Vocabulary","subsection":"UNKNOWN","table_id":null,"page":211,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":489,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"10.6 Grouping Context Vocabulary"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p211-490', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '10.7 Hashing Algorithm Vocabulary', 211, 'Vocabulary Name: hash-algorithm-ov The Hashing Algorithm open vocabulary is currently used in the following objects: - External Reference - Artifact - File - Alternate Data Stream - Windows™ PE Binary File - Windows™ PE Optional Header - Windows™ PE Section - X.509 Certificate A vocabulary of hashing algorithms. Vocabulary Summary MD5, SHA-1, SHA-256, SHA-512, SHA3-256, SHA3-512, SSDEEP, TLSH', 'vec_doc-10-oasis-stix21-p211-490', 0, 99, 'v2.1.0', 'ad570feb48b6b0a26f47295fef5d61d802ed27c0590a66fec4ad50a800b1839d', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"10.7 Hashing Algorithm Vocabulary","subsection":"UNKNOWN","table_id":null,"page":211,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":490,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"10.7 Hashing Algorithm Vocabulary"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p212-491', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '10.7 Hashing Algorithm Vocabulary', 212, 'Standards Track Work Product 02 April 2025 - Page 212 of 276Copyright © OASIS Open 2025. All Rights Reserved. Vocabulary Value Description MD5 Specifies the MD5 message digest algorithm. The corresponding hash string for this value MUST be a valid MD5 message digest as defined in [RFC1321]. SHA-1 Specifies the SHA-1 (secure-hash algorithm 1) cryptographic hash function. The corresponding hash string for this value MUST be a valid SHA-1 message digest as defined in [RFC3174]. SHA-256 Specifies the SHA-256 cryptographic hash function (part of the SHA2 family). The corresponding hash string for this value MUST be a valid SHA-256 message digest as defined in [RFC6234]. SHA-512 Specifies the SHA-512 cryptographic hash function (part of the SHA2 family). The corresponding hash string for this value MUST be a valid SHA-512 message digest as defined in [RFC6234]. SHA3-256 Specifies the SHA3-256 cryptographic hash function. The corresponding hash string for this value MUST be a valid SHA3-256 message digest as defined in [FIPS202]. SHA3-512 Specifies the SHA3-512 cryptographic hash function. The corresponding hash string for this value MUST be a valid SHA3-512 message digest as defined in [FIPS202]. SSDEEP Specifies the ssdeep fuzzy hashing algorithm. The corresponding hash string for this value MUST be a valid piecewise hash as defined in the [SSDEEP] specification. TLSH Specifies the TLSH fuzzy hashing algorithm. The corresponding hash string for this value MUST be a valid 35 byte long hash as defined in the [TLSH] specification.', 'vec_doc-10-oasis-stix21-p212-491', 0, 387, 'v2.1.0', 'dd0b1827d36297790e7a2d0e4a0bf4eea1c4f3f7239a789cc4846a6ceea7beda', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"10.7 Hashing Algorithm Vocabulary","subsection":"UNKNOWN","table_id":null,"page":212,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":491,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"10.7 Hashing Algorithm Vocabulary"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p212-492', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '10.8 Identity Class Vocabulary', 212, 'Vocabulary Name: identity-class-ov The identity class vocabulary is currently used in the following SDO(s): - Identity This vocabulary describes the type of entity that the Identity represents: whether it describes an organization, group, individual, or class. Vocabulary Summary individual, group, system, organization, class, unknown Vocabulary Value Description individual A single person. group An informal collection of people, without formal governance, such as a distributed hacker group. system A computer system, such as a SIEM. organization A formal organization of people, with governance, such as a company or country.', 'vec_doc-10-oasis-stix21-p212-492', 0, 158, 'v2.1.0', 'b7b44d616f97d3e3b352d7b14abb80147956ce6e44ad27ed55bc6532a26936f1', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"10.8 Identity Class Vocabulary","subsection":"UNKNOWN","table_id":null,"page":212,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":492,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"10.8 Identity Class Vocabulary"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p213-493', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '10.8 Identity Class Vocabulary', 213, 'Standards Track Work Product 02 April 2025 - Page 213 of 276Copyright © OASIS Open 2025. All Rights Reserved. class A class of entities, such as all hospitals, all Europeans, or the DomainAdministrators in a system. unknown It is unknown whether the classification is an individual, group, system, organization, or class. 10.9. Implementation Language Vocabulary Vocabulary Name: implementation-language-ov The implementation language vocabulary is currently used in the following SDO(s): - Malware This is a non-exhaustive, open vocabulary that covers common programming languages and is intended to characterize the languages that may have been used to implement a malware instance or family. Vocabulary Summary applescript, bash, c, c?+, c#, go, java, javascript, lua, objective-c, perl, php, powershell, python, ruby, rust, scala, swift, typescript, visual-basic, x86-32, x86- 64 Vocabulary Value Description applescript Specifies the AppleScript programming language. bash Specifies the Bash programming language. c Specifies the C programming language. c?+ Specifies the C++ programming language. c# Specifies the C# programming language. go Specifies the Go programming language. java Specifies the Java programming language. javascript Specifies the JavaScript programming language. lua Specifies the Lua programming language. objective-c Specifies the Objective-C programming language. perl Specifies the Perl programming language. php Specifies the PHP programming language. powershell Specifies the Windows Powershell programming language. python Specifies the Python programming language. ruby Specifies the Ruby programming language. rust Specifies the Rust programming language.', 'vec_doc-10-oasis-stix21-p213-493', 0, 423, 'v2.1.0', 'd0ca6db0a534a67062605283bcd860176eb470e71102f9e604c0fbea4064bf92', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"10.8 Identity Class Vocabulary","subsection":"UNKNOWN","table_id":null,"page":213,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":493,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"10.8 Identity Class Vocabulary"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p214-494', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '10.8 Identity Class Vocabulary', 214, 'Standards Track Work Product 02 April 2025 - Page 214 of 276Copyright © OASIS Open 2025. All Rights Reserved. scala Specifies the Scala programming language. swift Specifies the Swift programming language. typescript Specifies the TypeScript programming language. visual-basic Specifies the Visual Basic programming language. x86-32 Specifies the x86 32-bit Assembly programming language. x86-64 Specifies the x86 64-bit Assembly programming language.', 'vec_doc-10-oasis-stix21-p214-494', 0, 113, 'v2.1.0', '3544fd1476d37b9128222113ffea809f7c7eab76bc6f2f68d56c473e8713a025', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"10.8 Identity Class Vocabulary","subsection":"UNKNOWN","table_id":null,"page":214,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":494,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"10.8 Identity Class Vocabulary"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p214-495', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '10.10 Indicator Type Vocabulary', 214, 'Vocabulary Name: indicator-type-ov The indicator type vocabulary is currently used in the following SDO(s): - Indicator Indicator type is an open vocabulary used to categorize Indicators. It is intended to be high-level to promote consistent practices. Indicator types should not be used to capture information that can be better captured via related Malware or Attack Pattern objects. It is better to link an Indicator to a Malware object describing Poison Ivy rather than simply providing a type or label of “poison-ivy”. Vocabulary Summary anomalous-activity, anonymization, benign, compromised, malicious-activity, attribution, unknown Vocabulary Value Description anomalous-activity Unexpected, or unusual activity that may not necessarily be malicious or indicate compromise. This type of activity may include reconnaissance-like behavior such as port scans or version identification, network behavior anomalies, and asset and/or user behavioral anomalies. anonymization Suspected anonymization tools or infrastructure (proxy, TOR, VPN, etc.). benign Activity that is not suspicious or malicious in and of itself, but when combined with other activity may indicate suspicious or malicious behavior. compromised Assets that are suspected to be compromised. malicious-activity Patterns of suspected malicious objects and/or activity. attribution Patterns of behavior that indicate attribution to a particular Threat Actor or Campaign. unknown There is not enough information available to determine the type of indicator.', 'vec_doc-10-oasis-stix21-p214-495', 0, 381, 'v2.1.0', '34cd89eaee8d74bd4831f375a903edc12e37f44369d4ee62558defb989449616', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"10.10 Indicator Type Vocabulary","subsection":"UNKNOWN","table_id":null,"page":214,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":495,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"10.10 Indicator Type Vocabulary"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p214-496', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '10.11 Industry Sector Vocabulary', 214, 'Vocabulary Name: industry-sector-ov The industry sector vocabulary is currently used in the following SDO(s): - Identity', 'vec_doc-10-oasis-stix21-p214-496', 0, 30, 'v2.1.0', '32eab1a25300b89b832715f311398b2633b80aeda9728ec3df38736f84cf17e9', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"10.11 Industry Sector Vocabulary","subsection":"UNKNOWN","table_id":null,"page":214,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":496,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"10.11 Industry Sector Vocabulary"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p215-497', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '10.11 Industry Sector Vocabulary', 215, 'Standards Track Work Product 02 April 2025 - Page 215 of 276Copyright © OASIS Open 2025. All Rights Reserved. Industry sector is an open vocabulary that describes industrial and commercial sectors. It is intended to be holistic; it has been derived from several other lists and is not limited to “critical infrastructure” sectors. Vocabulary Summary agriculture, aerospace, automotive, chemical, commercial, communications, construction, defense, education, energy, entertainment, financial-services, government (emergency-services, government-local, government-national, government-public-services, government-regional), healthcare, hospitality- leisure, infrastructure (dams, nuclear, water), insurance, legal, manufacturing, mining, non-profit, pharmaceuticals, retail, technology, telecommunications, transportation, utilities Vocabulary Value Description agriculture Relates to the agricultural industry sector.', 'vec_doc-10-oasis-stix21-p215-497', 0, 229, 'v2.1.0', 'abe97d00e9382e4df7cd3b47534bdff0dd226db9b4332a390c82d632959ecd4c', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"10.11 Industry Sector Vocabulary","subsection":"UNKNOWN","table_id":null,"page":215,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":497,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"10.11 Industry Sector Vocabulary"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p215-498', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '10.11 Industry Sector Vocabulary', 215, 'aerospace Relates to the aerospace industry sector, including the design, manufacture, and operation of aircraft and spacecraft. automotive Relates to the automotive industry sector, including the design, manufacture, and sale of motor vehicles. chemical Relates to the chemical industry sector, including the production of chemicals and chemical products. commercial Relates to the commercial sector, including businesses engaged in commerce, trade, and services. communications Relates to the communications sector, including telecommunications, broadcasting, and related services. construction Relates to the construction industry sector, including building, civil engineering, and infrastructure development. defense Relates to the defense industry sector, including military, defense contractors, and related organizations. education Relates to the education sector, including schools, universities, and other educational institutions.', 'vec_doc-10-oasis-stix21-p215-498', 0, 235, 'v2.1.0', '30b2883dd6efe912189b2b6c324209eb2321789fb2d88c55722604ffeb6ce4a3', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"10.11 Industry Sector Vocabulary","subsection":"UNKNOWN","table_id":null,"page":215,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":498,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"10.11 Industry Sector Vocabulary"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p215-499', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '10.11 Industry Sector Vocabulary', 215, 'energy Relates to the energy sector, including the production and distribution of electricity, oil, gas, and renewable energy. entertainment Relates to the entertainment sector, including media, film, music, and related industries. financial-services Relates to the financial services sector, including banking, investment, insurance, and related services. government Relates to the government sector, including all levels of government and public administration. emergency-services Relates to emergency services, including police, fire, ambulance, and disaster response organizations.', 'vec_doc-10-oasis-stix21-p215-499', 0, 147, 'v2.1.0', '66320da9026270c16dae274beb8916fdccbd7f68aba750385ce4878f25438aed', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"10.11 Industry Sector Vocabulary","subsection":"UNKNOWN","table_id":null,"page":215,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":499,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"10.11 Industry Sector Vocabulary"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p216-500', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '10.11 Industry Sector Vocabulary', 216, 'Standards Track Work Product 02 April 2025 - Page 216 of 276Copyright © OASIS Open 2025. All Rights Reserved. government-local Relates to local government entities, such as city, municipal,or county administrations. government-national Relates to national or federal government entities. government-public-services Relates to government-provided public services, such as sanitation, public health, and welfare. government-regional Relates to regional government entities, such as state or provincial administrations. healthcare Relates to the healthcare sector, including hospitals, clinics, and other medical service providers. hospitality-leisure Relates to the hospitality and leisure sector, including hotels, restaurants, travel, and recreation services. infrastructure Relates to critical infrastructure sectors that support the functioning of society and the economy. dams Relates to the infrastructure sector focused on dams and water retention structures.', 'vec_doc-10-oasis-stix21-p216-500', 0, 241, 'v2.1.0', '67bbc3bb5232be7dce4613e29597614403b2fd7cfbc551e859283a3f48530ef5', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"10.11 Industry Sector Vocabulary","subsection":"UNKNOWN","table_id":null,"page":216,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":500,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"10.11 Industry Sector Vocabulary"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p216-501', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '10.11 Industry Sector Vocabulary', 216, 'nuclear Relates to the infrastructure sector focused on nuclear power generation and facilities. water Relates to the infrastructure sector focused on water supply, treatment, and distribution. insurance Relates to the insurance sector, including companies providing risk management and insurance products. legal Relates to the legal sector, including law firms, courts, and legal services providers. manufacturing Relates to the manufacturing sector, including the production of goods and industrial products. mining Relates to the mining sector, including extraction of minerals, metals, and other natural resources. non-profit Relates to the non-profit sector, including charitable, humanitarian, and non-governmental organizations. pharmaceuticals Relates to the pharmaceuticals sector, including drug development, manufacturing, and distribution. retail Relates to the retail sector, including businesses selling goods and services directly to consumers.', 'vec_doc-10-oasis-stix21-p216-501', 0, 240, 'v2.1.0', '1d540116affe3f15fbc5c6b4b8181c5111d941169e1f418124005e195de4a419', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"10.11 Industry Sector Vocabulary","subsection":"UNKNOWN","table_id":null,"page":216,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":501,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"10.11 Industry Sector Vocabulary"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p216-502', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '10.11 Industry Sector Vocabulary', 216, 'technology Relates to the technology sector, including software, hardware, and IT services companies. telecommunications Relates to the telecommunications sector, including providers of voice, data, and internet services.', 'vec_doc-10-oasis-stix21-p216-502', 0, 56, 'v2.1.0', '01e2b5cf50da1e30aafbb2269f2f540749f139256738f655be43d9f5d346f503', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"10.11 Industry Sector Vocabulary","subsection":"UNKNOWN","table_id":null,"page":216,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":502,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"10.11 Industry Sector Vocabulary"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p217-503', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '10.12 Infrastructure Type Vocabulary', 217, 'Vocabulary Name: infrastructure-type-ov The infrastructure type vocabulary is currently used in the following SDO(s): - Infrastructure A non-exhaustive enumeration of infrastructure types. Vocabulary Summary amplification, anonymization, botnet, command-and-control, control-system, exfiltration, firewall, hosting-malware, hosting-target-lists, phishing, reconnaissance, routers-switches, staging, workstation, unknown Vocabulary Value Description amplification Specifies infrastructure used for conducting amplification attacks. anonymization Specific infrastructure used for anonymization, such as a proxy. botnet Specifies the membership/makeup of a botnet, in terms of the network addresses of the hosts that comprise the botnet. command-and-control Specifies infrastructure used for command and control (C2). This is typically a domain name or IP address. control-system Specifies equipment such as IoT, HMI, RTU, PLC or other ICS devices. exfiltration Specifies infrastructure used as an endpoint for data exfiltration. firewall Specifies a device that inspects network traffic and restricts it based upon defined policies. hosting-malware Specifies infrastructure used for hosting malware. hosting-target-lists Specifies infrastructure used for hosting a list of targets for DDOS attacks, phishing, and other malicious activities. This is typically a domain name or IP address. phishing Specifies infrastructure used for conducting phishing attacks. reconnaissance Specifies infrastructure used for conducting reconnaissance activities. routers-switches Specifies IT infrastructure used to connect devices to the network. staging Specifies infrastructure used for staging. workstation Specifies an endpoint machine used for work by an organization that needs protection.', 'vec_doc-10-oasis-stix21-p217-503', 0, 445, 'v2.1.0', 'f0483412c965a9b6d8369668393834f5604624eed3b452809c4d1cfedb276523', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"10.12 Infrastructure Type Vocabulary","subsection":"UNKNOWN","table_id":null,"page":217,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":503,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"10.12 Infrastructure Type Vocabulary"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p218-504', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '10.13 Malware Capabilities Vocabulary', 218, 'Vocabulary Name: malware-capabilities-ov The malware capabilities vocabulary is currently used in the following SDO(s): - Malware This is an open vocabulary that covers common capabilities that may be exhibited by a malware instance or family.', 'vec_doc-10-oasis-stix21-p218-504', 0, 61, 'v2.1.0', '2714d6f23709a5e93ee70a157eabbfc4f922ac9dad45b8bcb70437a214810e31', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"10.13 Malware Capabilities Vocabulary","subsection":"UNKNOWN","table_id":null,"page":218,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":504,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"10.13 Malware Capabilities Vocabulary"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p218-505', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '10.13 Malware Capabilities Vocabulary', 218, 'Vocabulary Summary accesses-remote-machines, anti-debugging, anti-disassembly, anti-emulation, anti-memory-forensics, anti-sandbox, anti-vm, captures-input-peripherals, captures-output-peripherals, captures-system-state-data, cleans-traces-of- infection, commits-fraud, communicates-with-c2, compromises-data-availability, compromises-data-integrity, compromises-system-availability, controls-local- machine, degrades-security-software, degrades-system-updates, determines-c2- server, emails-spam, escalates-privileges, evades-av, exfiltrates-data, fingerprints-host, hides-artifacts, hides-executing-code, infects-files, infects-remote-machines, installs-other-components, persists-after-system- reboot, prevents-artifact-access, prevents-artifact-deletion, probes-network- environment, self-modifies, steals-authentication-credentials, violates- system-operational-integrity Vocabulary Value Description accesses-remote-machines Indicates that the malware instance or family is able to access one or more remote machines.', 'vec_doc-10-oasis-stix21-p218-505', 0, 256, 'v2.1.0', '1ed67b8f8833e4df56924041ca3d34a4130ddfa8ab828f582e0fad48bc8624e2', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"10.13 Malware Capabilities Vocabulary","subsection":"UNKNOWN","table_id":null,"page":218,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":505,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"10.13 Malware Capabilities Vocabulary"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p218-506', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '10.13 Malware Capabilities Vocabulary', 218, 'anti-debugging Indicates that the malware instance or family is able to prevent itself from being debugged and/or from being run in a debugger or is able to make debugging more difficult. anti-disassembly Indicates that the malware instance or family is able to prevent itself from being disassembled or make disassembly more difficult. anti-emulation Indicates that the malware instance or family is able to prevent its execution inside of an emulator or is able to make emulation more difficult. anti-memory-forensics Indicates that the malware instance or family is able to prevent or make memory forensics more difficult. anti-sandbox Indicates that the malware instance or family is able to prevent sandbox-based behavioral analysis or make it more difficult.', 'vec_doc-10-oasis-stix21-p218-506', 0, 191, 'v2.1.0', '88648e408deb159f61d302006d7fc19bd156969ccca0e210bce02102abaebb10', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"10.13 Malware Capabilities Vocabulary","subsection":"UNKNOWN","table_id":null,"page":218,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":506,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"10.13 Malware Capabilities Vocabulary"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p219-507', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '10.13 Malware Capabilities Vocabulary', 219, 'Standards Track Work Product 02 April 2025 - Page 219 of 276Copyright © OASIS Open 2025. All Rights Reserved. anti-vm Indicates that the malware instance or family isable to prevent virtual machine (VM) based behavioral analysis or make it more difficult. captures-input-peripherals Indicates that the malware instance or family is able to capture data from a system’s input peripheral devices, such as a keyboard or mouse. This includes things like keylogging. captures-output-peripherals Indicates that the malware instance or family captures data sent to a system’s output peripherals, such as a display. Examples include things like screen scraping. captures-system-state-data Indicates that the malware instance or family is able to capture information about a system’s state (e.g., data currently in its RAM). cleans-traces-of-infection Indicates that the malware instance or family is able to clean traces of its infection (e.g., file system artifacts) from a system.', 'vec_doc-10-oasis-stix21-p219-507', 0, 244, 'v2.1.0', '2a7c14569e0a40d0d2de9bc1784434c94e8f014e5ed509d72750854b76ec0e1a', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"10.13 Malware Capabilities Vocabulary","subsection":"UNKNOWN","table_id":null,"page":219,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":507,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"10.13 Malware Capabilities Vocabulary"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p219-508', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '10.13 Malware Capabilities Vocabulary', 219, 'commits-fraud Indicates that the malware instance or family commits fraud, such as click fraud (for example). communicates-with-c2 Indicates that the malware instance or family is able to communicate (i.e., send or receive data) with a command and control (C2) server. compromises-data-availability Indicates that the malware instance or family is able to compromise the availability of data on the local system on which it is executing and/or one or more remote systems. For example, encrypting data on disk, as done by ransomware. compromises-data-integrity Indicates that the malware instance or family is able to compromise the integrity of some data that resides on (e.g., in the case of files) or is received/transmitted (e.g., in the case of network traffic) by the system on which it is executing.', 'vec_doc-10-oasis-stix21-p219-508', 0, 202, 'v2.1.0', '845af847a417fea6074a0ecf055ee41766faa0117d9566be24ba3d1c2081c896', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"10.13 Malware Capabilities Vocabulary","subsection":"UNKNOWN","table_id":null,"page":219,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":508,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"10.13 Malware Capabilities Vocabulary"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p219-509', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '10.13 Malware Capabilities Vocabulary', 219, 'compromises-system-availability Indicates that the malware instance or family is able to consume system resources for its malicious purposes, such as password cracking or participating in a DDoS botnet, thereby compromising the availability of the local system and/or one or more remote systems. controls-local-machine Indicates that the malware instance or family is able to control the machine on which it is executing (e.g., RATs). degrades-security-software Indicates that the malware instance or family is able to bypass or disable security programs or operating system security features on a system (including mobile devices), either by stopping them from executing or by making changes to their code or configuration parameters. For', 'vec_doc-10-oasis-stix21-p219-509', 0, 185, 'v2.1.0', 'cad0d17480209d53a832738446f51426a85fd167ac279a487b3802ecb7793760', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"10.13 Malware Capabilities Vocabulary","subsection":"UNKNOWN","table_id":null,"page":219,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":509,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"10.13 Malware Capabilities Vocabulary"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p220-510', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '10.13 Malware Capabilities Vocabulary', 220, 'Standards Track Work Product 02 April 2025 - Page 220 of 276Copyright © OASIS Open 2025. All Rights Reserved. example, malware that blocks the local machine from accessing the websites of security vendors. degrades-system-updates Indicates that the malware instance or family is able to disable the downloading and installation of system updates and patches. determines-c2-server Indicates that the malware instance or family is able to identify one or more command and control (C2) servers with which to communicate (e.g., DGA). emails-spam Indicates that the malware instance or family is able to send spam email messages. escalates-privileges Indicates that the malware instance or family is able to escalate the privileges under which it is executing. evades-av Indicates that the malware instance or family is able to evade detection by antivirus tools.', 'vec_doc-10-oasis-stix21-p220-510', 0, 215, 'v2.1.0', 'f6732a6eca2177dcd808a34cb7335b90e12e27c2269ae7c7eb898de03ee1e282', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"10.13 Malware Capabilities Vocabulary","subsection":"UNKNOWN","table_id":null,"page":220,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":510,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"10.13 Malware Capabilities Vocabulary"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p220-511', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '10.13 Malware Capabilities Vocabulary', 220, 'exfiltrates-data Indicates that the malware instance or family is able to gather, prepare, (possibly obfuscate) data and transmit it to exfiltration points. fingerprints-host Indicates that the malware instance or family is able to fingerprint or probe the configuration of the host system on which it is executing for the purpose of altering its behavior based on this environment. hides-artifacts Indicates that the malware instance or family is able to hide its artifacts, such as files and open ports. hides-executing-code Indicates that the malware instance or family is able to hide its code by compromising the bootloader, kernel modules, hypervisor, etc. infects-files Indicates that the malware instance or family is able to infect one or more files on the system on which it executes. For example, malware whichinjects a malicious payload into all PDFs on a host as a means of propagation.', 'vec_doc-10-oasis-stix21-p220-511', 0, 225, 'v2.1.0', '9ac6b2ac47a07d6a293deb59b40ff68c1ee19062cf9fbda9fef92494f83c66c4', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"10.13 Malware Capabilities Vocabulary","subsection":"UNKNOWN","table_id":null,"page":220,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":511,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"10.13 Malware Capabilities Vocabulary"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p220-512', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '10.13 Malware Capabilities Vocabulary', 220, 'infects-remote-machines Indicates that the malware instance or family is able to self-propagate to a remote machine or infect a remote machine with malware that is different than itself. installs-other-components Indicates that the malware instance or family is able to install additional components. This encompasses the dropping/downloading of other malicious components such as libraries, other malware, and tools.', 'vec_doc-10-oasis-stix21-p220-512', 0, 105, 'v2.1.0', '6f4d572692ce4de949fa74fdee25ee7cb41ee14a22a7155be4fe0a84a0a01927', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"10.13 Malware Capabilities Vocabulary","subsection":"UNKNOWN","table_id":null,"page":220,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":512,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"10.13 Malware Capabilities Vocabulary"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p221-513', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '10.13 Malware Capabilities Vocabulary', 221, 'Standards Track Work Product 02 April 2025 - Page 221 of 276Copyright © OASIS Open 2025. All Rights Reserved. persists-after-system-reboot Indicates that the malware instance or family isable to continue executing after the reboot of the system on which it is resident. prevents-artifact-access Indicates that the malware instance or family is able to prevent its artifacts (e.g., files, registry keys, etc.) from being accessed. prevents-artifact-deletion Indicates that the malware instance or family is able to prevent its artifacts (e.g., files, registry keys, etc.) from being deleted. probes-network-environment Indicates that the malware instance or family is able to probe the properties of its network environment, e.g. to determine whether it funnels traffic through a proxy. self-modifies Indicates that the malware instance or family is able to modify itself. steals-authentication-credentials Indicates that the malware instance or family is able to steal authentication credentials. violates-system-operational-integrity Indicates that the malware instance is able to steal authentication credentials. violates-system-operational-integrity Indicates that the malware instance or family is able to compromise the operational integrity of the system on which it is executing and/or one or more remote systems, e.g., by causing them to operate beyond their set of specified operational parameters. For example, malware that causes the CPU fan on the machine that it is executing to spin at a higher than normal speed.', 'vec_doc-10-oasis-stix21-p221-513', 0, 382, 'v2.1.0', '071e7ae6678afc11d6cf38eb7c058c2264e768e999798b11ff5341d0fd934f8a', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"10.13 Malware Capabilities Vocabulary","subsection":"UNKNOWN","table_id":null,"page":221,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":513,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"10.13 Malware Capabilities Vocabulary"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p221-514', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '10.14 Malware Result Vocabulary', 221, 'Vocabulary Name: malware-result-ov The processor architecture vocabulary is currently used in the following SDO(s): - Malware Analysis This is a non-exhaustive, open vocabulary that captures common types of scanner or tool analysis process results. Vocabulary Summary malicious, suspicious, benign, unknown Vocabulary Value Description malicious The tool or human analysis determined that the sample is designed to operate, execute or take place in a manner that is not expected by legitimate users, or performs one or more actions generally deemed harmful to a system, or the legitimate users of a system. These can take the form of executables, source code, scripts or any other software or commands.', 'vec_doc-10-oasis-stix21-p221-514', 0, 176, 'v2.1.0', '455e9da97c3f9e9a05391754f3e05cde4985ff7dea54036cd3593c8b272faa5e', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"10.14 Malware Result Vocabulary","subsection":"UNKNOWN","table_id":null,"page":221,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":514,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"10.14 Malware Result Vocabulary"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p222-515', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '10.14 Malware Result Vocabulary', 222, 'Standards Track Work Product 02 April 2025 - Page 222 of 276Copyright © OASIS Open 2025. All Rights Reserved. suspicious The tool or human analysis determined that the sample does not operate asexpected or is is usually present in conjunction with a malicious file. But does not itself demonstrate malicious behaviors. Examples may include files not expected to be present or that support applications that have not been installed, files with an incorrect attribute (location, version, size), or which are accessed or loaded with unusual frequency or at unusual times. Other examples include files dropped or created when malware runs. benign The tool or human analysis determined that the sample has been confirmed to not demonstrate malicious behaviors and is not in and of itself associated with malware or malicious activity. unknown The tool or human analysis was unable to determine whether the malware binary is malicious.', 'vec_doc-10-oasis-stix21-p222-515', 0, 233, 'v2.1.0', 'a9e4e3e6cd346e2dba01aafc02ee9aeafe8bed12628bd6866768fd2f51dbc784', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"10.14 Malware Result Vocabulary","subsection":"UNKNOWN","table_id":null,"page":222,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":515,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"10.14 Malware Result Vocabulary"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p222-516', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '10.15 Malware Type Vocabulary', 222, 'Vocabulary Name: malware-type-ov The malware type vocabulary is currently used in the following SDO(s): - Malware Malware type is an open vocabulary that represents different types and functions of malware. Malware types are not mutually exclusive; for example, a malware instance can be both spyware and a screen capture tool. Vocabulary Summary adware, backdoor, bot, bootkit, ddos, downloader, dropper, exploit-kit, keylogger, ransomware, remote-access-trojan, resource-exploitation, rogue-security- software, rootkit, screen-capture, spyware, trojan, unknown, virus, webshell, wiper, worm Vocabulary Value Description adware Any software that is funded by advertising. Adware may also gather sensitive user information from a system. backdoor A malicious program that allows an attacker to perform actions on a remote system, such as transferring files, acquiring passwords, or executing arbitrary commands [NIST800-83]. bot A program that resides on an infected system, communicating with and forming part of a botnet. The bot may be implanted by a worm or Trojan, which opens a backdoor. The bot then monitors the backdoor for further instructions. bootkit A malicious program which targets the Master Boot Record of the target computer. ddos A program that is used to perform a distributed denial of service attack. downloader A small trojan file programmed to download and execute other files, usually more complex malware.', 'vec_doc-10-oasis-stix21-p222-516', 0, 358, 'v2.1.0', 'a094be9354e358bf2193240c312cfee7af9326bec9f94f707e96155513d4ce1e', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"10.15 Malware Type Vocabulary","subsection":"UNKNOWN","table_id":null,"page":222,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":516,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"10.15 Malware Type Vocabulary"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p223-517', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '10.15 Malware Type Vocabulary', 223, 'Standards Track Work Product 02 April 2025 - Page 223 of 276Copyright © OASIS Open 2025. All Rights Reserved. dropper A type of trojan that deposits an enclosed payload (generally, othermalware) onto the target computer. exploit-kit A software toolkit to target common vulnerabilities. keylogger A type of malware that surreptitiously monitors keystrokes and either records them for later retrieval or sends them back to a central collection point. ransomware A type of malware that encrypts files on a victim’s system, demanding payment of ransom in return for the access codes required to unlock files. remote-access-trojan A remote access trojan program (or RAT), is a trojan horse capable of controlling a machine through commands issued by a remote attacker. resource-exploitation A type of malware that steals a system’s resources (e.g., CPU cycles), such as a malicious bitcoin miner. rogue-security-software A fake security product that demands money to clean phony infections.', 'vec_doc-10-oasis-stix21-p223-517', 0, 247, 'v2.1.0', '142da445489801b9b4d10c5ca2b1db9b61f71b45c3c21e5f2bf959a1e308d3ce', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"10.15 Malware Type Vocabulary","subsection":"UNKNOWN","table_id":null,"page":223,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":517,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"10.15 Malware Type Vocabulary"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p223-518', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '10.15 Malware Type Vocabulary', 223, 'rootkit A type of malware that hides its files or processes from normal methods of monitoring in order to conceal its presence and activities. Rootkits can operate at a number of levels, from the application level — simply replacing or adjusting the settings of system software to prevent the display of certain information — through hooking certain functions or inserting modules or drivers into the operating system kernel, to the deeper level of firmware or virtualization rootkits, which are activated before the operating system and thus even harder to detect while the system is running. screen-capture A type of malware used to capture images from the target systems screen, used for exfiltration and command and control. spyware Software that gathers information on a user’s system without their knowledge and sends it to another party. Spyware is generally used to track activities for the purpose of delivering advertising.', 'vec_doc-10-oasis-stix21-p223-518', 0, 234, 'v2.1.0', '932946d775d64e2880e3227093d04a628f36cf119ccecf3aa71576b6cd98649c', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"10.15 Malware Type Vocabulary","subsection":"UNKNOWN","table_id":null,"page":223,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":518,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"10.15 Malware Type Vocabulary"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p223-519', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '10.15 Malware Type Vocabulary', 223, 'trojan Any malicious computer program which is used to hack into a computer by misleading users of its true intent. unknown There is not enough information available to determine the type of malware. virus A malicious computer program that replicates by reproducing itself or infecting other programs by modifying them. webshell A malicious script used by an attacker with the intent to escalate and maintain persistent access on an already compromised web application. wiper A piece of malware whose primary aim is to delete files or entire disks on a machine.', 'vec_doc-10-oasis-stix21-p223-519', 0, 141, 'v2.1.0', '5f790cbf03af677a8cda727912e832b801e74a1ff751ce274abaaff1a078c85c', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"10.15 Malware Type Vocabulary","subsection":"UNKNOWN","table_id":null,"page":223,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":519,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"10.15 Malware Type Vocabulary"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p224-520', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '10.16 Network Socket Address Family Enumeration', 224, 'Enumeration Name: network-socket-address-family-enum The network socket address family vocabulary is currently used in the following SCO(s): - Network Traffic (Network Socket extension) An enumeration of network socket address family types. Enumeration Summary AF_UNSPEC, AF_INET, AF_IPX, AF_APPLETALK, AF_NETBIOS, AF_INET6, AF_IRDA, AF_BTH Enumeration Value Description AF_UNSPEC Specifies an unspecified address family. AF_INET Specifies the IPv4 address family. AF_IPX Specifies the IPX (Novell Internet Protocol) address family. AF_APPLETALK Specifies the APPLETALK DDP address family. AF_NETBIOS Specifies the NETBIOS address family. AF_INET6 Specifies the IPv6 address family. AF_IRDA Specifies IRDA sockets. AF_BTH Specifies BTH sockets.', 'vec_doc-10-oasis-stix21-p224-520', 0, 186, 'v2.1.0', '4002d4c718695eedf8def611bafda66a3aa3d9ac94a9688111759c165e03b96d', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"10.16 Network Socket Address Family Enumeration","subsection":"UNKNOWN","table_id":null,"page":224,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":520,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"10.16 Network Socket Address Family Enumeration"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p224-521', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '10.17 Network Socket Type Enumeration', 224, 'Enumeration Name: network-socket-type-enum The network socket type vocabulary is currently used in the following SCO(s): - Network Traffic (Network Socket extension) An enumeration of network socket types. Enumeration Summary SOCK_STREAM, AF_ISOCK_DGRAMNET, SOCK_RAW, SOCK_RDM, SOCK_SEQPACKET Enumeration Value Description SOCK_STREAM Specifies a pipe-like socket which operates over a connection with a particular remote socket and transmits data reliably as a stream of bytes. SOCK_DGRAM Specifies a socket in which individually-addressed packets are sent (datagram).', 'vec_doc-10-oasis-stix21-p224-521', 0, 143, 'v2.1.0', 'b3ea1bb006797b65135ae280d8bbbaae06169dcf731c91bcba1c4234e928accc', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"10.17 Network Socket Type Enumeration","subsection":"UNKNOWN","table_id":null,"page":224,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":521,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"10.17 Network Socket Type Enumeration"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p225-522', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '10.17 Network Socket Type Enumeration', 225, 'Standards Track Work Product 02 April 2025 - Page 225 of 276Copyright © OASIS Open 2025. All Rights Reserved. SOCK_RAW Specifies raw sockets which allow new IP protocols to be implemented in userspace. A raw socket receives or sends the raw datagram not including link level headers. SOCK_RDM Specifies a socket indicating a reliably-delivered message. SOCK_SEQPACKET Specifies a datagram congestion control protocol socket.', 'vec_doc-10-oasis-stix21-p225-522', 0, 106, 'v2.1.0', 'd1925c7fa42c167be0f5b3a84671535d1e87d64bd7adf977e3ad7eef7d8d6fba', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"10.17 Network Socket Type Enumeration","subsection":"UNKNOWN","table_id":null,"page":225,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":522,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"10.17 Network Socket Type Enumeration"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p225-523', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '10.18 Opinion Enumeration', 225, 'Enumeration Name: opinion-enum The agreement enumeration is currently used in the following SDOs: - Opinion This enumeration captures a degree of agreement with the information in a STIX Object. It is an ordered enumeration, with the earlier terms representing disagreement, the middle term neutral, and the later terms representing agreement. Enumeration Summary strongly-disagree, disagree, neutral, agree, strongly-agree Enumeration Value Description strongly- disagree The creator strongly disagrees with the information and believes it is inaccurate or incorrect. This MAY be considered equivalent to a 1 in a numeric scale. disagree The creator disagrees with the information and believes it is inaccurate or incorrect. This MAY be considered equivalent to a 2 in a numeric scale. neutral The creator is neutral about the accuracy or correctness of the information. This MAY be considered equivalent to a 3 in a numeric scale. agree The creator agrees with the information and believes that it is accurate and correct. This MAY be considered equivalent to a 4 in a numeric scale. strongly-agree The creator strongly agrees with the information and believes that it is accurate and correct. This MAY be considered equivalent to a 5 in a numeric scale.', 'vec_doc-10-oasis-stix21-p225-523', 0, 314, 'v2.1.0', 'fdeddacbf44886f3efebb1a976ca5032b15005e236cb6412277272f2c25e1331', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"10.18 Opinion Enumeration","subsection":"UNKNOWN","table_id":null,"page":225,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":523,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"10.18 Opinion Enumeration"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p225-524', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '10.19 Pattern Type Vocabulary', 225, 'Vocabulary Name: pattern-type-ov The pattern type vocabulary is currently used in the following SDO(s): - Indicator This is a non-exhaustive, open vocabulary that covers common pattern languages and is intended to characterize the pattern language that the indicator pattern is expressed in.', 'vec_doc-10-oasis-stix21-p225-524', 0, 73, 'v2.1.0', 'e11edae877067d507dbcca58c89581f62234bdc81c49237c1365912de1391f10', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"10.19 Pattern Type Vocabulary","subsection":"UNKNOWN","table_id":null,"page":225,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":524,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"10.19 Pattern Type Vocabulary"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p226-525', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '10.19 Pattern Type Vocabulary', 226, 'Standards Track Work Product 02 April 2025 - Page 226 of 276Copyright © OASIS Open 2025. All Rights Reserved. Vocabulary Summary stix, pcre, sigma, snort, suricata, yara Vocabulary Value Description stix Specifies the STIX pattern language defined in section 9. pcre Specifies the Perl Compatible Regular Expressions language [PCRE]. sigma Specifies the SIGMA language. snort Specifies the SNORT language [SNORT]. suricata Specifies the SURICATA language [Suricata]. yara Specifies the YARA language [YARA]. 10.20. Processor Architecture Vocabulary Vocabulary Name: processor-architecture-ov The processor architecture vocabulary is currently used in the following SDO(s): - Malware This is a non-exhaustive, open vocabulary that covers common processor architectures and is intended to characterize the architectures that a malware instance or family may be able to execute on. Vocabulary Summary alpha, arm, ia-64, mips, powerpc, sparc, x86, x86-64 Vocabulary Value Description alpha Specifies the Alpha architecture. arm Specifies the ARM architecture. ia-64 Specifies the 64-bit IA (Itanium) architecture. mips Specifies the MIPS architecture. powerpc Specifies the PowerPC architecture. sparc Specifies the SPARC architecture. x86 Specifies the 32-bit x86 architecture. x86-64 Specifies the 64-bit x86 architecture. 10.21. Region Vocabulary Vocabulary Name: region-ov The region vocabulary is currently used in the following SDO(s): - Location', 'vec_doc-10-oasis-stix21-p226-525', 0, 362, 'v2.1.0', '92ed44c790088a954c052571eb7ac26a296d752816f8687d12d2b67eec931601', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"10.19 Pattern Type Vocabulary","subsection":"UNKNOWN","table_id":null,"page":226,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":525,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"10.19 Pattern Type Vocabulary"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p227-526', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '10.19 Pattern Type Vocabulary', 227, 'Standards Track Work Product 02 April 2025 - Page 227 of 276Copyright © OASIS Open 2025. All Rights Reserved. A list of world regions based on the United Nations geoscheme [UNSD M49]. Vocabulary Summary africa (eastern-africa, middle-africa, northern-africa, southern-africa, western-africa), americas (caribbean, central-america, latin-america- caribbean, northern-america, south-america), asia (central-asia, eastern- asia, southern-asia, south-eastern-asia, western-asia), europe (eastern- europe, northern-europe, southern-europe, western-europe), oceania (antarctica, australia-new-zealand, melanesia, micronesia, polynesia) Vocabulary Value Description africa Specifies the Africa region. eastern-africa Specifies the Eastern Africa region. middle-africa Specifies the Middle Africa region. northern-africa Specifies the Northern Africa region. southern-africa Specifies the Southern Africa region. western-africa Specifies the Western Africa region. americas Specifies the Americas region. caribbean Specifies the Caribbean region. central-america Specifies the Central America region. latin-america-caribbean Specifies the Latin America and Caribbean region. northern-america Specifies the Northern America region. south-america Specifies the South America region. asia Specifies the Asia region. central-asia Specifies the Central Asia region. eastern-asia Specifies the Eastern Asia region. southern-asia Specifies the Southern Asia region. south-eastern-asia Specifies the South-Eastern Asia region. western-asia Specifies the Western Asia region. europe Specifies the Europe region. eastern-europe Specifies the Eastern Europe region. northern-europe Specifies the Northern Europe region.', 'vec_doc-10-oasis-stix21-p227-526', 0, 425, 'v2.1.0', 'd911863be72500f8a7675ee220420f70a0b4242cfa84165b936b391127a8ce92', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"10.19 Pattern Type Vocabulary","subsection":"UNKNOWN","table_id":null,"page":227,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":526,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"10.19 Pattern Type Vocabulary"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p228-527', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '10.19 Pattern Type Vocabulary', 228, 'Standards Track Work Product 02 April 2025 - Page 228 of 276Copyright © OASIS Open 2025. All Rights Reserved. southern-europe Specifies the Southern Europe region. western-europe Specifies the Western Europe region. oceania Specifies the Oceania region. antarctica Specifies the Antarctica region. australia-new-zealand Specifies the Australia and New Zealand region. melanesia Specifies the Melanesia region. micronesia Specifies the Micronesia region. polynesia Specifies the Polynesia region. 10.22. Report Type Vocabulary Vocabulary Name: report-type-ov The report type vocabulary is currently used in the following SDO(s): - Report Report type is an open vocabulary to describe the primary purpose or subject of a report. For example, a report that contains malware and indicators for that malware should have a report type of malware to capture that the malware is the primary purpose. Report types are not mutually exclusive: a Report can be both a malware report and a tool report.', 'vec_doc-10-oasis-stix21-p228-527', 0, 248, 'v2.1.0', '4e557f07e671b252fa273cfca4b44de425e113eb39de3c6242f130c5ba9254fc', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"10.19 Pattern Type Vocabulary","subsection":"UNKNOWN","table_id":null,"page":228,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":527,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"10.19 Pattern Type Vocabulary"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p228-528', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '10.19 Pattern Type Vocabulary', 228, 'Just because a report contains objects of a type does not mean that the report should include that type. If the objects are there to simply provide evidence or context for other objects, it is not necessary to include them in the type. Vocabulary Summary attack-pattern, campaign, identity, incident, indicator, intrusion-set, malware, observed-data, threat-actor, threat-report, tool, vulnerability Vocabulary Value Description attack- pattern Report subject is a characterization of one or more attack patterns and related information. campaign Report subject is a characterization of one or more campaigns and related information. identity Report subject is a characterization of one or more identities and related information. incident Report subject is a characterization of one or more incidents and related information. indicator Report subject is a characterization of one or more indicators and related information.', 'vec_doc-10-oasis-stix21-p228-528', 0, 231, 'v2.1.0', '13fcc9c887fac5ffe8f4e1bc419ba84fc7f6d1234d8ef137a0ce16b7b3aa4989', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"10.19 Pattern Type Vocabulary","subsection":"UNKNOWN","table_id":null,"page":228,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":528,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"10.19 Pattern Type Vocabulary"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p228-529', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '10.19 Pattern Type Vocabulary', 228, 'intrusion-set Report subject is a characterization of one or more intrusion sets and related information.', 'vec_doc-10-oasis-stix21-p228-529', 0, 27, 'v2.1.0', '530dbd3e9a5ba0e7daedb3ce2e5ce0112d75414de916aaed91e0c740e17baae0', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"10.19 Pattern Type Vocabulary","subsection":"UNKNOWN","table_id":null,"page":228,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":529,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"10.19 Pattern Type Vocabulary"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p229-530', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '10.19 Pattern Type Vocabulary', 229, 'Standards Track Work Product 02 April 2025 - Page 229 of 276Copyright © OASIS Open 2025. All Rights Reserved. malware Report subject is a characterization of one or more malware instances andrelated information. observed-data Report subject is a characterization of observed data and related information. threat-actor Report subject is a characterization of one or more threat actors and related information. threat-report Report subject is a broad characterization of a threat across multiple facets. tool Report subject is a characterization of one or more tools and related information. vulnerability Report subject is a characterization of one or more vulnerabilities and related information. 10.23. Threat Actor Type Vocabulary Vocabulary Name: threat-actor-type-ov The threat actor type vocabulary is currently used in the following SDO(s): - Threat Actor Threat actor type is an open vocabulary used to describe what type of threat actor the individual or group is.', 'vec_doc-10-oasis-stix21-p229-530', 0, 243, 'v2.1.0', '28f567bc7d42657c5d325e57fbb23e7beb0777285568d5b39c0ff0d3e25a830e', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"10.19 Pattern Type Vocabulary","subsection":"UNKNOWN","table_id":null,"page":229,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":530,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"10.19 Pattern Type Vocabulary"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p229-531', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '10.19 Pattern Type Vocabulary', 229, 'For example, some threat actors are competitors who try to steal information, while others are activists who act in support of a social or political cause. Actor types are not mutually exclusive: a threat actor can be both a disgruntled insider and a sensationalist. Vocabulary Summary activist, competitor, crime-syndicate, criminal, hacker, insider-accidental, insider-disgruntled, nation-state, private-sector, sensationalist, spy, terrorist, unknown Vocabulary Value Description activist Highly motivated, potentially destructive supporter of a social or political cause (e.g., trade, labor, environment, etc.) that attempts to disrupt an organization’s business model or damage their image. This category includes actors sometimes referred to as anarchists, cyber vandals, extremists, and hacktivists. competitor An organization that competes in the same economic marketplace. The goal of a competitor is to gain an advantage in business with respect to the rival organization it targets.', 'vec_doc-10-oasis-stix21-p229-531', 0, 249, 'v2.1.0', '28f67cf86fc0c67ce91b4a93f4b9fcf9dbb3d63cce4ccba79572b55b3309ad53', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"10.19 Pattern Type Vocabulary","subsection":"UNKNOWN","table_id":null,"page":229,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":531,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"10.19 Pattern Type Vocabulary"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p229-532', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '10.19 Pattern Type Vocabulary', 229, 'It usually does this by copying intellectual property, trade secrets, acquisition strategies, or other technical or business data from a rival organization with the intention of using the data to bolster its own assets and market position. crime-syndicate An enterprise organized to conduct significant, large-scale criminal activity for profit. Crime syndicates, also known as organized crime, are generally large, well-resourced groups that operate to create profit from all types of crime.', 'vec_doc-10-oasis-stix21-p229-532', 0, 123, 'v2.1.0', '4f698ae546382ed9bff9540c389b26218c44365a26a622f4dd89885b9eee1933', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"10.19 Pattern Type Vocabulary","subsection":"UNKNOWN","table_id":null,"page":229,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":532,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"10.19 Pattern Type Vocabulary"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p230-533', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '10.19 Pattern Type Vocabulary', 230, 'Standards Track Work Product 02 April 2025 - Page 230 of 276Copyright © OASIS Open 2025. All Rights Reserved. criminal Individual who commits computer crimes, often for personal financial gainand often involves the theft of something valuable. Extortion via ransomware and physical destruction are common examples. A criminal as described here refers to those acting individually or in very small or informal groups. hacker An individual that tends to break into networks for the thrill or the challenge of doing so. Hackers may use advanced skills or simple attack scripts they have downloaded. insider-accidental A non-hostile insider who unintentionally exposes the organization to harm. “Insider” in this context includes any person extended internal trust, such as regular employees, contractors, consultants, and temporary workers. insider-disgruntled Current or former insiders who seek revengeful and harmful retaliation for perceived wrongs.', 'vec_doc-10-oasis-stix21-p230-533', 0, 238, 'v2.1.0', '8bbbd018243d87e87381c40167993c9fd406988828a81a9fa325322d864535ff', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"10.19 Pattern Type Vocabulary","subsection":"UNKNOWN","table_id":null,"page":230,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":533,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"10.19 Pattern Type Vocabulary"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p230-534', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '10.19 Pattern Type Vocabulary', 230, '“Insider” in this context includes any person extended internal trust, such as regular employees, contractors, consultants, and temporary workers. Disgruntled threat actors may have extensive knowledge that can be leveraged when conducting attacks and can take any number of actions including sabotage, violence, theft, fraud, espionage, or embarrassing individuals or the organization. nation-state Entities who work for the government of a nation state or who work at their direction. These actors typically have access to significant support, resources, training, and tools and are capable of designing and executing very sophisticated and effective Intrusion Sets and Campaigns. private-sector Entities who develop and sell attack tools and services for commercial gain. These actors often do not choose the targets themselves but work for other threat actors who direct the attacks.', 'vec_doc-10-oasis-stix21-p230-534', 0, 222, 'v2.1.0', 'e3a7a4c734145659703942ce01ce087d833f2619bedb00b1dc8ffed25b435deb', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"10.19 Pattern Type Vocabulary","subsection":"UNKNOWN","table_id":null,"page":230,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":534,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"10.19 Pattern Type Vocabulary"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p230-535', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '10.19 Pattern Type Vocabulary', 230, 'These entities are alternatively known as private-sector offensive actors (PSOA), Mercenary APTs, hackers-for-hire, and Cyber Mercenaries. sensationalist Seeks to cause embarrassment and brand damage by exposing sensitive information in a manner designed to cause a public relations crisis. A sensationalist may be an individual or small group of people motivated primarily by a need for notoriety. Unlike the activist, the sensationalist generally has no political goal, and is not using bad PR to influence the target to change its behavior or business practices. spy Secretly collects sensitive information for use, dissemination, or sale. Traditional spies (governmental and industrial) are part of a well- resourced intelligence organization and are capable of very sophisticated clandestine operations. However, insiders such as employees or', 'vec_doc-10-oasis-stix21-p230-535', 0, 212, 'v2.1.0', 'fef2cf187943acda71b8f873a7f41898e65c5aba3a3cd25138fd164347456459', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"10.19 Pattern Type Vocabulary","subsection":"UNKNOWN","table_id":null,"page":230,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":535,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"10.19 Pattern Type Vocabulary"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p231-536', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '10.19 Pattern Type Vocabulary', 231, 'Standards Track Work Product 02 April 2025 - Page 231 of 276Copyright © OASIS Open 2025. All Rights Reserved. consultants acting as spies can be just as effective and damaging, even when their activities are largely opportunistic and not part of an overall campaign. terrorist Uses extreme violence to advance a social or political agenda as well as monetary crimes to support its activities. In this context a terrorist refers to individuals who target noncombatants with violence to send a message of fear far beyond the actual events. They may act independently or as part of a terrorist organization. Terrorist organizations must typically raise much of their operating budget through criminal activity, which often occurs online. Terrorists are also often adept at using and covertly manipulating social media for both recruitment and impact. unknown There is not enough information available to determine the type of threat actor. 10.24.', 'vec_doc-10-oasis-stix21-p231-536', 0, 236, 'v2.1.0', '3e87e6bc92ea9edab663ea65be60dfd48e1ff07142db6c5327d0a1d985a59d92', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"10.19 Pattern Type Vocabulary","subsection":"UNKNOWN","table_id":null,"page":231,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":536,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"10.19 Pattern Type Vocabulary"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p231-537', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '10.19 Pattern Type Vocabulary', 231, 'Threat Actor Role Vocabulary Vocabulary Name: threat-actor-role-ov The threat actor role vocabulary is currently used in the following SDO(s): - Threat Actor Threat actor role is an open vocabulary that is used to describe the different roles that a threat actor can play. For example, some threat actors author malware or operate botnets while other actors actually carry out attacks directly. Threat actor roles are not mutually exclusive. For example, an actor can be both a financial backer for attacks and also direct attacks. Vocabulary Summary agent, director, independent, infrastructure-architect, infrastructure-operator, malware-author, sponsor Vocabulary Value Description agent Threat actor executes attacks either on behalf of themselves or at the direction of someone else. director The threat actor who directs the activities, goals, and objectives of the malicious activities. independent A threat actor acting by themselves. infrastructure-architect Someone who designs the battle space.', 'vec_doc-10-oasis-stix21-p231-537', 0, 252, 'v2.1.0', '3c06c7dee9755ff86f5b40bbf31f308d15451718ce673afc2231a31b21615cb1', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"10.19 Pattern Type Vocabulary","subsection":"UNKNOWN","table_id":null,"page":231,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":537,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"10.19 Pattern Type Vocabulary"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p231-538', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '10.19 Pattern Type Vocabulary', 231, 'infrastructure-operator The threat actor who provides and supports the attack infrastructure that is used to deliver the attack (botnet providers, cloud services, etc.). malware-author The threat actor who authors malware or other malicious tools. sponsor The threat actor who funds the malicious activities.', 'vec_doc-10-oasis-stix21-p231-538', 0, 77, 'v2.1.0', 'b06d66b003367a4912fd8f1de422d23e77219f11aa6d3f3374b03c37d908962c', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"10.19 Pattern Type Vocabulary","subsection":"UNKNOWN","table_id":null,"page":231,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":538,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"10.19 Pattern Type Vocabulary"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p232-539', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '10.19 Pattern Type Vocabulary', 232, 'Standards Track Work Product 02 April 2025 - Page 232 of 276Copyright © OASIS Open 2025. All Rights Reserved. 10.25. Threat Actor Sophistication Vocabulary Vocabulary Name: threat-actor-sophistication-ov Threat actor sophistication vocabulary is currently used in the following SDO(s): - Threat Actor Threat actor sophistication vocabulary captures the skill level of a threat actor. It ranges from “none”, which describes a complete novice, to “strategic”, which describes an attacker who is able to influence supply chains to introduce vulnerabilities. This vocabulary is separate from resource level because an innovative, highly-skilled threat actor may have access to very few resources while a minimal-level actor might have the resources of an organized crime ring. Vocabulary Summary none, minimal, intermediate, advanced, expert, innovator, strategic Vocabulary Value Description none Can carry out random acts of disruption or destruction by running tools they do not understand.', 'vec_doc-10-oasis-stix21-p232-539', 0, 248, 'v2.1.0', '560f0c4630c813f88fe7f1cb7514d77e1c68dfb0821cf4a9e9b741cff377ea8d', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"10.19 Pattern Type Vocabulary","subsection":"UNKNOWN","table_id":null,"page":232,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":539,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"10.19 Pattern Type Vocabulary"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p232-540', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '10.19 Pattern Type Vocabulary', 232, 'Actors in this category have average computer skills. Example Roles: Average User These actors: - can not launch targeted attacks minimal Can minimally use existing and frequently well known and easy-to-find techniques and programs or scripts to search for and exploit weaknesses in other computers. Commonly referred to as a script-kiddie. These actors rely on others to develop the malicious tools, delivery mechanisms, and execution strategy and often do not fully understand the tool they are using or how they work. They also lack the ability to conduct their own reconnaissance and targeting research. Example Roles: Script-Kiddie These actors: - attack known weaknesses; - use well known scripts and tools; and - have minimal knowledge of the tools. intermediate Can proficiently use existing attack frameworks and toolkits to search for and exploit vulnerabilities in computers or systems.', 'vec_doc-10-oasis-stix21-p232-540', 0, 225, 'v2.1.0', 'bb9f89afb1e88124b21db0011fc61948b3574308d2310aad32fd9481f3fa6562', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"10.19 Pattern Type Vocabulary","subsection":"UNKNOWN","table_id":null,"page":232,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":540,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"10.19 Pattern Type Vocabulary"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p232-541', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '10.19 Pattern Type Vocabulary', 232, 'Actors in this category have computer skills equivalent to an IT professional and typically have a working knowledge of networks, operating systems, and possibly even defensive techniques and will typically exhibit some operational security. These actors rely others to develop the malicious tools and delivery mechanisms but are able to plan their own execution strategy. They are proficient in the tools they are using and how they work and can even make minimal modifications as needed. Example Roles: Toolkit User These actors: - attack known vulnerabilities;', 'vec_doc-10-oasis-stix21-p232-541', 0, 141, 'v2.1.0', '6675ee5c4d2d80b5ae4c760e2484b7e9fcd1178d4e600126186dbde690974230', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"10.19 Pattern Type Vocabulary","subsection":"UNKNOWN","table_id":null,"page":232,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":541,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"10.19 Pattern Type Vocabulary"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p233-542', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '10.19 Pattern Type Vocabulary', 233, 'Standards Track Work Product 02 April 2025 - Page 233 of 276Copyright © OASIS Open 2025. All Rights Reserved. - use attack frameworks and toolkits; and - have proficient knowledge of the tools. advanced Can develop their own tools or scripts from publicly known vulnerabilities to target systems and users. Actors in this category are very adept at IT systems and have a background in software development along with a solid understanding of defensive techniques and operational security. These actors rely on others to find and identify weaknesses and vulnerabilities in systems, but are able to create their own tools, delivery mechanisms, and execution strategies. Example Roles: Toolkit Developer These actors: - attack known vulnerabilities; - can create their own tools; and - have proficient knowledge of the tools.', 'vec_doc-10-oasis-stix21-p233-542', 0, 206, 'v2.1.0', '7b25546799225150cfa3f912befd9108432b02be8d91a036e2f70ec6161f3fdd', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"10.19 Pattern Type Vocabulary","subsection":"UNKNOWN","table_id":null,"page":233,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":542,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"10.19 Pattern Type Vocabulary"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p233-543', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '10.19 Pattern Type Vocabulary', 233, 'expert Can focus on the discovery and use of unknown malicious code, are is adept at installing user and kernel mode rootkits, frequently use data mining tools, target corporate executives and key users (government and industry) for the purpose of stealing personal and corporate data. Actors in this category are very adept at IT systems and software development and are experts with security systems, defensive techniques, attack methods, and operational security. Example Roles: Vulnerability Researcher, Reverse Engineer, Threat Researcher, Malware Creator These actors: - attack unknown and known vulnerabilities; - can create their own tools from scratch; and - have proficient knowledge of the tools. innovator Typically, organized, highly technical, proficient, well-funded professionals working in teams to discover new vulnerabilities and develop exploits. Demonstrates sophisticated capability.', 'vec_doc-10-oasis-stix21-p233-543', 0, 227, 'v2.1.0', 'ec480925f1b50a54e52623f263dd785af0a4ea828b9ba04a9c6a13f49766d509', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"10.19 Pattern Type Vocabulary","subsection":"UNKNOWN","table_id":null,"page":233,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":543,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"10.19 Pattern Type Vocabulary"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p233-544', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '10.19 Pattern Type Vocabulary', 233, 'An innovator has the ability to create and script unique programs and codes targeting virtually any form of technology. At this level, this actor has a deep knowledge of networks, operating systems, programming languages, firmware, and infrastructure topologies and will demonstrate operational security when conducting his activities. Innovators are largely responsible for the discovery of 0-day vulnerabilities and the development of new attack techniques. Example Roles: Toolkit Innovator, 0-Day Exploit Author These actors: - attack unknown and known vulnerabilities; - create attacks against 0-Day exploits from scratch; and - create new and innovative attacks and toolkits. strategic State actors who create vulnerabilities through an active program to “influence” commercial products and services during design, development or manufacturing, or with the ability to impact products while in the supply chain to enable exploitation of networks and systems of interest.', 'vec_doc-10-oasis-stix21-p233-544', 0, 244, 'v2.1.0', '21e1970d402b4cf4737f38cad2d24f5ee3c1b7b1215b63bac5d1d7b05b0af886', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"10.19 Pattern Type Vocabulary","subsection":"UNKNOWN","table_id":null,"page":233,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":544,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"10.19 Pattern Type Vocabulary"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p233-545', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '10.19 Pattern Type Vocabulary', 233, 'These actors: - can create or use entire supply chains to launch an attack;', 'vec_doc-10-oasis-stix21-p233-545', 0, 19, 'v2.1.0', 'b4fd6fa60ffd9ea704e9c28f00d30292165defe6dbbcfadd90e0d8db3a480c8d', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"10.19 Pattern Type Vocabulary","subsection":"UNKNOWN","table_id":null,"page":233,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":545,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"10.19 Pattern Type Vocabulary"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p234-546', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '10.19 Pattern Type Vocabulary', 234, 'Standards Track Work Product 02 April 2025 - Page 234 of 276Copyright © OASIS Open 2025. All Rights Reserved. - can create and design attacks for any systems, software package, or device; and - are responsible for APT-level attacks. 10.26. Tool Type Vocabulary Vocabulary Name: tool-type-ov The tool type vocabulary is currently used in the following SDO(s): - Tool Tool types describe the categories of tools that can be used to perform attacks. Vocabulary Summary denial-of-service, exploitation, information-gathering, network-capture, credential-exploitation, remote-access, vulnerability-scanning, unknown Vocabulary Value Description denial-of-service Tools used to perform denial of service attacks or DDoS attacks, such as Low Orbit Ion Cannon (LOIC) and DHCPig. exploitation Tools used to exploit software and systems, such as sqlmap and Metasploit. information-gathering Tools used to enumerate system and network information, e.g., NMAP.', 'vec_doc-10-oasis-stix21-p234-546', 0, 237, 'v2.1.0', '0cfbbc472c3df0f9f940271dac836d4107f6f71103ae3cb380f72706c14b4ff6', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"10.19 Pattern Type Vocabulary","subsection":"UNKNOWN","table_id":null,"page":234,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":546,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"10.19 Pattern Type Vocabulary"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p234-547', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '10.19 Pattern Type Vocabulary', 234, 'network-capture Tools used to capture network traffic, such as Wireshark and Kismet. credential-exploitation Tools used to crack password databases or otherwise exploit/discover credentials, either locally or remotely, such as John the Ripper and NCrack. remote-access Tools used to access machines remotely, such as VNC and Remote Desktop. vulnerability-scanning Tools used to scan systems and networks for vulnerabilities, e.g., Nessus. unknown There is not enough information available to determine the type of tool. 10.27. Windows™ Integrity Level Enumeration Enumeration Name: windows-integrity-level-enum The Windows integrity level enumeration is currently used in the following STIX Cyber-observable Object(s): - Process (Windows Process extension) Windows integrity levels are a security feature and represent the trustworthiness of an object. Enumeration Summary low, medium, high, system', 'vec_doc-10-oasis-stix21-p234-547', 0, 225, 'v2.1.0', '1f5c21c493bd3bd84e2fd9367c20cba4715a25d9058f932c35931616338cee1a', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"10.19 Pattern Type Vocabulary","subsection":"UNKNOWN","table_id":null,"page":234,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":547,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"10.19 Pattern Type Vocabulary"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p235-548', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '10.19 Pattern Type Vocabulary', 235, 'Standards Track Work Product 02 April 2025 - Page 235 of 276Copyright © OASIS Open 2025. All Rights Reserved. Enumeration Value Description low A low level of integrity. medium A medium level of integrity. high A high level of integrity. system A system level of integrity. 10.28. Windows™ PE Binary Vocabulary Vocabulary Name: windows-pebinary-type-ov The Windows PE binary vocabulary is currently used in the following SCO(s): - File (Windows PE Binary extension) An open vocabulary of Windows PE binary types. Vocabulary Summary dll, exe, sys Vocabulary Value Description dll Specifies that the PE binary is a dynamically linked library (DLL). exe Specifies that the PE binary is an executable image (i.e., not an OBJ or DLL). sys Specifies that the PE binary is a device driver (SYS). 10.29. Windows™ Registry Datatype Enumeration Enumeration Name: windows-registry-datatype-enum The Windows registry datatype vocabulary is currently used in the following SCO(s): - Windows Registry Key An enumeration of Windows registry data types. Enumeration Summary REG_NONE, REG_SZ, REG_EXPAND_SZ, REG_BINARY, REG_DWORD, REG_DWORD_BIG_ENDIAN, REG_DWORD_LITTLE_ENDIAN, REG_LINK, REG_MULTI_SZ, REG_RESOURCE_LIST, REG_FULL_RESOURCE_DESCRIPTION, REG_RESOURCE_REQUIREMENTS_LIST, REG_QWORD, REG_INVALID_TYPE Enumeration Value Description REG_NONE No defined value type. REG_SZ A null-terminated string. This will be either a Unicode or an ANSI string, depending on whether you use the Unicode or ANSI functions.', 'vec_doc-10-oasis-stix21-p235-548', 0, 375, 'v2.1.0', '694c271266a0df9ec94f52c2a5d700e5023300aee5b2afc2500df6ddf64e6327', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"10.19 Pattern Type Vocabulary","subsection":"UNKNOWN","table_id":null,"page":235,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":548,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"10.19 Pattern Type Vocabulary"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p236-549', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '10.19 Pattern Type Vocabulary', 236, 'Standards Track Work Product 02 April 2025 - Page 236 of 276Copyright © OASIS Open 2025. All Rights Reserved. REG_EXPAND_SZ A null-terminated string that contains unexpandedreferences to environment variables (for example, “%PATH%”). It will be a Unicode or ANSI string depending on whether you use the Unicode or ANSI functions. REG_BINARY Binary data in any form. REG_DWORD A 32-bit number. REG_DWORD_BIG_ENDIAN A 32-bit number in big-endian format. REG_DWORD_LITTLE_ENDIAN A 32-bit number in little-endian format. REG_LINK A null-terminated Unicode string that contains the target path of a symbolic link. REG_MULTI_SZ A sequence of null-terminated strings, terminated by an empty string (\0). REG_RESOURCE_LIST A series of nested lists designed to store a resource list used by a hardware device driver or one of the physical devices it controls. This data is detected and written into the ResourceMap tree by the system and is displayed in Registry Editor in hexadecimal format as a Binary Value.', 'vec_doc-10-oasis-stix21-p236-549', 0, 251, 'v2.1.0', '6a55c4d038520ee719864384bb5c0364ac411a0bb167b9d2e0648e866ab42ec7', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"10.19 Pattern Type Vocabulary","subsection":"UNKNOWN","table_id":null,"page":236,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":549,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"10.19 Pattern Type Vocabulary"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p236-550', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '10.19 Pattern Type Vocabulary', 236, 'REG_FULL_RESOURCE_DESCRIPTION A series of nested lists designed to store a resource list used by a physical hardware device. This data is detected and written into the HardwareDescription tree by the system and is displayed in Registry Editor in hexadecimal format as a Binary Value. REG_RESOURCE_REQUIREMENTS_LIST A series of nested lists designed to store a resource list used by a hardware device driver or one of the physical devices it controls. This data is detected and written into the ResourceMap tree by the system and is displayed in Registry Editor in hexadecimal format as a Binary Value. REG_QWORD A 64-bit number. REG_INVALID_TYPE Specifies an invalid key. 10.30. Windows™ Service Start Type Enumeration Enumeration Name: windows-service-start-type-enum The Windows service start type vocabulary is currently used in the following SCO(s): - Process (Windows Service extension) An enumeration of Windows service start types.', 'vec_doc-10-oasis-stix21-p236-550', 0, 235, 'v2.1.0', '2375d2cfccfaa3c2676e901c64028f5ecddb7c59bee5b45a382548607a372d0d', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"10.19 Pattern Type Vocabulary","subsection":"UNKNOWN","table_id":null,"page":236,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":550,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"10.19 Pattern Type Vocabulary"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p236-551', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '10.19 Pattern Type Vocabulary', 236, 'Enumeration Summary SERVICE_AUTO_START, SERVICE_BOOT_START, SERVICE_DEMAND_START, SERVICE_DISABLED, SERVICE_SYSTEM_ALERT', 'vec_doc-10-oasis-stix21-p236-551', 0, 30, 'v2.1.0', '41291da49cc3d66e4d4d44027ccb1f4a8404074ab6e34491d32d19bbf2528504', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"10.19 Pattern Type Vocabulary","subsection":"UNKNOWN","table_id":null,"page":236,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":551,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"10.19 Pattern Type Vocabulary"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p237-552', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '10.19 Pattern Type Vocabulary', 237, 'Standards Track Work Product 02 April 2025 - Page 237 of 276Copyright © OASIS Open 2025. All Rights Reserved. Enumeration Value Description SERVICE_AUTO_START A service started automatically by the service control manager during system startup. SERVICE_BOOT_START A device driver started by the system loader. This value is valid only for driver services. SERVICE_DEMAND_START A service started by the service control manager when a process calls the StartService function. SERVICE_DISABLED A service that cannot be started. Attempts to start the service result in the error code ERROR_SERVICE_DISABLED. SERVICE_SYSTEM_ALERT A device driver started by the IoInitSystem function. This value is valid only for driver services. 10.31. Windows™ Service Type Enumeration Enumeration Name: windows-service-type-enum The Windows service type vocabulary is currently used in the following SCO(s): - Process (Windows Service extension) An enumeration of Windows service types. Enumeration Summary SERVICE_KERNEL_DRIVER, SERVICE_FILE_SYSTEM_DRIVER, SERVICE_WIN32_OWN_PROCESS, SERVICE_WIN32_SHARE_PROCESS Enumeration Value Description SERVICE_KERNEL_DRIVER The service is a device driver. SERVICE_FILE_SYSTEM_DRIVER The service is a file system driver. SERVICE_WIN32_OWN_PROCESS The service runs in its own process. SERVICE_WIN32_SHARE_PROCESS The service shares a process with other services. 10.32. Windows™ Service Status Enumeration Enumeration Name: windows-service-status-enum The Windows service status vocabulary is currently used in the following SCO(s): - Process (Windows Service extension) An enumeration of Windows service statuses. Enumeration Summary SERVICE_CONTINUE_PENDING, SERVICE_PAUSE_PENDING, SERVICE_PAUSED, SERVICE_RUNNING, SERVICE_START_PENDING, SERVICE_STOP_PENDING, SERVICE_STOPPED', 'vec_doc-10-oasis-stix21-p237-552', 0, 450, 'v2.1.0', '05c57311aad06845ed2dd0b87ea0c8df7e145ed2ca6ba8ada24d2e04f66815d9', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"10.19 Pattern Type Vocabulary","subsection":"UNKNOWN","table_id":null,"page":237,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":552,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"10.19 Pattern Type Vocabulary"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p238-553', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '10.19 Pattern Type Vocabulary', 238, 'Standards Track Work Product 02 April 2025 - Page 238 of 276Copyright © OASIS Open 2025. All Rights Reserved. Enumeration Value Description SERVICE_CONTINUE_PENDING The service continue is pending. SERVICE_PAUSE_PENDING The service pause is pending. SERVICE_PAUSED The service is paused. SERVICE_RUNNING The service is running. SERVICE_START_PENDING The service is starting. SERVICE_STOP_PENDING The service is stopping. SERVICE_STOPPED The service is not running.', 'vec_doc-10-oasis-stix21-p238-553', 0, 116, 'v2.1.0', 'c9869adf3e461e8cbcf580ca6e095729c1c0af02bb10e5b82de239e2cf1229a4', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"10.19 Pattern Type Vocabulary","subsection":"UNKNOWN","table_id":null,"page":238,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":553,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"10.19 Pattern Type Vocabulary"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p239-554', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '11. Customizing STIX (Deprecated)', 239, 'The recommended method to extend STIX is defined by the STIX Extension mechanisms described in', 'vec_doc-10-oasis-stix21-p239-554', 0, 24, 'v2.1.0', '542631180e528534e4307d36c50e1099671d31571317e398dd7ea7e5b0601268', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"11. Customizing STIX (Deprecated)","subsection":"UNKNOWN","table_id":null,"page":239,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":554,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"11. Customizing STIX (Deprecated)"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p239-555', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', 'section 7.3. These new mechanisms replace the customization mechanisms defined in this section', 239, 'including three means to customize STIX: Custom Properties, Custom Objects and Custom Extensions. These mechanisms are retained for backward-compatibility and should not be used to implement any new extensions of the specification. Custom Properties provide a mechanism and requirements for adding properties not defined by this specification to existing STIX Objects. Custom Objects, on the other hand, provides a mechanism and requirements to create custom STIX Objects (objects not defined by this specification). Custom Extensions provide a mechanism and requirements for the specification of extensions not defined by this specification on SCOs. A consumer that receives STIX content containing Custom Properties, Objects, or Extensions it does not understand MAY refuse to process the content or MAY ignore those properties or objects and continue processing the content.', 'vec_doc-10-oasis-stix21-p239-555', 0, 220, 'v2.1.0', '6b2c6b45f4098b38b0c4920f45bb6791b0c4f61e47ecc1f4a75d0c4d8f66cc55', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"section 7.3. These new mechanisms replace the customization mechanisms defined in this section","subsection":"UNKNOWN","table_id":null,"page":239,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":555,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"section 7.3. These new mechanisms replace the customization mechanisms defined in this section"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p239-556', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', 'section 7.3. These new mechanisms replace the customization mechanisms defined in this section', 239, 'Producers of STIX content that contain Custom Properties, Objects or Extensions should recognize that consumers may not understand them and may ignore them. Producers should define any Custom Properties, Objects and Extensions they use, along with any rules for processing them, and make these definitions and rules accessible to any potential consumers. This specification does not specify a process for doing this. Custom Properties SHOULD be used for cases where it is necessary to add one or more simple additional properties (i.e. key/value pairs) on an SCO. On the other hand, Custom Extensions SHOULD be used for cases where it is necessary to describe more complex additional properties (i.e., those with potentially multiple levels of hierarchy).', 'vec_doc-10-oasis-stix21-p239-556', 0, 189, 'v2.1.0', 'ecd6c52d0f05dbbb26a602269de91be9b954e216a09a60ba888edf99f997a7eb', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"section 7.3. These new mechanisms replace the customization mechanisms defined in this section","subsection":"UNKNOWN","table_id":null,"page":239,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":556,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"section 7.3. These new mechanisms replace the customization mechanisms defined in this section"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p239-557', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', 'section 7.3. These new mechanisms replace the customization mechanisms defined in this section', 239, 'As an example, a vendor-specific property that expresses some custom threat score for a File object should be added directly to the SCO as a custom property, whereas a set of properties that represent metadata around a new file system to the File object should be done as a custom extension. 11.1. Custom Properties (Deprecated) Custom properties SHOULD be defined using the STIX Extension mechanism for property-extension as described in section 7.3. There will be cases where certain information exchanges can be improved by adding properties to STIX Objects and STIX Cyber Observable (SCO) Extensions that are neither specified nor reserved in this specification; these properties are called Custom Properties. This section provides guidance and requirements for how producers can use Custom Properties and how consumers should interpret them in order to extend STIX in an interoperable manner.', 'vec_doc-10-oasis-stix21-p239-557', 0, 225, 'v2.1.0', '963ed36ad936c60d13dd1e1b051f63bbd988a2168f60b24b71f90a15449d5a5c', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"section 7.3. These new mechanisms replace the customization mechanisms defined in this section","subsection":"UNKNOWN","table_id":null,"page":239,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":557,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"section 7.3. These new mechanisms replace the customization mechanisms defined in this section"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p239-558', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', 'section 7.3. These new mechanisms replace the customization mechanisms defined in this section', 239, '11.1.1 Requirements (Deprecated) A STIX Object MAY have any number of STIX Extensions containing one or more properties. Custom Property names MUST be in ASCII and MUST only contain the characters a-z (lowercase ASCII), 0-9, and underscore (_). Custom Property names SHOULD start with “x_” followed by a source unique identifier (such as a domain name with dots replaced by underscores), an underscore and then the name. For example, x_example_com_customfield. Custom Property names MUST have a minimum length of 3 ASCII characters. Custom Property names MUST be no longer than 250 ASCII characters in length. Custom Property names that do not start with “x_” may be used in a future version of the specification for a different meaning. If compatibility with future versions of this specification is required, the “x_” prefix MUST be used. Custom Properties SHOULD only be used when there are no existing properties defined by the STIX specification that fulfils that need.', 'vec_doc-10-oasis-stix21-p239-558', 0, 244, 'v2.1.0', '0d9af761b63be2b7c6d19d45855e032ac2f999e27a640fa655d4f280b40166cb', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"section 7.3. These new mechanisms replace the customization mechanisms defined in this section","subsection":"UNKNOWN","table_id":null,"page":239,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":558,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"section 7.3. These new mechanisms replace the customization mechanisms defined in this section"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p239-559', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', 'section 7.3. These new mechanisms replace the customization mechanisms defined in this section', 239, 'For Custom Properties that use the hex type, the property name MUST end with ’_hex’.', 'vec_doc-10-oasis-stix21-p239-559', 0, 21, 'v2.1.0', 'd8f735461d8c91f204749732a9737714dfe0697ac2e559160920bd2730b0ace6', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"section 7.3. These new mechanisms replace the customization mechanisms defined in this section","subsection":"UNKNOWN","table_id":null,"page":239,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":559,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"section 7.3. These new mechanisms replace the customization mechanisms defined in this section"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p240-560', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '11.2 Custom Objects (Deprecated)', 240, 'Custom objects SHOULD be defined using the STIX Extension mechanism for new SDO, new SCO or new SRO as described in section 7.3. There will be cases where certain information exchanges can be improved by adding objects that are not specified nor reserved in this specification; these objects are called Custom Objects. This section provides guidance and requirements for how producers can use Custom Objects and how consumers should interpret them in order to extend STIX in an interoperable manner. 11.2.1 Requirements (Deprecated) Producers MAY include any number of Custom Objects in STIX content. Custom Objects MUST support the Common Properties as defined in section 3.2. Common property names MUST NOT be reused to represent the custom properties in the object. A Custom Object MUST have one or more properties. The name of a property of a Custom Object MUST be in ASCII and MUST only contain the characters a-z (lowercase ASCII), 0-9, and underscore ().', 'vec_doc-10-oasis-stix21-p240-560', 0, 241, 'v2.1.0', 'fc1bf68c419a40fa57323383b446ab86429a5bbd5cbc41cd8a5696d3bdc913a7', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"11.2 Custom Objects (Deprecated)","subsection":"UNKNOWN","table_id":null,"page":240,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":560,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"11.2 Custom Objects (Deprecated)"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p240-561', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '11.2 Custom Objects (Deprecated)', 240, 'The “x” prefix as described - section 11.1.1 MAY be used. The name of a property of a Custom Object MUST have a minimum length of 3 ASCII characters. The name of a property of a Custom Object MUST be no longer than 250 ASCII characters in length. The type property in a Custom Object MUST be in ASCII and MUST only contain the characters a- z (lowercase ASCII), 0-9, and hyphen (-). The type property MUST NOT contain a hyphen (-) character immediately following another hyphen (-) character. Custom Object names MUST have a minimum length of 3 ASCII characters. Custom Object names MUST be no longer than 250 ASCII characters in length. The value of the type property in a Custom Object SHOULD start with “x-” followed by a source unique identifier (like a domain name with dots replaced by hyphens), a hyphen and then the name. For example, x-example-com-customobject. A Custom Object whose name is not prefixed with “x-” may be used in a future version of the specification with a different meaning.', 'vec_doc-10-oasis-stix21-p240-561', 0, 251, 'v2.1.0', '7fba0876a0391dbdb7a95642e7a34a6e6de849cf35d0aa036aea52bc79998a7a', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"11.2 Custom Objects (Deprecated)","subsection":"UNKNOWN","table_id":null,"page":240,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":561,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"11.2 Custom Objects (Deprecated)"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p240-562', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '11.2 Custom Objects (Deprecated)', 240, 'Therefore, if compatibility with future versions of thisspecification is required, the “x-” prefix MUST be used. The value of the id property in a Custom Object MUST use the same format as the identifier type, namely, [object-type]–[UUID]. Custom Objects SHOULD only be used when there is no existing STIX Object defined by the STIX specification that fulfils that need. Example { "type": "bundle", "id": "bundle--f37aa79d-f5f5-4af7-874b-734d32c08c10",', 'vec_doc-10-oasis-stix21-p240-562', 0, 113, 'v2.1.0', '8018b630c6fa4f4b2ee262240ac003842eda9457108cf0862577f3698b6eb3b8', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"11.2 Custom Objects (Deprecated)","subsection":"UNKNOWN","table_id":null,"page":240,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":562,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"11.2 Custom Objects (Deprecated)"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p241-563', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '11.2 Custom Objects (Deprecated)', 241, 'Standards Track Work Product 02 April 2025 - Page 241 of 276Copyright © OASIS Open 2025. All Rights Reserved. "objects": [ { "type": "x-example-com-customobject", "id": "x-example-com-customobject--4527e5de-8572-446a-a57a-706f15467461", "created": "2016-08-01T00:00:00.000Z", "modified": "2016-08-01T00:00:00.000Z", "some_custom_stuff": 14, "other_custom_stuff": "hello" } ] }', 'vec_doc-10-oasis-stix21-p241-563', 0, 94, 'v2.1.0', '7cde54fe478e018d18e066b9e55a9edc2af66eabee3b2e4c111a815b6d681961', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"11.2 Custom Objects (Deprecated)","subsection":"UNKNOWN","table_id":null,"page":241,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":563,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"11.2 Custom Objects (Deprecated)"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p241-564', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '11.3 Custom Object Extensions (Deprecated)', 241, 'Custom Object Extensions SHOULD be defined using the STIX Extension mechanism for property- extension as described in section 7.3. In addition to the Predefined Cyber Observable Object extensions, STIX supports user-defined custom extensions for STIX Cyber-observable Objects (SCO). As with Predefined Object Extensions, custom extension data MUST be conveyed under the extensions property. Note, custom extensions can only be used with SCOs. 11.3.1 Requirements (Deprecated) A SCO MAY have any number of Custom Extensions. Custom Extension names MUST be in ASCII and are limited to characters a-z (lowercase ASCII), 0-9, and hyphen (-). Custom Extension names MUST end with “-ext”. Custom Extension names SHOULD start with “x-” followed by a source unique identifier (like a domain name), a hyphen and then the name. For example: x-example-com- customextension. Custom Extension names MUST have a minimum length of 3 ASCII characters.', 'vec_doc-10-oasis-stix21-p241-564', 0, 234, 'v2.1.0', '72181d09598501b88d1921e465062b373f166967dbd582cd83cd7dcd8958a94a', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"11.3 Custom Object Extensions (Deprecated)","subsection":"UNKNOWN","table_id":null,"page":241,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":564,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"11.3 Custom Object Extensions (Deprecated)"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p241-565', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '11.3 Custom Object Extensions (Deprecated)', 241, 'Custom Extension names MUST be no longer than 250 ASCII characters in length. Custom Extension names that are not prefixed with “x-” may be used in a future version of the specification for a different meaning. If compatibility with future versions of this specification is required, the “x-” prefix MUST be used. Custom Extensions SHOULD only be used when there is no existing extension defined by the STIX 2.1 specification that fulfills that need. A Custom Extension MUST have one or more properties. The name of a property of a Custom Object Extension MUST be in ASCII and MUST only contain the characters a-z (lowercase ASCII), 0-9, and underscore (). The “x” prefix as described in section 11.1.1 MAY be used. Example Custom File object extension { "type": "file", "hashes": { "SHA-256": "effb46bba03f6c8aea5c653f9cf984f170dcdd3bbbe2ff6843c3e5da0e698766" }, "extensions": { "x-example-com-foo": { "foo_val": "foo", "bar_val": "bar" } } }', 'vec_doc-10-oasis-stix21-p241-565', 0, 236, 'v2.1.0', 'bdf42405fd89a4032646af205d30f97ac65fd6e21872106402930b98655cc419', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"11.3 Custom Object Extensions (Deprecated)","subsection":"UNKNOWN","table_id":null,"page":241,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":565,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"11.3 Custom Object Extensions (Deprecated)"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p242-566', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '12.1 STIX Object Producers and Consumers', 242, 'A “STIX 2.1 Producer” is any software that can create STIX 2.1 content and conforms to the following normative requirements: - It MUST be able to create content encoded as JSON. - All properties marked required in the property table for the STIX Object or type MUST be present in the created content. - All properties MUST conform to the data type and normative requirements for that property. - It MUST support at least one STIX Object. - It MUST support all features listed in section 12.2, Mandatory Features. - It MAY support any features listed in section 12.3, Optional Features. Software supporting an optional feature MUST comply with the normative requirements of that feature. - It MUST support JSON as a serialization format and MAY support serializations other than JSON. A “STIX 2.1 Consumer” is any software that can consume STIX 2.1 content and conforms to the following normative requirements: - It MUST support parsing all required properties for the content that it consumes. - It MUST support all features listed in section 12.2, Mandatory Features. - It MAY support any features listed in section 12.3, Optional Features. Software supporting an optional feature MUST comply with the normative requirements of that feature. - It MUST support JSON as a serialization format and MAY support serializations other than JSON.', 'vec_doc-10-oasis-stix21-p242-566', 0, 335, 'v2.1.0', 'd241c2d8f3acdd6c82e65b8b4618ee3761103813ab3bd8040748fffc12d360e0', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"12.1 STIX Object Producers and Consumers","subsection":"UNKNOWN","table_id":null,"page":242,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":566,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"12.1 STIX Object Producers and Consumers"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p242-567', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '12.2 STIX Object Mandatory Features', 242, '12.2.1 Versioning A STIX 2.1 Producer or STIX 2.1 Consumer MUST support versioning by following the normative requirements listed in section 3.6.', 'vec_doc-10-oasis-stix21-p242-567', 0, 37, 'v2.1.0', 'b8515f8b45877b09b78a992a466479d6bcad1fcb8c6dd204192308fea71bacfe', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"12.2 STIX Object Mandatory Features","subsection":"UNKNOWN","table_id":null,"page":242,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":567,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"12.2 STIX Object Mandatory Features"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p242-568', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '12.3 STIX Object Optional Features', 242, '12.3.1 Object-Level Data Markings A STIX 2.1 Producer or STIX 2.1 Consumer MAY support “Object-Level Data Markings”. Software claiming to support “Object-Level Data Markings” MUST follow the normative requirements listed in', 'vec_doc-10-oasis-stix21-p242-568', 0, 56, 'v2.1.0', 'ee525bc4cfafa6c99de5d02a512598387e15d28ffd1ef3ff8493c59467e08880', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"12.3 STIX Object Optional Features","subsection":"UNKNOWN","table_id":null,"page":242,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":568,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"12.3 STIX Object Optional Features"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p242-569', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', 'section 7.2.1 and section 7.2.2.', 242, '12.3.2. Granular Data Markings A STIX 2.1 Producer or STIX 2.1 Consumer MAY support “Granular Data Markings”. Software claiming to support “Granular Data Markings” MUST follow the normative requirements listed in section 7.2.1 and', 'vec_doc-10-oasis-stix21-p242-569', 0, 58, 'v2.1.0', 'f57e9a58d55b47b01136ca79a4d6fc67b36025545d7c286fa14a4c8e09d9e55b', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"section 7.2.1 and section 7.2.2.","subsection":"UNKNOWN","table_id":null,"page":242,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":569,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"section 7.2.1 and section 7.2.2."}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p242-570', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', 'section 7.2.3.', 242, '12.3.3. STIX Extensions A STIX 2.1 Producer or STIX 2.1 Consumer MAY support STIX Extensions as defined in section 7.3.Software claiming to support STIX Extensions MUST follow the normative requirements defined in', 'vec_doc-10-oasis-stix21-p242-570', 0, 54, 'v2.1.0', '49e660160dbe6e521467af7658de6c26a99fc0752d6f13355ad5c077413b4891', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"section 7.2.3.","subsection":"UNKNOWN","table_id":null,"page":242,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":570,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"section 7.2.3."}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p242-571', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '12.4 STIX Patterning Conformance', 242, 'Implementers of the STIX Patterning language are not required to support the full capabilities provided by the language. Rather, implementers are strongly encouraged to support as much of STIX Patterning as feasible, given the capabilities of their products, but only required to support the minimum conformance level (defined below) necessary for their particular use cases. For example, the vendor of a network intrusion detection system (NIDS) that looks for malicious network traffic may only need to implement the Comparison Operators and support basic Observation Expressions to explicitly match against network traffic and IP addresses. While the STIX Patterning language specification is tightly coupled with the STIX Cyber-observable Object data models, it is understood that in many (or even most) implementations STIX Patterns will beused as an abstraction layer for transcoding into other proprietary query formats. STIX Patterns may be', 'vec_doc-10-oasis-stix21-p242-571', 0, 237, 'v2.1.0', '6c2d497ca44d409d28e32f928e9930372be1333b7e87fb11340e9d5daa526055', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"12.4 STIX Patterning Conformance","subsection":"UNKNOWN","table_id":null,"page":242,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":571,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"12.4 STIX Patterning Conformance"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p243-572', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '12.4 STIX Patterning Conformance', 243, 'Standards Track Work Product 02 April 2025 - Page 243 of 276Copyright © OASIS Open 2025. All Rights Reserved. evaluated directly against a corpus of STIX Observed Data instances, but they may also, for example, be translated into some query syntax for a packet inspection device. In this second case, the STIX Patterns are in fact evaluated in the context of data passing on the wire, not in the form of STIX Cyber Observables. The STIX Patterning language’s Observation Operators allow for the creation of patterns that explicitly match across multiple Observations; however, the language purposefully does not specify anything about the source of the underlying data for each Observation. For example, depending on a particular patterning implementation, the data for a pattern that matches on network traffic could come from an endpoint or from a NIDS. It is incumbent upon implementers to ascertain the appropriate data sources (where applicable) for each Observation within a given pattern.', 'vec_doc-10-oasis-stix21-p243-572', 0, 249, 'v2.1.0', 'd7aa3ce9c1c5f8295b370355838b937d28e997f783b47253e1f1c65b5ba847a3', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"12.4 STIX Patterning Conformance","subsection":"UNKNOWN","table_id":null,"page":243,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":572,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"12.4 STIX Patterning Conformance"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p243-573', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '12.5 STIX Pattern Producer', 243, 'Software that creates STIX patterns is known as a “Pattern Producer”. Such software MUST support the creation of patterns that conform to all normative statements and formatting rules in this document. Pattern Producers MUST specify their conformance in terms of the conformance levels defined in section 12.7.', 'vec_doc-10-oasis-stix21-p243-573', 0, 78, 'v2.1.0', '5737bc1979606b43d1b3d5082586aaab54956059c47b8990b9bf31263c6e3e2f', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"12.5 STIX Pattern Producer","subsection":"UNKNOWN","table_id":null,"page":243,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":573,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"12.5 STIX Pattern Producer"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p243-574', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '12.6 STIX Pattern Consumer', 243, 'Software that consumes STIX patterns is known as a “Pattern Consumer”. Such software MUST support the consumption of patterns that conform to all normative statements and formatting rules in this document. Pattern Consumers MUST specify their conformance in terms of the conformance levels defined in section 12.7.', 'vec_doc-10-oasis-stix21-p243-574', 0, 79, 'v2.1.0', '4ae8702e54ca73b981b4a2c7e658352e22b4da960d46425b206f3aed4a628abf', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"12.6 STIX Pattern Consumer","subsection":"UNKNOWN","table_id":null,"page":243,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":574,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"12.6 STIX Pattern Consumer"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p243-575', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '12.7 STIX Patterning Conformance Levels', 243, '12.7.1 Level 1: Basic Conformance Software that conforms to the minimum required aspects of the patterning specification, is known as a “Level 1 STIX Patterning Implementation”. Such software MUST support the following features by conforming to all normative statements and behaviors in the referenced sections: - Single Observation Expressions (omitting Qualifiers), as described in section 9.5 - All Comparison Operators, as described in section 9.6.1 This level of conformance is intended primarily for software that is deployed at endpoints or network boundaries and which is architecturally unable to maintain state, as would be required in order to support Qualifiers such as WITHIN. 12.7.2 Level 2: Basic Conformance plus Observation Operators Software that supports the minimum required aspects of the patterning specification but can operate on multiple Observations, is known as a “Level 2 STIX Patterning Implementation”. Such software MUST support the following features by conforming to all normative statements and behaviors in the referenced sections: - Single and Compound Observation Expressions (omitting Qualifiers) as described in section 9.5 - The AND Observation Operator, as described in section 9.5.2 - The OR Observation Operator, as described in section 9.5.2 - All Comparison Operators, as described in', 'vec_doc-10-oasis-stix21-p243-575', 0, 333, 'v2.1.0', 'ae6a67cc9c5547fd874cfec7d010555e37c7fe1520f21d9b52fb6529e744312a', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"12.7 STIX Patterning Conformance Levels","subsection":"UNKNOWN","table_id":null,"page":243,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":575,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"12.7 STIX Patterning Conformance Levels"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p243-576', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', 'section 9.6.1', 243, 'This level of conformance is intended primarily for software such as HIDS that can detect patterns across separate Observations but may not support temporal-based patterning. 12.7.3 Level 3: Full Conformance Software that is fully conformant with all of the capabilities of the patterning specification is known as a “Level 3 STIX Patterning Implementation”.', 'vec_doc-10-oasis-stix21-p243-576', 0, 90, 'v2.1.0', 'fc47336a5c850c61ca5f256842d3327c211f3aa018b722461110a4b0fe9534f1', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"section 9.6.1","subsection":"UNKNOWN","table_id":null,"page":243,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":576,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"section 9.6.1"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p244-577', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', 'section 9.6.1', 244, 'Standards Track Work Product 02 April 2025 - Page 244 of 276Copyright © OASIS Open 2025. All Rights Reserved. Such software MUST support the following features by conforming to all normative statements and behaviors in the referenced sections: - section 9.1 Definitions - section 9.3 STIX Patterns - section 9.4 Pattern Expressions - section 9.5 Observation Expressions - section 9.6 Comparison Expressions -', 'vec_doc-10-oasis-stix21-p244-577', 0, 102, 'v2.1.0', '5d5340ca11d025cf784a0ddbdabbd3c9b01cc08ed1065ae0b385cdc3378c2df9', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"section 9.6.1","subsection":"UNKNOWN","table_id":null,"page":244,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":577,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"section 9.6.1"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p244-578', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', 'section 9.7 Object Path Syntax', 244, 'This level of conformance is intended primarily for software such as SIEMs that support temporal-based patterning and can also aggregate and detect patterns across multiple and disparate sources of Observations.', 'vec_doc-10-oasis-stix21-p244-578', 0, 53, 'v2.1.0', '6e2ed8354ec3f0f7ca3e8b15c8953d5a7ecd16cbd4228fd44961792d6dc89009', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"section 9.7 Object Path Syntax","subsection":"UNKNOWN","table_id":null,"page":244,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":578,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"section 9.7 Object Path Syntax"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p245-579', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', 'section 9.7 Object Path Syntax', 245, 'Standards Track Work Product 02 April 2025 - Page 245 of 276Copyright © OASIS Open 2025. All Rights Reserved. Appendix A: Confidence Scales The use of these confidence scales is defined in section 3.2, confidence property. A value of “Not Specified” in the table below means that the confidence property is not present. None/Low/Med/High STIX Confidence Value Ranges of Values Not Specified Not Specified N/A None 0 0 Low 15 1-29 Med 50 30-69 High 85 70-100 0-10 Scale STIX Confidence Value Ranges of Values Not Specified Not Specified N/A 0 0 0-4 1 10 5-14 2 20 15-24 3 30 25-34 4 40 35-44 5 50 45-54 6 60 55-64 7 70 65-74 8 80 75-84 9 90 85-94 10 100 95-100 Admiralty Credibility STIX Confidence Value Ranges of Values 6 - Truth cannot be judged Not Specified N/A 5 - Improbable 10 0-19 4 - Doubtful 30 20-39 3 - Possibly True 50 40-59 2 - Probably True 70 60-79', 'vec_doc-10-oasis-stix21-p245-579', 0, 216, 'v2.1.0', 'a08cca5054535f54674094b6e9301b4b49037fbc6d67cfbc74e28945bbffd68d', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"section 9.7 Object Path Syntax","subsection":"UNKNOWN","table_id":null,"page":245,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":579,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"section 9.7 Object Path Syntax"}');
