INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p255-592', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', 'section 9.7 Object Path Syntax', 255, '[ { "type": "marking-definition", "spec_version": "2.1", "id": "marking-definition--34098fce-860f-48ae-8e50-ebd3cc5e41da", "created": "2016-08-01T00:00:00.000Z", "definition_type": "statement", "definition": { "statement": "Copyright 2019, Example Corp" } }, { "id": "extension-definition--04b2d3ef-d061-4912-ab77-6bbe807a5bd5", "type": "extension-definition", "spec_version": "2.1", "created": "2014-02-20T09:16:08.989000Z", "modified": "2014-02-20T09:16:08.989000Z", "created_by_ref": "identity--11b76a96-5d2b-45e0-8a5a-f6994f370731", "name": "New SDO 2", "description": "This schema creates a new object type called my-favorite-sdo-2", "schema": "https://www.example.com/schema-my-favorite-sdo-2/v1/", "version": "1.2.1", "object_marking_refs": ["marking-definition--34098fce-860f-48ae-8e50-ebd3cc5e41da"], "extension_types": [ "new-sdo" ] }, { "type": "my-favorite-sdo", "spec_version": "2.1", "id": "my-favorite-sdo--64b8f076-a336-4d08-a0a3-fa6bd4ccc7c6", "created": "2014-02-20T09:16:08.989000Z",', 'vec_doc-10-oasis-stix21-p255-592', 0, 251, 'v2.1.0', '2a603705c968483095b2455fa37dd35f500962165e3376ff19fd6c8ef263f3e6', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"section 9.7 Object Path Syntax","subsection":"UNKNOWN","table_id":null,"page":255,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":592,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"section 9.7 Object Path Syntax"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p256-593', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', 'section 9.7 Object Path Syntax', 256, 'Standards Track Work Product 02 April 2025 - Page 256 of 276Copyright © OASIS Open 2025. All Rights Reserved. "modified": "2014-02-20T09:16:08.989000Z", "name": "This is the name of my favorite", "some_property_name1": "value1", "some_property_name2": "value2", "extensions": { "extension-definition--04b2d3ef-d061-4912-ab77-6bbe807a5bd5" : { "extension_type": "new-sdo" } } } ] C.2.2 Adding properties to an existing STIX object instance This example adds the properties rank and toxicity to the indicator object. [ { "id": "extension-definition--d83fce45-ef58-4c6c-a3f4-1fbc32e98c6e", "type": "extension-definition", "spec_version": "2.1", "name": "Extension Foo 1", "description": "This schema adds two properties to a STIX object", "created": "2014-02-20T09:16:08.989000Z", "modified": "2014-02-20T09:16:08.989000Z", "created_by_ref": "identity--11b76a96-5d2b-45e0-8a5a-f6994f370731", "schema": "https://www.example.com/schema-foo-1/v1/", "version": "1.2.1", "extension_types": [ "property-extension" ] }, { "type": "indicator", "spec_version": "2.1", "id": "indicator--e97bfccf-8970-4a3c-9cd1-5b5b97ed5d0c", "created": "2014-02-20T09:16:08.989000Z", "modified": "2014-02-20T09:16:08.989000Z", "name": "File hash for Poison Ivy variant", "description": "This file hash indicates that a sample of Poison Ivy is present.", "labels": [ "malicious-activity" ], "pattern": "[file:hashes.''SHA-256'' = ''ef537f25c895bfa782526529a9b63d97aa631564d5d789c2b765448c8635fb6c'']", "pattern_type": "stix", "valid_from": "2014-02-20T09:00:00.000000Z", "extensions": { "extension-definition--d83fce45-ef58-4c6c-a3f4-1fbc32e98c6e" : { "extension_type": "property-extension", "rank": 5, "toxicity": 8 } } } ]', 'vec_doc-10-oasis-stix21-p256-593', 0, 423, 'v2.1.0', 'bd2841296d049b76bfc04d359a2fe61797c909c0a16bfcbfa3a7492d8e5ee170', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"section 9.7 Object Path Syntax","subsection":"UNKNOWN","table_id":null,"page":256,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":593,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"section 9.7 Object Path Syntax"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p257-594', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', 'section 9.7 Object Path Syntax', 257, 'Standards Track Work Product 02 April 2025 - Page 257 of 276Copyright © OASIS Open 2025. All Rights Reserved. This example shows how one can also add the same extension (properties rank and toxicity) to the artifact object. { "type": "artifact", "spec_version": "2.1", "id": "artifact--6be1fbcb-fd03-5ec3-b05f-4329746e9d2b", "mime_type": "application/zip", "payload_bin": "ZX7HIBWPQA99NSUhEUgAAADI== ...", "encryption_algorithm": "mime-type-indicated", "decryption_key": "My voice is my passport", "extensions": { "extension-definition--d83fce45-ef58-4c6c-a3f4-1fbc32e98c6e" : { "extension_type": "property-extension", "rank" :5, "toxicity": 8 } } } C.2.3 Adding properties to an existing STIX relationship object instance This example adds the property mysightingprop to the sighting object. [ { "id": "extension-definition--a19a6f0a-93dc-4f34-ac9f-83a0141261de", "type": "extension-definition", "spec_version": "2.1", "name": "Extension Foo 2", "description": "This schema adds a property to the sighting object", "created": "2014-02-20T09:16:08.989000Z", "modified": "2014-02-20T09:16:08.989000Z", "created_by_ref": "identity--11b76a96-5d2b-45e0-8a5a-f6994f370731", "schema": "https://www.example.com/schema-foo-2/v1/", "version": "1.2.1", "extension_types": [ "property-extension" ] }, { "type": "sighting", "spec_version": "2.1", "id": "sighting--ee20065d-2555-424f-ad9e-0f8428623c75", "created_by_ref": "identity--f431f809-377b-45e0-aa1c-6a4751cae5ff", "created": "2016-04-06T20:08:31.000Z", "modified": "2016-04-06T20:08:31.000Z", "sighting_of_ref": "indicator--8e2e2d2b-17d4-4cbf-938f-98ee46b3cd3f", "extensions": { "extension-definition--a19a6f0a-93dc-4f34-ac9f-83a0141261de" : { "extension_type": "property-extension", "mysightingprop" : "life is a bunch of bananas" } } } ]', 'vec_doc-10-oasis-stix21-p257-594', 0, 446, 'v2.1.0', 'b24f3fa113c87d27cc985bd22d60e56ed36ee9eaac39a8da61b904ad8e65c15f', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"section 9.7 Object Path Syntax","subsection":"UNKNOWN","table_id":null,"page":257,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":594,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"section 9.7 Object Path Syntax"}');
