INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p272-627', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '5. Object Identifiers: None', 272, 'Standards Track Work Product 02 April 2025 - Page 272 of 276Copyright © OASIS Open 2025. All Rights Reserved. Appendix G: Revision History Revision Date Editor Changes Made 01 2018- 07-20 Bret Jordan, John Wunder, Rich Piazza, Ivan Kirillov, Trey Darley Initial Version Github Issues: 2, 3, 4, 5, 6, 7, 9, 11, 13, 15, 16, 17, 18, 19, 20, 21, 22, 25, 26, 27, 31, 33, 35, 36, 37, 38, 39, 40, 41, 42, 54, 55, 57, 68, 71, 78, 88, 89, 91, 98, 99, 121 02 2018- 08-10 Bret Jordan, John Wunder, Rich Piazza, Ivan Kirillov, Trey Darley Multiple editorial, style, and grammar fixes. Added normative text to ensure that the various ending timestamp properties are before the first timestamp. Updates to the “labels” property description to better describe potential overlap with the specific classification properties. Fixed relevant common properties to the definition for Language Content.', 'vec_doc-10-oasis-stix21-p272-627', 0, 220, 'v2.1.0', '44415205d1f7fb43f6eb746bb078fab6bc61112c6a52262ec9abe5dd95ee1f61', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"5. Object Identifiers: None","subsection":"UNKNOWN","table_id":null,"page":272,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":627,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"5. Object Identifiers: None"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p272-628', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '5. Object Identifiers: None', 272, 'Language Content object: Fixed relevant common property definitions, expanded the definition of “contents” property to include handling of lists when not all list items have language content in that language. Added a “roles” property to Identity. Observed Data object: expanded description to broaden its usage, made “first_observed”, “last_observed”, and “number_observed” properties optional, added normative statements to “first_observed” and “last_observed” properties to address consistency between the properties. Option object: renamed “description” property to “explanation”. Sighting object: updated normative text for the “where_sighted_refs” property to allow for using Location objects in addition to Identity objects. Artifact object: updated normative text for “encryption_algorithm” from a SHOULD to a MUST use values from the defined enumeration. Network Traffic object: added text to indicate that values for byte and packet counts are positive integers.', 'vec_doc-10-oasis-stix21-p272-628', 0, 243, 'v2.1.0', '36f41fd9cfca65dbaefb899864680714d84259b18f61e918bb1634882fb97a08', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"5. Object Identifiers: None","subsection":"UNKNOWN","table_id":null,"page":272,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":628,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"5. Object Identifiers: None"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p272-629', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '5. Object Identifiers: None', 272, 'Patterning Observation Expression: updated normative text to clarify the behavior of Observation Expression comparisons with OR is a short-circuit. Github Issues: n/a', 'vec_doc-10-oasis-stix21-p272-629', 0, 42, 'v2.1.0', 'c7536bf78ee2a93c40729b0ed176e810c0d3882b82ea9e4b3ad40ae89bbfc57c', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"5. Object Identifiers: None","subsection":"UNKNOWN","table_id":null,"page":272,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":629,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"5. Object Identifiers: None"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p273-630', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '5. Object Identifiers: None', 273, 'Standards Track Work Product 02 April 2025 - Page 273 of 276Copyright © OASIS Open 2025. All Rights Reserved. 03 2018-09-05 Bret Jordan,John Wunder, Rich Piazza, Ivan Kirillov, Trey Darley Reverted Observed Data properties back to required. Github Issues: 90 This version became CSD 01. 04 2019- 05-29 Bret Jordan, Rich Piazza, Trey Darley Updated the entire introduction. Merged content down into a single document. Merged down the following content sections into the master document: Introductions, Vocabularies, Customization, Conformance. Added the following objects and their respective vocabularies: Infrastructure, Grouping, Malware Analysis. Updated the following objects: COA, Malware.', 'vec_doc-10-oasis-stix21-p273-630', 0, 174, 'v2.1.0', '4f166eae1bb8cb78421c124b3e6abb6f4b063de11213f20e0ee3ed84f8a09eaf', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"5. Object Identifiers: None","subsection":"UNKNOWN","table_id":null,"page":273,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":630,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"5. Object Identifiers: None"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-10-oasis-stix21-p273-631', 'doc-10-oasis-stix21', 'doc-10-oasis-stix21', '5. Object Identifiers: None', 273, 'Github Issues: 8, 10, 12, 14, 24, 32, 64, 72, 76, 79, 81, 87, 92, 93, 94, 101, 103, 104, 105, 106, 107, 108, 109, 110, 111, 113, 114, 116, 117, 118, 120, 122, 124, 127, 128, 129, 132, 133, 134, 135, 136, 137, 138, 139, 140, 141, 142, 143, 144, 145, 147, 148, 152, 154 05 2019- 07-12 Bret Jordan, Rich Piazza, Trey Darley Some basic formatting cleanup. Renamed conflicting properties on Directory Object, File Object, Process Object, and Windows Registry Key Object. Changed Language Content property that allowed version pinning to be optional. Added relationship from Indicator to Observed Data called “based-on”. Added a description to Sighting. Added a name to Location. Made some SCO relationships external on Domain-Name, IPv4-Addr, and IPv6-Addr. Added some text to 3.4 and 3.6. Relaxed requirements that prevented relationships pointing to Language Content, Marking Definitions, and Relationships themselves.', 'vec_doc-10-oasis-stix21-p273-631', 0, 229, 'v2.1.0', '8e5dbb30aac3139c1c763a85274941a3a2d67ce909a54aa89bf78d8ef68f3165', '{"document_id":"doc-10-oasis-stix21","document_title":"OASIS STIX v2.1 Specification","chapter":"UNKNOWN","section":"5. Object Identifiers: None","subsection":"UNKNOWN","table_id":null,"page":273,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":631,"source_path":".zayron/knowledge/physical-15/10-oasis-stix21.pdf","section_path":"5. Object Identifiers: None"}');
